window.PLATFORM_DATAPSYDIS = {"courseTitle": "الاضطرابات النفسية الحركية عند المصاب بالتوحد", "courseSub": "دورة متخصصة كاملة: تسع عشرة وحدة و79 درسًا — كل اضطراب نفسي حركي عند أصحاب طيف التوحد بشكلِه وتأثيراته وآلية عمله وأنشطته، من العلامات المبكرة والآليات العابرة إلى المقوّية العضلية والمخطط الجسدي وصورة الجسم والمشية والتوازن والتناسق والحركة الدقيقة والجانبية والإيقاع والحركات النمطية والتقليد والتخطيط والاستباق، ثم الاضطرابات الحسية المؤثرة في الحركة وطبقة التعديلات وبناء الخطة من الاضطراب إلى التنفيذ، وحالات تطبيقية كاملة، ومراجع ومسرد عربي-فرنسي.", "lessons": [{"n": 1, "title": "ما النفسية الحركية؟ وكيف وُلد مفهومها", "intro": "<p>تتعرف في هذا الدرس على اللحظة التي وُلد فيها مفهوم النفسية الحركية، ولماذا وُلد أصلًا. القصة ليست زخرفة تاريخية: التخصص كله قام على ملاحظة عيادية واحدة ما زالت هي قلب عملنا مع المصاب بالتوحد حتى اليوم، وهي أن طفلًا قد تكون عضلاته وأعصابه سليمة ومع ذلك يفشل في الحركة المنظمة، لأن ما تعطّل ليس العضو بل العلاقة بين النفس والجسد. من فهم هذه الولادة فهم لماذا لا تبدأ دورتنا من الحركة، بل من المقوّية والمخطط الجسدي.</p>", "slides": [{"kind": "cover", "title": "ما النفسية الحركية؟ وكيف وُلد مفهومها", "sub": "الوحدة الأولى: مدخل تاريخي: نشأة النفسية الحركية وتطورها ومجالات تدخلها", "goals": ["أن تشرح كيف وُلد مفهوم النفسية الحركية ومن أي تربة علمية خرج", "أن تميّز جسد الرياضة والمدرسة ما قبل المفهوم عن الجسد الذي صار موضوع التخصص", "أن تسمّي علامات دوبريه الثلاث في متلازمة الوهن الحركي 1907"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l01.jpg", "img2": null}, {"kind": "slide", "title": "ما النفسية الحركية؟ وكيف وُلد مفهومها", "points": ["قبل التخصص كان الجسد والعقل يُعالجان منفصلين.", "الطفل الأخرق بلا إصابة عضوية لم يكن له تفسير ولا جهة تعنى به.", "المنطقة بين العصبي والنفسي هي مهد النفسية الحركية."], "text": {"head": "قبل المفهوم — جسد للرياضة ونفس للمدرسة", "body": "<p>قبل أن توجد النفسية الحركية تخصصًا، كان جسد الطفل موزّعًا بين جهتين لا تلتقيان: المدرسة تعنى بعقله، وأستاذ الرياضة يعنى بجسده، على قاعدة أن الجسد السليم يخدم العقل السليم. أما الطفل الذي يتعثر ويخرق ويتخبط في حركاته دون مرض عضوي ظاهر، فلم يكن له مكان في هذا التقسيم: لا هو مريض عصبي صريح، ولا هو كسول كما كان يُحكم عليه. وقد مهّد لهذا الدخول أطباء في بلدان عدة، مثل غريسينغر ومولر في ألمانيا وفرانكل في سويسرا ولاندوا ثم دوبريه في فرنسا. هذه المنطقة العمياء هي التي ستدخل منها النفسية الحركية إلى الوجود، حين بدأ أطباء الأعصاب النفس يلاحظون أن بين العصبي والنفسي أرضًا ثالثة لم يسمّها أحد بعد.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "ما النفسية الحركية؟ وكيف وُلد مفهومها", "points": ["شيرينغتون وصف الحس العميق وأسّس لفكرة التكامل العصبي للحركة.", "الحركة المنظمة تفترض أن الجسد يحسّ بنفسه أولًا.", "اضطراب المدخلات الجسدية الداخلية سيظهر في قلب اضطرابات التوحد الحركية."], "text": {"head": "شيرينغتون — الجسد يحسّ بنفسه", "body": "<p>في مطلع القرن العشرين وضع عالم الفيزيولوجيا البريطاني تشارلز شيرينغتون (Charles Sherrington) أساسًا علميًا غيّر فهم الحركة: في أعماله عن العمل التكاملي للجهاز العصبي (1906) وصف مستقبلات الحس العميق (proprioception) التي تخبر الدماغ باستمرار عن مواضع أطرافنا وشدة انقباض عضلاتنا دون أن ننظر إليها. صار للجسد، علميًا، حسّ سادس داخلي يبني عليه كل تنظيم حركي. هذه الفكرة ستصبح لاحقًا أحد أركان النفسية الحركية: فمن لا يصله إحساسه العميق سليمًا لا يستطيع أن يبني مخططًا لجسده ولا أن يضبط مقوّيته، وهما أول اضطرابين في هذه الدورة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "ما النفسية الحركية؟ وكيف وُلد مفهومها", "points": ["1907: دوبريه يصف الوهن الحركي متلازمة قائمة بذاتها.", "ثلاث علامات: خرق حركي، باراتونيا، حركات مصاحبة.", "لأول مرة يصبح للفشل الحركي غير العضوي اسم وتشخيص."], "text": {"head": "دوبريه 1907 — الوهن الحركي أول متلازمة", "body": "<p>الخطوة الحاسمة جاءت من إرنست دوبريه (Ernest Dupré)، طبيب الأعصاب وتلميذ شاركو (Charcot)، حين وصف سنة 1907 متلازمة الوهن الحركي (syndrome de débilité motrice). جمع دوبريه ثلاث علامات كان الأطباء يرونها متفرقة: الخرق الحركي (maladresse) أي الفشل في الحركات الدقيقة والمنسقة رغم سلامة القوة، والباراتونيا (paratonie) أي عجز العضلة عن الاسترخاء الكامل عند الفحص المقاوم، والحركات المصاحبة الزائدة (syncinésies) أي تحرك أعضاء لا شأن لها بالحركة المطلوبة. بتشبيهها بالوهن العقلي، قال دوبريه إن هناك ضعفًا حركيًا قائمًا بذاته له سيميولوجيته الخاصة، يُولد به الطفل أو يكتسبه مبكرًا، ولا يُختزل في كسل ولا في إصابة عضوية صريحة. لهذا يُلقَّب في أدبيات التخصص بجدّ النفسية الحركية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "ما النفسية الحركية؟ وكيف وُلد مفهومها", "points": ["الصعوبة الحركية قد تكون نفسية-علائقية المصدر لا عضوية.", "الحركة في النفسية الحركية وسيلة علاج لا غاية رياضية.", "وحدة النفس والجسد هي العقيدة المؤسسة للتخصص."], "text": {"head": "الفكرة المؤسِّسة — ليست كل صعوبة حركية عصبية", "body": "<p>توالت الملاحظات بعد دوبريه واتسعت: صعوبات نفسية حركية كثيرة لا يفسرها منشأ عصبي وحده، ولا منشأ عضوي وحده؛ فالطفل نفسه قد ينجح في حركة معقدة داخل لعبه ويفشل في حركة أبسط داخل موقف فحص، لأن الانفعال والعلاقة والقصد يدخلون في إنتاج الحركة نفسها. من هنا تبلور تعريف العمل الذي ما زال يحكم التخصص: النفسية الحركية علاج عصبي-نفسي-فيزيولوجي يعمل من خلال الجسد، ويتوجه إلى الإنسان بكليته وحدة لا تتجزأ؛ لا هي رياضة بدنية لأن الحركة فيها وسيلة لا غاية، ولا تعليم مهارة محددة، بل استقلال تدريجي للجسد بكامله ورفاهية جسدية تفتح اتصالًا أفضل بين الطفل ومحيطه، كما في الصياغة التي نقلها مازيت وهوزل (Mazet et Houzel).</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "ما النفسية الحركية؟ وكيف وُلد مفهومها", "points": ["التوحد يعيد طرح سؤال التخصص الأول: فشل حركي بلا تفسير عصبي كامل.", "ترتيب دورتنا (مقوّية ثم مخطط جسدي) امتداد لمنطق الولادة نفسه.", "القراءة بالآلية قبل النشاط قاعدة تلازم كل الوحدات."], "text": {"head": "لماذا تهمّك هذه الولادة في عملك مع التوحد", "body": "<p>المصاب بالتوحد هو الوريث العيادي المباشر لسؤال دوبريه: علامات حركية مبكرة موثقة، ومقوّية مضطربة، وتناسق ينهار في موقف وينجح في آخر، دون أن يفسر الفحص العصبي الكلاسيكي الصورة كاملة. لهذا لا تبدأ هذه الدورة بمهارات حركية معزولة، بل تبدأ من حيث بدأ التخصص نفسه: من المقوّية العضلية بوصفها قاعدة، ثم المخطط الجسدي الذي يُبنى عليها، ثم بقية المكونات بترتيب المؤسس المعتمد. وكل اضطراب في الوحدات القادمة سيُقرأ بهذه الروح: شكلًا وآلية، قبل أي نشاط مقترح.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما العلامات الثلاث التي جمعها دوبريه في متلازمة الوهن الحركي (1907)؟", "الإجابة: الخرق الحركي (maladresse)، والباراتونيا (paratonie) أي عجز الاسترخاء العضلي الكامل، والحركات المصاحبة الزائدة (syncinésies)."], "text": null, "take": "النفسية الحركية وُلدت حين سمّى دوبريه (1907) فشلًا حركيًا لا يفسره العضو، وقامت على أن النفس والجسد وحدة واحدة، وأن الحركة فيها وسيلة علاج لا غاية.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 2, "title": "فالون — الحوار المقوّي ووحدة النفس والجسد", "intro": "<p>إذا كان دوبريه قد سمّى المشكلة، فإن هنري فالون (Henri Wallon) هو من أعطى التخصص روحه النظرية. في هذا الدرس تتعرف على فكرته المركزية: المقوّية العضلية عند الإنسان ليست خاصية ميكانيكية في العضلات، بل أول لغة يتواصل بها الرضيع مع من يحمله، والقناة التي يعبر منها الانفعال قبل أن توجد الكلمات. فهمُك لهذه الفكرة شرطٌ لفهم اضطراب المقوّية، وهو أول اضطرابات دورتنا، ولفهم لماذا يقرأ المختص النفسي الحركي مقوّيةَ المتعلم قبل أن يقرأ حركته.</p>", "slides": [{"kind": "cover", "title": "فالون — الحوار المقوّي ووحدة النفس والجسد", "sub": "الوحدة الأولى: مدخل تاريخي: نشأة النفسية الحركية وتطورها ومجالات تدخلها", "goals": ["أن تشرح الحوار المقوّي عند فالون ودور المقوّية في وحدة النفس والجسد", "أن تربط الانفعال بالمقوّية في قراءة سلوك المتعلم الحركي", "أن تطبق مفهوم الحوار المقوّي في ملاحظة تفاعل رضيع ومقدّم رعاية"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l02.jpg", "img2": null}, {"kind": "slide", "title": "فالون — الحوار المقوّي ووحدة النفس والجسد", "points": ["فالون: مؤسس علم نفس النمو الجيني في فرنسا.", "أعماله على المقوّية والانفعال منذ 1925.", "وحدة بيولوجية-نفسية لا تقبل الفصل بين الجسد والنفس."], "text": {"head": "فالون وموقعه في تاريخ التخصص", "body": "<p>هنري فالون (1879-1962) طبيب وعالم نفس فرنسي، مؤسس علم نفس النمو الجيني (psychologie génétique) في فرنسا. في أعماله المبكرة، ومنذ 1925 درس في أعماله المبكرة الأطفال ذوي الاضطرابات الحركية والانفعالية ملاحظًا أن حركاتهم ومقوّيتهم لا تنفصلان عن حياتهم الانفعالية وعلاقاتهم. رفض فالون الفصل بين البيولوجي والنفسي: الإنسان عنده وحدة بيولوجية-حركية-نفسية متماسكة، والمقوّية هي نقطة التقائها الأولى. لهذا يُعَدّ في تاريخ التخصص الأب الروحي لجوليان دو أجورياغيرا (Julian de Ajuriaguerra) الذي سيحوّل هذه الفلسفة إلى مهنة، كما سترى في الدرس القادم.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فالون — الحوار المقوّي ووحدة النفس والجسد", "points": ["المقوّية وظيفة وضعية وانفعالية في آن واحد.", "الانفعال يعبر عبر العضلات قبل الكلام.", "فحص المقوّية قراءة مزدوجة: جسدية وعلائقية."], "text": {"head": "المقوّية عند فالون — وظيفة وضعية وانفعالية معًا", "body": "<p>عند أطباء الأعصاب كانت المقوّية خاصية عضلية تُقاس بالمقاومة والارتخاء. فالون وسّع النظر: المقوّية عند الإنسان وظيفتان في واحدة. هي أولًا وظيفة وضعية (fonction tonique posturale) تُبقي الجسد قائمًا ومهيأ للحركة، وهي ثانيًا وفي الوقت نفسه وظيفة انفعالية وعلائقية: فرح الرضيع وخوفه واطمئنانه يظهرون أول ما يظهرون في تصلب جسده أو ارتخائه، قبل أي تعبير آخر. العضلة عند فالون تتكلم: شدّها وارتخاؤها رسائل. وهذا هو الأساس النظري الذي ستقوم عليه وحدة اضطراب المقوّية في هذه الدورة: حين نفحص مقوّية المصاب بالتوحد فنحن نقرأ حالته الانفعالية وعلاقته بالآخر في الوقت نفسه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فالون — الحوار المقوّي ووحدة النفس والجسد", "points": ["الحوار المقوّي تبادل شدّ وارتخاء بين الرضيع وحامله.", "هو أول تواصل إنساني، سابق للغة والنظر المشترك.", "اضطرابه المبكر علامة ومدخل علاجي في التوحد معًا."], "text": {"head": "الحوار المقوّي — أول محادثة في حياة الإنسان", "body": "<p>من هذه الفكرة وُلد مفهوم الحوار المقوّي (dialogue tonique): منذ الأسابيع الأولى، يدخل الرضيع ومن يحمله في تبادل مقوّي مستمر؛ جسد الأم يشدد ويرخي فيجيب جسد الرضيع بشد وارتخاء، وهذا التناغم أو اضطرابه هو أول تواصل إنساني، قبل النظر المشترك وقبل الأصوات وقبل الكلمات بزمن طويل. صاغ أجورياغيرا المفهوم صياغته الناضجة (1960) على أساس فالون، وصار حجر زاوية في الممارسة النفسية الحركية كلها: فالمختص حين يحمل المتعلم أو يقاومه أو يهدهده يقرأ مقوّيته ويجيب بمقوّيته، أي أنه يدخل الحوار المقوّي نفسه أداةَ فحص وعلاج معًا. وفي التوحد، حيث يضطرب هذا الحوار مبكرًا (غياب الوضعية الاستباقية عند الحمل علامة موثقة في وحدة العلامات المبكرة من هذه الدورة)، يصبح استئنافه مدخلًا علاجيًا قائمًا بذاته.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فالون — الحوار المقوّي ووحدة النفس والجسد", "points": ["مرحلة الانفعال: المقوّية وسيط العلاقة الكلي.", "المرحلة الحسية الحركية: الجسد أداة معرفة أولى.", "العلاج يعود أحيانًا لبناء طبقة نمائية فائتة لا لمهارة العمر."], "text": {"head": "مراحل فالون باختصار وظيفي", "body": "<p>رسم فالون نمو الطفل مراحل يتناوب فيها الغالب الانفعالي والغالب المعرفي، تهمّنا منها هنا مرحلتان. في مرحلة الانفعال (stade émotionnel) من حياة الرضيع الأولى، المقوّية هي الوسيط الكلي للعلاقة: لا يملك الرضيع إلا جسده ليقول رضاه وضيقه. ثم في المرحلة الحسية الحركية (stade sensorimoteur) يتحول الجسد أداة استكشاف ومعرفة، فتُبنى التمثيلات الأولى للفضاء والجسد نفسه على الحركة والإحساس. الدرس العملي للمختص: الاضطراب الذي تراه عند متعلم في السادسة قد يكون قائمًا على طبقة من هاتين المرحلتين لم تُبنَ في وقتها، والعمل العلاجي كثيرًا ما يعود ليبني الطبقة الفائتة بوسائل عمرها الأصغر، لا بتدريب مهارة العمر الحالي مباشرة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فالون — الحوار المقوّي ووحدة النفس والجسد", "points": ["المقوّية قاعدة المخطط الجسدي عند فالون، وترتيب الدورة يتبع ذلك.", "سيميولوجيا اضطراب المقوّية امتداد عيادي لمفاهيمه.", "القاعدة: قراءة المقوّية تسبق قراءة الحركة."], "text": {"head": "لماذا يتصدّر فالون دورتنا عمليًا", "body": "<p>المقوّية عند فالون قاعدة كل بناء لاحق: المخطط الجسدي يُبنى على تجارب مقوّية-وضعية متراكمة، وصورة الجسم تنشأ داخل هذا البناء. وأدوات قراءة اضطراب المقوّية عند المصاب بالتوحد (تصلب وارتخاء بحسب السياق، وضعيات متناقضة، تعديل مقوّي أمام الآخر) هي مفاهيم فالون وقد صارت سيميولوجيا عيادية. احتفظ إذن بقاعدة واحدة من هذا الدرس: لا تقرأ حركة متعلمك قبل أن تقرأ مقوّيته، ففيها يبدأ كل شيء.</p><p>وعند فالون تُقرأ المقوّية في وجهين متزامنين دائمًا: وجه حركي يضبط الجسد في الفضاء، ووجه تعبيري يخاطب الآخرين قبل أي كلام؛ فشدّ الرضيع على ذراعي حامله وارتخاؤه عليه رسائل علائقية كاملة، ولهذا صار الحوار المقوّي عنده اسمًا لأول محادثة إنسانية — محادثة لا تحتاج لغة لأن لغتها هي الشدّ والارتخاء نفسيهما.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الحوار المقوّي (dialogue tonique)؟", "الإجابة: تبادل مستمر من الشدّ والارتخاء العضلي بين الرضيع ومن يحمله، يشكّل أول تواصل إنساني قبل اللغة، ويقرأ فيه كل طرف حالة الآخر الانفعالية من جسده."], "text": null, "take": "عند فالون المقوّية لغة الانفعال الأولى، والحوار المقوّي أول تواصل إنساني؛ ومن هنا صارت المقوّية قاعدة التقييم والتدخل النفسي الحركي كله.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 3, "title": "1947 — أجورياغيرا وسوبيران وميلاد مهنة في مستشفى هنري روسيل", "intro": "<p>في الدرسين الماضيين وُلد المفهوم نظريةً. في هذا الدرس تتعرف على اللحظة التي صار فيها التخصص مهنة تمارَس داخل مؤسسة: سنة 1947 في باريس، حين التقى طبيب أعصاب نفسي شاب هو جوليان دو أجورياغيرا (Julian de Ajuriaguerra, 1911-1993) بممارسة بنت الميدان هي جيزيل سوبيران (Giselle Soubiran)، فأنتج لقاؤهما أول قسم لإعادة التربية النفسية الحركية (rééducation psychomotrice)، وأدوات الحوصلة الأولى، والنص الذي عرّف الاضطرابات النفسية الحركية تعريفًا مؤسسًا.</p>", "slides": [{"kind": "cover", "title": "1947 — أجورياغيرا وسوبيران وميلاد مهنة في مستشفى هنري روسيل", "sub": "الوحدة الأولى: مدخل تاريخي: نشأة النفسية الحركية وتطورها ومجالات تدخلها", "goals": ["أن تروي بدقة كيف تأسس فريق 1947 في هنري روسيل ومن أعضاؤه", "أن تشرح ما أضافته سوبيران لأدوات الحوصلة الأولى", "أن تميّز إعادة التربية النفسية الحركية المؤسسية عن الممارسات المتناثرة قبلها"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l03.jpg", "img2": null}, {"kind": "slide", "title": "1947 — أجورياغيرا وسوبيران وميلاد مهنة في مستشفى هنري روسيل", "points": ["1947: أول قسم إعادة تربية نفسية حركية في هنري روسيل.", "الفريق متعدد التخصصات من اليوم الأول.", "1948: مركز إعادة التربية النفسية الحركية واللغة."], "text": {"head": "باريس 1947 — فريق متعدد التخصصات حول طفل", "body": "<p>بعد الحرب العالمية الثانية، كُلّف الطبيب بيير مال (Pierre Male) بإنشاء مركز إرشاد للطفولة في مستشفى هنري روسيل (hôpital Henri-Rousselle) بباريس، فاستدعى أجورياغيرا لبناء فريق بحث متعدد التخصصات. وبمبادرة من سوبيران أُنشئ داخل المركز أول قسم لإعادة التربية النفسية الحركية، ثم صار سنة 1948 مركز إعادة التربية النفسية الحركية واللغة (Centre de rééducation psychomotrice et du langage). ضمّ الفريق أسماء ستصنع طب نفس الطفل الفرنسي كله: رينيه زازو (René Zazzo) في علم النفس، ورينيه دياطكين (René Diatkine) وسيرج لوبوفيتشي (Serge Lebovici) في التحليل النفسي، وجان بيرجيس (Jean Bergès)، وميرا ستامباك (Mira Stambak). الدرس البنيوي هنا: النفسية الحركية لم تولد تخصصًا منعزلًا بل عضوًا في فريق، وهذا موقعها الطبيعي حتى اليوم.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "1947 — أجورياغيرا وسوبيران وميلاد مهنة في مستشفى هنري روسيل", "points": ["سوبيران بنت أولى أدوات الحوصلة النفسية الحركية.", "الحوصلة عندها فحص منظم يسبق أي مشروع تدخل.", "الاسترخاء النفسي الجسدي تقنيتها المميزة (1975)."], "text": {"head": "سوبيران — من الممارسة إلى أدوات التقييم", "body": "<p>جيزيل سوبيران، المعالجة الآتية من ميدان إعادة التأهيل الجسدي، هي التي حوّلت أفكار الفريق إلى ممارسة قابلة للنقل والتعليم. من مطلع الخمسينيات بنت أول الأعمال المنظمة في النفسية الحركية، وطوّرت أولى أدوات التقييم النفسي الحركي التي ستتفرع عنها الحوصلة (bilan psychomoteur) كما نعرفها: فحص منظّم للمقوّية والوضعية والتوازن والتناسقات والمخطط الجسدي والجانبية والتنظيمين المكاني والزماني، يُبنى عليه مشروع تدخل فردي. ترأست قسم النفسية الحركية، وطوّرت مع جان-كلود كوست تقنية الاسترخاء النفسي الجسدي (relaxation psychosomatique) (1975). لهذا تُوصف في تاريخ التخصص بأنها أمّ الممارسة النفسية الحركية، كما يُوصف أجورياغيرا بأبيها النظري.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "1947 — أجورياغيرا وسوبيران وميلاد مهنة في مستشفى هنري روسيل", "points": ["1959: النص المؤسس يعرّف الاضطرابات النفسية الحركية فئة مستقلة.", "أربعة مصادر في بناء واحد: عصبي ونمائي وظاهراتي وتحليلي.", "ميثاق 1960 جمّع عمل فريق هنري روسيل كله."], "text": {"head": "النص المؤسس 1959 — تعريف الاضطرابات النفسية الحركية", "body": "<p>سنة 1959 نشر أجورياغيرا وسوبيران نصهما المؤسس (1959) الذي صار بمثابة عقد ميلاد التخصص العلمي؛ تلاه سنة 1960 نص جماعي لفريق هنري روسيل عُرف بميثاق 1960. قيمة النص المؤسس في تعريفه للاضطرابات النفسية الحركية: فئة قائمة بذاتها لا تُردّ إلى إصابة عصبية ولا إلى اضطراب نفسي خالص، بل تُفهم من تقاطع أربعة مصادر جمعها أجورياغيرا في بناء واحد: الطب العصبي النفسي (إرث دوبريه)، وعلم نفس النمو (إرث فالون)، والظاهراتية (تجربة الجسد المعيش)، والتحليل النفسي (حياة الجسد الوجدانية). ودورتُنا هذه وريثة هذا التعريف حرفيًا: كل اضطراب فيها يُقرأ جسديًا وعلائقيًا ووجدانيًا في الوقت نفسه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "1947 — أجورياغيرا وسوبيران وميلاد مهنة في مستشفى هنري روسيل", "points": ["منهج 1947: حوصلة موثقة قبل أي تدخل.", "البروفيل النفسي الحركي أساس المشروع العلاجي وقياسه.", "لا نشاط لاضطراب غير مقيّم."], "text": {"head": "الحوصلة تولد منهجًا — تقييم قبل أي تدخل", "body": "<p>أخطر ما ورّثه جيل 1947 لممارستنا ليس تقنية، بل ترتيب عمل: لا تدخل قبل حوصلة. صارت الحوصلة النفسية الحركية إجراءً منظمًا له مجالاته وأدواته واستنتاجاته (profil psychomoteur) التي تُبنى عليها أهداف المشروع العلاجي وتُقاس بها نتائجه لاحقًا. وحين تصل إلى وحدة الحوصلة في برنامجنا الكامل، أو إلى طبقة التعديلات في هذه الدورة، فأنت تعمل داخل هذا الميراث: تقييم موثق، ثم مشروع مكتوب، ثم تقييم مستمر. والقاعدة التي كرّرها أجورياغيرا بصيغ مختلفة تحكم دورتنا من أولها: المختص لا يصف نشاطًا لاضطراب لم يقيّمه، لأن النشاط الخاطئ لآلية غير مقروءة ليس علاجًا محايدًا بل ضجيجًا إضافيًا في جسد المتعلم.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "1947 — أجورياغيرا وسوبيران وميلاد مهنة في مستشفى هنري روسيل", "points": ["متدربو هنري روسيل نشروا التخصص دوليًا.", "مدرسة سويسرية من جنيف، وتيار لاتيني قوي.", "المرجعية الفرنسية أمّ لممارسة بلداننا العربية."], "text": {"head": "الانتشار — من باريس إلى جنيف وأمريكا اللاتينية", "body": "<p>لم يبق التخصص باريسيًا: تدرب في هنري روسيل بين 1948 و1960 مئات المتدربين الفرنسيين والأجانب من أصول تربوية وعلاجية متنوعة، فكان القسم مدرسة بقدر ما كان مصلحة علاجًا، وحمل المتدربون التخصص إلى بلدانهم. في سويسرا عملت سوزان نافيل (Suzanne Naville) مع أجورياغيرا حين انتقل إلى مستشفى بيل-إير بجنيف، فكانت أصل المدرسة السويسرية للنفسية الحركية. وحمل متدربون من أمريكا اللاتينية التخصص إلى قارتهم فصار فيها تيارًا قويًا قائمًا حتى اليوم. هذا الانتشار المبكر يفسر حضور النفسية الحركية في بلداننا العربية عبر خريجي المدرسة الفرنسية واللبنانية منذ عقود، ويفسر لماذا تبقى المرجعية الفرنسية هي المرجعية الأم لهذه الدورة في المصطلح والأدوات.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الإسهام المميز لكل من أجورياغيرا وسوبيران في ميلاد التخصص؟", "الإجابة: أجورياغيرا أعطى البناء النظري وتعريف الاضطرابات النفسية الحركية (نص 1959 المؤسس)، وسوبيران حوّلت الأفكار إلى ممارسة ببناء أولى أدوات الحوصلة النفسية الحركية وتنظيم القسم والتعليم."], "text": null, "take": "في 1947 صارت النفسية الحركية مهنة داخل فريق؛ سوبيران بنت أدوات تقييمها، وأجورياغيرا عرّف اضطراباتها (1959)، وقاعدتهما الباقية: لا تدخل قبل حوصلة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 4, "title": "من إعادة التربية إلى دبلوم الدولة — مأسسة التخصص وتفرّعه", "intro": "<p>تخصص بلا تكوين رسمي يبقى حرفة تُتناقل بالممارسة. في هذا الدرس تتتبع كيف انتقلت النفسية الحركية في ربع قرن من قسم مستشفى واحد إلى مهنة صحية معترف بها بدبلوم دولة، وكيف تفرّعت أثناء ذلك إلى ثلاثة فروع ما زالت تحدد مجالات عملك اليوم: التربية النفسية الحركية (éducation psychomotrice)، وإعادة التربية النفسية الحركية (rééducation psychomotrice)، والعلاج النفسي الحركي (thérapie psychomotrice). ستخرج بخريطة زمنية دقيقة وبفهم لما يعنيه غياب هذا الإطار القانوني في أغلب بلداننا العربية.</p>", "slides": [{"kind": "cover", "title": "من إعادة التربية إلى دبلوم الدولة — مأسسة التخصص وتفرّعه", "sub": "الوحدة الأولى: مدخل تاريخي: نشأة النفسية الحركية وتطورها ومجالات تدخلها", "goals": ["أن ترتّب محطات مأسسة التخصص حتى دبلوم الدولة 1974", "أن تسمّي الفروع الثلاثة التي تفرع إليها التخصص ومجال كل منها", "أن تفسّر لماذا غيّرت الشهادات الرسمية مصير المهنة وممارسيها"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l04.jpg", "img2": null}, {"kind": "slide", "title": "من إعادة التربية إلى دبلوم الدولة — مأسسة التخصص وتفرّعه", "points": ["1956: أول تعليم منظم داخل هنري روسيل.", "1963: شهادة الأهلية بقرار وزاري (4 فبراير).", "1967: سوبيران تؤسس ISRP أول معهد متخصص."], "text": {"head": "التعليم يتنظّم — 1956 ثم شهادة 1963", "body": "<p>بدأ فريق هنري روسيل تعليم إعادة التربية منذ 1956 بصورة أولية داخل المستشفى، لكن الطلب المتزايد فرض تقنينًا. نقل الدكتور جوليفِت (Dr Jolivet) التعليم إلى مستشفى لا بيتييه-سالبيتريير (La Pitié-Salpêtrière)، وصدر في 4 فبراير 1963 قرار وزاري ينشئ شهادة الأهلية في إعادة التربية النفسية الحركية (certificat de capacité en rééducation psychomotrice)، فصار للتكوين اعتراف رسمي أول وبرنامج موحد. وفي 1967 أنشأت جيزيل سوبيران مع ابنها جوزيه المعهد العالي لإعادة التربية النفسية الحركية (Institut Supérieur de Rééducation Psychomotrice, ISRP)، أول معهد متخصص قائم بذاته، وما زال يعمل حتى اليوم.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من إعادة التربية إلى دبلوم الدولة — مأسسة التخصص وتفرّعه", "points": ["1972: اتحاد مهني يخوض معركة الاعتراف.", "15 فبراير 1974: دبلوم الدولة بالمرسوم 74-112، الأول عالميًا.", "1988: إدراج قانوني كمهنة مساعدة طبية ومرسوم أعمال."], "text": {"head": "1974 — دبلوم الدولة والاعتراف الصحي", "body": "<p>نظّم الممارسون أنفسهم سنة 1972 في الاتحاد الفرنسي للنفسيين الحركيين (Fédération Française des Psychomotriciens, FFP) وخاضوا معركة الاعتراف الكامل. ثمرتها جاءت بالمرسوم 74-112 في 15 فبراير 1974 منشئًا دبلوم الدولة (diplôme d'État) — باسم دبلوم مُعيد التربية النفسية الحركية (psychorééducateur) أولًا ثم دبلوم النفسي الحركي — وهو أول دبلوم دولة من نوعه في العالم. تلا ذلك اكتمال الإطار: إدراج المهنة سنة 1988 في الكتاب الرابع من قانون الصحة العامة الفرنسي بوصفها مهنة مساعدة طبية (auxiliaire médical)، وصدور مرسوم أعمالها الذي يحدد ما يجوز للنفسي الحركي إجراؤه، وفي مقدمته الحوصلة النفسية الحركية ومشاريع التدخل. التكوين صار ثلاث سنوات في معاهد معتمدة (Instituts de Formation en Psychomotricité, IFP).</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من إعادة التربية إلى دبلوم الدولة — مأسسة التخصص وتفرّعه", "points": ["توجه وقائي لكل الأطفال في الوسط المدرسي.", "يبني المفاهيم الجسدية المؤسسة للقراءة والكتابة والحساب.", "يمنع تحول النقص الحركي إلى فشل مدرسي."], "text": {"head": "الفرع الأول — التربية النفسية الحركية", "body": "<p>الفرع الوقائي التربوي من التخصص يتوجه إلى الأطفال جميعًا لا إلى أصحاب الاضطرابات فقط، غالبًا في الوسط المدرسي وما قبله. هدفه أن يعيش الطفل جسده ويكتشف قدراته ويوظفها: إحساس بالذات، وإتقان للمفاهيم الجسدية المؤسسة للاكتساب المدرسي (جانبية، واتجاهات، وزمان ومكان، وذاكرة بصرية وسمعية، وانتباه)، وتعبير عن النفس وتواصل مع الآخرين عبر الجسد. قيمته العملية عندنا: كثير مما يصل المختص بوصفه صعوبة أكاديمية (كتابة معكوسة الاتجاه، بطء، خلط أحرف) جذره مفاهيم نفسية حركية ما قبل أكاديمية لم تُبنَ، والتربية النفسية الحركية هي باب بنائها قبل أن تتحول إلى فشل مدرسي موصوف.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من إعادة التربية إلى دبلوم الدولة — مأسسة التخصص وتفرّعه", "points": ["إعادة التربية: اضطرابات محددة بحوصلة ومشروع مقاس.", "العلاج النفسي الحركي: الوساطة الجسدية لاضطرابات نفسية وعلائقية.", "التوحد يقع في تقاطع الفرعين."], "text": {"head": "الفرعان العلاجيان — إعادة التربية والعلاج النفسي الحركي", "body": "<p>إعادة التربية النفسية الحركية تتوجه إلى اضطرابات النمو النفسي الحركي المحددة: التأخر النفسي الحركي، واضطرابات تنظيم المقوّية، واضطرابات معرفة الجسد وتصوّره، والجانبية، وتنظيم الزمان والمكان، وعجز التناسق، واضطرابات المهارات الحركية والحركة الكتابية، وتعمل بحوصلة ومشروع فردي مقاس. أما العلاج النفسي الحركي فيتجه إلى الحالات التي يكون فيها الاضطراب الجسدي محمولًا على حياة نفسية وعلائقية مضطربة: اضطرابات تصور الجسد، واضطرابات المزاج والشخصية والانفعال، والإعاقة الذهنية والتوحد، حيث تكون الوساطة الجسدية باب العلاج حين لا تكفي الكلمة. والحد بين الفرعين ليس في الأدوات بل في سؤال العمل: هل نعيد بناء وظيفة مضطربة، أم نعالج عبر الجسد علاقة صاحبها بجسده وبالآخر؟ ودورتنا تعمل في الفرعين معًا: تقرأ الاضطراب وظيفةً وعلاقةً.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من إعادة التربية إلى دبلوم الدولة — مأسسة التخصص وتفرّعه", "points": ["لا إطار قانوني للمهنة في أغلب البلدان العربية بعد.", "الصرامة الموثقة تعوّض غياب الإطار الخارجي.", "حدود الاختصاص والأخلاقيات جزء من التكوين لا إضافة إليه."], "text": {"head": "ما الذي يعنيه هذا التاريخ لممارستك في بلد بلا إطار", "body": "<p>في أغلب البلدان العربية لا يوجد حتى اليوم دبلوم دولة في النفسية الحركية ولا مرسوم أعمال يحمي المهنة ويحدد حدودها؛ يمارسها خريجو تخصصات قريبة (نفسية، أرطوفونيا، تربية خاصة، علاج وظيفي) بقدر ما يحمل كل منهم من تكوين فعلي. لهذا التاريخ درسان عمليان. الأول: الصرامة الفرنسية ليست ترفًا — الحوصلة الموثقة والمشروع المكتوب وحدود الممارسة هي ما يميز المختص من الممارس العابر، وهي ما تبنيه هذه الدورة فيك درسًا درسًا. الثاني: لأن الإطار الخارجي غائب، يصير الإطار الداخلي (تكوينك الموثق وأخلاقياتك وحدود اختصاصك) هو حمايتك وحماية متعلميك، وستلقاه مفصّلًا في وحدة أخلاقيات هذه المنظومة ودروس حدود الممارسة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الحدثان المؤسسان لمأسسة المهنة في فرنسا وتاريخاهما الدقيقان؟", "الإجابة: إنشاء شهادة الأهلية في إعادة التربية النفسية الحركية بقرار 4 فبراير 1963، ثم إنشاء دبلوم الدولة بالمرسوم 74-112 في 15 فبراير 1974."], "text": null, "take": "بين 1947 و1974 انتقل التخصص من قسم مستشفى إلى مهنة بدبلوم دولة (مرسوم 74-112)، وتفرّع إلى تربية وقائية وإعادة تربية وعلاج نفسي حركي — وهي الفروع الثلاثة التي تعمل فيها اليوم.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 5, "title": "مجالات تدخل النفسية الحركية اليوم — وموقع التوحد فيها", "intro": "<p>خريطة عمل التخصص كما هو اليوم: أين يعمل النفسي الحركي، ومع من، وفي أي مرحلة من العمر. ستجد في الخريطة خمسة مجالات كبرى، وستجد التوحد حاضرًا فيها كلها لا في مجال واحد: في الكشف المبكر، وفي المؤسسات، وفي المدرسة، وفي المرافقة الأسرية.</p>", "slides": [{"kind": "cover", "title": "مجالات تدخل النفسية الحركية اليوم — وموقع التوحد فيها", "sub": "الوحدة الأولى: مدخل تاريخي: نشأة النفسية الحركية وتطورها ومجالات تدخلها", "goals": ["أن تعدّد مجالات تدخل النفسية الحركية الخمسة اليوم", "أن تحدّد موقع التوحد داخل خريطة التدخل الحديثة", "أن تميّز ما يقدّمه النفسي الحركي في فريق التوحد عما يقدمه غيره"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l05.jpg", "img2": null}, {"kind": "slide", "title": "مجالات تدخل النفسية الحركية اليوم — وموقع التوحد فيها", "points": ["PMI والحضانات وCAMSP أطر عمل الطفولة المبكرة.", "الرصد المبكر للانحرافات المقوّية والوضعية أولى المهام.", "العلامة اشتباه يستدعي تقييمًا لا حكمًا نهائيًا."], "text": {"head": "مجال الطفولة المبكرة والوقاية", "body": "<p>أصغر مجالات العمل عمرًا وأكبرها أثرًا. يعمل النفسي الحركي في فرنسا في هيئات حماية الأمومة والطفولة (Protection Maternelle et Infantile, PMI) ودور الحضانة ومراكز العمل الطبي-الاجتماعي المبكر (Centres d'Action Médico-Sociale Précoce, CAMSP) التي تستقبل الأطفال من الولادة إلى 6 سنوات. مهمته هنا رصد الانحرافات الأولى عن مسار النمو النفسي الحركي: رضيع لا يبني وضعياته الاستباقية، أو يتأخر إمساك رأسه وجلوسه، أو يظهر شذوذًا مقوّيًا مبكرًا. قيمة هذا المجال لدورتنا مباشرة: وحدة العلامات الحركية المبكرة (0-24 شهرًا) القادمة هي مادة الكشف في هذا المجال، وقاعدة المنظومة فيه ثابتة — العلامة مؤشر اشتباه يستدعي تقييمًا، لا تشخيصًا يُلقى على الأسرة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مجالات تدخل النفسية الحركية اليوم — وموقع التوحد فيها", "points": ["العرض مدرسي والجذر غالبًا نفسي حركي.", "الحوصلة تفرز الطبقة الجسدية تحت صعوبة التعلم.", "نجاح التدخل يُقاس بنقله إلى الحياة المدرسية."], "text": {"head": "مجال المدرسة وصعوبات التعلم", "body": "<p>في الوسط المدرسي وحوله (مراكز الطب النفسي-التربوي CMPP، وخدمات التربية الخاصة SESSAD، والممارسة الحرة) يستقبل النفسي الحركي أطفالًا مشكلتهم المعلنة أكاديمية: خط غير مقروء، وبطء في النسخ، وخلط في اتجاهات الأحرف والأرقام، وتشتت انتباه، وفرط حركة. الحوصلة تكشف غالبًا طبقة جسدية تحت العرض المدرسي: جانبية غير مستقرة، أو مخطط جسدي ناقص، أو تنظيم مكاني-زماني هش، أو مهارات غرافوموتورية (graphomotricité) غير مؤسسة. التدخل هنا إعادة تربية موجهة تبني الطبقة الناقصة، ويقاس نجاحها في الصف لا في قاعة الجلسات وحدها. وكثير من متعلميك المصابين بالتوحد يعيشون هذا المجال يوميًا: اضطراب الحركة الدقيقة والكتابة عنده وحدتان كاملتان في دورتنا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مجالات تدخل النفسية الحركية اليوم — وموقع التوحد فيها", "points": ["الوساطة الجسدية مدخل علاجي حين لا تكفي الكلمة.", "صورة الجسد والانفعال قلب عمل هذا المجال.", "المختص عضو فريق لا معالج منفرد."], "text": {"head": "مجال الطب النفسي والصحة النفسية", "body": "<p>في أقسام الطب النفسي للطفل والراشد يعمل النفسي الحركي عضوًا في فريق علاجي، حيث تكون الوساطة الجسدية (médiation corporelle) مدخلًا حين تعجز الكلمة أو تسبقها: اضطرابات تصور الجسد وصورته، واضطرابات الانفعال وتنظيمه، وحالات الانسحاب أو الهياج التي يقرأها المختص في المقوّية والوضعية قبل أن تُقال. أدواته هنا الحوصلة والجلسات الفردية والجماعية بالوسائط الجسدية (ماء، إيقاع، استرخاء، لعب حركي)، وهدفه إعادة ربط المريض بجسده وبالآخر عبر تجربة جسدية آمنة. لهذا المجال صلة بدورتنا من بابين: صورة الجسم جزء من وحدة المخطط الجسدي عندنا، واضطراب المقوّية عند المصاب بالتوحد يُقرأ انفعاليًا كما تعلمت من فالون.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مجالات تدخل النفسية الحركية اليوم — وموقع التوحد فيها", "points": ["الشيخوخة: توازن وسقوط واستقلالية وظيفية.", "الإعاقة: مرافقة عبر العمر بمشاريع فردية.", "التخصص مهنة عمر كامل لا مرحلة طفولة فقط."], "text": {"head": "مجال الشيخوخة والإعاقة والرعاية الطويلة", "body": "<p>في مؤسسات إقامة المسنين (EHPAD) وبرامج مرافقة ألزهايمر — وقد وسّعت خطط ألزهايمر الفرنسية منذ 2008 حضور النفسيين الحركيين — يعمل التخصص على حفظ الاستقلالية الوظيفية: توازن ومشي آمن، ووقاية من السقوط، وتحفيز جسدي-معرفي يحفظ صورة جسد لم يعد يطيع صاحبه. وفي مؤسسات الإعاقة (Instituts Médico-Éducatifs, IME) ومؤسسات الراشدين، يرافق التخصص أصحاب الإعاقات الذهنية والحركية والتوحد عبر العمر كله، بمشاريع فردية تعيد بناء ما يمكن من استقلالية. الدرس المشترك بين المجالين: النفسية الحركية مهنة عمر كامل، من الرضيع إلى المسن، لأن علاقتنا بأجسادنا لا تتوقف عن التغير، واضطرابها في كل عمر باب تدخل.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مجالات تدخل النفسية الحركية اليوم — وموقع التوحد فيها", "points": ["التوحد حاضر في مجالات التخصص الخمسة كلها.", "لا بروفيل نفسي حركي واحد للتوحد.", "الدورة تبني قراءة فردية اضطرابًا اضطرابًا."], "text": {"head": "التوحد في هذه الخريطة — ولماذا هذه الدورة", "body": "<p>يتقاطع التوحد مع المجالات الخمسة كلها: علاماته الحركية قد تظهر في مجال الطفولة المبكرة قبل علاماته الاجتماعية أحيانًا، وملفه المدرسي مثقل بصعوبات نفسية حركية، ومرافقته المؤسسية والأسرية طويلة العمر. ومع ذلك يبقى التحذير الذي يحكم منظومتنا كلها قائمًا: لا يوجد بروفيل نفسي حركي واحد للتوحد؛ الخصوصيات الحركية عند أصحابه تتوزع على طيف واسع من السليم ظاهريًا إلى المضطرب بعمق، ومن مجال إلى آخر عند الشخص نفسه. لهذا بُنيت الدورة اضطرابًا اضطرابًا لا صورة نمطية واحدة: لتملك عينًا تقرأ هذا المتعلم بعينه، ومقوّيته ومخططه وتناسقه وقصديته، ثم تبني تدخلك على ما وجدت لا على ما توقعت. وهذا هو تعريف المختص المحترف في عقيدة أوسع كلها: يضع الاحتمالات كلها فوق الطاولة، ويقيّم، ثم يتدخل.</p><p>ولهذه الخريطة وجه عملي مباشر لمتعلمك الأول: الأهل؛ فأغلب أسئلتهم اليومية (لماذا لا يجلس؟ لماذا لا يكتب؟ من يرافقنا في البيت والمدرسة؟) تجد إجاباتها الموزعة على المجالات الخمسة لا عند مختص واحد، ووظيفتك أن ترشدهم إلى الباب الصحيح في الخريطة بدل أن تتركهم يدورون بين الأبواب.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا لا تكتفي هذه الدورة بباب واحد اسمه «النفسية الحركية في التوحد» داخل مجال الإعاقة؟", "الإجابة: لأن التوحد يتقاطع مع مجالات التخصص الخمسة كلها (كشف مبكر، مدرسة، صحة نفسية، مرافقة طويلة)، وبروفيلاته النفسية الحركية متعددة لا واحدًا، فاحتاج قراءة مستقلة اضطرابًا اضطرابًا."], "text": null, "take": "مجالات النفسية الحركية اليوم خمسة — طفولة مبكرة ووقاية، مدرسة وصعوبات تعلم، طب نفسي، شيخوخة، وإعاقة ومرافقة طويلة — والتوحد يتقاطع معها كلها، ولا بروفيل واحدًا له.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 6, "title": "التوحد يمسّ الجسد منذ البداية", "intro": "<p>تتعرف في هذا الدرس على الحقيقة التي تقوم عليها هذه الدورة كلها: الاضطرابات النفسية الحركية عند المصاب بالتوحد ليست آثارًا جانبية لحالته، بل جزء من بنية الاضطراب نفسه، تظهر مبكرًا، وأحيانًا قبل العلامات التي بُني عليها التشخيص الكلاسيكي. من أدرك هذا لم يعد يرى العمل النفسي الحركي خدمة مرافقة اختيارية، بل بابًا أصليًا من أبواب فهم المصاب بالتوحد والتدخل معه.</p>", "slides": [{"kind": "cover", "title": "التوحد يمسّ الجسد منذ البداية", "sub": "الوحدة الثانية: لماذا النفسية الحركية في التوحد؟", "goals": ["أن تشرح بأي معنى يمسّ التوحد الجسد منذ بداياته لا في مراحل متأخرة", "أن تسمّي أقدم العلامات الجسدية الموثقة في أدبيات التوحد", "أن تربط الاضطراب العلائقي بالجسد الحركي ربطًا علميًا منضبطًا"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l06.jpg", "img2": null}, {"kind": "slide", "title": "التوحد يمسّ الجسد منذ البداية", "points": ["التعريف التشخيصي يركز على التواصل والسلوك ويترك الجسد في الهامش.", "العلامات الحركية قد تسبق العلامات الكلاسيكية.", "الاضطراب الحركي جزء من بنية التوحد لا نتيجة ثانوية له."], "text": {"head": "صورة ناقصة — حين يُختزل التوحد في التواصل والسلوك", "body": "<p>تُعرّف الأدلة التشخيصية التوحد بمعيارين كبيرين: عجز في التواصل والتفاعل الاجتماعي، وسلوكيات واهتمامات مقيدة ومتكررة. هذا التعريف صحيح لكنه يلتقط نصف الصورة: فمنذ الأوصاف السريرية الأولى لاحظ الممارسون عند هؤلاء الأطفال مقوّية مضطربة ومشية خاصة وحركات نمطية وخرقًا حركيًا، لكنها بقيت في الهامش لأنها ليست معيار تشخيص. الدراسات اللاحقة أخرجتها من الهامش: الشذوذات الحركية عند المصابين بالتوحد قد تسبق العلامات الكلاسيكية الظاهرة، وليست مجرد نتيجة ثانوية لاضطراب معرفي؛ أي أن الجسد ليس مسرحًا متأخرًا للاضطراب بل أحد مواقعه الأولى.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التوحد يمسّ الجسد منذ البداية", "points": ["تأخر نفسي حركي مقاس يقارب خمسة أشهر (2001).", "نحو 40 بالمئة شذوذات حسية مرافقة (1990).", "شدة النمطيات ترتبط بشدة الاضطراب (2002)."], "text": {"head": "ماذا تقول البحوث — أرقام أولية", "body": "<p>قيست الفجوة النفسية الحركية رقميًا في دراسات متعددة: وجد هوك وديوي (Hauck et Dewey, 2001) تأخرًا نفسيًا حركيًا يقارب خمسة أشهر عند أطفال التوحد مقارنة بأقرانهم. وقدّر ريملاند (Rimland, 1990) أن نحو 40 بالمئة من المصابين بالتوحد يظهرون شذوذات حسية مؤثرة في أدائهم الحركي والانتباهي. وربط ميليتيرني (Militerni, 2002) شدة الحركات النمطية بشدة الاضطراب وبانخفاض المستوى المعرفي، فليست النمطية عادة عابرة بل علامة ذات دلالة. الأرقام ليست غاية الدرس؛ غايته أن تعرف أن ما ستلاحظه في جلساتك ظاهرة موثقة بالقياس، وأن اختلافها من متعلم لآخر هو موضوع الدرس الثالث من هذه الوحدة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التوحد يمسّ الجسد منذ البداية", "points": ["النمو عند المصاب بالتوحد غير متجانس بين المجالات.", "جزر كفاءة لا تلغي وديان العجز المجاورة.", "الخطة تُبنى على الأعمار النمائية لكل مجال لا على العمر الزمني."], "text": {"head": "نمو غير متجانس — جزر كفاءة ووديان عجز", "body": "<p>النمو النفسي الحركي عند المصاب بالتوحد لا يتأخر كتلة واحدة، بل يتفكك إيقاعه: مجالات تتقدم ومجالات تتخلف عند الطفل نفسه في الوقت نفسه، وهو ما يوصف بعدم تجانس النمو (dysharmonie développementale). تجد متعلمًا يركّب ألغازًا معقدة ويعجز عن رمي كرة نحو هدف، أو يحفظ تسلسلات طويلة ولا يستطيع تقليد حركة يدين بسيطة. هذا التفاوت ليس تفصيلًا وصفيًا؛ هو قاعدة عمل: ممنوع أن تستنتج من كفاءة مجال سلامة مجال آخر، وممنوع أن تبني خطة على عمر المتعلم الزمني بدل أعماره النمائية المختلفة من مجال لآخر، وهي أعمار تخرج بها الحوصلة مجالًا مجالًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التوحد يمسّ الجسد منذ البداية", "points": ["الكفاءات عند المصاب بالتوحد غير مستقرة عبر الزمن.", "فشل اليوم لا يلغي نجاح الأمس، والعكس صحيح.", "الاكتساب يُقاس بالثبات والتعميم لا بالنجاح الواحد."], "text": {"head": "أداء متقلب — الكفاءة التي تظهر وتختفي", "body": "<p>ظاهرة ثانية لا تقل أهمية وثّقها فيرنازا-مارتان (Vernazza-Martin, 2005): كفاءات المصاب بالتوحد غير مستقرة؛ ما نجح فيه اليوم قد يفشل فيه غدًا دون سبب ظاهر، والتكرار وحده لا يثبّتها كما عند غيره. أسباب التقلب متعددة وستفصّلها وحدة الآليات: حالة مقوّية وانفعالية متغيرة، وانتباه هش، واعتماد على التغذية الراجعة بدل الاستباق. النتيجة العملية مزدوجة: في التقييم، جلسة واحدة لا تكفي للحكم على كفاءة؛ وفي التدخل، نجاح واحد لا يعني اكتسابًا — الاكتساب يُقاس بالثبات عبر الجلسات والسياقات، وهو ما تنظّمه وحدة التدرج والتقييم المستمر في برنامجنا الكامل.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التوحد يمسّ الجسد منذ البداية", "points": ["الجسد موقع أصلي للاضطراب والتدخل معًا.", "الاستقلالية اليومية رهينة بالبناء النفسي الحركي.", "الوحدة تفصّل النظرة والاختلاف والإسهام تباعًا."], "text": {"head": "خلاصة الدرس — الجسد باب أصلي لا باب خلفي", "body": "<p>اجمع الخيوط الثلاثة: اضطراب حركي بنيوي ومبكر، ونمو غير متجانس، وأداء متقلب. نتيجتها أن العمل النفسي الحركي مع المصاب بالتوحد ليس تحسينًا تجميليًا لصورته الحركية، بل مدخل لفهم كيفية تنظيمه لجسده وفضائه وعلاقاته، ولبناء استقلاليته الفعلية: فالطفل الذي لا يضبط مقوّيته لا يجلس ليتعلم، والذي لا يبني مخططه الجسدي لا يكتب ولا يلبس وحده، والذي لا يستبق حركيًا لا يعبر شارعًا بأمان. لهذا تأتي النفسية الحركية في التوحد من الباب الأصلي، وبقية هذه الوحدة تفصّل كيف تنظر وأين تختلف وماذا تقدم.</p><p>وعند بعض ذوي الأداء الأعلى وصف غيلبرت (Gilbert, 1989) وهاليت (Hallett, 1993) مشية شبه باركنسونية بتردد في بدء الخطو وخطوات صغيرة بطيئة، وهي تذكير بأن الطيف يشمل أقصى الأداء كما يشمل أدناه، وأن العلامة الحركية لا ترتبط بانخفاض القدرات وحده بل باضطراب التنظيم العصبي للحركة في كل مستوياته.</p><p>ولأن العلامات قد تسبق الصورة الكلاسيكية، صار تقييم النمو النفسي الحركي في كثير من وحدات تشخيص التوحد جزءًا من بروتوكول التقييم الشامل نفسه، لا إضافة اختيارية تُطلب عند الحاجة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الظواهر الثلاث التي تلخص الصورة النفسية الحركية للتوحد في هذا الدرس؟", "الإجابة: اضطراب حركي بنيوي قد يسبق العلامات الكلاسيكية، ونمو غير متجانس بين المجالات (dysharmonie développementale)، وأداء متقلب غير مستقر عبر الجلسات."], "text": null, "take": "الاضطرابات النفسية الحركية عند المصاب بالتوحد بنيوية ومبكرة وغير متجانسة ومتقلبة، والعمل عليها باب أصلي في فهمه وبناء استقلاليته.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 7, "title": "ما الذي تبحث عنه عين النفسي الحركي عند المصاب بالتوحد", "intro": "<p>أطباء ومختصون كثيرون يرون المتعلم نفسه، وكل منهم يرى شيئًا مختلفًا لأن كلًا منهم يبحث عن شيء مختلف. في هذا الدرس تتعرف على موضوع بحث العين النفسية الحركية تحديدًا: طبقات القراءة الخمس التي يعبرها المختص وهو يلاحظ مصابًا بالتوحد، من المقوّية إلى القصد، ولماذا تتوقف قراءته عند احتمالات متعددة قبل أن تحسم — فالمحترف يضع الاحتمالات كلها فوق الطاولة ويقيّم.</p>", "slides": [{"kind": "cover", "title": "ما الذي تبحث عنه عين النفسي الحركي عند المصاب بالتوحد", "sub": "الوحدة الثانية: لماذا النفسية الحركية في التوحد؟", "goals": ["أن تصف ما تبحث عنه عين النفسي الحركي في أول لقاء بمتعلم توحد", "أن تميّز أسئلة الحوصلة النفسية الحركية عن أسئلة التقييمات الأخرى", "أن تحدّد بيانات اللقاء الأول التي تؤسس لخطة الفحص"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l07.jpg", "img2": null}, {"kind": "slide", "title": "ما الذي تبحث عنه عين النفسي الحركي عند المصاب بالتوحد", "points": ["سؤال النفسي الحركي: كيف يُنظَّم الجسد في الفضاء والزمان والعلاقة.", "قراءته تكمل قراءات الفريق ولا تنافسها.", "كثير من السلوكيات تبدأ اضطراب تنظيم جسدي."], "text": {"head": "نظرة مختلفة لنفس المتعلم", "body": "<p>طبيب الأعصاب يسأل عن سلامة الجهاز العصبي، والمربي يسأل عن الاكتساب المدرسي، والمحلل السلوكي يسأل عن وظيفة السلوك. النفسي الحركي يسأل سؤالًا رابعًا: كيف ينظّم هذا المتعلم جسده في الفضاء والزمان والعلاقة؟ كيف يقف ويجلس ويتحرك ويهدأ ويتوتر؟ سؤاله لا ينافس أسئلتهم بل يكملها، وموضعه الدقيق هو الجسر بين الجسد والسلوك: فكثير مما يُسجَّل سلوكًا (رفض، هياج، انسحاب) يبدأ اضطرابًا في تنظيم الجسد لم تقرأه العيون الأخرى. من هنا كانت أول مهارة في هذه الدورة كلها مهارة قراءة، لا مهارة أنشطة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "ما الذي تبحث عنه عين النفسي الحركي عند المصاب بالتوحد", "points": ["خمس طبقات: مقوّية ووضعية، حركة، تمثيل، حسية، قصد وعلاقة.", "اضطراب الطبقة السفلى يفسر أعراض الطبقات العليا.", "ترتيب الدورة يتبع ترتيب الطبقات نفسه."], "text": {"head": "طبقات القراءة الخمس", "body": "<p>تقرأ العين النفسية الحركية المتعلم في خمس طبقات متراكبة. الأولى المقوّية والوضعية: شدّه وارتخاؤه ووضعياته الغالبة وقاعدته الجسدية. الثانية الحركة المنفذة: تناسقها وتوازنها ودقتها وإيقاعها. الثالثة التمثيل: مخططه الجسدي وصورته عنه وتنظيمه للمكان والزمان. الرابعة الحسية: قنواته المفرطة والناقصة الاستجابة وكيف تلوّن كل ما سبق. الخامسة القصد والعلاقة: هل لحركته هدف، وكيف يدخل بها في تبادل مع الآخر. الترتيب ليس اعتباطيًا: كل طبقة عليا تُبنى على ما تحتها، واضطراب طبقة سفلى يفسّر أعراضًا في طبقات أعلى — وترتيب وحدات هذه الدورة نفسه يتبع هذه الطبقات.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "ما الذي تبحث عنه عين النفسي الحركي عند المصاب بالتوحد", "points": ["العرض الواحد يحتمل تفسيرات من طبقات مختلفة.", "الحسم بالتقييم لا بأول انطباع.", "لا نشاط قبل حسم الاحتمال الفعلي."], "text": {"head": "الاحتمالات كلها فوق الطاولة", "body": "<p>أمام عرض واحد — متعلم ينهض من كرسيه كل دقائق مثلًا — تقف احتمالات من طبقات مختلفة: مقوّية لا تثبت جلوسًا طويلًا، أو حس عميق يطلب ضغطًا وحركة، أو منعكس بدائي باقٍ يحرّك الجسد، أو سلوك هروب من مطلب، أو تخطيط حركي لا يعرف كيف يبقى. المختص المحترف لا يقفز إلى أول احتمال يعرفه؛ يضع الاحتمالات كلها فوق الطاولة، ثم يقيّم ليحسم أيها الفعلي عند هذا المتعلم. هذه هي عقيدة منظومة أوسع المؤسسة: لا وصفة بلا تقييم بروفيل، لأن النشاط الصحيح لاحتمال خاطئ لا يفيد، وقد يثبّت المشكلة التي جاء ليحلها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "ما الذي تبحث عنه عين النفسي الحركي عند المصاب بالتوحد", "points": ["ملاحظة حرة أولًا تُظهر الاستراتيجيات العفوية.", "مواقف مقننة تستثير كل طبقة على حدة.", "سؤال الأهل عن الجسد اليومي جزء من التقييم."], "text": {"head": "من الملاحظة الحرة إلى الحوصلة المقننة", "body": "<p>تبدأ القراءة بملاحظة حرة: المتعلم في لعبه وتنقله وتعامله العفوي، حيث تظهر استراتيجياته الحقيقية لا أداؤه المطلوب منه. ثم تنتقل إلى مواقف مقننة داخل الحوصلة (bilan psychomoteur) تُستثار فيها كل طبقة بمهمة مصممة لها، مع تعديلات تجعل الموقف ممكنًا لمصاب بالتوحد، وستفصّلها وحدة التعديلات في هذه الدورة. وبين الملاحظة والحوصلة يقف ملف المتعلم وسؤال أهله: هل يرونه ماهرًا أم أخرق؟ ما ألعابه المفضلة؟ فجواب الأهل عن الجسد اليومي مادة تقييم لا مجاملة افتتاحية. الناتج بروفيل (profil psychomoteur) موثق، لا انطباع جلسة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "ما الذي تبحث عنه عين النفسي الحركي عند المصاب بالتوحد", "points": ["رفض الكتابة قد يكون خمس مشكلات مختلفة.", "لكل احتمال فحصه وتدخله الخاص.", "القراءة بالطبقات تمنع التدخل الأعمى."], "text": {"head": "مثال تطبيقي — متعلم يرفض الجلوس للكتابة", "body": "<p>متعلم في السابعة يُدفع إلى كرسيه كل حصة ويُسجَّل «رافضًا للكتابة». بالطبقات الخمس: مقوّيته الخلفية منخفضة فينهار جذعه بعد دقائق ويتعب الجلوس نفسه؛ حسّه العميق ناقص فيطلب حركة ليحس بجسده؛ مخططه الجسدي لا يثبّت وضعية يد الكتابة فتتعب يده بسرعة؛ تخطيطه الحركي يفشل في تسلسل مسك القلم والبدء؛ وقصده من الرفض هروب من فشل متكرر صار يعرفه. خمسة احتمالات، ولكل منها فحصه داخل الحوصلة وتدخله المختلف تمامًا. من قفز إلى «عزّز جلوسه» عالج طبقة واحدة محتملة وترك الباقي — وهذا هو الفرق العملي كله بين قراءة نفسية حركية وسطحية.</p><p>وليس ترتيب الطبقات اختراعًا محليًا: جداول الحوصلة الكلاسيكية نفسها تنظم فحصها في الحقول ذاتها تقريبًا — مقوّية ووضعية وتوازن وتناسقات وحركة دقيقة ووعي بالجسد وتنظيم مكاني وزماني — فطبقات القراءة هي خريطة الحوصلة حين تُمارس على المصاب بالتوحد بخصوصياته الحسية والقصدية والعلائقية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا لا يكفي تفسير واحد جاهز لعرض مثل رفض الجلوس للكتابة؟", "الإجابة: لأن العرض الواحد قد ينتج عن طبقات مختلفة (مقوّية، حسية، مخطط جسدي، تخطيط، قصد)، ولكل طبقة تدخل مختلف؛ فلا يُحسم السبب إلا بتقييم الطبقات كلها."], "text": null, "take": "العين النفسية الحركية تقرأ خمس طبقات (مقوّية، حركة، تمثيل، حسية، قصد وعلاقة)، وتضع الاحتمالات كلها فوق الطاولة، ولا تحسم إلا بالتقييم.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 8, "title": "لا يوجد بروفيل نفسي حركي واحد للتوحد", "intro": "<p>أخطر خطأ ينتظر من يعمل مع المصابين بالتوحد أن يحمل في ذهنه صورة حركية نمطية واحدة ويسقطها على كل متعلم. في هذا الدرس تتعرف على أشكال التباين الثلاثة التي تهدم أي صورة نمطية: تباين بين الأفراد، وتباين داخل الفرد نفسه بين المجالات، وأداء متناقض يفشل في البسيط وينجح في المعقد. وستخرج بقاعدة الدورة العملية الأولى: قيّم هذا المتعلم، لا فئته.</p>", "slides": [{"kind": "cover", "title": "لا يوجد بروفيل نفسي حركي واحد للتوحد", "sub": "الوحدة الثانية: لماذا النفسية الحركية في التوحد؟", "goals": ["أن تفسّر لماذا لا يوجد بروفيل نفسي حركي واحد لطيف التوحد", "أن تصنّف أنماط البروفيلات الحركية المختلفة عند أصحاب التوحد", "أن تحذّر من أحكام الفئة الواحدة في تقاريرك وخططك"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l08.jpg", "img2": null}, {"kind": "slide", "title": "لا يوجد بروفيل نفسي حركي واحد للتوحد", "points": ["الأعمار النمائية النفسية الحركية متوزعة على مدى واسع.", "التشخيص وحده لا يتنبأ بالبروفيل الحركي.", "الخطة للبروفيل المقاس لا للفئة التشخيصية."], "text": {"head": "التباين بين الأفراد — طيف حقيقي لا شعار", "body": "<p>أعمار النمو النفسي الحركي عند المصابين بالتوحد، كما تخرج بها أدوات التقييم النمائي مثل البروفيل النفسي-التربوي (PEP-R) في الدراسات العيادية، أدنى من العمر الزمني عمومًا لكنها متوزعة على مدى واسع: من متعلم قريب من أقرانه في أغلب المجالات إلى متعلم بعمر نمائي دون ثلاث سنوات وهو في الخامسة. والفارق لا يفسره التشخيص وحده؛ يدخل فيه المستوى المعرفي وشدة الاضطراب والتاريخ الحسي والحركي لكل طفل. لهذا لا يصح أن تُبنى خطة «لأطفال التوحد»؛ تُبنى خطة لهذا المتعلم ببروفيله المقاس، وتشابه الخطط بين متعلمين نتيجة تشابه بروفيلات لا تشابه تشخيصات.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "لا يوجد بروفيل نفسي حركي واحد للتوحد", "points": ["البروفيل الفردي قمم وقيعان لا مستوى واحد.", "الدرجة الكلية تخفي المداخل والمخاطر معًا.", "العرض مجالًا مجالًا قاعدة في التقييم والتقارير."], "text": {"head": "التباين داخل الفرد — بروفيل ممزق لا خط مستقيم", "body": "<p>عند رسم بروفيل متعلم مصاب بالتوحد مجالًا مجالًا، نادرًا ما تحصل على خط أفقي متسق؛ تحصل على قمم وقيعان: تناسق عام جيد ومقوّية مضطربة، أو حركة دقيقة متقنة ومخطط جسدي ناقص، أو إيقاع محفوظ وتخطيط منهار. هذا التمزق هو التعبير العيادي لعدم تجانس النمو الذي مرّ في الدرس الأول، وهو ما يجعل التقارير من نوع «مستواه النفسي الحركي متوسط» عديمة القيمة عمليًا: المتوسط يخفي القمة التي تُستثمر مدخلًا والوادي الذي يحتاج بناء. لهذا تُعرض بروفيلات دورتنا مجالًا مجالًا دائمًا، ولا يُختصر متعلم في درجة كلية واحدة أبدًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "لا يوجد بروفيل نفسي حركي واحد للتوحد", "points": ["الفشل في البسيط والنجاح في المعقد ظاهرة موثقة.", "مقاس الصعوبة الفعلي: وضوح الهدف والقصد لا الهندسة.", "مهمة واحدة لا تكفي حكمًا على كفاءة."], "text": {"head": "الحركيات المتناقضة — يفشل في البسيط وينجح في المعقد", "body": "<p>وثّق ليري وهيل (Leary et Hill) ظاهرة تربك كل مقيّم متعجل: حركيات متناقضة (kinésies paradoxales) يفشل فيها المصاب بالتوحد في حركة بسيطة وينجح في حركة أعقد منها ظاهريًا. متعلم لا يقفز بقدمين من نقطة لأخرى قد يتسلق بنية لعب معقدة ببراعة؛ وآخر لا يقلّد إيماءة يد بسيطة وينفذ تسلسل بناء طويلًا من ذاكرته. التفسير الذي ستفصّله وحدة الآليات: البساطة والتعقيد عندنا مقاس هندسي، أما عند الجهاز العصبي فالمقاس هو وضوح الهدف والقصد وقنوات الإحساس المستعملة؛ فالحركة «البسيطة» المجردة من سياق وهدف هي الأصعب عليه، والحركة المركبة ذات المعنى قد تكون أيسر. من حكم من مهمة واحدة ظلم متعلمه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "لا يوجد بروفيل نفسي حركي واحد للتوحد", "points": ["الأداء يتقلب بحسب الحالة المقوّية والانفعالية والحسية.", "الحكم الكبير يحتاج أكثر من لقاء واحد.", "كل قياس يُوثَّق مع سياقه."], "text": {"head": "تقلّب الأداء عبر الزمن — جلسة واحدة لا تحسم", "body": "<p>أضف إلى التمزق المكاني تمزقًا زمانيًا: أداء المتعلم نفسه يتغير من جلسة لأخرى ومن ساعة لأخرى بتغير حالته المقوّية والانفعالية والحسية، وقد بيّن فيرنازا-مارتان (Vernazza-Martin, 2005) أن الكفاءات هنا غير مستقرة بنيويًا. النتائج العملية ثلاث: تقييم يمتد على أكثر من لقاء كلما أمكن قبل الحسم في القضايا الكبرى؛ وحذر من قراءة يوم سيئ بوصفه تراجعًا ومن يوم جيد بوصفه اكتسابًا؛ وتوثيق للسياق مع كل قياس (نوم، حالة انفعالية، بيئة) لأن القياس بلا سياقه رقم أعمى. وهذه القاعدة ستعود بتفصيلها الإجرائي في وحدة التعديلات: تدريج مزدوج وتفسير مقيّد بالسياق.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "لا يوجد بروفيل نفسي حركي واحد للتوحد", "points": ["كل ملف يبدأ من صفر معرفي.", "الفرضيات من ملاحظة الفرد وتُختبر بالحوصلة.", "التقرير بلغة الفرد ومجالاته لا بلغة الفئة."], "text": {"head": "القاعدة العملية — قيّم هذا المتعلم لا فئته", "body": "<p>مجموع هذا الدرس قاعدة واحدة تصلح شعارًا للدورة: لا يوجد بروفيل نفسي حركي واحد للتوحد، فلا تستعير بروفيلًا من كتاب ولا من متعلم سابق. عمليًا يعني هذا ثلاث ممارسات: ابدأ كل ملف من صفر معرفي مهما كثرت خبرتك بالفئة؛ وابنِ فرضياتك من ملاحظة هذا المتعلم ثم اختبرها في الحوصلة؛ واكتب تقريرك بلغة هذا المتعلم ومجالاته لا بلغة التوحد العام. المختص الذي يحمل صورة نمطية يرى ما يتوقعه ويعمى عما أمامه، والمختص الذي يقيّم فردًا فردًا يكتشف في كل ملف خريطة جديدة — وهذا هو الفرق بين ممارسة تُراكم سنوات وممارسة تُراكم متعلمين.</p><p>وفي تقارير وحدات تقييم التوحد العيادية تظهر أعمار نمائية نفسية حركية دون ثلاث سنوات عند أطفال في الخامسة على مقاييس نمو مثل غريفيث (Griffiths)، بينما يقترب آخرون في العمر نفسه من أقرانهم في أغلب المجالات — مدى واسع لا يفسره اسم التشخيص الواحد، ويفسره تفاعل المستوى المعرفي وشدة الاضطراب والتاريخ الحسي والحركي لكل طفل.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الحركيات المتناقضة (kinésies paradoxales)؟", "الإجابة: ظاهرة موثقة يفشل فيها المصاب بالتوحد في حركة بسيطة ظاهريًا وينجح في أعقد منها، لأن مقاس الصعوبة الفعلي عنده وضوح الهدف والقصد وقنوات الإحساس، لا التعقيد الهندسي للحركة."], "text": null, "take": "التباين بين الأفراد، وتمزق البروفيل داخل الفرد، وتناقض الأداء وتقلبه — أربعة أسباب تجعل القاعدة: قيّم هذا المتعلم، لا فئته.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 9, "title": "ما الذي تقدمه النفسية الحركية للمصاب بالتوحد ولا يقدمه غيرها", "intro": "<p>في فريق متعدد التخصصات، على كل تخصص أن يعرف إسهامه الخاص الذي لا يقوم به غيره، وحدوده الصادقة التي يقف عندها. في هذا الدرس تتعرف على الإسهامات الأربعة الخاصة للنفسية الحركية مع المصاب بالتوحد: الوساطة الجسدية، وحلقة التقييم والمشروع، وحرفة التعديلات، ومعرفة الجسد اليومي — ثم على الحدّين اللذين تعترف بهما المهنة لنفسها بصراحة علمية.</p>", "slides": [{"kind": "cover", "title": "ما الذي تقدمه النفسية الحركية للمصاب بالتوحد ولا يقدمه غيرها", "sub": "الوحدة الثانية: لماذا النفسية الحركية في التوحد؟", "goals": ["أن تشرح الإضافة النوعية للنفسية الحركية في منظومة دعم التوحد", "أن تميّز مساهمتها عن مساهمات العلاج الوظيفي والنطق والسلوك", "أن تصوغ بلغة مهنية ما لا يقدمه غيرها لفريق المتعلم وأهله"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l09.jpg", "img2": null}, {"kind": "slide", "title": "ما الذي تقدمه النفسية الحركية للمصاب بالتوحد ولا يقدمه غيرها", "points": ["الوساطة الجسدية قناة علاقة بلا اشتراط لغة.", "الجسد المشترك يبني الثقة والقصد والتبادل.", "مدخل فعال مع الحالات الأشد اضطرابًا."], "text": {"head": "الوساطة الجسدية — علاج حين لا تكفي الكلمة", "body": "<p>كثير من المصابين بالتوحد يصعب بلوغهم بالكلام: غير متكلمين، أو كلامهم لا يحمل انفعالهم، أو الكلمة عندهم محفز إضافي. الوساطة الجسدية (médiation corporelle) هي إسهام النفسية الحركية الأول: العمل عبر نشاط جسدي مشترك (كرة، ماء، إيقاع، توازن، استرخاء) يصير فيه الجسد قناة علاقة وتواصل وتعلم، بلا اشتراط لغة أولًا. في الوساطة تُقرأ المقوّية وتُبنى الثقة ويُستدرج القصد والتقليد والتبادل، بالترتيب الذي يسمح به جسد المتعلم لا بترتيب برنامج لفظي. وهذا الإسهام هو ما يجعل النفسي الحركي عضو الفريق الذي يستطيع البدء مع المتعلمين الأشد اضطرابًا، حيث تقف المداخل اللفظية عند الباب.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "ما الذي تقدمه النفسية الحركية للمصاب بالتوحد ولا يقدمه غيرها", "points": ["حوصلة ثم بروفيل ثم مشروع ثم إعادة قياس.", "كل نشاط مربوط بهدف ومؤشر نجاح.", "لغة مهنية واحدة عبر منظومة التقييم والتدخل."], "text": {"head": "حلقة كاملة — من الحوصلة إلى المشروع إلى القياس", "body": "<p>الإسهام الثاني منهجي: النفسية الحركية لا تقدم أنشطة متناثرة بل حلقة مغلقة: حوصلة موثقة تستخرج بروفيلًا مجالًا مجالًا، ثم مشروع تدخل فردي بأهداف مشتقة من البروفيل وأولويات مرجحة، ثم تنفيذ بمستويات مساعدة معروفة، ثم إعادة قياس تقرر الاستمرار أو التعديل. قيمة الحلقة أنها تجعل كل نشاط قابلًا للمحاسبة: لماذا هذا النشاط، لأي مجال، وبأي مؤشر سنعرف أنه نجح؟ وفي منظومة أوسع تُبنى الحلقة نفسها في أداة البروفيل الحسي وخططها وفي الدورات، فتتكلم المنظومة لغة مهنية واحدة من التقييم إلى التقرير.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "ما الذي تقدمه النفسية الحركية للمصاب بالتوحد ولا يقدمه غيرها", "points": ["التعديلات تقنيات مهنية لا ارتجال.", "تُظهر كفاءة المتعلم بدل اضطرابه فقط.", "لها وحدة كاملة في هذه الدورة."], "text": {"head": "حرفة التعديلات — جعل التقييم والتعلم ممكنين", "body": "<p>إسهام ثالث لا يظهر في قوائم الخدمات لكنه يقرر نجاحها: النفسي الحركي صانع تعديلات (aménagements). يعرف كيف يهيئ فضاء يقلل الحمل الحسي، وينظم زمان الجلسة بصريًا، ويبسّط تعليمة دون أن يفرّغها، ويقدّم توجيهًا جسديًا متدرجًا، ويحترم زمن كمون متعلمه قبل أن يحكم عليه بالعجز. هذه الحرفة، الموثقة بالتفصيل في أدبيات تقييم التوحد، هي الفرق بين موقف يُظهر كفاءة المتعلم وموقف يُظهر اضطرابه فقط. وحدة كاملة في آخر هذه الدورة مخصصة لها، لأنها ليست حسن نية بل تقنيات لها أسماء وقواعد وحدود.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "ما الذي تقدمه النفسية الحركية للمصاب بالتوحد ولا يقدمه غيرها", "points": ["الجسد اليومي ميدان التخصص الأكبر.", "سؤال الأهل عن الأداء اليومي جزء من الحوصلة.", "النقل إلى الروتينات معيار نجاح التدخل."], "text": {"head": "معرفة الجسد اليومي — ما لا تراه العيادات", "body": "<p>المتعلم يعيش جسده في البيت والمدرسة أكثر مما يعيشه في الجلسات، والنفسي الحركي هو مختص هذا الجسد اليومي: كيف ينام ويأكل ويلبس ويتنقل ويلعب ويهدأ. لذلك تتضمن الحوصلة النفسية الحركية سؤال الأهل المنهجي عن الأداء الجسدي اليومي، وتتضمن خططها نقل المكاسب إلى الروتينات الحقيقية، لا الاكتفاء بأداء القاعة. وهذا الإسهام يفسر موضع النفسية الحركية في منظومتنا بين المدرسة المنزلية وأداة البروفيل: فالبيت هو ميدان التدخل الأكبر، والولي شريك ملاحظة وتنفيذ، لا متفرج ينتظر تقريرًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "ما الذي تقدمه النفسية الحركية للمصاب بالتوحد ولا يقدمه غيرها", "points": ["لا أدوات مقننة خاصة بالتوحد بعد — تفسير حذر ومصرّح به.", "التشخيص النفسي الحركي وظيفي لا طبي.", "معرفة الحدود شرط الثقة المهنية."], "text": {"head": "حدود صادقة — ما لا تدّعيه المهنة", "body": "<p>أخيرًا حدّان تعترف بهما النفسية الحركية علميًا ويزيدانها قوة. الأول: لا توجد حتى اليوم اختبارات نفسية حركية مقننة مصممة خصيصًا للمصابين بالتوحد؛ نعمل بأدوات عامة معدّلة، فنفسّر نتائجها بحذر وبتدريج مزدوج أحيانًا، ونصرّح بذلك في تقاريرنا بدل ادعاء دقة غير موجودة. الثاني: النفسية الحركية لا تشخّص التوحد ولا تستبدل أعضاء الفريق؛ تشخيصها وظيفي (بروفيل ومشروع) داخل تشخيص شامل يقوده الطبيب مع الفريق. مختص يعرف حدوده يُوثق به داخل الحدود، ومن ادعى الكل خسر الكل.</p><p>وقد لخّصت أدبيات التقييم أهداف الحوصلة عند المصاب بالتوحد في ثلاث: استخراج بروفيل نفسي حركي دقيق مجالًا مجالًا، وتحديد محاور تدخل مرتبة بالأولوية، وتوثيق نقاط القوة والمثبطات والاستراتيجيات التي يتعلم بها هذا المتعلم تحديدًا، لتكون الحوصلة وثيقة عمل لكل من سيرافقه بعده — فالحوصلة الجيدة تخدم الفريق كله لا صاحبها فقط، وتختصر على الجميع شهورًا من التجريب.</p><p>وفي فرنسا حضرت النفسية الحركية في الاستراتيجية الوطنية للتوحد ضمن مهن التقييم والمرافقة في الفريق المتعدد، وهو اعتراف مؤسسي بأن البروفيل النفسي الحركي وثيقة لازمة في ملف المصاب بالتوحد لا ترفًا تخصصيًا يُستغنى عنه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الحدّان اللذان تعترف بهما النفسية الحركية في عملها مع التوحد؟", "الإجابة: غياب اختبارات مقننة مصممة خصيصًا لهذه الفئة (فيُفسَّر النتائج بحذر مصرّح به)، وأن تشخيصها وظيفي (بروفيل ومشروع) لا يحل محل التشخيص الطبي الشامل ولا أعضاء الفريق."], "text": null, "take": "إسهام النفسية الحركية الخاص: وساطة جسدية تبلغ من لا تبلغه الكلمة، وحلقة تقييم ومشروع وقياس، وحرفة تعديلات تُظهر الكفاءة، ومعرفة بالجسد اليومي — وحدّاها معلنان ومحترمان.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 10, "title": "قراءة العلامات المبكرة — ما تعد به وما لا تعد", "intro": "<p>في هذا الدرس تتعرف على طبيعة العلامات الحركية المبكرة للتوحد: من أين جاءت معرفتنا بها، ولماذا تظهر الحركة أحيانًا قبل الكلام والتواصل في قصة الاضطراب، وما القواعد الأربع التي تحكم استعمالها حتى لا تتحول أداة كشف نافعة إلى مصدر تهويل أو تطمين كاذب.</p>", "slides": [{"kind": "cover", "title": "قراءة العلامات المبكرة — ما تعد به وما لا تعد", "sub": "الوحدة الثالثة: العلامات الحركية المبكرة 0-24 شهرًا", "goals": ["أن تشرح ما تعد به قراءة العلامات المبكرة وما لا تعد به", "أن تميّز الاشتباه البحثي الوظيفي عن التشخيص القاطع", "أن تطبق قواعد تسمية «لا يحدث» و«حدث ثم توقف» في أي بند مبكر"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l10.jpg", "img2": null}, {"kind": "slide", "title": "قراءة العلامات المبكرة — ما تعد به وما لا تعد", "points": ["الجهاز الحركي أول الأنظمة نضجًا فيظهر عليه الاضطراب مبكرًا.", "علامات حركية موثقة في السنة الأولى.", "الكشف الحركي يكمل كشف التواصل لا يستبدله."], "text": {"head": "لماذا قد تتكلم الحركة أولًا", "body": "<p>التوحد اضطراب نمو عصبي يبدأ قبل أن تظهر صورته الاجتماعية الكاملة؛ والجهاز الحركي يعمل منذ الحياة الجنينية ويُبنى في الشهور الأولى بسرعة لا يضاهيها أي نظام آخر، فمن الطبيعي أن تنعكس الاضطرابات الأولى عليه مبكرًا. تقليديًا كان الكشف يدور على علامات التواصل (لا مناداة بالاسم، لا إشارة، تأخر كلام)، لكن دراسات النمو المبكر بيّنت أن انحرافات المقوّية والوضعية والحركة قد تكون حاضرة في السنة الأولى نفسها، أحيانًا قبل أن يستطيع أحد ملاحظة فرق اجتماعي واضح. قراءة هذه العلامات لا تستبدل الكشف التواصلي؛ تضيف إليه قناة أبكر زمنيًا، وهي قناة اختصاصنا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "قراءة العلامات المبكرة — ما تعد به وما لا تعد", "points": ["طريقان: تحليل فيديو استرجاعي ومتابعة أتراب استقبالية.", "الاتفاق على المحاور الكبرى أقوى من الاتفاق على التفاصيل.", "العلامات تُرتَّب بقوة المؤشر لا تُعرض متساوية."], "text": {"head": "من أين نعرف — أفلام عائلية ودراسات الأتراب", "body": "<p>معرفتنا بالعلامات المبكرة جاءت من طريقين منهجيين يجب أن تعرفهما لتحكم على قوة كل علامة. الأول استرجاعي: تحليل أشرطة فيديو عائلية صُوّرت قبل التشخيص بسنوات، كما في أعمال تيتلباوم (Teitelbaum, 1998) التي حللت حركات رضّع شُخّصوا لاحقًا بالتوحد، ودراسات بارانيك (Baranek, 2003) على أطفال في 9-12 شهرًا. والثاني استقبالي: متابعة رضّع معرضين (إخوة مصابين) وقياس انحرافاتهم قبل أي تشخيص. الطريقان يتفقان على المحاور الكبرى (مقوّية، وضعيات، استكشاف) ويختلفان في التفاصيل، ولهذا تُعرض العلامات في هذه الوحدة مرتبة بقوة مؤشراتها لا قائمة مسطحة متساوية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "قراءة العلامات المبكرة — ما تعد به وما لا تعد", "points": ["العلامة مؤشر اشتباه لا تشخيص أبدًا.", "لا علامة خاصة بالتوحد وحده.", "القوة في التجمع والاستمرار عبر المجالات والأشهر."], "text": {"head": "القاعدة الأولى والثانية — اشتباه لا تشخيص، وتجميع لا إفراد", "body": "<p>القاعدة الأولى: لا توجد علامة حركية واحدة خاصة بالتوحد وحده؛ الانحرافات نفسها قد تظهر في تأخر نمو عام أو اضطرابات عصبية أخرى أو لا تعني شيئًا عابرًا. العلامة المبكرة إذن مؤشر اشتباه (signe d'alerte) يستدعي تقييمًا شاملًا، ولا يجوز أن تتحول في فم المختص أو الولي إلى تشخيص. القاعدة الثانية: قيمة العلامة في تجمعها وتزامنها واستمرارها؛ علامة عابرة وحيدة ضعيفة الدلالة، أما نمط متكرر عبر مجالات (مقوّية ووضعية واستكشاف) ومستمر عبر أشهر فمؤشر قوي. لهذا تُبنى دروس الوحدة مراحل زمنية تراكمية: لتلاحظ النمط وهو يتشكل، لا لتطارد علامات مفردة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "قراءة العلامات المبكرة — ما تعد به وما لا تعد", "points": ["التوثيق المعاصر بالفيديو أقوى من الذاكرة الرجعية.", "الكشف باب دعم مبكر لا حكم مستقبلي.", "لا تهويل ولا تطمين كاذب — ملاحظة وتحويل ومتابعة."], "text": {"head": "القاعدة الثالثة والرابعة — التوثيق قبل الحكم، والحديث المسؤول", "body": "<p>القاعدة الثالثة: ما لا يُوثَّق لا يُبنى عليه؛ الانطباع الرجعي للأهل بعد التشخيص مشوّش بالمعرفة اللاحقة، ولهذا تعتمد القراءة الجادة على فيديو منزلي معاصر أو ملاحظة موثقة بالتاريخ. والمختص الذكي يعلّم الأهل مبكرًا توثيق ما يقلقهم بالتصوير بدل وصفه من الذاكرة بعد سنوات. القاعدة الرابعة أخلاقية: الكشف المبكر يُقدَّم للأسرة بوصفه باب تقييم يفتح دعمًا مبكرًا، لا حكمًا على مستقبل طفلهم؛ فالتدخل المبكر المبني على تقييم صحيح يغيّر مسارات كثيرة، أما التهويل فيشّل الأسرة والتطمين الكاذب يسرق منها زمنًا لا يعوّض. وبين الحدين يقف كلام المختص الدقيق: نلاحظ، نوثق، نحوّل للتقييم، ونتابع.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "قراءة العلامات المبكرة — ما تعد به وما لا تعد", "points": ["ثلاث مراحل: مقوّية ووضعيات، ثم استكشاف وقبضات، ثم مشية وقصد.", "لكل علامة آليتها لا وصفها فقط.", "كل درس ينتهي بسلوك مهني: لاحظ، وثّق، حوّل."], "text": {"head": "خريطة الوحدة — ثلاث مراحل زمنية", "body": "<p>تنظم الدروس الثلاثة القادمة العلامات في ثلاث مراحل: من الولادة إلى 6 أشهر حيث تسود المقوّية والوضعيات والمنعكسات؛ ومن 6 إلى 12 شهرًا حيث تظهر الوضعيات الاستباقية والزحف والاستكشاف وقبضة الكماشة؛ ومن 12 إلى 24 شهرًا حيث تتكلم المشية والتنقل والقصد. في كل مرحلة ستجد العلامات مرتبة من الأقوى مؤشرًا، ولكل علامة معناها الآلي (لماذا تحدث)، لأن العلامة بلا آلية تُحفظ وتُنسى، وبآليتها تُقرأ وتُستعمل. وستجد في آخر كل درس السلوك المهني المطلوب أمام المرحلة: ماذا نلاحظ، وكيف نوثق، ومتى نحوّل.</p><p>وقد جمع جوهيل (Juhel, 2003) في جداول تلخيصية علامات المراحل الثلاث (0-6 و6-12 و12-24 شهرًا) في صورة واحدة ما زالت مرجعًا عمليًا لتنظيم الملاحظة المبكرة في أدبيات التوحد الفرنسية، وتُقرأ علامات كل مرحلة فيها مرتبة بقوة مؤشراتها الموثقة لا بترتيب اكتشافها.</p><p>وتذكّر دائمًا أن أغلب هذه العلامات اكتُشف بأثر رجعي عند أطفال شُخّصوا أصلًا؛ فهي خريطة اشتباه تُرشد ملاحظتك المقبلة، لا شبكة صيد تُطبَّق بقلق على كل رضيع يمر بك.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا لا تكفي علامة حركية واحدة مبكرة للحكم بوجود توحد؟", "الإجابة: لأن لا علامة خاصة بالتوحد وحده، فقد تظهر في اضطرابات أخرى أو عابرة؛ قيمتها في تجمعها عبر المجالات واستمرارها عبر الزمن، ووظيفتها استدعاء تقييم شامل لا إصدار تشخيص."], "text": null, "take": "العلامات الحركية المبكرة مؤشرات اشتباه تُقرأ مجمعة وموثقة ومسؤولة، تفتح باب تقييم مبكر ولا تلفظ تشخيصًا.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 11, "title": "من الولادة إلى 6 أشهر — المقوّية والوضعيات والمنعكسات", "intro": "<p>في الشهور الستة الأولى لا يملك الرضيع حركة إرادية يُختبر بها؛ مادته النفسية الحركية كلها في مقوّيته ووضعياته ومنعكساته وجودة تبادله الجسدي مع حامله. في هذا الدرس تتعرف على أربع علامات كبرى لهذه المرحلة وآلية كل منها: غياب الوضعية الاستباقية عند الحمل، واضطراب المقوّية بنقصها أو فرطها، واستمرار منعكس الإمساك بعد أجله، وتأخر ضبط الرأس — مرتبة كما تظهر في الملاحظة العيادية والمنزلية.</p>", "slides": [{"kind": "cover", "title": "من الولادة إلى 6 أشهر — المقوّية والوضعيات والمنعكسات", "sub": "الوحدة الثالثة: العلامات الحركية المبكرة 0-24 شهرًا", "goals": ["أن تسمّي علامات المقوّية والوضعيات والمنعكسات في الأشهر الستة الأولى", "أن تفسّر معنى غياب الوضعية الاستباقية واستمرار الإمساك الانعكاسي", "أن تقرأ جدول العلامات بمراحله قراءة اشتباه مرتبة لا أحكامًا"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l11.jpg", "img2": null}, {"kind": "slide", "title": "من الولادة إلى 6 أشهر — المقوّية والوضعيات والمنعكسات", "points": ["الوضعية الاستباقية: تهيؤ جسد الرضيع للحمل وتكيّفه مع حامله.", "غيابها علامة حركية وعلائقية مزدوجة.", "هي الصورة الأولى لآلية الاستباق الوضعي كلها."], "text": {"head": "غياب الوضعية الاستباقية عند الحمل", "body": "<p>الرضيع السليم النمو، حين يُرفع ويُحمل، يهيئ جسده للحمل قبل أن يستقر فيه: يلتصق، يوزع مقوّيته، ويتكيف مع جسد حامله في ما يسمى الوضعية الاستباقية (posture anticipatrice). عند رضّع سيظهر عندهم التوحد لاحقًا، وثّقت الملاحظات غياب هذا التهيؤ: جسد لا يتشكل على حامله، يُحمل كأنه قطعة لا شريك جسدي. الآلية عميقة: الاستباق الوضعي هو أول صورة للتعديلات الوضعية الاستباقية (ajustements posturaux anticipatoires) التي سترافق الدورة كلها، وهو في الوقت نفسه أول حوار مقوّي مع الآخر بمفهوم فالون؛ فغيابه علامة مزدوجة: حركية وعلائقية في واحدة، ولهذا يتصدّر علامات المرحلة الأولى.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من الولادة إلى 6 أشهر — المقوّية والوضعيات والمنعكسات", "points": ["نقص مقوّية أو فرطها، وقد يتبدلان عند الرضيع نفسه.", "المقوّية المضطربة تبطئ كل بناء وضعي لاحق.", "الترتيب واحد في العلامات والاضطرابات: المقوّية أولًا."], "text": {"head": "اضطراب المقوّية — نقص يغلب أو فرط يتبدل", "body": "<p>ثاني علامات المرحلة اضطراب المقوّية (trouble du tonus) في صورتيه: نقص مقوّية غالب (hypotonie) يظهر رضيعًا رخوًا يتأخر تثبيت رأسه ويسيل جسده من ذراعي حامله، أو فرط مقوّية (hypertonie) بتصلب وانثناءات غالبة ومقاومة للحمل والتغيير. والأدق عياديًا أن الصورتين قد تتبدلان عند الرضيع نفسه بحسب السياق والحالة، وهو النمط الذي سيستمر في أعمار لاحقة تحت اسم تذبذب المقوّية. الآلية: المقوّية قاعدة ما بعدها؛ رضيع لا يضبط قاعدته سيتأخر في الجلوس والاستكشاف وكل بناء وضعي لاحق، ولهذا كانت المقوّية أول وحدات الاضطرابات في هذه الدورة كما كانت أول علاماتها هنا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من الولادة إلى 6 أشهر — المقوّية والوضعيات والمنعكسات", "points": ["منعكس الإمساك يندمج طبيعيًا نحو 3.5 شهر.", "استمراره يعيق انتقال اليد إلى الإمساك الإرادي والاستكشاف.", "المنعكسات الباقية احتمال دائم في تقييمات المنظومة."], "text": {"head": "منعكس الإمساك الذي لا يرحل في أجله", "body": "<p>يولد الرضيع بمنعكس إمساك (réflexe d'agrippement) قوي يغلق يده على ما يلامس راحته، ويفترض أن يندمج ويختفي تدريجيًا نحو الشهر الثالث والنصف ليحل محله الإمساك الإرادي. استمرار المنعكس طاغيًا بعد هذا الأجل علامة موثقة في المرحلة الأولى. آليتها أن بقاء المنعكسات البدائية يعيق انتقال اليد من الانعكاس إلى القصد: يد مشغولة بالإغلاق التلقائي لا تتفرغ للاستكشاف والمعالجة التي ستبني الحركة الدقيقة والمخطط الجسدي. تذكّر هذه العلامة جيدًا؛ ستقابل عائلتها الكاملة في منظومة أوسع حين تصل إلى كشف المنعكسات الباقية ووحدة قراءتها، فالمنعكس الباقي احتمال دائم على طاولة التقييم عندنا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من الولادة إلى 6 أشهر — المقوّية والوضعيات والمنعكسات", "points": ["ضبط الرأس المتأخر يرافق اضطراب المقوّية ويتغذى منه.", "الرأس بوابة النظر، والنظر وقود القصد والاستكشاف.", "العلامات تُقرأ حلقات مترابطة لا بنودًا منفصلة."], "text": {"head": "تأخر ضبط الرأس وضعف الانتباه البصري", "body": "<p>يُنتظر من رضيع الأشهر الأولى أن يرفع رأسه ويثبته تدريجيًا وهو على بطنه أو محمولًا؛ تأخر هذا الضبط مع رخاوة المحور علامة ترافق اضطراب المقوّية غالبًا وتتغذى منه. ويرافق الصورة عند كثير من هؤلاء الرضّع انتباه بصري ضعيف: تتبع بصري قصير للوجوه والأشياء، واهتمام منخفض بالمثيرات الاجتماعية البصرية مقارنة بالمثيرات الشيئية. الآلية المشتركة أن الرأس بوابة الحواس البعيدة: من لا يثبّت رأسه لا يثبّت نظره، ومن لا يثبّت نظره يفوته الوقود البصري الذي يبني القصد والاستكشاف في المرحلة التالية. لا تُقرأ العلامة وحدها إذن؛ تُقرأ حلقة: مقوّية، رأس، نظر، قصد.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من الولادة إلى 6 أشهر — المقوّية والوضعيات والمنعكسات", "points": ["الملاحظة في المواقف الطبيعية والتوثيق بالفيديو.", "التحويل المبكر لتقييم نمائي شامل.", "خطة دعم فورية دون انتظار اسم نهائي."], "text": {"head": "السلوك المهني أمام المرحلة الأولى", "body": "<p>أمام رضيع تُشتبه علاماته: لاحظ الحمل نفسه (هل يتشكّل على حامله؟)، وجسّ المقوّية في الحمل والتهدئة لا في موقف فحص قسري، وسجّل المنعكسات وآجالها بدقة، ووثّق بالفيديو المنزلي القصير في مواقف طبيعية (حمل، رضاعة، لعب على البطن). ثم حوّل إلى تقييم نمائي شامل مبكرًا، لأن نافذة التدخل المبكر أثمن ما في هذه المرحلة كلها: كل شهر مبكر يُبنى فيه أساس وضعي وحسي يوفر أشهرًا من العمل اللاحق. ولا تُلقِ على الأهل اسم اضطراب؛ ألقِ عليهم خطة: نقيّم الآن، ونتابع، ونبدأ الدعم الذي لا يحتاج انتظار تشخيص نهائي.</p><p>كما وُثّق عند بعض هؤلاء الرضّع نفور مبكر من التلامس الجسدي غير المتوقع وصعوبات في تنظيم حالات اليقظة والنوم والتهدئة، وهي بذور بروفيل حسي لم يكتمل تشكّله بعد، سيتكلم بصوت أعلى في المرحلتين التاليتين حين يبدأ الاستكشاف والتنقل وتتضاعف المدخلات المطلوب تنظيمها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الوضعية الاستباقية (posture anticipatrice) ولماذا يعدّ غيابها علامة مزدوجة؟", "الإجابة: هي تهيؤ جسد الرضيع وتكيّفه مع جسد حامله عند رفعه وحمله؛ وغيابها مزدوج لأنه علامة على اضطراب التعديلات الوضعية الاستباقية حركيًا، وعلى اضطراب الحوار المقوّي مع الآخر علائقيًا في الوقت نفسه."], "text": null, "take": "في 0-6 أشهر تتكلم المقوّية والوضعيات والمنعكسات: غياب وضعية استباقية، مقوّية مضطربة، إمساك باقٍ، وضبط رأس متأخر — نمط يُوثَّق ويُحوَّل مبكرًا.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 12, "title": "من 6 إلى 12 شهرًا — الجلوس والزحف والاستكشاف والقبضات", "intro": "<p>في النصف الثاني من السنة الأولى يتحول الرضيع من محمول إلى فاعل: يجلس، يزحف، يستكشف بيديه وفمه، ويبني قبضاته الدقيقة. في هذا الدرس تتعرف على علامات هذه المرحلة الأربع الكبرى وآلياتها: سقوطات الجلوس لغياب التعديلات الاستباقية، والزحف غير المتماثل، والاستكشاف الفموي المستمر مع نفور اللمس، وغياب قبضة الكماشة في أجلها.</p>", "slides": [{"kind": "cover", "title": "من 6 إلى 12 شهرًا — الجلوس والزحف والاستكشاف والقبضات", "sub": "الوحدة الثالثة: العلامات الحركية المبكرة 0-24 شهرًا", "goals": ["أن تصف محطات الجلوس والزحف والاستكشاف في النصف الثاني من السنة الأولى", "أن تفسّر دلالة غياب الكماشة عند 11 شهرًا وتأخر الزحف الرباعي", "أن تربط الاستكشاف الفموي والنفور اللمسي بملف الحسي اللاحق"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l12.jpg", "img2": null}, {"kind": "slide", "title": "من 6 إلى 12 شهرًا — الجلوس والزحف والاستكشاف والقبضات", "points": ["ثبات الجلوس يحتاج تعديلات استباقية لا قوة عضلية فقط.", "السقوط عند حركة الرأس أو الذراع علامة غياب الاستباق.", "آلية واحدة تربط علامة الرضيع باضطرابات الأعمار اللاحقة."], "text": {"head": "الجلوس الذي يسقط — تعديلات استباقية غائبة", "body": "<p>يجلس رضيع هذه المرحلة متكئًا ثم مستقلًا، وبقاء جلوسه مشروط بأن يعدّل جسده مسبقًا كلما تحرك رأسه أو امتدت ذراعه نحو لعبة: تعديلات وضعية استباقية (ajustements posturaux anticipatoires, APA) تنقل مركز الثقل قبل أن يختل. وثّق تيتلباوم (Teitelbaum, 1998) في تحليله لأشرطة رضّع شُخّصوا لاحقًا بالتوحد سقوطات متكررة عند تحريك الرأس أو الذراع أثناء الجلوس: الجسد لا يستبق الإخلال فيسقط كأنه فوجئ بحركته هو. هذه الآلية — غياب الاستباق والاعتماد على ردود متأخرة — ستجدها قلب اضطراب التوازن والتخطيط الحركي في وحدات قادمة؛ فهي خيط واحد من الجلوس الأول إلى كتابة المدرسة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من 6 إلى 12 شهرًا — الجلوس والزحف والاستكشاف والقبضات", "points": ["الزحف الطبيعي يبني تناسقًا متقاطعًا وقصدًا تنقليًا.", "الزحف غير المتماثل يفوّت لبنات في المخطط الجسدي والمكان.", "قيمة العلامة في وظيفتها الفائتة لا في غرابتها."], "text": {"head": "زحف غير متماثل — نمط لا يتناسق", "body": "<p>الزحف والحبو الطبيعيان يبنيان تناسقًا متقاطعًا بين الأطراف (ذراع يمنى مع ساق يسرى) يؤسس لاحقًا للمشي والتناسقات المعقدة. عند بعض رضّع هذه المرحلة يظهر زحف غير متماثل: دفع بجهة غالبة، أو سحب الجسم بذراع واحدة، أو تجاوز لمرحلة الزحف أصلًا بلا بديل ناضج. الدلالة ليست في الشكل الغريب وحده بل في ما يفوته: خبرة التناسق المتقاطع والتنقل القصدي نحو هدف، وهما لبنتان في بناء المخطط الجسدي والتنظيم المكاني. ولاحظ القاعدة العامة للوحدة: العلامة تهمّنا بوظيفتها الفائتة أكثر مما تهمّنا بغرابتها البصرية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من 6 إلى 12 شهرًا — الجلوس والزحف والاستكشاف والقبضات", "points": ["الاستكشاف الفموي المفرط نمطية مميزة موثقة عند 9-12 شهرًا.", "نفور اللمس علامة فرط استجابة لمسية مبكرة.", "البروفيل الحسي يبدأ التشكل من السنة الأولى."], "text": {"head": "الاستكشاف الفموي المستمر ونفور اللمس", "body": "<p>يستكشف رضيع هذه المرحلة العالم بفمه أولًا ثم بيديه تدريجيًا. وجد بارانيك (Baranek, 2003) عند أطفال 9-12 شهرًا شُخّصوا لاحقًا بالتوحد نمطين لافتين: وضع الأشياء في الفم مستمرًا ومفرطًا — وكان النمطية الوحيدة المميزة إحصائيًا في هذا العمر — ونفورًا من التلامس الاجتماعي والملامسة غير المتوقعة. الآلية حسية: فم ما زال قناة المعرفة الأولى لأن اليد لم تستلم مهمتها، ولمس يُعاش إغراقًا لا معلومة فيُتجنّب. وهنا تدخل مبكر لمنظومتنا: البروفيل الحسي للرضيع يبدأ من هنا، وقنواته المفرطة والناقصة ستقود قراءة اضطرابات الحركة كلها في وحدات الحسية القادمة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من 6 إلى 12 شهرًا — الجلوس والزحف والاستكشاف والقبضات", "points": ["قبضة الكماشة أجلها نحو 11 شهرًا.", "غيابها حلقة في قصة يد تبدأ من منعكس الإمساك الباقي.", "معالم اليد تُوثَّق بتواريخها في التقييم المبكر."], "text": {"head": "قبضة الكماشة الغائبة عند 11 شهرًا", "body": "<p>نحو الشهر الحادي عشر ينتقل الرضيع من قبضة الراحة الكاملة إلى قبضة الكماشة (pince pouce-index) بين الإبهام والسبابة، فاتحًا باب المعالجات الدقيقة كلها. غيابها أو تأخرها الكبير في هذه المرحلة علامة رابعة: يد لم تنتقل من الإمساك الكلي إلى الأداة الدقيقة. رتّبها مع علامتي المرحلة الأولى (منعكس إمساك باقٍ واستكشاف متأخر) تحصل على قصة يد واحدة متصلة: منعكس لا يرحل، واستكشاف يتلكأ، وكماشة لا تحضر — وهي قصة اضطراب الحركة الدقيقة قبل أن يولد بسنوات. لهذا تُدوَّن معالم اليد في كل تقييم مبكر بتواريخها، لا تُترك لانطباع عام عن «حركة دقيقة ضعيفة».</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من 6 إلى 12 شهرًا — الجلوس والزحف والاستكشاف والقبضات", "points": ["توثيق مؤرخ ومقارنة بالأجال النمائية.", "التجمع عبر المراحل يستدعي التحويل لا الانتظار.", "تحفيز مبكر آمن يبدأ بالتوازي مع التقييم."], "text": {"head": "السلوك المهني أمام المرحلة الثانية", "body": "<p>وثّق الجلوس والزحف والقبضات بفيديوهات قصيرة مؤرخة، وقارنها بأجالها لا بانطباعك، وسجّل النمط الحسي المرافق (فموي، لمسي) لأنه سيقود التقييم الحسي لاحقًا. عند تجمع علامتين فأكثر من مراحل مختلفة، لا تنتظر اكتمال الصورة: التحويل إلى تقييم نمائي وحسي-حركي شامل هو القرار، وبرامج التحفيز المبكر الآمنة (وضعيات، استكشاف موجه، ألعاب قبضات) تبدأ بالتوازي لأنها نافعة في كل الاحتمالات التشخيصية. وذكّر الأهل دائمًا بقاعدة الوحدة: نحن نتابع نمطًا ونبني دعمًا، ولا نسمي اضطرابًا من علامات.</p><p>وتجاور الكماشة علامات يد مرافقة تُرصد في المرحلة نفسها: نقل الأشياء من يد إلى يد بلا تناسق سلس، وإمساك بالراحة والأصابع مبسوطة بدل أطراف الأصابع، وإسقاط للأشياء دون تتبع بصري لها، وتفاصيل صغيرة كهذه ترسم — إذا اجتمعت — تأخر انتقال اليد من الإمساك الانعكاسي الكلي إلى الأداة الدقيقة المقصودة التي ستحمل القلم والأزرار وأدوات الأكل لاحقًا.</p><p>وقارن دائمًا بين اليدين في ملاحظتك: كماشة تحضر في يد وتتأخر في الأخرى معلومة مبكرة عن الجانبية والتناسق الثنائي تُدوَّن في موضعها، ولا تُذوَّب في حكم عام على «اليدين».</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الآلية التي تفسر سقوط الرضيع الجالس عند تحريك رأسه أو ذراعه عند من سيظهر عندهم التوحد؟", "الإجابة: غياب التعديلات الوضعية الاستباقية (APA) التي تنقل مركز الثقل وتهيئ الجسد قبل الإخلال، فيعتمد الجسد على ردود متأخرة لا تنقذ التوازن."], "text": null, "take": "في 6-12 شهرًا تتكلم الوضعيات والاستكشاف والقبضات: سقوطات استباق غائب، زحف غير متماثل، فم مفرط ولمس منفور، وكماشة غائبة عند 11 شهرًا.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 13, "title": "من 12 إلى 24 شهرًا — المشية والتنقل والقصد، ومسار ما بعد الاشتباه", "intro": "<p>في السنة الثانية يمشي الطفل، فتتكلم علامات لم تكن ممكنة قبله: جودة المشية نفسها، وطريقة تدوير الجسد، ووجهة التنقل وقصده. في هذا الدرس تتعرف على علامات المرحلة الأخيرة من الوحدة وآلياتها، ثم تنتقل إلى النصف المهني الأهم: ماذا يحدث بعد الاشتباه — مسار التحويل والتوثيق والحديث مع الأسرة كما يجب أن يكون.</p>", "slides": [{"kind": "cover", "title": "من 12 إلى 24 شهرًا — المشية والتنقل والقصد، ومسار ما بعد الاشتباه", "sub": "الوحدة الثالثة: العلامات الحركية المبكرة 0-24 شهرًا", "goals": ["أن تسمّي علامات المشية والتنقل والقصدية بين 12 و24 شهرًا", "أن تشرح سقوطات الاستباق الوضعي عند تيتيلباوم وما تعنيه تنمويًا", "أن تصف مسار ما بعد الاشتباه مهنيًا: توثيق وإحالة ومتابعة بلا وعود زائفة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l13.jpg", "img2": null}, {"kind": "slide", "title": "من 12 إلى 24 شهرًا — المشية والتنقل والقصد، ومسار ما بعد الاشتباه", "points": ["معالم المشية الناضجة: تأرجح متناوب وتناظر وتراجع أصابعي.", "انحرافاتها عند السنتين مؤشرات موثقة.", "فيديو المشية وثيقة أساسية للمقارنة اللاحقة."], "text": {"head": "مشية غير ناضجة عند السنتين", "body": "<p>المشية الناضجة الوليدة لها معالم: تأرجح ذراعين متناوب مع الساقين، وتناظر مقبول بين الجانبين، وانتقال تدريجي من مشية القاعدة الواسعة إلى مشية واثقة، وتراجع المشي على رؤوس الأصابع بعد 18 شهرًا. وثّقت الملاحظات والدراسات عند أطفال السنتين ممن شُخّصوا لاحقًا بالتوحد مشية غير ناضجة: غياب تأرجح الذراعين أو تأرجحًا مضادًا للإيقاع، وعدم تناظر في حركة الأطراف، واستمرار المشي على رؤوس الأصابع. الآلية مركبة: تناسقات بين القطاعات لم تُبنَ على قاعدة الزحف المتقاطع، ومقوّية أطراف سفلية مضطربة التنظيم، واستباق وضعي ما زال غائبًا. سجّل المشية فيديو من الأمام والجانب؛ فهي وثيقة مقارنة عند كل إعادة تقييم.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من 12 إلى 24 شهرًا — المشية والتنقل والقصد، ومسار ما بعد الاشتباه", "points": ["التدوير الطبيعي قطاعي متسلسل من الرأس إلى الحوض.", "التدوير كتلة واحدة علامة جذع لا يعمل سلسلة.", "العلامة الدقيقة تصوّر آلية لا مجرد عرض."], "text": {"head": "التدوير كتلة واحدة — تسلسل مفقود", "body": "<p>حين يغيّر الطفل اتجاهه، يدوّر جسده قطعة قطعة بتسلسل: رأس، أكتاف، جذع، حوض — وهو التسلسل القطاعي (rotation segmentaire) الذي يميز الحركة الناضجة. وثّق تيتلباوم (Teitelbaum, 1998) عند هؤلاء الأطفال تدويرًا «كتلة واحدة» (en bloc): الجسد كله يلتفت قطعة صلبة واحدة بلا تفكيك قطاعي. الآلية أن التسلسل القطاعي ثمرة نضج تناسقات الجذع والمقوّية المحورية؛ غيابه يعني جذعًا يعمل كتلة لا سلسلة، وهو ما ستجده لاحقًا في صعوبات التناسق العام والتوازن الديناميكي. علامة صغيرة في فيديو منزلي، لكنها من أدق علامات المرحلة لأنها تصوّر آلية لا عرضًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من 12 إلى 24 شهرًا — المشية والتنقل والقصد، ومسار ما بعد الاشتباه", "points": ["التنقل القصدي معلم نمائي للسنة الثانية.", "المشي بلا وجهة صورة قصدية مبكرة محتملة.", "لا قراءة مفردة خارج النمط الكلي الموثق."], "text": {"head": "تنقّل بلا وجهة — أول صور اضطراب القصد", "body": "<p>مع المشي يظهر سؤال جديد: إلى أين؟ يتنقل طفل السنتين النموذجي بين أهداف: لعبة، شخص، فضول. عند بعض أطفال هذه المرحلة يظهر تنقل كثير بلا وجهة مستقرة: مشي لا يستقر على هدف، واستكشاف قليل للأشياء الجديدة، وانشغال حركي متكرر. هذه هي الصورة المبكرة لما ستدرسه وحدة الآليات بوصفه اضطراب القصدية (intentionnalité): جهاز حركي يعمل لكنه غير مسخّر لهدف يمثله صاحبه. احذر الخلطين: فرط الحركة العادي عند الصغار واسع وشائع، وقلة الاستكشاف قد تعللها بيئة فقيرة؛ لا تُقرأ العلامة إلا داخل النمط الكلي الموثق عبر المراحل الثلاث.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من 12 إلى 24 شهرًا — المشية والتنقل والقصد، ومسار ما بعد الاشتباه", "points": ["تحويل موثق مرفق بالتسلسل الزمني للعلامات.", "تقييم نفسي حركي وحسي بالتوازي يبني خطة دعم فورية.", "متابعة مجدولة وأهل مراقبون مدربون."], "text": {"head": "من الاشتباه إلى التقييم — المسار المهني", "body": "<p>اكتمل الاشتباه الموثق؛ فما المسار؟ أولًا تحويل مكتوب إلى تقييم نمائي شامل (طبيب نمو، فريق متعدد) مع إرفاق التوثيقات والتسلسل الزمني للعلامات. ثانيًا تقييم نفسي حركي وحسي خاصتنا بالتوازي، لأنه يحوّل الاشتباه إلى بروفيل عمل وخطة دعم فورية أيًا كان الاسم النهائي. ثالثًا متابعة مجدولة لا مفتوحة: موعد مراجعة محدد تُقارن فيه المعالم الجديدة، لأن النمو في هذا العمر سريع والفروق تظهر بالأشهر. ورابعًا إشراك الأهل مراقبين مدربين: قائمة معالم بسيطة يرصدونها وفيديوهات يقتنونها، فيتحول قلقهم إلى أداة التقييم الأدق — عين يومية موثقة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "من 12 إلى 24 شهرًا — المشية والتنقل والقصد، ومسار ما بعد الاشتباه", "points": ["وصف مرئي للملاحظة لا أسماء اضطرابات.", "الخطوة التالية تُعرض مكسبًا مبكرًا.", "صدق مقاس يبني شراكة طويلة."], "text": {"head": "الحديث مع الأسرة — دقة بلا تهويل ولا تطمين", "body": "<p>أصعب لحظات هذا العمل ليست فنية بل كلامية. القواعد: صِف ما لاحظته بلغة مرئية («لاحظنا أنه لا يهيئ جسده عند حمله» لا «عنده علامات توحد»)، واعرض الخطوة التالية بوصفها مكسبًا («التقييم المبكر يفتح دعمًا يغيّر المسار»)، واعترف بحدود العلامات صراحة («هذه مؤشرات تستدعي تقييمًا، وكثير من الأطفال أصحاب مؤشرات جزئية يسيرون نموًا طبيعيًا بعد دعم بسيط»)، ولا تعد بنتائج ولا تخفِ قلقك المهني خلف عموميات. الأسرة التي تُحترم بصدق مقاس تصير شريك التقييم والتدخل لسنوات؛ والأسرة التي هُوّلت تهرب، والتي طُمئنت كذبًا تعود بعد فوات نافذة.</p><p>ولا يقف التوثيق عند العلامات المشتبهة: سجّل أيضًا ما يحسنه الصغير وما يستجيب له — وضعيات تريحه وأصوات تلفت انتباهه وألعاب يطلبها — فخطة الدعم المبكر تُبنى على مواطن القوة الموثقة بقدر ما تُبنى على مواطن الاشتباه، وسجل القوة هذا أول هدية حقيقية يقدمها الكشف المبكر للفريق الذي سيعمل مع الأسرة بعدك.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما التدوير «كتلة واحدة» (en bloc) ولماذا يعدّ من أدق علامات السنة الثانية؟", "الإجابة: أن يلتفت الجسد كله قطعة صلبة واحدة عند تغيير الاتجاه بدل التسلسل القطاعي الطبيعي (رأس، أكتاف، جذع، حوض)؛ ودقته أنه يصوّر آلية مباشرة — جذع لا يعمل سلسلة قطاعية — لا مجرد عرض عابر."], "text": null, "take": "في 12-24 شهرًا تتكلم المشية والتدوير والوجهة؛ وبعد الاشتباه مسار واحد: وثّق، حوّل، قيّم، تابع مجدولًا، وتكلم مع الأسرة بصدق مقاس.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 14, "title": "لماذا آليات عابرة؟ — الطبقة التي تفسّر الأداء كله", "intro": "<p>قبل أن تدخل وحدات الاضطرابات واحدًا واحدًا، تحتاج طبقة تفسير تجمعها. في هذا الدرس تتعرف على فكرة الآليات العابرة: عمليات معرفية-حركية قليلة تقف تحت أداء كل المكونات، فإذا اضطرابت ظهر اضطرابها في المقوّية والتناسق والكتابة واللعب معًا. وستتعرف أيضًا على الخلفية الاجتماعية-المعرفية التي تحكم فهم التعليمات عند المصاب بالتوحد، لأنها شرط تصميم أي موقف تعلم حركي.</p>", "slides": [{"kind": "cover", "title": "لماذا آليات عابرة؟ — الطبقة التي تفسّر الأداء كله", "sub": "الوحدة الرابعة: الآليات العابرة الأربعة", "goals": ["أن تفسّر لماذا تُدرس بعض الآليات عابرةً للاضطرابات كلها", "أن تسمّي الآليات الأربع وموضع كل منها في سلسلة الفعل", "أن تطبق قراءة الآليات على أي أداء حركي مضطرب قبل تسميته"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l14.jpg", "img2": null}, {"kind": "slide", "title": "لماذا آليات عابرة؟ — الطبقة التي تفسّر الأداء كله", "points": ["فشل متعدد الأسطح قد يكون آلية واحدة مضطربة.", "الآليات تعمل عبر كل المكونات وعابرة لها.", "سؤال الآلية يسبق اقتراح النشاط في كل وحدة قادمة."], "text": {"head": "مشكلة التفسير بالمكونات وحدها", "body": "<p>قراءة الاضطرابات مكونًا مكونًا ضرورية لكنها لا تكفي: متعلم يفشل في التوازن والتناسق والكتابة والتقليد معًا — أهي أربعة اضطرابات مستقلة أم آلية واحدة مضطربة تظهر في أربعة أسطح؟ ومتعلم آخر ينجح في الحركة حرة وينهار فيها داخل موقف مقنن — أين يقع العطل؟ أسئلة كهذه لا تجيبها خريطة المكونات؛ تجيبها طبقة الآليات: عمليات مثل التقليد والقصدية والتخطيط والاستباق والانتباه تعمل عبر كل المكونات، فتفسيرها يوحّد الصورة ويختصر الطريق. لهذا تتقدم هذه الوحدة وحدات الاضطرابات: كل اضطراب قادم سيُسأل عن آلياته قبل أن تُقترح أنشطته.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "لماذا آليات عابرة؟ — الطبقة التي تفسّر الأداء كله", "points": ["تمثيل معتقدات الآخرين صعب، والرغبات والمشاعر البسيطة مفهومة أكثر.", "التعليمة الغامضة عائق معرفي قبل أن تكون حركيًا.", "تصميم الدورة: تعليمات حرفية مفككة مدعومة بصريًا وجسديًا."], "text": {"head": "نظرية العقل — خلفية كل تعليمة ستعطيها", "body": "<p>منذ أعمال بارون-كوهين وليزلي وفريث (Baron-Cohen, Leslie et Frith, 1985) نعرف أن المصاب بالتوحد يعالج عقول الآخرين على نحو مختلف: يفهم الرغبات والمشاعر البسيطة وما يراه الآخر، ويصعب عليه تمثيل المعتقدات (خاصة الخاطئة منها عند الآخر)، ويغيب عنده اللعب التظاهري المبكر غالبًا. ما علاقة هذا بدرس حركي؟ علاقة يومية مباشرة: تعليمتك اللفظية تفترض أن المتعلم يخمّن قصدك من كلماتك وسياقك؛ فإذا كان تمثيل القصد مضطربًا، صارت التعليمة الغامضة أو المجازية أو الطويلة عائقًا معرفيًا قبل أن تكون عائقًا حركيًا. النتيجة التصميمية التي تلازم الدورة كلها: تعليمات قصيرة حرفية مفككة، مدعومة بإيماء ودعامة محسوسة وإرشاد جسدي عند الحاجة، لا تعليمات تُقرأ بين أسطرها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "لماذا آليات عابرة؟ — الطبقة التي تفسّر الأداء كله", "points": ["تقليد وقصدية وتخطيط واستباق وانتباه.", "كل آلية شرط لعمل جاراتها.", "ترتيب الدروس يتبع ترتيب أثرها في التعلم الحركي."], "text": {"head": "خريطة الآليات الأربع", "body": "<p>أربع آليات ستفصّلها الدروس القادمة بترتيب أثرها في التعلم الحركي. التقليد (imitation): قناة اكتساب الحركة الأولى، واضطرابه يغلق باب «افعل مثلي». القصدية (intentionnalité): أن تكون الحركة نحو هدف ممثَّل، واضطرابها يجعل التنقل تجوالًا والنشاط تكرارًا بلا وجهة. التخطيط والاستباق (planification et anticipation): برمجة الحركة قبل تنفيذها، واضطرابه يجعل الأداء ارتجاليًا معتمدًا على التصحيح المتأخر. والانتباه (attention): بوابة كل ما سبق، واضطرابه يسرق المادة قبل أن تصل إلى أي آلية. الآليات الأربع متداخلة: تقليد بلا انتباه لا يبدأ، وتخطيط بلا قصد لا يُبنى، وسترى في كل درس خيوطه إلى جيرانه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "لماذا آليات عابرة؟ — الطبقة التي تفسّر الأداء كله", "points": ["الفشل الواحد يُقرأ بالمكونات وبالآليات معًا.", "كل آلية تنتج فرضية فحص وتدخلًا مختلفين.", "الآليات تمنع علاج السطح بدل العمق."], "text": {"head": "مثال جامع — كتابة فاشلة تُقرأ بأربع آليات", "body": "<p>متعلم في الثامنة لا ينسخ من السبورة. قراءة بالمكونات تقول: حركة دقيقة وغرافوموتورية ضعيفتان. قراءة بالآليات تسأل أعمق: هل ينتبه إلى النموذج أصلًا وإلى أين وصل فيه (انتباه)؟ هل يستطيع تقليد وضعية الجلوس والقبضة المعروضتين أمامه (تقليد)؟ هل يمثل هدف النسخ تسلسلًا يقصده أم ينقل حرفًا بلا خطة (قصدية وتخطيط)؟ هل يستبق حركة يده أم يصحح كل حرف بعد كتابته (استباق)؟ الأسئلة الأربعة تنتج أربع فرضيات قابلة للفحص داخل الحوصلة، وكل فرضية مثبتة تنتج تدخلًا مختلفًا. هكذا تعمل الآليات: لا تستبدل فحص المكونات، بل تمنعك من أن تعالج السطح الذي ظهر فيه الفشل بدل العمق الذي أنتجه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "لماذا آليات عابرة؟ — الطبقة التي تفسّر الأداء كله", "points": ["لكل آلية مواقف فحص ومؤشرات قابلة للملاحظة.", "التسمية بلا فحص تخمين ممنوع مهنيًا.", "الآليات احتمالات تُحسم كغيرها بالتقييم."], "text": {"head": "قاعدة الوحدة — الآلية تُقيَّم ولا تُخمَّن", "body": "<p>تنبيه منهجي يختم الدرس ويحكم الوحدة كلها: الآليات ليست كلمات تفسيرية نلصقها بأي فشل؛ كل آلية لها مواقف فحصها ومؤشراتها السلوكية القابلة للملاحظة والقياس، وستعرفها في درسها. من قال «مشكلته تخطيط» دون موقف أظهر اضطراب التحضير مع سلامة التنفيذ، خمّن لا قيّم. والتخمين في منظومتنا ممنوع بقاعدة الاحتمالات: تضع الآليات الأربع فوق الطاولة مع احتمالات المكونات والحسية والمنعكسات، ثم تحسم بالفحص. عندها فقط تصير الآلية أداة عمل، لا لغة وصف أنيقة.</p><p>ويمتد أثر نظرية العقل إلى اللعب الحركي نفسه: فاللعب التظاهري الغائب يعني أن ألعاب «كأنّ» وتمثيل الأدوار — وقودًا تقليديًا لجلسات الأطفال الجماعية — لا تؤدي عند كثير من متعلميك الوظيفة التي تؤديها عند غيرهم؛ فابنِ مواقفك على أفعال حقيقية بأشياء حقيقية ونتائج حقيقية، واترك التظاهر نفسه هدفًا يُبنى تدريجيًا لا وسيلة تُفترض جاهزة منذ الجلسة الأولى.</p><p>وتعمل الآليات الأربع متزامنة في كل فعل واحد: تنتبه إلى نموذج فتقلّده أو تخطط فتستبق نتيجته؛ وعزلها في دروس متتابعة عزل تعليمي يقتضيه الفهم، لا وصف لطريقة عملها في الواقع حيث يتداخل عطلها كما يتداخل عملها، فيجرّ ضعف انتباه تقليدًا ناقصًا وتخطيطًا أعمى في سلسلة واحدة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا لا تكفي قراءة الاضطرابات بالمكونات وحدها؟", "الإجابة: لأن آلية واحدة مضطربة (تقليد أو قصدية أو تخطيط أو انتباه) قد تظهر في مكونات كثيرة معًا؛ فبدون طبقة الآليات نعالج أسطح الفشل المتعددة ونترك العمق الواحد الذي أنتجها."], "text": null, "take": "الآليات العابرة طبقة تفسير تحت المكونات كلها؛ ونظرية العقل تحكم تصميم تعليماتك؛ وكل آلية تُقيَّم بمواقفها لا تُخمَّن من انطباع.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 15, "title": "التقليد — قناة التعلم الحركي الأولى حين تضطرب", "intro": "<p>«افعل مثلي» هي أقدم جملة تعليم في حياة الإنسان وأكثرها استعمالًا في الجلسات. في هذا الدرس تتعرف على اضطراب التقليد (trouble de l'imitation) عند المصاب بالتوحد: أين يشتد وأين يخف، وما الآليات المركبة التي يقف عليها، ولماذا لا يُنتظر نضجه بل يُبنى بناؤه هدفًا أول في أي خطة — لأن من لا يقلّد يُحرم قناة التعلم الحركي والاجتماعي الأولى.</p>", "slides": [{"kind": "cover", "title": "التقليد — قناة التعلم الحركي الأولى حين تضطرب", "sub": "الوحدة الرابعة: الآليات العابرة الأربعة", "goals": ["أن تشرح دور التقليد قناةَ تعلم حركي أولى وأشكال اضطرابه الأولية", "أن تميّز فشل التقليد عند دي ماير وروجرز بحسب نوع المادة المقلدة", "أن تربط اضطراب التقليد بكلفته على اللعب والتعلم الاجتماعي"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l15.jpg", "img2": null}, {"kind": "slide", "title": "التقليد — قناة التعلم الحركي الأولى حين تضطرب", "points": ["التقليد سلسلة: انتباه وتمثيل وتخطيط ومراقبة.", "قناة التعلم الحركي والاجتماعي الأولى بلا وسيط لفظي.", "دوائر عصبية مشتركة بين رؤية الفعل وتنفيذه."], "text": {"head": "ما التقليد ولماذا هو قناة أولى", "body": "<p>التقليد (imitation) أن ترى فعلًا عند غيرك فتستخرج منه برنامجًا حركيًا في جسدك وتنفذه. يبدو بسيطًا وهو في الحقيقة سلسلة عمليات: انتباه إلى النموذج، وتمثيل لحركته في فضاء جسدك، وتخطيط لتنفيذها بأعضائك، ومراقبة للنتيجة ومقارنتها بالأصل. عبر هذه القناة يتعلم الطفل الحركات والأصوات واللعب والمهارات الاجتماعية دون تعليم لفظي واحد. وربطت بحوث الخلايا العصبية المرآتية (neurones miroirs) عند ريزولاتي (Rizzolatti) بين رؤية الفعل وتنفيذه في دوائر عصبية مشتركة، فصار التقليد جسرًا معترفًا به بين الإدراك والحركة والفهم الاجتماعي معًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التقليد — قناة التعلم الحركي الأولى حين تضطرب", "points": ["العجز أشد في حركات الجسد والتعبيرات والجديد والمتسلسل.", "وأخف في أفعال مألوفة على أشياء ذات نتيجة مرئية.", "تدرج الصعوبة نفسه خطة بناء التدخل."], "text": {"head": "شكل الاضطراب — أين يشتد وأين يخف", "body": "<p>منذ دراسات دو ماير (De Myer, 1972) المبكرة وصف أداء المصابين بالتوحد في التقليد أدنى من أقرانهم، وتفصّل أعمال روجرز (Rogers) وآخرين خريطة الاشتداد: أشدّ العجز في حركات الجسد الخالصة بلا أشياء، وفي تعبيرات الوجه الانفعالية، وفي الأفعال الجديدة غير المألوفة، وفي التسلسلات الحركية المركبة — وأخفّه في أفعال مألوفة على أشياء حقيقية ذات نتيجة مرئية. النمط نفسه تعرفه من وحدة العلامات: المجرد والجديد والمتسلسل أصعب؛ والمحسوس والمألوف وذو النتيجة أيسر. احفظ هذا التدرج؛ هو بذاته وصفة تصميم مواقف التقليد في التدخل: نبدأ من الطرف الأيسر ونمشي نحو الأصعب درجة درجة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التقليد — قناة التعلم الحركي الأولى حين تضطرب", "points": ["الاضطراب قد يقع في انتباه أو تمثيل أو براكسيا أو قصدية.", "الفحص يفكك الحلقات بمواقف معزولة المتغيرات.", "لكل حلقة مضطربة تدخلها الخاص."], "text": {"head": "آليته المركبة — لماذا لا يوجد «عطل» واحد", "body": "<p>لأن التقليد سلسلة، فاضطرابه قد يقع في أي حلقة: انتباه لا يثبت على النموذج أو لا ينتقي منه الجوهري؛ أو تمثيل لا ينقل حركة جسد آخر إلى خريطة الجسد الذاتي (وهنا يلتقي اضطراب التقليد باضطراب المخطط الجسدي)؛ أو براكسيا (praxie) لا تبرمج التسلسل؛ أو قصدية لا ترى في الفعل هدفًا يستحق النسخ. النتيجة العملية: «لا يقلّد» ليست نتيجة فحص كافية أبدًا؛ الفحص الجاد يفكك الحلقات — يعرض فعلًا بسيطًا جدًا ليعزل الانتباه، وفعلًا مألوفًا ليعزل الجدة، ويسمح بزمن طويل ليعزل سرعة البرمجة — حتى يسمي الحلقة المضطربة باسمها. ولكل حلقة تدخلها: تدريب انتباه مشترك، أو بناء مخطط جسدي، أو تفكيك تسلسلات، أو بناء قصد من اهتمامات المتعلم.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التقليد — قناة التعلم الحركي الأولى حين تضطرب", "points": ["النمطية مخزون مغلق متقن، والتقليد قدرة مفتوحة على التعلم.", "الإتقان النمطي لا يقيس قدرة التقليد.", "والعجز التقليدي لا يقيس القدرة الحركية العامة."], "text": {"head": "مفارقة يجب أن تحسمها — دقة في النمطية وعجز في التقليد", "body": "<p>ستقابل متعلمين ينفذون معالجات دقيقة معقدة داخل سلوكياتهم النمطية المتكررة، ثم يعجزون عن تقليد حركة أبسط تطلبها منهم. لا تناقض هنا إذا فهمت الآلية: النمطية فعل أتقنه جسده بتكرار ذاتي الدفع بلا نموذج خارجي ولا قصد تواصلي؛ والتقليد فعل يُبنى الآن من نموذج خارجي بقصد نسخه. الأول مخزون حركي مغلق، والثاني قدرة مفتوحة على التعلم. ولهذا لا تقيس التقليد بما يتقنه المتعلم في عالمه المغلق، ولا تحكم على قدرته الحركية العامة من عجزه التقليدي. الفارق بين المخزون والقدرة فارق جوهري في كل تقييمات هذه الدورة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التقليد — قناة التعلم الحركي الأولى حين تضطرب", "points": ["التقليد يُعلَّم بمواقف مصممة ولا يُنتظر (Schopler).", "التقليد المتبادل من البالغ يفتح القناة عكسيًا (Nadel).", "نسختان من الأداة وتوجه مشترك شرطان تصميميان."], "text": {"head": "المخرج العملي — التقليد يُعلَّم ولا يُنتظر", "body": "<p>خلاصتان من الأدبيات تحكمان التدخل. الأولى عند شوبلر (Schopler): التقليد عند المصاب بالتوحد مهارة تُعلَّم بمواقف مصممة، لا مرحلة تُنتظر حتى تنضج وحدها. والثانية عند نادل (Nadel): التقليد المتبادل (imitation réciproque) — أن يبدأ البالغ بتقليد حركات المتعلم وأصواته هو — يبني عنده انتباهًا للآخر ومتعة تبادل وينشّط تقليده التلقائي لاحقًا؛ أي ندخل القناة من بابها العكسي حين يكون بابها المباشر مغلقًا. أضف قاعدتين تصميميتين: مادة مكررة بنسختين (أداة لك وأداة له) حتى يكون النسخ ممكنًا جسديًا، وبناء اتصال بصري وتوجه مشترك قبل مطالبة النسخ لا شرطًا مانعًا له. ستعود هذه القواعد موسعة في وحدة اضطراب التقليد التطبيقية آخر الدورة.</p><p>ويُفحص التقليد بمواقف مخصصة داخل الحوصلة، من مواقف وضعيات وتسلسلات معدّلة عن بطارية برجيس-ليزين (Bergès-Lézine) إلى ملاحظة التقليد التلقائي في اللعب الحر، لأن ما يظهر عفويًا في اللعب قد يغيب كليًا في موقف الطلب المباشر — والفارق بين الموقفين نفسه معلومة عن الآلية لا تناقض في القياس.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا لا تناقض بين إتقان متعلم معالجات دقيقة في نمطياته وعجزه عن تقليد حركة أبسط؟", "الإجابة: لأن النمطية مخزون حركي مغلق أُتقن بتكرار ذاتي بلا نموذج خارجي، بينما التقليد قدرة مفتوحة على بناء فعل جديد من نموذج بقصد نسخه؛ فهما نظامان مختلفان لا يقيس أحدهما الآخر."], "text": null, "take": "التقليد سلسلة آليات (انتباه وتمثيل وبراكسيا وقصد)؛ اضطرابه يُفكَّك حلقة حلقة، ويُبنى تعليمًا وتقليدًا متبادلًا لا انتظارًا.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 16, "title": "القصدية — حين تتحرك الحركة بلا هدف", "intro": "<p>تتعرف في هذا الدرس على آلية القصدية (intentionnalité): الخاصية التي تجعل الحركة «نحو» شيء — هدف ممثَّل يسخّر الجهاز الحسي-الحركي كله لبلوغه. عند المصاب بالتوحد قد تجد معالم حركة سليمة ومسارات منحرفة ووجهة غائبة؛ وهنا يقع واحد من أعمق اضطرابات الأداء وأكثرها إرباكًا لمن يقرأ السلوك قراءة سطحية.</p>", "slides": [{"kind": "cover", "title": "القصدية — حين تتحرك الحركة بلا هدف", "sub": "الوحدة الرابعة: الآليات العابرة الأربعة", "goals": ["أن تشرح القصدية بوصفها محرك الحركة الهادفة وعلامات غيابها", "أن تميّز حركة بلا هدف عن حركة هدفها غير مقروء لك", "أن تربط القصدية المضطربة بخطط بناء الانتباه المشترك"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l16.jpg", "img2": null}, {"kind": "slide", "title": "القصدية — حين تتحرك الحركة بلا هدف", "points": ["القصدية: تمثيل هدف وتسخير الجسد لبلوغه.", "تُقرأ في مسار الفعل: بداية وتصحيح وتوقف عند البلوغ.", "هي ما يحول الاستجابة إلى فعل قابل للتعلم."], "text": {"head": "ما القصدية عند بولينجيه", "body": "<p>في تحليل بولينجيه (Bullinger) للنمو الحسي-الحركي، القصدية هي ما يحوّل الاستجابات والأفعال المنعكسة إلى أفعال: أن يمثّل الطفل هدفًا (شيئًا يبلغه، أثرًا يحدثه) ويجعل جسده أداة بلوغه، فيتعلم من نتائج أفعاله ويعدّلها. الرضيع القصدي يستكشف لأنه يريد أثرًا؛ وحركاته الأولى الفوضوية تنتظم تدريجيًا حول أهداف. القصدية بهذا المعنى ليست رغبة واعية معلنة، بل تنظيم عميق للفعل حول غاية، تُقرأ في مسار الحركة لا في كلام صاحبها: فعل له بداية نحو هدف، وتصحيحات في الطريق، وتوقف عند البلوغ أو تعديل عند الفشل.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "القصدية — حين تتحرك الحركة بلا هدف", "points": ["معالم مشي سليمة ومسارات منحرفة عن الهدف (2005).", "استكشاف أقل ونمطيات أكثر (2001).", "الجهاز يعمل والغاية غائبة — اضطراب تسخير لا قدرة."], "text": {"head": "مشي سليم المعالم منحرف المسارات", "body": "<p>أدق وصف عيادي للآلية مضطربة جاء من فيرنازا-مارتان (Vernazza-Martin, 2005): عند أطفال مصابين بالتوحد قيسَت معالم مشيهم (سرعة، إيقاع خطوة، أطوال) فكانت قريبة من الطبيعي، لكن مساراتهم انحرفت باستمرار عن الأهداف المكانية المقصودة: المشي موجود والوجهة غائبة. ضعفّ الصورة أكثر بدراسات بيرس وكورشن (Pierce et Courchesne, 2001): استكشاف أقل للبيئة والأشياء الجديدة، ووقت أطول في حركات متكررة بلا موضوع. المفارقة التعليمية هنا أساسية لفهم متعلميك: مشكلة هذا المتعلم ليست أنه «لا يستطيع» بل أن جهازه الحركي لا يعمل في خدمة فضول وهدف؛ ولهذا تبدو حركته الحرة كثيرة أحيانًا وقليلة الجدوى دائمًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "القصدية — حين تتحرك الحركة بلا هدف", "points": ["تكيّف المقوّية الخلفية مع الموقف مؤشر قصدية.", "الكرة الكبيرة موقف قراءة كلاسيكي للتعديل والقصد.", "القراءة لحظية وتُبنى عليها فرضية لا حكم."], "text": {"head": "المقوّية الخلفية علامة قصدية مقروءة", "body": "<p>للقصدية مؤشر جسدي يقرأه النفسي الحركي في الحوصلة: تكيّف المقوّية الخلفية (tonus de fond) مع الموقف والقصد؛ فحين يوجَّه المتعلم أو يُقاوم أو يُحمَل على الكرة الكبيرة، يظهر في تعديلات مقوّيته إن كان «داخل» الفعل مشاركًا فيه أم خارجه متلقيًا. في أدبيات الحوصلة يُستعمل نشاط الكرة الكبيرة تحديدًا لقراءة التعديلات الوضعية ومستوى القصدية معًا: جسد يكيّف مقوّيته استباقيًا مع إزاحات الكرة يعلن قصدية حاضرة في الفعل، وجسد يبقى كتلة سلبية يعلن غيابها لحظيًا. لاحظ «لحظيًا»: القصدية تتقلب مع الحالة والسياق والاهتمام، وقراءتها في موقف واحد بداية فرضية لا حكم نهائي.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "القصدية — حين تتحرك الحركة بلا هدف", "points": ["التجوال وعدم البدء قد يكونان غياب هدف ممثَّل لا عنادًا.", "التدخل يبني أهدافًا مرئية بدل كبح الحركة.", "قراءة القصدية تفرّق بين خطة عقاب وخطة بناء."], "text": {"head": "كيف يربك اضطراب القصدية قراءة السلوك", "body": "<p>غياب الوجهة يُقرأ خطأً بسهولة: تجوال في القسم يُسجَّل «فرط حركة وتشتتًا»، ورفض البدء في مهمة يُسجَّل «عنادًا»، ونشاط متكرر بلا هدف يُسجَّل «سلوكًا نمطيًا يجب إيقافه». في الحالات الثلاث قد يكون الواقع قصدية لا تجد هدفًا ممثلًا: المتعلم لا يرفض الهدف، بل الهدف لم يُبنَ في تمثيله أصلًا لأن التعليمة لم تصله أو لم تعنه. الفارق يغيّر التدخل جذريًا: بدل كبح التجوال، تُبنى أهداف مرئية ملموسة داخل الفضاء (محطات، مسارات، غايات محسوسة)؛ وبدل معاقبة عدم البدء، يُعلَن الهدف ويُفكَّك ويُربط باهتمام قائم. قراءة القصدية إذن ليست ترفًا نظريًا؛ هي ما يفرّق بين خطة تعاقب جسدًا وخطة تبني له وجهة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "القصدية — حين تتحرك الحركة بلا هدف", "points": ["اهتمامات المتعلم ونمطياته خريطة قصديته الحرة.", "الأهداف التعليمية تُغرس أولًا في وجهات قائمة.", "هدف مرئي قابل للتحقق الذاتي ينمّي القصدية."], "text": {"head": "مدخل العمل — اهتمامات المتعلم باب قصديته", "body": "<p>إذا كانت القصدية تُبنى حول أهداف تعني صاحبها، فالمدخل العملي الوحيد الصادق هو اهتمامات المتعلم القائمة: أشياؤه المفضلة، ونشاطاته الحسية التي يطلبها، وحتى نمطياته مقروءة بوصفها إعلانات عن قنواته ودوافعه. منهج العمل: حلّل ما يفعله المتعلم تلقائيًا (أين تذهب قصديته حين تُترك حرة؟)، واربط أهدافك التعليمية الأولى بتلك الوجهات، ثم وسّع دائرة الأهداف درجة درجة من المألوف المحبوب إلى الجديد المطلوب. وابنِ في كل نشاط هدفًا مكانيًا أو أثريًا مرئيًا يستطيع المتعلم التحقق من بلوغه بنفسه؛ فالقصدية تنمو حين يرى الفعل أثره. ستجد هذا المبدأ يعمل في وحدات الاضطرابات كلها تحت أسماء مختلفة: هدف مرئي، نتيجة محسوسة، نجاح سريع موثق.</p><p>وللقصدية باب جسدي آخر لا تنسَه: الحوار المقوّي الذي درسته في الوحدة الأولى؛ فكثير من أهداف المتعلم الأولى لا تُبنى بتعليمة بل بمقاومة متبادلة وشدّ وارتخاء مشتركين يصير فيهما جسدك أنت هدفه المؤقت ووسيلته في الوقت نفسه — وهنا تلتقي أقدم آليات العلاقة الإنسانية بأحدث خطط التدخل النفسي الحركي.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما المفارقة التي وصفها فيرنازا-مارتان (2005) في مشي أطفال التوحد؟", "الإجابة: معالم المشي نفسها (سرعة وإيقاع وخطوات) قريبة من الطبيعي، بينما تنحرف المسارات باستمرار عن الأهداف المكانية — أي اضطراب في تسخير الحركة لهدف، لا في تنفيذ الحركة ذاتها."], "text": null, "take": "القصدية تنظيم الفعل حول هدف ممثَّل؛ اضطرابها مشي بلا وجهة واستكشاف شحيح، وتُبنى من اهتمامات المتعلم وأهداف مرئية يتحقق من بلوغها بنفسه.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 17, "title": "التخطيط والاستباق — عطل في التحضير لا في التنفيذ", "intro": "<p>كل حركة ناجحة تُبنى مرتين: مرة في التحضير الصامت قبل أن تبدأ، ومرة في التنفيذ الظاهر. في هذا الدرس تتعرف على اضطراب التخطيط (planification) والاستباق (anticipation) عند المصاب بالتوحد: لماذا تقع المشكلة في المرحلة الأولى غالبًا بينما يبقى التنفيذ قريبًا من السلامة، وكيف تفسّر هذه الحقيقة الواحدة اضطرابات التناسق والتوازن والكتابة معًا.</p>", "slides": [{"kind": "cover", "title": "التخطيط والاستباق — عطل في التحضير لا في التنفيذ", "sub": "الوحدة الرابعة: الآليات العابرة الأربعة", "goals": ["أن تشرح قاعدة راينهارت: التحضير مضطرب والتنفيذ محفوظ", "أن تميّز أخطاء التحضير عن أخطاء التنفيذ في أي مهمة تلاحظها", "أن تفسّر تجربة شميتز (حمل الصينية) بوصفها درس استباق كاملًا"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l17.jpg", "img2": null}, {"kind": "slide", "title": "التخطيط والاستباق — عطل في التحضير لا في التنفيذ", "points": ["تحكم استباقي يبرمج قبل، وارتجاعي يصحح أثناء.", "الأداء الناضج يغلب فيه الاستباق مع الإتقان.", "عند التوحد: غلبة ارتجاعية تنتج بطئًا وتفاوتًا واعتمادًا بصريًا."], "text": {"head": "برمجة الحركة — استباق يهيئ وارتجاع يصحح", "body": "<p>يملك الجهاز الحركي نمطي تحكم: تحكمًا استباقيًا (contrôle anticipatoire, feed-forward) يبرمج الحركة مسبقًا — قوتها واتجاهها وتسلسلها وتعديلات الجسد المرافقة — وتحكمًا ارتجاعيًا (rétrocontrôle, feed-back) يصحح أثناء التنفيذ اعتمادًا على ما ترده الحواس. الحركة الناضجة خليط يغلب فيه الاستباق كلما أُتقنت المهارة، فيصير الأداء سريعًا وسلسًا واقتصاديًا. عند المصاب بالتوحد تشير البحوث إلى غلبة النمط الارتجاعي: يبدأ الحركة ببرمجة ناقصة ثم يصحح ويصحح، فتخرج الحركة بطيئة متقطعة متفاوتة بين مرة وأخرى، وتنهار كلما سُحبت التغذية البصرية أو تغير السياق. هذا هو الخيط الآلي الذي يربط دروس الوحدة كلها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التخطيط والاستباق — عطل في التحضير لا في التنفيذ", "points": ["الشذوذ يتركز في زمن التحضير وبرمجته (2001).", "التنفيذ ذاته أقرب إلى السلامة متى انطلق.", "زمن الكمون حق آلي للمتعلم لا تساهل تربوي."], "text": {"head": "مرحلة التحضير هي المضطربة — نتيجة راينهارت", "body": "<p>قسّم راينهارت (Rinehart, 2001) وزملاؤه الحركة مخبريًا إلى زمن تحضير وزمن تنفيذ عند مصابين بالتوحد وآخرين، فوجدوا أن الشذوذ يتركز في مرحلة الإعداد والتخطيط: زمن تحضير أطول وبرمجة أولية أضعف، بينما تقترب خصائص التنفيذ ذاته من الطبيعي متى انطلقت الحركة. النتيجة ذات وزن عملي كبير: كثير من «بطء» متعلمك و«تردده» و«بداياته الفاشلة» ليست كسلًا ولا ضعف عضلات، بل مرحلة برمجة تحتاج زمنًا ودعمًا؛ ومن قاطع التحضير باستعجال أو كرّر الأمر بصوت أعلى لم يعالج شيئًا. احترام زمن الكمون (temps de latence) قبل الحكم على أي أداء — قاعدة ستلقاها في وحدة التعديلات — جذره العلمي هنا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التخطيط والاستباق — عطل في التحضير لا في التنفيذ", "points": ["APA: تهيؤ وضعي يسبق الحركة المخلّة بالتوازن.", "مهمة التفريغ الثنائي أظهرت تأخرها أو غيابها (2003).", "آلية واحدة من سقوط الرضيع إلى اضطراب توازن المدرسي."], "text": {"head": "التعديلات الوضعية الاستباقية — نموذج «خادم المقهى»", "body": "<p>أوضح تجليات الاستباق في الجسد هي التعديلات الوضعية الاستباقية (ajustements posturaux anticipatoires, APA): قبل أن ترفع ذراعك شيئًا ثقيلًا، يشدّ جسدك عضلات جذعه وساقيه مسبقًا حتى لا يختل توازنه بالحمل. درس شميتز (Schmitz, 2003) هذه الآلية عند أطفال التوحد بمهمة تفريغ يدين تشبه عمل خادم المقهى الذي يفرّغ صينية بيد ويثبتها بالأخرى: عند الأطفال النموذجيين تسبق تعديلات اليد المثبتة حركةَ اليد العاملة استباقًا، أما عند أطفال التوحد فتأخرت التعديلات أو غابت فاضطرب الثبات مع كل تفريغ. تذكّر أنك قابلت الآلية نفسها رضيعًا يسقط جالسًا في وحدة العلامات: خيط واحد من السنة الأولى إلى الكتابة على كرسي المدرسة، وسيظهر ثالثة في وحدة التوازن.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التخطيط والاستباق — عطل في التحضير لا في التنفيذ", "points": ["الفشل في ترتيب الخطوات لا في الخطوات ذاتها (1996).", "التغيير في السياق يبطل الخطة ويكشف اضطراب التخطيط.", "التدخل يبني التخطيط: تفكيك وتسلسل بصري وتثبيت تدريجي."], "text": {"head": "التخطيط أصل مشاكل التناسق — قراءة هيوز", "body": "<p>ربط هيوز (Hughes, 1996) بين اضطرابات التناسق عند التوحد والوظائف التنفيذية (fonctions exécutives): تسلسل بسيط ظاهريًا مثل «أمسك، اقبض، ضع» يفشل لا لأن أي حركة من الثلاث صعبة، بل لأن ترتيبها وبرمجتها في خطة واحدة هو الصعب — عسر أداء تنفيذي (dyspraxie d'origine exécutive). بهذه القراءة تصير كثير من أخطاء التناسق مفهومة: سقوط خطوة من الوسط، أو بدء من الخطوة الخاطئة، أو انهيار عند أول تغيير في السياق يبطل الخطة المحفوظة. والتدخل المقابل ليس مزيدًا من تكرار الحركة المفردة، بل بناء التخطيط نفسه: تفكيك المهمة إلى خطوات معلنة، وتسلسلات بصرية، وتثبيت خطوة قبل إضافة أختها — أدوات ستفصّلها وحدة اضطراب التخطيط التطبيقية ووحدة التعديلات.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التخطيط والاستباق — عطل في التحضير لا في التنفيذ", "points": ["إعلان الهدف والتسلسل قبل البدء يغذي التحضير.", "زمن بدء بلا مقاطعة ولا إعادة أمر.", "روتين ثابت أولًا ثم تنويع — هكذا يُبنى الاستباق."], "text": {"head": "انعكاسات على الجلسة — ابنِ الاستباق بدل مطالبته", "body": "<p>أربع قواعد جلسة تخرج بها من هذا الدرس. أولًا: أعلن هدف المهمة وتسلسلها قبل البدء (صورة أو كلمات ثابتة) فأنت تزوّد مرحلة التحضير بما تعجز عن توليده وحدها. ثانيًا: امنح زمن بدء كافيًا بلا مقاطعة ولا إعادة أمر؛ إعادة الأمر تعيد التحضير من الصفر. ثالثًا: درّب على أهداف متحركة بسرعات ثابتة متوقعة، فالهدف المتحرك يفرض التهيؤ الزمني ويبنيه لعبًا. رابعًا: ثبّت الروتينات الحركية الناجحة بتكرار حرفي أولًا قبل تنويعها، لأن الخطة المستقرة داخليًا هي تعريف الاستباق المكتسب. وكل قاعدة منها ستعود في وحدة التعديلات بصيغتها الإجرائية الكاملة.</p><p>وخامسًا: وثّق أزمنة البدء كما توثق النتائج؛ فتحسّن زمن التحضير عند متعلمك مؤشر تقدم آلي حقيقي قد يسبق تحسن أدائه الظاهر بأسابيع، وهو ما ترصده إعادة الحوصلة الدورية في وحدة التقييم المستمر من برنامجنا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الذي وجده راينهارت (2001) عند تفكيك الحركة إلى تحضير وتنفيذ عند المصابين بالتوحد؟", "الإجابة: أن الشذوذ يتركز في مرحلة التحضير والتخطيط (زمن إعداد أطول وبرمجة أولية أضعف)، بينما تقترب خصائص مرحلة التنفيذ من الطبيعي متى انطلقت الحركة."], "text": null, "take": "عطل التخطيط والاستباق يقع في تحضير الحركة لا تنفيذها؛ علاجه المهني زمن كمون محترم، وأهداف معلنة مفككة، وروتينات تثبّت البرمجة الداخلية.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 18, "title": "الانتباه — البوابة التي يمر منها كل تعلم حركي", "intro": "<p>آلية الانتباه (attention) ليست «تركيزًا» عامًا يُطلب من المتعلم بأمر، بل منظومة انتقاء وتثبيت وتحويل تحدد ما يصل إلى بقية الآليات من مادة. في هذا الدرس تتعرف على أشكال اضطرابها عند المصاب بالتوحد داخل المواقف الحركية تحديدًا، وعلى علاقتها بالحسية والوظائف التنفيذية، وعلى شروط تهيئتها التي تسبق أي تعليم ناجح.</p>", "slides": [{"kind": "cover", "title": "الانتباه — البوابة التي يمر منها كل تعلم حركي", "sub": "الوحدة الرابعة: الآليات العابرة الأربعة", "goals": ["أن تشرح الانتباه بوابةً يمر منها كل تعلم حركي", "أن تميّز انتباهًا غائبًا عن انتباه مشغول بمدخلات حسية منافسة", "أن تطبق قراءة الانتباه قبل أي حكم على فشل مهارة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l18.jpg", "img2": null}, {"kind": "slide", "title": "الانتباه — البوابة التي يمر منها كل تعلم حركي", "points": ["هشاشة: التصاق بتفصيل أو تشتت سريع أو عسر تحويل.", "تظهر حركيًا في فقدان التسلسل والخطوات والإشارات.", "إدارة الانتباه تصميم موقف لا أوامر انضباط."], "text": {"head": "انتباه هش في الموقف الحركي", "body": "<p>في الحوصلة والجلسة يظهر انتباه المصاب بالتوحد هشًا: يلتصق بتفصيل واحد من المشهد ويفقد كله، أو يتشتت عند أول مثير جانبي، أو يصعب تحويله من نشاط إلى نشاط فيعلق في السابق. بنود الانتباه البصري في البطاريات العصبية-النفسية (مثل بنود Nepsy في البحث البصري عن أهداف بين مشتتات) تقيس جانبًا من هذا في موقف مقنن، لكن قراءته الحركية اليومية أهم: متعلم يفقد مكانه في تسلسل، أو ينسى خطوة الوسط، أو لا يلاحظ تغيّر إشارة البدء. الانتباه هنا ليس مشكلة انضباط؛ إنه سعة معالجة موزعة على مشهد، وإدارتها جزء من تصميم الموقف لا من أوامر المختص.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الانتباه — البوابة التي يمر منها كل تعلم حركي", "points": ["دمج قناتين معًا صعب: معالجة أحادية القناة.", "«إذا كلمته توقف» علامة عنق معالجة لا عناد.", "قناة تعليم واحدة غالبة في كل لحظة."], "text": {"head": "معالجة أحادية القناة — مدخل واحد في كل مرة", "body": "<p>يرتبط بالانتباه نمط معالجة موثق في الأدبيات الحسية للتوحد: معالجة أحادية القناة (traitement monomodal) يصعب فيها دمج مدخلات قناتين حسيتين في وقت واحد (أن يسمع تعليمة ويرى نموذجًا وينفذ حركة معًا مثلًا)، مع عسر في النقل بين القنوات. عمليًا تعرف هذا المتعلم من جملة يقولها الممارسون: «إذا كلّمته توقف عن العمل، وإذا عمل لم يسمعني». ليس هذا عنادًا ولا سمعًا ضعيفًا؛ إنه عنق زجاجة معالجة. القاعدة التصميمية: قناة تعليم واحدة غالبة في كل لحظة — أرِه ثم اتركه يعمل صامتًا، أو قل ثم أرِه — ولا تكدّس قنواتك اعتقادًا أن الجمع يقوّي الرسالة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الانتباه — البوابة التي يمر منها كل تعلم حركي", "points": ["اضطراب التثبيط يظهر مثابرة وعسر انتقال.", "المرونة المضطربة شقيقة اضطراب التخطيط.", "إشارات انتقال معلنة ونهايات مرئية بدل الاقتلاع المفاجئ."], "text": {"head": "التثبيط والمثابرة — الوظائف التنفيذية الشقيقة", "body": "<p>إلى جانب الانتقاء يقف التثبيط (inhibition): كبح الاستجابة الجارية أو المشتتة للبقاء في المهمة. اضطرابه يظهر مثابرة (persévération): استمرار في فعل انتهى وقته، وتكرار إجابة أو حركة سابقة في موقف جديد، وعسر انتقال بين الأنشطة. تقيسه أدوات مثل اختبار ويسكونسن لفرز البطاقات وبرج هانوي في التقليد البحثي العصبي-النفسي، وتراه أنت يوميًا في متعلم لا يستطيع مغادرة نشاط محبب أو يكرر الخطوة الأولى من تسلسل في كل محاولة. التثبيط والمثابرة وجهان لمرونة (flexibilité) مضطربة، وهي شقيقة التخطيط في عائلة الوظائف التنفيذية؛ ودواؤها المهني إشارات انتقال معلنة مسبقًا ونهايات مرئية للأنشطة، لا اقتلاعًا مفاجئًا يفجّر أزمة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الانتباه — البوابة التي يمر منها كل تعلم حركي", "points": ["فرط الاستجابة يجعل المثيرات العادية أحداثًا مستهلِكة للانتباه.", "نقص الاستجابة يسرق الانتباه نحو بحث حسي دائم.", "لا قراءة انتباه قبل قراءة البروفيل الحسي."], "text": {"head": "الحسية تسرق الانتباه — فرط الاستجابة منافس داخلي", "body": "<p>منافس الانتباه الأقوى عند المصاب بالتوحد ليس مشتتًا خارجيًا فقط؛ فرط الاستجابة الحسية (hyperréactivité sensorielle) يجعل مثيرات عادية عند غيره (وميض ضوء، صوت مروحة، ملمس كرسي) أحداثًا كاملة تستهلك سعة المعالجة كلها، فيبدو المتعلم «غير منتبه» وهو في الحقيقة منتبه كليًا لشيء لا تراه أنت مهمًا. وبالعكس قد يسرق نقص الاستجابة انتباهه نحو بحث حسي دائم (حركة، ضغط، دوران). لهذا لا تُقرأ مشكلة انتباه حركية قبل سؤال البروفيل الحسي: ما الذي ينافس مهمتك داخل جسد متعلمك الآن؟ ولهذا تسبق تهيئة البيئة الحسية (تقليل المشتتات، موضع جلوس مدروس، إشباع حسي منظم قبل المهمة) أي مطالبة انتباهية عادلة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الانتباه — البوابة التي يمر منها كل تعلم حركي", "points": ["فضاء منقّى ومهام قصيرة بنهايات مرئية.", "قناة واحدة وإشارات ثابتة للبدء والانتقال والانتهاء.", "التوقيت بعد إشباع أو راحة لا في ذروة إغراق."], "text": {"head": "تهيئة الانتباه شرط أول — قواعد قبل أي تعليم", "body": "<p>أربع قواعد تهيئة تجعل مطالبة الانتباه عادلة وممكنة. نقِّ الفضاء بصريًا وسمعيًا من غير المستعمل، فكل مشتت مرئي منافس مدفوع الأجر من سعة متعلمك. قصّر المهام واجعل لكل مهمة بداية ونهاية مرئيتين، فالانتباه يُستأجر لمدد قصيرة معلومة لا يُصادَر لمدة مفتوحة. قدّم قناة واحدة غالبة كما مرّ، وثبّت إشارات البدء والانتقال والانتهاء صيغًا لا تتغير. واختر توقيت المطالبة بعد إشباع حسي منظم أو راحة، لا في ذروة إغراق أو جوع حسي. بهذه الشروط يتحول «لا ينتبه» من وصف لمتعلمك إلى سؤال عن موقفك — وهو التحول المهني الذي تبنيه هذه الدورة كلها.</p><p>وتذكّر أن الانتباه المشترك (attention conjointe) — أن يتابع متعلمك نظرك وإشارتك نحو هدف واحد — بوابة اجتماعية للانتباه الحركي كله: بلا حد أدنى منه لا يصل نموذج التقليد ولا تصل إشارة البدء؛ فبناؤه بألعاب تبادل ومتابعة أهداف متحركة واهتمامات مشتركة جزء من تهيئة الانتباه نفسها، لا ترفًا اجتماعيًا يضاف إليها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما المعالجة أحادية القناة (traitement monomodal) وكيف تظهر في الجلسة؟", "الإجابة: صعوبة دمج مدخلات قناتين حسيتين معًا (كسماع تعليمة أثناء تنفيذ حركة)؛ تظهر في توقف المتعلم عن العمل إذا كلمته، أو عدم سماعه إذا انشغل بالتنفيذ — وتستدعي قناة تعليم واحدة غالبة في كل لحظة."], "text": null, "take": "الانتباه عند المصاب بالتوحد هش وأحادي القناة ومنافَس حسيًا من الداخل؛ وتهيئته بتصميم الموقف شرط يسبق أي مطالبة تعليمية عادلة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 19, "title": "المقوّية العضلية — خلفية كل حركة", "intro": "<p>قبل أن تتحرك أي عضلة إراديًا، تكون العضلات كلها في حالة شدّ جزئي دائم اسمه المقوّية العضلية (tonus musculaire). في هذا الدرس تتعرف على أنواعها الثلاثة ووظيفة كل منها، ولماذا يبدأ فحص أي اضطراب حركي من هذه الخلفية الصامتة لا من الحركة الظاهرة.</p>", "slides": [{"kind": "cover", "title": "المقوّية العضلية — خلفية كل حركة", "sub": "الوحدة الخامسة: اضطراب المقوّية العضلية", "goals": ["أن تشرح المقوّية العضلية خلفيةً لكل حركة ووضعية وانفعال", "أن تميّز المقوّية الخلفية عن مقوّية الفعل والمقوّية المستحثّة", "أن تطبق فحص التأرجح والامتدادية قراءةً أولى لخلفية أي متعلم"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l19.jpg", "img2": null}, {"kind": "slide", "title": "المقوّية العضلية — خلفية كل حركة", "points": ["شدّ جزئي دائم في الراحة، لا انقباض إرادي.", "شرط إمكان للوقوف والجلوس ورفع الرأس.", "تُقاس بجودة الضبط والتوزيع لا بالقوة القصوى."], "text": {"head": "ما المقوّية — شدّ لا ينام", "body": "<p>المقوّية هي التوتر الجزئي الدائم في العضلات في حالة الراحة، تحافظ به على تماسك المفاصل واستعداد الجسد للفعل دون أي قرار واعٍ. بلا مقوّية لا وقوف ولا جلوس ولا حتى إبقاء للرأس مرفوعًا؛ وبمقوّية زائدة يصير كل فعل معركة ضد جسد متصلب. هي بهذا المعنى ليست حركة بل شرط إمكان الحركة، ولا تُقاس بقوة الانقباض الأقصى بل بجودة التوزيع والضبط في الراحة وأثناء الفعل. ولهذا يفتتح فحص النفسية الحركية الكلاسيكي بها: من قرأ المقوّية قرأ الأرضية التي ستقف عليها قراءته لكل ما بعدها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "المقوّية العضلية — خلفية كل حركة", "points": ["مستوى قاعدي فردي يشبه بصمة جسدية.", "يرتبط بالمزاج واليقظة والانفعال.", "تعديله مع الموقف مؤشر قصدية في الحوصلة."], "text": {"head": "المقوّية الخلفية — حالة الجسد العامة", "body": "<p>أول الأنواع المقوّية الخلفية (tonus de fond): المستوى القاعدي العام لشدّ العضلات، يختلف بين الأفراد كأنه بصمة جسدية، ويرتبط بالمزاج واليقظة والانفعال. صاحب الخلفية المرتفعة جسده «مشدود» حتى في نومه النسبي، وصاحب المنخفضة جسده «رخو» يبحث دائمًا عن سند. وقد مرّ بك في وحدة الآليات أن ملاحظة هذه الخلفية أثناء مواقف الحوصلة (وعلى الكرة الكبيرة خاصة) تعطي مؤشرًا على القصدية أيضًا، لأن تعديلها مع الموقف دليل مشاركة الجسد في الفعل لا مجرد حضوره فيه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "المقوّية العضلية — خلفية كل حركة", "points": ["توزيع شدّ لحظي يثبّت الجسد ضد الجاذبية.", "اضطرابها يجعل الثبات مهمة واعية مستنزفة.", "تتنافس مباشرة مع الكتابة والانتباه الصفي."], "text": {"head": "المقوّية الوضعية — حارسة الثبات", "body": "<p>النوع الثاني المقوّية الوضعية (tonus postural): التوزيع اللحظي للشدّ الذي يبقي الجسد ثابتًا ضد الجاذبية في كل وضعية — واقفًا أو جالسًا أو على أربع. هي التي تشدّ عضلات الجذع والرقبة بلا انتباه منك الآن وأنت تقرأ. اضطرابها يعني أن الثبات نفسه يستهلك جهدًا واعيًا عند متعلمك، فيتنافس مع كل مهمة أخرى على انتباهه وسعة معالجته: من يحارب الجلوس لا يملك كامل طاقته للكتابة. ستجد هذا النوع بطلَ وحدة التوازن والتحكم الوضعي الآتية، وحاضرًا في كل دروس هذه الوحدة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "المقوّية العضلية — خلفية كل حركة", "points": ["زيادة مضبوطة ترافق الفعل وتعود بعده للخلفية.", "اضطرابها: إفراط يكسر الأدوات أو خبوّ يفقد الأهداف.", "الأنواع الثلاثة شبكة واحدة لا جزر منفصلة."], "text": {"head": "مقوّية الفعل — شدّ يرافق الحركة", "body": "<p>النوع الثالث مقوّية الفعل (tonus d'action): الزيادة المضبوطة في الشدّ التي ترافق تنفيذ حركة مقصودة، وتتدرج مع قوة الفعل ودقته وتعود للخلفية عند انتهائه. سلامتها تعني اقتصادًا: شدّ بقدر الحاجة لا أكثر. اضطرابها يظهر في الجهتين: فعل «يفلت» بقوة زائدة (ضغط قلم يكسر السنّ أو يمزق الورقة) أو فعل يخبو قبل بلوغ هدفه (مسكة تخفّ في منتصف الحمل). وبين الخلفية والوضعية والفعل تدور أغلب صور اضطراب المقوّية التي ستصفها الدروس التالية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "المقوّية العضلية — خلفية كل حركة", "points": ["الانفعال يُقرأ في المقوّية قبل أن يُقال.", "الحوار المقوّي أول قناة تواصل إنساني.", "اضطراب التعديل يصعّب قراءة الآخرين وقراءتهم لنا."], "text": {"head": "فالون — المقوّية لغة الانفعال الأولى", "body": "<p>ربط فالون، الذي عرفته في وحدة التاريخ، بين المقوّية والانفعال ربطًا تأسيسيًا: الانفعال عنده يُقرأ أولًا في تعديلات المقوّية (شدّ الخوف وارتخاء الأمان وتصلب الغضب)، والحوار المقوّي بين الرضيع وحامله أول قناة تواصل قبل الكلام. عند المصاب بالتوحد يأخذ هذا الربط وزنًا مضاعفًا: جسد لا يعدّل مقوّيته بسلاسة هو أيضًا جسد تصعب قراءته على الآخرين ويصعب عليه قراءة أجسادهم، فتتأثر العلاقة من بابها الجسدي الأول. احتفظ بهذا الخيط؛ سيعود في درس آلية التعديل.</p><p>وتُدار المقوّية عصبيًا على مستويات متداخلة يعلوها المخيخ (cervelet) منظمًا لشدّ العضلات وحركات الأطراف والتوازن معًا، ولهذا تترافق اضطرابات المقوّية والتوازن والتناسق في ملفات متعلميك أكثر مما تفترق. كما أن المقوّية ليست قيمة ثابتة عبر اليوم: ترتفع مع اليقظة والجهد والانفعال وتنخفض مع التعب واقتراب النوم، فتوقيت ملاحظتك جزء من دقتها، ومقارنة أداء الصباح بأداء المساء بلا ضبط توقيت مقارنة مخدوعة من أساسها.</p><p>ويرتبط بالمقوّية عضو يجمع وظيفتين: الحجاب الحاجز عضلة التنفس الأولى وعضلة وضعية في الوقت نفسه، يشدّ الجذع من الداخل مع كل شهقة منظمة. لهذا يرافق اضطراب المقوّية عند كثير من متعلميك تنفس سطحي سريع في الجهد والانفعال، ولهذا أيضًا تدخل أعمال التنفس البطيء المقترن بالحركة في برامج التنظيم المقوّي لا بوصفها استرخاءً عامًا بل ضبطًا لعضلة وضعية مركزية. وحين ترى متعلمًا يحبس أنفاسه في كل مهمة دقيقة، فأنت ترى مقوّية فعل تفقد تدرجها في أعمق صورها — وسجّلها في خريطته.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الفرق بين المقوّية الوضعية (tonus postural) ومقوّية الفعل (tonus d'action)؟", "الإجابة: الوضعية توزع الشدّ لتثبيت الجسد ضد الجاذبية في وضعية ما (كالجلوس)، أما مقوّية الفعل فهي الزيادة المضبوطة المرافقة لتنفيذ حركة مقصودة، وتتدرج مع قوتها وتعود للخلفية عند انتهائها."], "text": null, "take": "المقوّية خلفية شدّ دائمة بثلاثة أوجه — خلفية عامة، ووضعية مثبّتة، وفعل مرافق مضبوط — واضطراب أي وجه منها يعيد تشكيل كل أداء فوقه.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 20, "title": "فرط المقوّية — جسد مشدود بلا استراحة", "intro": "<p>أول قطبَي اضطراب المقوّية هو فرطها (hypertonie): جسد يعيش بشدّ أعلى من حاجته، فيدفع صاحبه كلفة كل حركة وكل وضعية وكل انفعال مضاعفة. في هذا الدرس تتعرف على شكله عند المصاب بالتوحد وتأثيراته اليومية، وعلى الباراتونيا التي ترافقه كثيرًا وتُقرأ خطأً عنادًا.</p>", "slides": [{"kind": "cover", "title": "فرط المقوّية — جسد مشدود بلا استراحة", "sub": "الوحدة الخامسة: اضطراب المقوّية العضلية", "goals": ["أن تصف شكل فرط المقوّية وتأثيراته اليومية عند المصاب بالتوحد", "أن تميّز الشدّ المقوّي عن التشنج والقوة العضلية", "أن تسمّي أنشطة تنظيم أولى لملف فرط قبل أي تقوية"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l20.jpg", "img2": null}, {"kind": "slide", "title": "فرط المقوّية — جسد مشدود بلا استراحة", "points": ["مقاومة عند التحريك السلبي واتجاهات ثني غالبة.", "وضعيات خاصة موثقة: رأس مرتد ويدان بوضعيات غريبة.", "تشتد مع التعب والانفعال وتخفّ مع الأمان."], "text": {"head": "الشكل — تصلب واتجاهات خلل توتري", "body": "<p>يظهر فرط المقوّية عند المصاب بالتوحد في مقاومة محسوسة عند تحريك أطرافه سلبيًا، وفي اتجاهات خلل توتري (attitudes dystoniques) غالبة في الثني: جسد منكمش على نفسه، وأصابع منقبضة، ومشية على أطراف مشدودة. وتوثّق الأدبيات السريرية وضعيات خاصة مرافقة: رأس مرتد إلى الخلف أو مائل على جانب، واتجاهات متقوقعة، ووضعيات يدين غريبة ثابتة. هذه ليست «عادات» يقلع عنها بالتذكير؛ إنها توزيع شدّ مفروض على الجسد من نظام تعديله نفسه، يشتد مع التعب والانفعال والتغيير، ويخفّ نسبيًا في الأمان والروتين.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فرط المقوّية — جسد مشدود بلا استراحة", "points": ["استحالة إرخاء أثناء التحريك السلبي، مقاومة متزايدة.", "تُقرأ خطأً عنادًا ورفض تعاون.", "ثلاث درجات حتى الانسداد غير المُختزل."], "text": {"head": "الباراتونيا — المقاومة التي تُقرأ عنادًا", "body": "<p>رفيقة فرط المقوّية الكبرى هي الباراتونيا (paratonie): استحالة إرخاء العضلة أثناء التحريك السلبي، فيقاوم الطرف يدَ الفاحص مقاومة تزيد كلما زاد التحريك، كأن الجسد «يعارض» بإرادته. في صورها الفعلية تظهر انسدادًا أثناء العمل نفسه: يد تتجمد في منتصف فعل بسيط. تُقرأ الباراتونيا اجتماعيًا قراءة ظالمة — «يرفض التعاون»، «يعاند الفاحص» — وهي ظاهرة تعديل مقوّي لا موقف أخلاقي. تصنيفها الكلاسيكي ثلاث درجات: من ردّة فعل خفيفة مع إرخاء ممكن، إلى انسداد لا يُختزل وهو الباراتونيا الحقيقية؛ وستجد إجراءات فحصها في درس الآلية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فرط المقوّية — جسد مشدود بلا استراحة", "points": ["تعب سريع وحركات خشنة قليلة التدرج.", "كتابة مؤلمة بضغط مفرط تولّد نفورًا من القلم.", "ألم صامت قد يخرج سلوكًا، وحلقة شدّ وتوتر متبادلة."], "text": {"head": "التأثيرات — كلفة مضاعفة لكل شيء", "body": "<p>يدفع صاحب فرط المقوّية كلفة يومية مركبة: تعب سريع لأن عضلاته تعمل فوق طاقتها حتى في «الراحة»؛ وحركات خشنة قليلة التدرج تصطدم بالأشياء والأشخاص فيُوصَف بالعنف أو الإهمال؛ وكتابة بضغط مفرط يمزق الورق ويؤلم اليد فتولّد نفورًا من كل مهمة قلم؛ وألم عضلي مزمن منخفض الدرجة قد لا يجد طريقه إلى الشكوى عند غير المتكلم فيخرج سلوكًا مضطربًا يُبحث عن سببه في كل مكان إلا الجسد. وفوق ذلك حلقة انفعالية: الشدّ يولّد توترًا، والتوتر يزيد الشدّ، فتكون عتبة الأزمة عند هذا المتعلم أدنى من أقرانه دون ذنب سلوكي.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فرط المقوّية — جسد مشدود بلا استراحة", "points": ["قبضة بيضاء المفاصل وضغط منغرس وألم متكرر.", "القراءة السطحية تعاقب، وقراءة المقوّية تعالج.", "الحكم على السلوك يأتي بعد قراءة الجسد."], "text": {"head": "مثال — يد تكتب بجسد كامل", "body": "<p>تأمل متعلمًا في الثامنة: يجلس منحنيًا ممسكًا القلم بقبضة بيضاء المفاصل، يضغط حتى ينغرس الخط في الصفحات تحت الورقة، يتوقف كل سطرين ليهزّ يده من الألم، وينفجر إذا طُلبت منه فقرة ثانية. قراءة سطحية تقول: «يكره الكتابة ويتعمد التمزيق». قراءة المقوّية تقول: مقوّية فعل لا تتدرج، وباراتونيا خفيفة في الأصابع، وجسد يدفع كلفة كل حرف. التدخلان مختلفان جذريًا: الأول يعاقب ويزيد الشدّ، والثاني يعالج التدرج والوضعية وفترات التفريغ. ولهذا الترتيب — اقرأ المقوّية قبل الحكم على السلوك — تعود الدورة مرارًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فرط المقوّية — جسد مشدود بلا استراحة", "points": ["القوة العضلية ليست فرط مقوّية.", "التسمية من فحص لا من انطباع.", "فرط شديد ثابت أو علامات عصبية = إحالة طبية."], "text": {"head": "ما ليس فرط مقوّية — حدود التسمية", "body": "<p>احذر تسميتين خاطئتين: القوة العضلية العالية ليست فرط مقوّية (متعلم قوي البنية قد تكون خلفيته طبيعية تمامًا)، والحركات النمطية الاهتزازية ليست فرطًا بذاتها وإن رافقته أحيانًا. التسمية تُبنى على فحص: مقاومة التحريك السلبي، واختبارات الإرخاء والباراتونيا، وملاحظة التوزيع عبر المواقف. ومتى كان الفرط شديدًا ثابتًا أو مصحوبًا بعلامات عصبية أخرى (تراجع مهارات، نوبات، ضعف جهة واحدة) خرج الأمر عن درسنا إلى إحالة طبية عصبية واجبة، فالنفسية الحركية تعمل داخل فريق لا فوقه.</p><p>ورفيقة ثانية للفرط هي الحركات المصاحبة الفائضة: حين يعمل طرف بجهد تفيض المقوّية إلى أطراف أخرى وإلى الوجه واللسان، فترى يدًا تكتب ويدًا أخرى تنقبض بلا مهمة وفمًا يتحرك مع الأصابع. في النمو الطبيعي تتراجع هذه المصاحبات مع النضج العصبي حتى تختفي نحو الثانية عشرة، وبقاؤها الصريح بعد ذلك علامة خلل نضج عصبي-حركي تُدوَّن في الحوصلة. وعند مفرط المقوّية تكون المصاحبات أشد ظهورًا لأن «فيض» الشدّ هو طبيعة جهازه اليومية لا حادثًا عارضًا.</p><p>ولا يغيب الفرط عن منطقة الوجه والفم عند بعضهم: فكّ مشدود وصرير أسنان (bruxisme) في اليقظة أو النوم، وشدّ في عضلات الوجه يجعل التعبيرات أصلب قراءة على المحيط، فيُفهم وجه المتعلم خطأً غضبًا أو لا مبالاة وهو يعبّر بجهاز مشدود. تُدوَّن هذه العلامات في ملف المقوّية وتُحال الصريرية الشديدة إلى طب الأسنان وقائيًا، لأن كلفة الأسنان المتآكلة تُدفع سنوات بعد أن ننسى سببها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا تُعدّ قراءة الباراتونيا (paratonie) «عنادًا» خطأً مهنيًا؟", "الإجابة: لأنها ظاهرة تعديل مقوّي — استحالة إرخاء عضلي أثناء التحريك السلبي أو انسداد أثناء الفعل — لا موقف إرادي من المتعلم؛ وقراءتها عنادًا تقود إلى معاقبة جسد على اضطرابه بدل معالجة التعديل المقوّي نفسه."], "text": null, "take": "فرط المقوّية شدّ زائد وباراتونيا مقاوِمة تُقرأ ظلمًا عنادًا، وكلفته تعب وألم وكتابة مؤلمة وعتبة أزمة أدنى — ويُسمّى من الفحص لا من الانطباع.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 21, "title": "نقص المقوّية — جسد يبحث عن سند", "intro": "<p>القطب الثاني هو نقص المقوّية (hypotonie): خلفية شدّ أدنى من الحاجة، تجعل الجسد «ثقيلًا على صاحبه» وكل وضعية مشروع انهيار بطيء. في هذا الدرس تتعرف على شكله عند المصاب بالتوحد منذ السنة الأولى، وتأثيراته في التحمل واليد والانتباه، ولماذا يُقرأ خطأً كسلًا وخمولًا.</p>", "slides": [{"kind": "cover", "title": "نقص المقوّية — جسد يبحث عن سند", "sub": "الوحدة الخامسة: اضطراب المقوّية العضلية", "goals": ["أن تصف شكل نقص المقوّية وسلوكيات البحث عن السند عند صاحبه", "أن تفسّر كلفة النقص على الجلوس والتحمل والكتابة", "أن تسمّي دعائم وضعية مشروعة لا تُقرأ كسلًا عند أصحاب النقص"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l21.jpg", "img2": null}, {"kind": "slide", "title": "نقص المقوّية — جسد يبحث عن سند", "points": ["موثق منذ السنة الأولى في دراسات الأفلام العائلية.", "جلوس منهار ومسكة رخوة وبحث دائم عن سند.", "قد يجاور فرط المقوّية تحت التشخيص نفسه عند غيره."], "text": {"head": "الشكل — رخاوة تمتد من الرضيع إلى المدرسي", "body": "<p>وُثّق نقص المقوّية علامة مبكرة: أظهرت دراسة أدريان (Adrien, 1993) وزملائه على أفلام عائلية علامات نقص مقوّية في السنة الأولى عند أطفال شُخّصوا لاحقًا بالتوحد، رافقتها اضطرابات في تعبيرات الوجه. عند المدرسي يظهر النقص في جلوس ينهار تدريجيًا حتى يستلقي الرأس على الطاولة، ومسكة قلم رخوة بخط خفيف متردد، ووقوف يتكئ على كل جدار وطاولة، واتكاء دائم على الآخرين جسديًا. وفي حالات التقييم الموثقة في أدبيات التوحد تجد الحوصلة تسجل لأحدهم «مسكة راحية غير ناضجة ناقصة المقوّية» وخطًا مترددًا، بينما تسجل لآخر في الفئة نفسها فرطًا — القطبين تحت تشخيص واحد.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "نقص المقوّية — جسد يبحث عن سند", "points": ["وضعيات العمل تستنزف بسرعة، والتحمل أول الضحايا.", "تدهور منتظم داخل المهمة واستعادة بعد الراحة.", "يُسمّى خطأً دلالًا أو كسلًا أو نعاسًا."], "text": {"head": "التأثير الأول — تحمّل قصير يتنكر في صور كثيرة", "body": "<p>أثقل كلفة لنقص المقوّية هي التحمّل (endurance): عضلات خلفية ضعيفة تعني أن الحفاظ على أي وضعية عملٍ يستنزف بسرعة، فيبدو المتعلم «يتعب من كل شيء»: يكتب أسطرًا مقبولة ثم ينهار خطه، يشارك في بداية النشاط ثم ينسحب، يجلس مستقيمًا في أول الحصة ومائلًا في آخرها. يتنكر هذا التعب في أسماء مدرسية جاهزة: دلال، عدم اهتمام، نعاس، بطء متعمد. وعلامته الفارقة مهنية: الأداء يتدهور مع الزمن داخل المهمة الواحدة تدهورًا منتظمًا، بينما يستعيد جودته بعد راحة — منحنى تعب جسدي لا منحنى مزاج.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "نقص المقوّية — جسد يبحث عن سند", "points": ["مسكة غير ناضجة وخط باهت يُعاقَب مرتين.", "تعبيرات وجهية أخفت وفم مرتخٍ عند بعضهم.", "أرضية واحدة تفسّر ملامح تبدو متفرقة."], "text": {"head": "التأثير الثاني — يد ضعيفة وفم وملامح مشاركة", "body": "<p>تمتد كلفة النقص إلى اليد: مسكة غير ناضجة تبقى راحية أو بأصابع مبسوطة، وضغط قلم خفيف يجعل الخط باهتًا غير مقروء فيُعاقَب صاحب «الخط الضعيف» مرتين. وتمتد إلى الوجه والفم عند بعضهم: تعبيرات وجهية أقل وضوحًا (كما في دراسة أدريان)، وفم مفتوح في الراحة عند آخرين، وصعوبات في المضغ والنفخ تصاحب أحيانًا ملف التأخر الكلامي فيُقرأ كلٌّ منها منفصلًا عن أخيه. وحدة التفسير هنا هي الدرس: أرضية مقوّية واحدة منخفضة تفسّر ملامح متفرقة تبدو للناظر المتعجل ملفات مستقلة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "نقص المقوّية — جسد يبحث عن سند", "points": ["لفّ الساقين والاتكاء والالتصاق تعويضات ثبات وحدود.", "طلب القفز والاصطدام بحث عن إحساس عميق منشّط.", "التعويض رسالة تُقرأ ولا تُمنع قبل فهمها."], "text": {"head": "التأثير الثالث — تعويضات تُقرأ مشاكل", "body": "<p>يبتكر صاحب نقص المقوّية تعويضات ذكية تُقرأ بدورها مشاكل: يلفّ ساقيه حول قوائم الكرسي ليصنع لنفسه ثباتًا لا تمنحه عضلاته، ويتكئ بذقنه على يده أو ببطنه على حافة الطاولة، ويلتصق جسديًا بالآخرين باحثًا عن ضغط وحدود لجسده، ويطلب أنشطة القفز والاصطدام التي تمنحه دفعة إحساس عميق ترفع يقظة جهازه مؤقتًا. كل تعويض منها رسالة مقروءة: الجسد يطلب ما ينقصه بالأدوات المتاحة له. مهمة المختص أن يقرأ الطلب داخل التعويض، ثم يمنحه صورة منظمة آمنة بدل منع الصورة الفوضوية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "نقص المقوّية — جسد يبحث عن سند", "points": ["ارتخاء الأربطة ملف مستقل قد يجاور النقص.", "أسباب طبية عامة تُستبعد بالإحالة.", "التسمية من فحص وتاريخ لا من انطباع."], "text": {"head": "ما ليس نقص مقوّية — ارتخاء الأربطة وحدود أخرى", "body": "<p>فرّق بين نقص المقوّية العضلي وارتخاء الأربطة (laxité ligamentaire) الذي يُفحص باختبارات الامتدادية: قد يجتمعان وقد يفترقان، وخلطهما يفسد الخطة (تدريب الشدّ لا يصلح رباطًا مرتخيًا، وحماية المفصل لا تبني مقوّية). وفرّق أيضًا بين النقص والتعب العام أو فقر الدم أو قلة النوم — أسباب طبية عامة تستبعدها الإحالة لا الحوصلة. قاعدة الدرس: النقص يُسمّى من فحص (تأرجح وامتدادية ومقاومة وتحمل موثق) ومن تاريخ نمائي متسق، لا من انطباع «طفل هادئ بطيء».</p><p>وتمتد الكلفة إلى المفاصل نفسها: جسد ناقص المقوّية يعتمد على أربطته أكثر من عضلاته في تثبيت مفاصله، فتتكرر الالتواءات الخفيفة والآلام المفصلية بعد الجهد، ويتجنب المتعلم ألعاب الاحتكاك والجري الطويل تجنبًا يُقرأ نفسيًا وهو في جزء منه حماية مفصلية عاقلة. وفي الصورة الأوسع يقف النقص وراء تأخرات الاستحقاقات الكبرى الموثقة في مسار التوحد — ضبط رأس وجلوس ومشي متأخرة — فهو ليس وصفًا لحظيًا لمتعلمك المدرسي بل خيط يمر بتاريخه النمائي كله ويجب أن يُسأل عنه في كل حوصلة.</p><p>وفي النوم تظهر بصمة النقص أيضًا: نوم متقلب بوضعيات بحث دائمة عن تماسّ واحتكاك (متدثر بإحكام، محشور بين الوسائد أو بجانب جدار) كأن الجسد يواصل في نومه بحث يقظته عن حدود وضغط. سؤال الأهل عن وضعيات النوم سؤال حوصلة مشروع في هذا الباب، وجوابه قد يكون أول خيط خريطة التعديل كلها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما العلامة الفارقة التي تميز تعب نقص المقوّية عن «الكسل» في أداء متعلمك داخل المهمة؟", "الإجابة: منحنى الأداء: يتدهور بانتظام مع مرور الزمن داخل المهمة الواحدة (خط يضعف، وضعية تنهار) ثم يستعيد جودته بعد راحة — وهو منحنى استنزاف جسدي، لا تقلب مزاج أو رفض."], "text": null, "take": "نقص المقوّية خلفية منخفضة تجعل الثبات واليد والتحمل ضحاياها، وتولّد تعويضات ذكية تُقرأ خطأً مشاكل سلوك؛ وعلاج قراءتها أن ترى الطلب داخل التعويض.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 22, "title": "آلية التعديل المقوّي — المشكلة في الضبط لا في القطب", "intro": "<p>بعد القطبين يأتي الدرس الأهم: عند المصاب بالتوحد المشكلة العميقة ليست فرطًا ولا نقصًا ثابتين، بل تعديلًا (régulation tonique) لا يستجيب للموقف بسلاسة — المتعلم نفسه ناقص المقوّية في سياق ومفرطها في آخر. في هذا الدرس تتعرف على الآلية وحلقتها الانفعالية الحسية، وعلى كيفية فحصها بأدوات الحوصلة الكلاسيكية.</p>", "slides": [{"kind": "cover", "title": "آلية التعديل المقوّي — المشكلة في الضبط لا في القطب", "sub": "الوحدة الخامسة: اضطراب المقوّية العضلية", "goals": ["أن تشرح آلية التعديل المقوّي ولماذا المشكلة في الضبط لا في قطب واحد", "أن تميّز الباراتونيا والحركات المصاحبة المقوّية-الحركية في الفحص", "أن تفسّر مفارقة كوهن-راز الوضعية بمنطق الأنظمة البدائية"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l22.jpg", "img2": null}, {"kind": "slide", "title": "آلية التعديل المقوّي — المشكلة في الضبط لا في القطب", "points": ["القطب يتبدل عند المتعلم الواحد بحسب السياق.", "صعوبة التعديل اللحظي موثقة سريريًا.", "السؤال الصحيح عن خريطة التعديل لا عن القطب."], "text": {"head": "ما تقوله الملاحظة السريرية — قطب يتبدل بتبدل السياق", "body": "<p>تصف الأدبيات السريرية مقوّية المصابين بالتوحد بأنها مضطربة بالتقلب: علامات نقص عند بعضهم وفرط عند آخرين، وعند المتعلم الواحد بحسب السياق — فيُسجَّل لأحدهم ميل ناقص ولآخر ميل مفرط ولثالث «صعوبات ضبط» صريحة في جداول الحوصلة. وتُضاف صعوبة موثقة في تعديل المقوّية والتحكم بها لحظيًا. المعنى المهني: لا تسأل «ما قطب متعلمي؟» بل «كيف يعدّل مقوّيته عبر المواقف؟»: في الهدوء والضغط، في المألوف والجديد، في بداية الجلسة ونهايتها. خريطة التعديل عبر السياقات هي التشخيص الوظيفي الحقيقي في هذا الباب.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية التعديل المقوّي — المشكلة في الضبط لا في القطب", "points": ["حلقة متبادلة بين الانفعال والمقوّية.", "العطل في زمن العودة إلى الخلفية غالبًا.", "زمن العودة رقم يُسجَّل ويُقاس عبر الخطة."], "text": {"head": "الحلقة الانفعالية — المقوّية تنفعل والانفعال يشدّ", "body": "<p>تعود هنا حكمة فالون بثوب آلي: الانفعال يعدّل المقوّية فورًا (خوف يشدّ، أمان يرخي)، والمقوّية المعدَّلة تغيّر الإحساس بالجسد فتغذي الانفعال بدورها. عند تعديل سليم تدور الحلقة بسلاسة وتعود للخلفية؛ عند متعلمك قد تتعطل العودة: شدّ أثارته مفاجأة صغيرة يبقى مشتعلًا ساعة، أو ارتخاء انهياري بعد جهد لا يتعافى إلا بنوم. لهذا تبدو أزماته «بلا سبب» لمن يرى السبب لحظيًا فقط، بينما هي تراكم تعديلات لم تُطفأ. سجّل في ملاحظتك زمن العودة إلى الخلفية بعد كل إثارة؛ فهو رقم التدخل الأهم في هذا الباب.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية التعديل المقوّي — المشكلة في الضبط لا في القطب", "points": ["الإحساس العميق المنظم أداة تعديل في الاتجاهين.", "الإغراق الحسي يخلّ بالميزان في الاتجاهين أيضًا.", "التقلب المقوّي يُقرأ مع البروفيل الحسي دائمًا."], "text": {"head": "الحلقة الحسية — مدخلات ترفع وتخفض بلا ميزان", "body": "<p>المقوّية أيضًا ابنة المدخلات الحسية: إحساس عميق منظم يرفع اليقظة عند الناقص ويهدئ التنظيم عند المفرط، بينما إغراق لمسي أو سمعي يدفع المفرط إلى مزيد شدّ ويدفع الناقص أحيانًا إلى انسحاب انهياري. التعديل المضطرب يعني أن «الميزان» الحسي-المقوّي لا يضبط نفسه، فيحتاج المتعلم إلى منظّم خارجي: روتين حسي مقصود قبل المواقف المطلوبة، لا مفاجآت حسية أثناءها. هنا تلتقي وحدة الاضطرابات الحسية الآتية بهذا الدرس التقاءً كاملًا: كثير من «تقلبات المقوّية» ستجد مفتاحها في البروفيل الحسي لصاحبها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية التعديل المقوّي — المشكلة في الضبط لا في القطب", "points": ["تأرجح وامتدادية ودفع: الخلفية والرخاوة والوضعية.", "دمى متحركة وباراتونيا: المصاحبات والضبط.", "الكرة الكبيرة تجمع التعديل والقصدية في موقف واحد."], "text": {"head": "فحص التعديل — أدوات الحوصلة الكلاسيكية", "body": "<p>يُفحص التعديل المقوّي بمنظومة اختبارات مستقرة في الحوصلة. اختبار التأرجح (épreuve du ballant): تأرجح الأطراف بعد دفعات خفيفة يكشف الخلفية والهيمنات المقوّية. اختبار الامتدادية (extensibilité): فتح زوايا المفاصل وإغلاقها مقارنًا بين نصفي الجسد لقياس الرخاوة والمقاومة معًا. اختبار الدفع (résistance à la poussée): مقاومة الجسد لدفعات مضبوطة تكشف المقوّية الوضعية والتعديلات. الدمى المتحركة (marionnettes): تعاقب حركات متناوبة بسرعة متزايدة يكشف الحركات المصاحبة وجودة الضبط. واختبارات الباراتونيا بدرجاتها الثلاث. وتُستكمل الصورة بمواقف الكرة الكبيرة حيث تظهر التعديلات الوضعية والقصدية معًا في فعل واحد.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية التعديل المقوّي — المشكلة في الضبط لا في القطب", "points": ["الحكم فقرة خريطة تعديل لا كلمة قطب واحدة.", "تتضمن المثيرات القلبية وزمن العودة ومواقف النجاح.", "إعادة الحوصلة تقيس تقدم التعديل نفسه."], "text": {"head": "من الفحص إلى الحكم — خريطة لا كلمة واحدة", "body": "<p>ناتج الفحص الجيد ليس كلمة «فرط» أو «نقص» في خانة، بل فقرة خريطة: الخلفية الغالبة، والقطب الذي يظهر تحت الضغط، وزمن العودة، والمثيرات التي تقلب الميزان في الاتجاهين، والمواقف التي يعدّل فيها بنجاح. على هذه الخريطة تُبنى توصيات الدرس التالي وأهداف أي خطة، وبها تقارن إعادة الحوصلة بعد أشهر لتقيس تقدم التعديل نفسه — لا أداء مهمة واحدة. وهذا هو معنى «لا وصفة بلا تقييم» في باب المقوّية: نشاط يرفع مقوّية متعلم قد يفجّر شدّ متعلم آخر يشاركه اسم التشخيص.</p><p>ويلحق بالفحص باب المقوّية المستحثّة (tonus induit): الحركات المصاحبة بنوعيها — مقوّية-حركية تحاكي حركة الطرف الفاعل، وانتشار مقوّي يفيض إلى الوجه والشفتين والأصابع — وتُقرأ باختبارات تعاقب الحركات المتناوبة بسرعة متزايدة (الدمى المتحركة نفسها بقراءة ثانية): جودتها وتعبها واستحالتها درجات نضج عصبي-حركي. فالدمى عند الفاحص الجيد اختبار مزدوج: تضبط إيقاع الحركة المتناوبة من باب، وتكشف نظافة التوزيع المقوّي من باب آخر — وادّخار الاختبار الواحد لقراءتين عادة الحوصلة الاقتصادية الراقية.</p><p>وسجّل أخيرًا أن التعديل يتبدل بالمخاطَب والمهمة: متعلم يعدّل بنجاح مع مختص مألوف في مهمة محببة، وينهار تعديله مع غريب أو في مهمة مكروهة — فخريطته ليست رقمًا واحدًا بل جدول سياقات. ابنِ فحصك على ثلاثة سياقات على الأقل (مألوف/جديد، محبب/مفروض، بداية جلسة/نهايتها) قبل أن تكتب فقرة حكمك، فالحكم من سياق واحد أشهر أخطاء هذا الباب وأسهلها اجتنابًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما المؤشر الكمي الأهم الذي تنصح الدرس بتسجيله في ملاحظة متعلم مضطرب التعديل المقوّي؟", "الإجابة: زمن العودة إلى المقوّية الخلفية بعد كل إثارة أو جهد؛ فهو يقيس سلامة التعديل نفسه، ويُبنى عليه أثر الخطة عند إعادة القياس."], "text": null, "take": "اضطراب المقوّية العميق عند المصاب بالتوحد اضطراب تعديل — قطب يتبدل بالسياق وحلقات انفعالية وحسية لا تُطفأ بسلاسة — ويُفحص بمنظومة التأرجح والامتدادية والدفع والدمى والباراتونيا لينتج خريطة لا كلمة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 23, "title": "أنشطة المقوّية وتوصياتها — تنظيم قبل تقوية", "intro": "<p>توصيات وأنشطة لاضطرابات المقوّية عند المصاب بالتوحد. قاعدتها الأولى أن الهدف تنظيم التعديل لا «تقوية العضلات» عمومًا؛ وكل نشاط فيها يخرج من خريطة تعديل موثقة، ويُقدَّم ببطاقة عناصر كاملة، ويُقاس أثره بزمن العودة وجودة الأداء الذي بعده.</p>", "slides": [{"kind": "cover", "title": "أنشطة المقوّية وتوصياتها — تنظيم قبل تقوية", "sub": "الوحدة الخامسة: اضطراب المقوّية العضلية", "goals": ["أن تبني أنشطة تنظيم مقوّي قبل أي هدف تقوية أو مهارة", "أن تطبق بطاقة نشاط مقوّية كاملة بعناصرها العشرة", "أن تقيس أثر التنظيم المقوّي بمؤشرات تحمل ووضعية قابلة للعدّ"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act1_img1.webp", "img2": null}, {"kind": "slide", "title": "أنشطة المقوّية وتوصياتها — تنظيم قبل تقوية", "points": ["الاختيار باتجاه التعديل اللحظي لا باسم الاضطراب.", "الإحساس العميق مدخل ملكي، والإيقاع والمقاومة جرعة.", "ختم النشاط بعودة إلى وضعية العمل شرط الانتقال."], "text": {"head": "مبادئ قبل الأنشطة — خمس قواعد حاكمة", "body": "<p>أولًا: النشاط يُختار باتجاه التعديل المطلوب في هذا الوقت من يوم هذا المتعلم (رفع يقظة ناقص صباحًا، تهدئة مفرط قبل مهمة دقيقة)، لا باسم الاضطراب وحده. ثانيًا: المدخل الملكي هو الإحساس العميق (proprioception) — دفع وشد وحمل وضغط — لأنه المنظّم الأقل إثارة والأوسع قبولًا. ثالثًا: الإيقاع البطيء المنتظم يهدئ، والجهد المتدرج المقاوم ينشّط؛ فاضبط إيقاع نشاطك ومقاومته كأنك تضبط جرعة. رابعًا: كل نشاط تنظيمي يُختم بعودة مقصودة إلى وضعية العمل، وإلا بقي أثره لعبًا لا ينتقل. خامسًا: لا نشاط مقوّيًا بلا قراءة خريطة التعديل، فالنشاط الواحد دواء لمتعلم وسمّ تنظيمي لآخر.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة المقوّية وتوصياتها — تنظيم قبل تقوية", "points": ["حمل ودفع وشد وزحف بمقاومات متدرجة حقيقية.", "دفعات قصيرة قبل مهام الجلوس لرفع اليقظة.", "تعديلات صفية: قدم ثابتة وفواصل قبل ذروة التعب."], "text": {"head": "مع ناقص المقوّية — أنشطة الرفع والتحمل", "body": "<p>لصاحب الخلفية المنخفضة تُبنى الأنشطة على جهد مقاوم متدرج: حمل أشياء حقيقية بأوزان متصاعدة (سلة كتب، قارورات ماء)، ودفع جدار بالكفين أو دفع عربة محملة، وشدّ حبل أو أشرطة مقاومة، وزحف وتسلق بأثقال خفيفة آمنة. تُقدَّم في دفعات قصيرة متكررة قبل مهام الجلوس والكتابة لرفع اليقظة، وتُبنى أهداف التحمل أسبوعيًا (زمن وضعية سليمة قبل الانهيار). وفي الصف ترافقها تعديلات: كرسي بارتفاع يثبّت القدمين، وفواصل حركة مجدولة قبل ذروة التعب لا بعدها، ومسكة قلم أعرض تخفف كلفة القبضة الرخوة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة المقوّية وتوصياتها — تنظيم قبل تقوية", "points": ["ضغط عميق بطيء وإيقاع هادئ ودحرجة مسنودة.", "تدريب طيف الشدّ بحركات كاملة بطيئة.", "تفريغ قصير قبل الكتابة، ولا إحماء عنيفًا مفاجئًا."], "text": {"head": "مع مفرط المقوّية — أنشطة التهدئة والتدرج", "body": "<p>لصاحب الفرط يُبنى العمل على خفض الخلفية وتدريب التدرج: ضغط عميق بطيء (تدليك كرات ثابتة، لفّ آمن ببطانية بضغط مضبوط وبموافقة ومراقبة)، وأنشطة إيقاعية بطيئة (أرجوحة هادئة، دحرجة بطيئة على كرة كبيرة مع سند)، وتنفس مقترن بحركة ممتدة، وحركات بمدى كامل بطيئة ضد مقاومة خفيفة تُعلّم العضلة طيف الشدّ لا طرفه الأقصى. وقبل الكتابة تحديدًا: تفريغ مقوّي قصير (عصر كرة إسفنجية شديدة، ضغط كفين متعاكسين) ثم قلم بمسكة مريحة وفترات إرخاء يد مجدولة. ويُمنع عنه الإحماء العنيف المفاجئ الذي يرفع الشدّ أكثر.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة المقوّية وتوصياتها — تنظيم قبل تقوية", "points": ["هدف قابل للقياس وخطوات وتدرج وقياس أسبوعي.", "النشاط موقوت قبل حصة الكتابة ليظهر انتقال أثره.", "الأمان والأوزان المتدرجة شرطان لا زخارف."], "text": {"head": "بطاقة نشاط كاملة — «ساعي البريد الحمّال»", "body": "<p>المجال: المقوّية الخلفية والتحمل الوضعي. الهدف القابل للقياس: أن ينقل المتعلم 6 أكياس رمل (1-2 كغ) عبر مسار 8 أمتار ذهابًا وإيابًا دون إسقاط، محافظًا على جذع مستقيم، في 4 من 5 محاولات. الأدوات: أكياس رمل متدرجة، سلّتا بداية ونهاية، علامتا مسار أرضية. الإعداد: مسار خالٍ، الكيس الأول بوزن ينجح فيه المتعلم من أول مرة. الخطوات: يختار الكيس، يحمله بكلتا يديه أمام بطنه، يمشي على العلامات، يضعه في سلة النهاية، يعود للكيس التالي. التدرج: أخف/أقصر/بحمل ثنائي مع مختص، إلى أثقل/أطول/بنقلة واحدة على الرأس بوسادة توازن لاحقًا. التنويع: توصيل «طرود» بأسماء زملاء لربطه اجتماعيًا. الأمان: أوزان دون إجهاد مفصلي، إيقاف عند ألم، أرضية غير زلقة. التكرار: 3 مرات أسبوعيًا قبل حصة الكتابة. القياس: عدد النقلات السليمة وزمن الجلوس الجيد بعدها. مؤشر النجاح: بلوغ الهدف أسبوعين متتاليين ثم رفع الوزن درجة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة المقوّية وتوصياتها — تنظيم قبل تقوية", "points": ["القياس في الأداء التالي للنشاط لا داخله.", "مراجعة ستة أسابيع وتعديل متغير واحد كل مرة.", "نسخة بيتية آمنة تعمّم التعديل على اليوم كله."], "text": {"head": "القياس والمتابعة — أثر يُرى في الأداء التالي", "body": "<p>قياس أنشطة المقوّية يكون خارج النشاط نفسه: زمن الجلوس بوضعية مقبولة في الحصة التالية، وجودة خط الكتابة في أول عشرة أسطر بعد النشاط مقارنة بقبلها، وزمن العودة إلى الهدوء بعد إثارة معتادة، وعدد مرات الانهيار الوضعي في اليوم. سجّل هذه المؤشرات أسبوعيًا على الخريطة نفسها، وراجع كل ستة أسابيع: إن لم يتحرك مؤشران على الأقل، فالخلل في جرعة النشاط أو توقيته أو في قراءة الخريطة أصلًا — عدّل واحدًا منها في كل مرة لتعرف أيها كان السبب. ووثّق للأسرة نسخة بيتية من الأنشطة الآمنة فقط، بتوقيتاتها، لتعمّم التعديل على اليوم كله لا على جلستك وحدها.</p><p>تنبيه جرعة أخير قبل أن تبدأ: الأوزان والمقاومات عند المتعلمين ليست أرقام كبار مصغّرة؛ ابدأ دائمًا من وزن ينجح فيه المتعلم من المحاولة الأولى، ولا ترفع إلا درجة واحدة بعد أسبوعي نجاح موثقين، وأوقف عند أي ألم مفصلي معلن أو ملحوظ. فالنشاط الذي يؤلم مرة واحدة يخسر ثقة الجسد الذي تعمل على تنظيمه، وخسارة الثقة في هذا الباب أغلى من أي تأخر في التدرج.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يُقاس نجاح نشاط مقوّي في الحصة التي تلي النشاط (كالكتابة) لا داخل النشاط نفسه؟", "الإجابة: لأن هدف النشاط هو تعديل حالة المقوّية بما ينتقل أثره إلى الأداء الحقيقي المطلوب (جلوس وكتابة وهدوء)؛ أما إتقان النشاط ذاته فقد يتحسن بالممارسة دون أي انتقال تنظيمي."], "text": null, "take": "أنشطة المقوّية تنظيم موجّه بخريطة تعديل: إحساس عميق وإيقاع ومقاومة مضبوطة كجرعة، تُقاس فاعليتها في الجلوس والكتابة والهدوء الذي يعقبها.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 24, "title": "مفهومان لا مفهوم واحد — خريطة الجسد وصورته", "intro": "<p>يخلط كثيرون بين المخطط الجسدي (schéma corporel) وصورة الجسم (image du corps) كأنهما اسمين لشيء واحد، والخلط يفسد التقييم والخطة معًا. في هذا الدرس تتعرف على المفهومين وتمييزهما الدقيق: الأول تمثيل حسي-حركي يُبنى بالحركة والإحساس، والثاني تمثيل نفسي-وجداني يُبنى بالعلاقة والكلام ونظرة الآخر.</p>", "slides": [{"kind": "cover", "title": "مفهومان لا مفهوم واحد — خريطة الجسد وصورته", "sub": "الوحدة السادسة: اضطراب المخطط الجسدي وصورة الجسم", "goals": ["أن تميّز المخطط الجسدي تمثيلًا حسيًا-حركيًا عن صورة الجسم تمثيلًا نفسيًا-وجدانيًا", "أن تشرح مصدر كل مفهوم عند أصحابه (هيد ودولتو)", "أن تطبق التمييز في قراءة شكاوى جسدية مختلطة البابين"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l24.jpg", "img2": null}, {"kind": "slide", "title": "مفهومان لا مفهوم واحد — خريطة الجسد وصورته", "points": ["تمثيل لحظي لوضعية الأجزاء في الفضاء.", "تغذّيه الحواس العميقة ويعمل صامتًا تحت الحركة.", "يُقاس بالأداء العملي لا بالكلام عن الجسد."], "text": {"head": "المخطط الجسدي — تمثيل عامل صامت", "body": "<p>المخطط الجسدي هو التمثيل الداخلي المتجدد لحظة بلحظة لوضعية أجزاء الجسد بعضها إلى بعض وفي الفضاء، يغذّيه الإحساس العميق والدهليزي واللمسي والبصري، ويعمل صامتًا تحت كل حركة: به تعرف أين يدك دون أن تنظر إليها، وكم تبعد قدمك عن الدرجة التالية. وصفه أجورياغيرا (Ajuriaguerra) بأنه بنية حية تُراجع باستمرار بفعل الحركة ذاتها؛ فالحركة تبني المخطط والمخطط يوجّه الحركة في حلقة نمو دائمة. هو إذن معرفة عملية بالجسد، تُقاس بالأداء لا بما يقوله صاحبها عن جسده.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مفهومان لا مفهوم واحد — خريطة الجسد وصورته", "points": ["تمثيل نفسي-وجداني لا واعٍ عند دولتوه.", "يُبنى بنظرة الآخر وكلامه وحدوده منذ الطفولة.", "يتكلم في الرسم واللعب الرمزي والعلاقة لا في الأداء وحده."], "text": {"head": "صورة الجسم — تمثيل يُروى ويُعاش", "body": "<p>صورة الجسم عند دولتوه (Dolto) صورة لا واعية (image inconsciente du corps): التمثيل النفسي-الوجداني الذي يحمله كل فرد عن جسده، مشكَّلًا من تاريخه العلائقي منذ الطفولة الأولى — من نظرات حامليه وكلامهم عنه ولمساتهم وحدودهم. هي ليست ما يراه في المرآة؛ فقد يرى جسدًا صحيح الأجزاء ويعيشه غريبًا أو مكروهًا أو غير موجود أصلًا. وتتحدث صورتُه في أحلامه ورسومه ولعبه الرمزي وعلاقته بالآخرين. ميدانها الأول النفساني والتحليلي، لكن النفسي الحركي يلتقيها كل يوم لأنها تسكن الجسد الذي يعمل عليه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مفهومان لا مفهوم واحد — خريطة الجسد وصورته", "points": ["المخطط المضطرب عمله حسّي-حركي، والصورة المضطربة عملها علائقي.", "الخلط ينتج خططًا تعالج الملف الخطأ.", "في الحوصلة فقرتان منفصلتان لبابين مختلفين."], "text": {"head": "لماذا يهمّ التمييز مهنيًا", "body": "<p>التمييز يقرر التدخل: متعلم لا يجد ركبته بعينين مغمضتين مشكلته مخطط — عمله حسّي-حركي (تحديد، تسمية أثناء الفعل، خرائط جسد). ومتعلم يعرف كل أجزائه ويؤدي بها لكنه يخفي جسده ويرفض المرآة ويضطرب من صوره مشكلته صورة — عمله علائقي رمزي وحدوده عند تخصص آخر يقود الملف. الخلط بينهما ينتج خططًا عبثية: تمارين تعيين أجزاء لمن يعرفها ويكرهها، أو حديث وجداني مطوّل لمن لا يملك خريطة جسده أصلًا. في الحوصلة يُفحص الاثنان ويُكتبان في فقرتين منفصلتين، لأن لكل منهما باب تدخل مختلفًا وفريقًا مختلفًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مفهومان لا مفهوم واحد — خريطة الجسد وصورته", "points": ["المخطط يُبنى بالحركة والتسمية من الأسفل.", "الصورة تُبنى بالحمل والنداء والحدود من العلاقة.", "عوائق التوحد تصيب البناءين ويجرّ كلٌّ منهما الآخر."], "text": {"head": "كيف يُبنى الاثنان في النمو", "body": "<p>يُبنى المخطط من الأسفل إلى الأعلى عبر النمو: تعديلات مقوّية ووضعية أولى، ثم استكشاف فموي ويدوي، ثم تقليد وحركات موجّهة، ثم تسمية لغوية تثبّت الخريطة («هذه ركبتك»)، ثم تمثيل مرسوم ومجسّم. وتُبنى الصورة بالتوازي من الأعلى العلائقي: جسد يُحمل ويُنادى ويُحدَّد بحدود محترمة يصير «لي» وآمنًا وقابلًا للسكن. عند المصاب بالتوحد يتعرض البناءان معًا لعوائق ستفصّلها الدروس التالية: مدخلات حسية مشوشة تضعف الخريطة، وتواصل علائقي مضطرب يضعف الصورة، وكل ضعف في أحدهما يجرّ الآخر معه لأن الجسد واحد.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مفهومان لا مفهوم واحد — خريطة الجسد وصورته", "points": ["عمق الدورة في المخطط، ومعالجة عملية للصورة.", "حدود الإحالة والعمل المشترك جزء من الخطة.", "معرفة نهاية الميدان علامة كفاءة لا نقص."], "text": {"head": "حدود الدرس داخل الدورة", "body": "<p>ستعمل الدروس التالية بعمق في المخطط — فحصًا وآلية وأنشطة — لأنه ميدان النفسي الحركي الأصيل، وستعالج الصورة بما يحتاجه الممارس: التعرف على علاماتها، وفهم آليتها، والأنشطة الداعمة داخل الجلسة الحركية، وحدود الإحالة والعمل المشترك. هذا التوزيع نفسه درس مهني: المختص الكفء يعرف أين ينتهي ميدانه ليبدأ ميدان زميله، ويكتب ذلك في خطته صراحة بدل التوسع الصامت في كل اتجاه.</p><p>تاريخيًا التقى المفهومان في الأدبيات من بابين مختلفين يؤكد تمييزهما: المخطط جاء من العصبية مع نموذج هيد (Head) الوضعي الذي يجدد نفسه بكل حركة واردة، والصورة جاءت من التحليل النفسي حتى صاغتها دولتوه صورة لا واعية تحمل آثار العلاقات الأولى. وبين النموذجين وقف أجورياغيرا بمشروعه الجامع: جسد يُعاش ويُمثَّل في النفسية الحركية بوصفها علم الجسد في علاقته بالنفس، فلا يُختزل إلى خريطة أعصاب ولا إلى رمز نفسي. أن تعرف أصل كل مفهوم من بابه هو أن تعرف لماذا لا يصلح أحدهما بديلًا عن الآخر في تقريرك.</p><p>واحمل من الدرس سؤالين فارقين تلخّص بهما التمييز في أي موقف عيادي: «أين يقع هذا الجزء وكيف أستعمله؟» سؤال مخطط يُجاب بالأداء الصامت الدقيق، و«كيف أعيش هذا الجسد وأقدّمه للعالم؟» سؤال صورة يُجاب بالسلوك والرسم والعلاقة. متى اختلط عليك ملف متعلم، أعد طرح السؤالين وفرز إجاباته عليهما؛ فأغلب الالتباس في هذا الباب يذوب حين تُفرز المادة على سؤالين لا على انطباع واحد كبير.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: متعلم يؤدي كل مهام تعيين أجزاء الجسد بنجاح لكنه يرفض النظر في المرآة ويخفي جسده باستمرار؛ أين يقع ملفه الأرجح؟", "الإجابة: في صورة الجسم لا في مخططه؛ فخريطته الحسية-الحركية عاملة بشهادة الأداء، والاضطراب في تمثيله الوجداني لجسده — وبابه علائقي وبقيادة تخصص نفسي، مع دعم حركي مرافق."], "text": null, "take": "المخطط الجسدي خريطة حسية-حركية عاملة تُقاس بالأداء، وصورة الجسم تمثيل وجداني لا واعٍ يُبنى بالعلاقة؛ والتمييز بينهما يوجّه الفحص والخطة والفريق.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 25, "title": "اضطراب المخطط الجسدي — حين تضيع خريطة الجسد", "intro": "<p>حين تضعف خريطة الجسد الداخلية، يعيش المتعلم في جسد لا يعرف حدوده ولا مواضع أجزائه بدقة. في هذا الدرس تتعرف على أشكال اضطراب المخطط الجسدي (schéma corporel) عند المصاب بالتوحد في المهام اليومية، وتأثيراته التي تمتد من اللبس والأكل إلى تحديد موضع الألم نفسه.</p>", "slides": [{"kind": "cover", "title": "اضطراب المخطط الجسدي — حين تضيع خريطة الجسد", "sub": "الوحدة السادسة: اضطراب المخطط الجسدي وصورة الجسم", "goals": ["أن تصف أشكال اضطراب المخطط الجسدي: تعرّفًا وتعيينًا وحدودًا", "أن تميّز أخطاء الخريطة عن أخطاء الانتباه والفهم", "أن تقرأ اصطدامات المتعلم المتكررة بياناتِ خريطة لا خراقة شخصية"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act69_img2.webp", "img2": null}, {"kind": "slide", "title": "اضطراب المخطط الجسدي — حين تضيع خريطة الجسد", "points": ["ثلاث عمليات: تعرّف وتعيين وتسمية متدرجة.", "الأجزاء الدقيقة والمواضع على الآخر أول الضحايا.", "إغماض العينين يكشف الاعتماد على البصر بديلًا للخريطة."], "text": {"head": "الشكل الأول — تعرّف وتعيين وتسمية ناقصة", "body": "<p>يُفحص المخطط تقليديًا بثلاث عمليات متدرجة: التعرّف (reconnaissance) أن يشير المتعلم إلى الجزء المسمّى، والتعيين (désignation) أن يحدّد موضعه على جسده وجسد الآخر ونموذج مجسّم، والتسمية (dénomination) أن يسمّي الجزء المشاهَد. عند مضطرب المخطط تختل النتائج بنمط دال: أجزاء كبرى معروفة (رأس، يد) ودقيقة ضائعة (كوع، كعب، معصم)، وأجزاء يعرفها على نفسه ويضيّعها على الآخر أو العكس، وأداء ينهار بعينين مغمضتين لأنه كان يستعير الخريطة من البصر. بطاقات المتابعة الميدانية في الممارسة العربية تبني شبكات حوصلة الجسد على هذا التدرج نفسه: تعرّف وتعيين وتسمية، على النفس والمرآة والآخرين.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "اضطراب المخطط الجسدي — حين تضيع خريطة الجسد", "points": ["اصطدام بالأطر وتقدير خاطئ للممرات والمسافات.", "اختراق مسافات الآخرين بحثًا عن حدّ محسوس.", "تردد عند الانتقالات لإعادة حساب خريطة ضبابية."], "text": {"head": "الشكل الثاني — حدود جسد غير مرسومة", "body": "<p>من لا يملك خريطة دقيقة لا يملك حدودًا محسوسة: يصطدم بأطر الأبواب والأثاث كأن جسده أعرض أو أضيق مما هو، ويقدّر خطأً إن كان يمرّ من فتحة ما، ويجلس «خارج» الكرسي جزئيًا، ويقترب من الآخرين مسافة تخترق حدودهم دون قصد اجتماعي — يبحث جسده عن حدّ يلمسه ليتحقق من مكانه. وتظهر في الحركة ترددات عند الانتقالات (عتبات، درجات، تغير أرضية) لأن كل انتقال يتطلب إعادة حساب خريطة غير ثابتة أصلًا. كثير من «الحماقة الحركية» المشهورة في التوحد تُقرأ هنا قراءة مختلفة: خريطة ضبابية لا إهمال.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "اضطراب المخطط الجسدي — حين تضيع خريطة الجسد", "points": ["لبس معكوس ومهام خارج النظر تخفق.", "أكل فوضوي بإدارة بصرية دائمة.", "عسر تحديد موضع الألم خطر سلامة موثق الكلفة."], "text": {"head": "التأثيرات اليومية — لبس وأكل وسلامة", "body": "<p>تظهر الكلفة في مهام الحياة: لبس مقلوب أو معكوس الترتيب لأن تسلسل الأجزاء غير ممثَّل، وصعوبة في الأزرار والسحّابات الموضوعة خارج النظر (خلف الظهر، تحت الذقن) لأنها مهام خريطة صِرفة، واتساخ وجه وملابس أثناء الأكل لأن موضع الفم واليدين في الفضاء يُدار بصرًا بلا توقف. وأخطر الكلفات سلامةً: عسر تحديد موضع الألم وتسميته — متعلم يشير إلى جسده كله أو يصمت عن ألم حاد، فيتأخر اكتشاف التهاب أو كسر. لهذا يُدرَّب تحديد موضع الأحاسيس وتسميتها في خطط المخطط بوصفه مهارة سلامة لا مهارة معرفية فقط.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "اضطراب المخطط الجسدي — حين تضيع خريطة الجسد", "points": ["انهيار التعيين للأجزاء الدقيقة والخفية.", "الخطة بناء خريطة لا محاضرات نظافة.", "«الإهمال» قد يكون مخططًا ضبابيًا متنكرًا."], "text": {"head": "مثال — الفتى الذي «لا يحسّ بملابسه»", "body": "<p>فتى في العاشرة يصفه فريقه بأنه «مهمل»: قميصه مقلوب كل يوم تقريبًا، ووجهه ملطخ بعد كل وجبة، ويصطدم بباب القسم حتى صار مزحة زملائه. فحص المخطط أظهر: تعرّف سليم للأجزاء الكبرى، وتعيين منهَار للأجزاء الدقيقة وللأجزاء على ظهره وجانبيه، ورسم إنسان بلا رقبة ولا معصمين. الخطة لم تكن محاضرات نظافة بل بناء خريطة: تسمية أثناء اللبس، ألعاب تحديد بعينين مغمضتين، خرائط جسد مرسومة وملصقة، ومرآة كاملة في روتين الصباح. بعد أشهر صار القميص المقلوب حدثًا نادرًا — لأن «الإهمال» كان خريطة، والخرائط تُبنى.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "اضطراب المخطط الجسدي — حين تضيع خريطة الجسد", "points": ["الحس العميق يتحسن بالمقاومة، والمخطط يضيع حتى ساكنًا.", "الانتباه يتفكك مع طول الموقف وتشتته.", "ترتيب ثقل الأبواب يرتب الخطة."], "text": {"head": "التفريق — مخطط أم حس عميق أم انتباه؟", "body": "<p>ثلاثة أبواب تفسر وحدها أعراضًا متشابهة ففرّق بينها قبل التسمية: مضطرب الحس العميق يضيّع أجزاءه تحت الحمل والحركة ويتحسن بالضغط والمقاومة، ومضطرب المخطط يضيّعها حتى ساكنًا مرتاحًا وفي التمثيل المرسوم، ومضطرب الانتباه يؤدي جيدًا في موقف قصير مركز ويتفكك في المواقف الطويلة المشتتة. الفحص المحكم يمرّ بالثلاثة: مهام ساكنة بعينين مغمضتين للمخطط، ومهام تحت مقاومة للحس العميق، وتكرار عبر زمن للموقف للانتباه. والواقع العيادي أن الأبواب تجتمع كثيرًا، لكن ترتيب ثقلها يغيّر ترتيب الخطة.</p><p>ومنطقته العمياء الأكبر هي الظهر: أجزاء لا يراها صاحبها أبدًا (ظهر وكتفان خلفيان ومنطقة ما بين اللوحين) تُبنى خريطتها باللمس والحركة وحدهما، فتتأخر عند الجميع وتغيب كليًا عند مضطرب المخطط — ومنها تُفهم إخفاقات حقيبة الظهر وربطات ما خلف العنق وملابس تُلبس من الخلف. ويلحق بها تمثيل الجانبية داخل المخطط: جزء أيمن وأيسر متماثلان الشكل مختلفا التمثيل عند كثير من متعلميك، فتجد تعيينًا سليمًا في جهة ومنهارًا في أختها، وهي قرينة مبكرة على ملف الجانبية الذي ستفتحه وحدة الحركة الدقيقة والجانبية لاحقًا.</p><p>ولهذا يُدرج في خطط المخطط هدف سلامة صريح: أن يحدّد المتعلم موضع إحساس جديد (ألم، حرارة، ضغط) على خريطة جسد مرسومة وعلى جسده، وأن يستعمل إشارة أو كلمة متفقًا عليها لطلبه. يُبنى هذا الهدف بأنشطة اللمس والتحديد نفسها مع تسميات إحساس لا أجزاء فقط، ويُقاس بمواقف حقيقية موثقة عند حدوثها — وهو من الأهداف القليلة التي قد تغيّر نتيجة طبية في حياة متعلمك فعلًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يُعدّ إغماض العينين كاشفًا مهمًا في فحص المخطط الجسدي؟", "الإجابة: لأنه يسحب التعويض البصري الذي يستعير به المتعلم خريطته من النظر؛ فمن كان أداؤه سليمًا بعينين مفتوحتين وانهار مغمضًا، خريطته الداخلية ضعيفة مهما بدا أداؤه الظاهر مقبولًا."], "text": null, "take": "اضطراب المخطط الجسدي خريطة ضبابية تظهر في التعيين والتسمية والحدود واللبس وتحديد الألم؛ ويُفرَّق عن الحس العميق والانتباه بفحص مصمَّم، لأن لكل باب خطة مختلفة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 26, "title": "اضطراب صورة الجسم — الجسد كما يُعاش من الداخل", "intro": "<p>قد تكون الخريطة سليمة والصورة مضطربة: متعلم يعرف جسده جزءًا جزءًا لكنه يعيشه غريبًا أو مهدِّدًا أو غير جدير بالظهور. في هذا الدرس تتعرف على أشكال اضطراب صورة الجسم (image du corps) عند المصاب بالتوحد وتأثيراتها، وحدود عمل النفسي الحركي معها بلا تجاوز لميدان النفساني.</p>", "slides": [{"kind": "cover", "title": "اضطراب صورة الجسم — الجسد كما يُعاش من الداخل", "sub": "الوحدة السادسة: اضطراب المخطط الجسدي وصورة الجسم", "goals": ["أن تصف اضطراب صورة الجسم عند أصحاب التوحد ومظاهره اليومية", "أن تميّز صورة هشّة عن باب نفسي أوسع يستحق الإحالة", "أن تحترم حدود صاحب الجسد في أي قراءة أو نشاط يمس صورته"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l26.jpg", "img2": null}, {"kind": "slide", "title": "اضطراب صورة الجسم — الجسد كما يُعاش من الداخل", "points": ["مرآة متجنَّبة أو مشغول بها مفرطًا أو لامبالية شاذة.", "رفض صور الذات أو عدم تعرّفها.", "حياء غائب كليًا أو حساسية نظرات حادة — الطرفان قرينة."], "text": {"head": "الشكل — مرآة وصور وآخرون", "body": "<p>تظهر صورة الجسم في ثلاث ساحات قابلة للملاحظة. المرآة: تجنّب كامل لها، أو انشغال مفرط بها، أو لا مبالاة بجسد منعكس عند من يهتم بكل انعكاس آخر — أنماط تخرج عن فضول الأقران المعتاد. الصور الفوتوغرافية: رفض التصوير، أو تمزيق الصور الشخصية، أو عدم تعرّف الذات فيها عند الصغار بدرجة تفوق تأخرهم العام. الآخرون: حساسية حادة لنظراتهم وتعليقاتهم على الجسد، أو على العكس غياب أي حياء جسدي متوقع عمرًا لأن «نظرة الآخر» غير مسكونة أصلًا في تمثيل الجسد. كل نمط منها قرينة تُجمع ولا تُحسم فرادى.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "اضطراب صورة الجسم — الجسد كما يُعاش من الداخل", "points": ["تجنّب أنشطة جسدية يفاقم ضعف المخطط والمهارة.", "ملابس درعية وتغيّرات نمائية مهزّة لتمثيل هش.", "سلوكيات جسدية محيّرة قد تكون لغة صورة مضطربة."], "text": {"head": "التأثيرات — تجنب وحماية واجتماع متعثر", "body": "<p>يدفع صاحب الصورة المضطربة كلفة يومية: تجنّب لأنشطة جسدية كاملة (سباحة، رياضة، تغيير ملابس جماعي) فيخسر مع التجنب فرص بناء المخطط والمهارة معًا، وملابس حماية دائمة (قبعة وأكمام طويلة صيفًا) قد تُقرأ عنادًا وهي درع صورة، واضطراب عند كل تغيّر جسدي نمائي (بلوغ خاصة) لأن الجسد المتغير يهزّ تمثيلًا هشًا أصلًا، واجتماع متعثر حيث يُقرأ الجسد واجهةً اجتماعية أولى قبل أي كلام. وعند غير المتكلمين تخرج الصورة المضطربة سلوكيات جسدية (ضرب أجزاء من الجسد، رفض لمس مناطق) قد تُطارد وظيفتها شهورًا في ملفات سلوكية قبل أن يُسأل سؤال الصورة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "اضطراب صورة الجسم — الجسد كما يُعاش من الداخل", "points": ["نظرة الآخر المضطربة تشوّش مواد البناء من المنبع.", "لغة متأخرة تعني كلام جسد أقل وأكثر تشوهًا.", "لا تُختزل في ثقة تُشجَّع، ولا تُنفى عند غير المتكلم."], "text": {"head": "لماذا يشتد الاضطرابان معًا في التوحد", "body": "<p>يلتقي ملف الصورة بملف التوحد في ثلاث نقاط تجعل اضطرابها أرجح وأعمق. أولًا: نظرة الآخر — حجر بناء الصورة الأول — هي نفسها قناة مضطربة في التوحد (انتباه مشترك ونظر اجتماعي ضعيفان)، فتصل مواد بناء الصورة مشوشة من المنبع. ثانيًا: الكلام عن الجسد (تسمية ومدح وحدود يلفظها المحيط) يصل إلى متعلم لغته متأخرة أو حرفية، فتُبنى الصورة بمواد أقل وبتأويلات مشوهة أحيانًا. ثالثًا: تجارب جسدية مؤلمة متراكمة (فحوص، أزمات، سخرية أقران من حركة أو مشية) تُرسب في الصورة طبقاتها الأثقل. فهم هذا الاشتداد يمنع خطأين: اختزال الصورة في «ثقة بالنفس» تُعالج بالتشجيع، أو إنكار وجودها عند غير المتكلم لأنه لا يصفها لفظيًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "اضطراب صورة الجسم — الجسد كما يُعاش من الداخل", "points": ["نجاح جسدي متكرر واحترام حدود ومرآة بالألعاب.", "توثيق وإحالة عند المؤشرات الثقيلة.", "لا تفسيرات تحليلية ولا وعود خارج الفريق."], "text": {"head": "داخل الجلسة الحركية — ما يفعله النفسي الحركي وما لا يفعله", "body": "<p>داخل الجلسة يملك النفسي الحركي أدوات دعم حقيقية دون ادعاء العلاج النفسي: تجارب جسدية ناجحة متكررة يعيش فيها المتعلم جسده قادرًا ومقبولًا (مادة خام لأي صورة)، وعمل مرآة متدرج داخل ألعاب حركية لا مواجهات، واحترام صارم لحدود الجسد (استئذان قبل اللمس، حق الرفض محفوظ) يجعل الجلسة نفسها درس صورة آمن، وتوثيق للعلامات وإحالة موصوفة حين تظهر مؤشرات ثقيلة (إيذاء جسد، رفض أكل مرتبط بالجسد، اضطراب هوية معلن). ما لا يفعله: تفسيرات تحليلية للمادة الرمزية، ولا وعود لأهل بمعالجة «صورة» خارج فريق يقود ملفها النفسي مختصه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "اضطراب صورة الجسم — الجسد كما يُعاش من الداخل", "points": ["حذف ثابت وأحجام مشوهة عبر الزمن قرائن تراكمية.", "الفرضية من تقاطع رسم ولعب وكلام لا من رسم واحد.", "للرسم أسباب مهارية — لا إدانة من نافذة واحدة."], "text": {"head": "الرسم واللعب — نوافذ قراءة لا أدوات إدانة", "body": "<p>رسم الإنسان (dessin du bonhomme) واللعب الرمزي نافذتا الممارس الأوسع على الصورة: أجزاء محذوفة باستمرار (فم، يدان، جسد كامل)، وأحجام مشوهة (رأس ضخم بلا جسد)، وشخصيات مرسومة ممزقة أو محاطة بأسوار. قراءتها المهنية احتمالية تراكمية: رسم واحد لا يقول شيئًا، ونمط ثابت عبر أشهر وعبر وسائط (رسم ولعب وكلام) يقول الكثير ويُكتب فرضية تُناقش في الفريق. احذر خاصة تحويل غياب جزء في رسم إلى «تشخيص» جاهز؛ فللرسم أسباب مهارية ومعرفية كثيرة، والصورة تُقرأ في التقاء النوافذ لا في نافذة واحدة.</p><p>وتبلغ حساسية الصورة ذروتها عند البلوغ: جسد يتغير شكله وحجمه ووظائفه في أشهر، عند مراهق تمثيله الجسدي أصلًا هش وعلاقته بنظرات الأقران متوترة. هنا تتحول توصيات الدعم إلى واجبات حماية: خصوصية صارمة في التغيير والاستحمام، وكلام أهل مضبوط عن التغيرات الجسدية بوصفها نموًا لا مدعاة سخرية أو قلق، ومراقبة لأي مؤشر انسحاب أو إيذاء. والمراهق غير المتكلم يعيش التحول نفسه بلا لغة تصفه — فتظهر حيرته سلوكًا جسديًا يحتاج من فريقه سؤال الصورة قبل سؤال الوظيفة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يكون اضطراب صورة الجسم أرجح في التوحد تحديدًا بحسب آلية بنائها؟", "الإجابة: لأن مواد بنائها الأولى مضطربة في التوحد ذاته: نظرة الآخر والانتباه المشترك (قناة النظرة)، والكلام عن الجسد (قناة اللغة)، يضاف إليها تراكم تجارب جسدية مؤلمة وسخرية — فتصل الصورة مشوشة من منابعها."], "text": null, "take": "صورة الجسم المضطربة جسد يُعاش غريبًا: تظهر في المرآة والصور والحياء والتجنب، وتشتد في التوحد لاضطراب مواد بنائها نفسها؛ وعمل النفسي الحركي معها دعم جسدي آمن وحدود صارمة وإحالة موصوفة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 27, "title": "آلية بناء المخطط والصورة — من الإحساس إلى التمثيل", "intro": "<p>لآلية البناء هنا وجهان: كيف تُبنى خريطة الجسد من مدخلات حسية وحركية ولغوية، وكيف تُبنى صورته من مواد علائقية ورمزية، وأين يتعطل البناءان عند المصاب بالتوحد تحديدًا. فهم خط الإنتاج يحدد أين تتدخل وأين تحيل.</p>", "slides": [{"kind": "cover", "title": "آلية بناء المخطط والصورة — من الإحساس إلى التمثيل", "sub": "الوحدة السادسة: اضطراب المخطط الجسدي وصورة الجسم", "goals": ["أن تشرح كيف يُبنى المخطط والصورة من الإحساس إلى التمثيل عبر النمو", "أن تربط خبرات الجسد المبكرة بثبات الخريطة اللاحقة", "أن تسمّي محطات البناء التي تُبنى عليها أنشطة الوحدة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l27.jpg", "img2": null}, {"kind": "slide", "title": "آلية بناء المخطط والصورة — من الإحساس إلى التمثيل", "points": ["مدخلات أربع ترسم، والحركة تراجع وتصحّح.", "التقليد مدرسة مخطط لأنه مطابقة جسد بجسد.", "التسمية تثبّت الخريطة وتجعلها قابلة للاستدعاء."], "text": {"head": "خط بناء المخطط — إحساس يتحرك فيُسمّى فيثبت", "body": "<p>يبدأ البناء بمدخلات: إحساس عميق يخبر عن وضعية المفاصل، ودهليزي يخبر عن موضع الرأس والجاذبية، ولمسي يرسم سطح الجسد وحدوده، وبصري يراقب الأجزاء العاملة. ثم تأتي الحركة مختبرًا: كل فعل يطابق التوقع الحسي بالنتيجة فيراجع الخريطة ويصحّحها — ولهذا كان التقليد (الذي درسته آليته) مدرسة مخطط من الطراز الأول، لأنه يفرض مطابقة جسد بجسد. ثم تختم اللغة البناء بالتسمية: كلمة ثابتة لكل جزء تثبّت موضعه في الخريطة وتجعله قابلًا للاستدعاء والتعليم. عطّل أي محطة — مدخلًا مشوشًا، أو حركة قليلة التنوع، أو تسمية غائبة — يخرج مخطط ناقص على قدر العطل.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية بناء المخطط والصورة — من الإحساس إلى التمثيل", "points": ["مدخلات مشوشة وحركة فقيرة التنوع وتقليد مسدود.", "تسمية متأخرة تعني مثبتات أقل.", "الناتج ثقوب موضعية تتبع الاستعمال لا العشوائية."], "text": {"head": "أين يتعطل خط المخطط في التوحد", "body": "<p>تتعطل المحطات كلها تقريبًا بدرجات: مدخلات حسية مضطربة التعديل (دهليزي وعميق خاصة) تعطي مواد بناء مشوشة؛ وحركة استكشافية فقيرة التنوع (اهتمامات ضيقة ونمطيات متكررة) تقلّص عدد مراجعات الخريطة؛ وتقليد مضطرب يسدّ مدرسة المطابقة؛ ولغة متأخرة تؤخر مثبتات التسمية. الناتج التراكمي مخطط يُبنى ببطء وبثقوب موضعية — أجزاء كثيرة الاستعمال مرسومة وأخرى شبحية — وهو ما رأيته في درس الاضطراب نمطًا: كبرى حاضرة ودقيقة ضائعة، وأداء ينهار حين تُسحب المرآة البصرية لأن البناء الداخلي لم يكتمل.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية بناء المخطط والصورة — من الإحساس إلى التمثيل", "points": ["المواد: نظرة وقبول وكلام وحدود ولمس آمن.", "الصورة تاريخ علائقي مجسّد عند دولتوه.", "لا تُصلح بتمارين بل بتجارب علائقية وعمل متخصص."], "text": {"head": "خط بناء الصورة — نظرة وكلام وحدود", "body": "<p>تُبنى الصورة بمواد من نوع آخر: نظرة حامل يرى الرضيعَ كاملًا ومقبولًا فتعكس له جسدًا يستحق السكن، وكلام يسمّي الجسد ويمدح قدراته ويصف حدوده («جسدك لك»)، ولمس محترم متوقع يعلم الجسد أنه آمن، وتجارب نجاح واعتراف اجتماعي ترسّب في التمثيل قيمته. ثم يعيد صاحب الصورة إنتاجها في كل علاقة جديدة. لهذا كانت الصورة عند دولتوه تاريخًا علائقيًا مجسّدًا لا صورة فوتوغرافية داخلية؛ ولهذا أيضًا لا تُصلَح بتمارين، بل بتجارب علائقية مصححة متراكمة وبعمل نفسي متخصص عند الحاجة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية بناء المخطط والصورة — من الإحساس إلى التمثيل", "points": ["إخفاقات المخطط ترسّب صورة سلبية، وتجنّب الصورة يجوّع المخطط.", "خطط الباب الواحد تُفرَّغ من الباب الآخر.", "قِس الاثنين واعمل بميدانك مع إحالة موثقة."], "text": {"head": "جسد واحد — كيف يجرّ كل اضطراب أخاه", "body": "<p>المخطط والصورة بنيان مستقلان في جسد واحد، فيتبادلان الضرر: مخطط ضبابي يعني إخفاقات يومية متراكمة (اصطدام، سخرية، فشل مهارات) تترسب في الصورة «جسدي خائن ومضحك»؛ وصورة مضطربة تعني تجنبًا للحركة واللعب والأجساد الأخرى، فتجوع الخريطة من مراجعاتها فيزداد ضبابها. هذه الحلقة المغلقة تفسّر لماذا يبدو بعض متعلميك «عالقين» رغم خطط سليمة في باب واحد: الباب الآخر يفرّغ ما يبنيه الأول. قاعدة الخطة المركبة: قِس البابين دائمًا، واعمل في ميدانك (المخطط) مع إحالة ودعم موثقين للباب الثاني، فيتقدم الجسد الواحد من جبهتين.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية بناء المخطط والصورة — من الإحساس إلى التمثيل", "points": ["شبكة واحدة: أداء للخريطة وملاحظة للصورة.", "عينان مغمضتان والتحديد المخفي أدوات كشف أساسية.", "فقرتان منفصلتان في التقرير لبابين منفصلين."], "text": {"head": "إجراءات الفحص الموحّدة — شبكة الجسد", "body": "<p>يجمع الفحص شبكة واحدة للبابين: للمخطط — تعرّف وتعيين وتسمية للأجزاء (على النفس، وعلى الآخر، وعلى نموذج، وفي رسم) بعينين مفتوحتين ومغمضتين، ومهام تحديد مواضع ولمس مخفي، ورسم إنسان بقراءة مهارية أولًا. وللصورة — ملاحظة المرآة والصور والحياء والتجنب عبر مواقف طبيعية، وقراءة تراكمية للرسم واللعب، وأسئلة أهل عن تاريخ الجسد اليومي (لبس، استحمام، تصوير، تعليقات). تُكتب النتائج فقرتين منفصلتين بعنوانين صريحين، وتتحول كل فقرة إلى أهداف في ميدانها أو إحالة موصوفة في ميدان جارها.</p><p>ويضيف بولينجيه (Bullinger) طبقة بناء أعمق: التمثيل الجسدي يتشكل أصلًا من تدفقات حسية منظمة (تدفق جاذبي ولمسي ودهليزي) يلتقطها الرضيع داخل الحوار المقوّي مع حامله، فيبني منها أول «خلفية جسدية» يستند إليها كل تمثيل لاحق. على هذا الأساس يُفهم لماذا يكون اضطراب المخطط عند المصاب بالتوحد أعمق من «نقص معلومات عن الأجزاء»: العطل يبدأ من طبقة التدفقات وتنظيمها قبل طبقة التسمية بسنوات. ولهذا تحمل أنشطة الدرس التالي مكونًا حسيًا منظِّمًا دائمًا، لا تمارين تعيين جافة على جسد غير مهيأ الإحساس.</p><p>ومحطة أخيرة في خط البناء كثيرًا ما تُنسى: الألم والمرض في الطفولة يعلّمان الجسد دروسًا تمثيلية — جزء أليم يُستبعد من الخريطة تجنبًا، ومنطقة فحوص متكررة تُقرأ منطقة غريبة مهددة. عند متعلميك أصحاب التاريخ الطبي الثقيل (عمليات، إقامات، فحوص مؤلمة متكررة) اسأل عن هذا التاريخ بوصفه جزءًا من بناء مخططهم وصورتهم، لا بندًا إداريًا في ملفهم الطبي وحده.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يُعدّ التقليد «مدرسة مخطط» من الطراز الأول؟", "الإجابة: لأنه يفرض مطابقة جسد المتعلم بجسد النموذج جزءًا جزءًا، فتُراجع الخريطة الداخلية وتُصحَّح بمقارنة التوقع الحسي بالنتيجة المرئية — وهي آلية بناء المخطط ذاتها في أنقى صورها."], "text": null, "take": "المخطط يُبنى إحساسًا وحركة وتسمية ويتعطل في التوحد في محطاته كلها، والصورة تُبنى نظرة وكلامًا وحدودًا وتتعطل بمصادرها؛ والبابان يجرّ كلٌّ منهما الآخر، فتُقاسان معًا وتُعالج كلٌّ في ميدانها.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 28, "title": "أنشطة المخطط الجسدي وتوصيات الصورة — خرائط تُبنى باللعب والفعل", "intro": "<p>أنشطة بناء المخطط الجسدي بأدوات حسية-حركية يملكها النفسي الحركي كاملة، وتوصيات دعم صورة الجسم داخل الجلسة وحدودها. والقاعدة الحاكمة هنا: المخطط يُبنى بالفعل المتكرر المسمّى، والصورة تُدعم بتجربة جسد قادر ومحترم الحدود.</p>", "slides": [{"kind": "cover", "title": "أنشطة المخطط الجسدي وتوصيات الصورة — خرائط تُبنى باللعب والفعل", "sub": "الوحدة السادسة: اضطراب المخطط الجسدي وصورة الجسم", "goals": ["أن تبني أنشطة خريطة عبر اللعب والفعل بتدرج محسوس فممثَّل", "أن تطبق بطاقة نشاط مخطط جسدي كاملة بعناصرها العشرة", "أن تصوغ توصيات صورة جسم آمنة بلا تعرّض قسري"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act70_img1.webp", "img2": null}, {"kind": "slide", "title": "أنشطة المخطط الجسدي وتوصيات الصورة — خرائط تُبنى باللعب والفعل", "points": ["التسمية مقترنة بالحركة والإحساس لحظيًا.", "التدرج: نفس ثم آخر ثم نموذج ورسم.", "الإغماض مرحلة متقدمة، واللعب شرط التعلّم."], "text": {"head": "مبادئ أنشطة المخطط — سمِّ أثناء الفعل", "body": "<p>أربعة مبادئ تسبق أي نشاط. أولًا: التسمية تحدث أثناء الحركة والإحساس لا في درس نظري — الجزء يُسمّى وهو يتحرك ويُلمس ويُقاوم، لأن الخريطة تُبنى بالاقتران الحسي-الحركي-اللفظي. ثانيًا: التدرج المعروف من الفحص (على النفس أولًا، ثم على الآخر، ثم على نموذج ورسم) هو تدرج الأنشطة نفسه. ثالثًا: العينان المغمضتان واللمس المخفي مراحل متقدمة تُدخَل بعد نجاح المكشوف، وبهما وحدهما يثبت أن الخريطة صارت داخلية. رابعًا: كل نشاط يُلعب بوصفه لعبة اجتماعية ممتعة، فخرائط الصغار تُبنى في اللعب لا في التدريب الجاف، والمتعة هنا شرط تعلّم لا ترفيهًا مرفقًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة المخطط الجسدي وتوصيات الصورة — خرائط تُبنى باللعب والفعل", "points": ["ست عائلات أنشطة: رسم محيط وبازل ومرآة ولمس ومسارات وطبعات.", "الاختيار من ثقوب خريطة هذا المتعلم.", "المقارنة عبر الزمن (طبعات ورسوم) تُري النمو لصاحبه."], "text": {"head": "ترسانة الأنشطة — من البصمة إلى الخريطة الكاملة", "body": "<p>أنشطة مجرّبة البنية: رسم محيط الجسد كاملًا على ورق كبير ثم تلوين الأجزاء وتسميتها ونقلها عبر الجلسات إلى أجزاء أدق؛ وبازل الإنسان والدمى المفككة تركيبًا مع تسمية كل قطعة عند وضعها؛ وألعاب المرآة الثنائية (تقليد وضعيات ببطاقات أجزاء)؛ و«صندوق اللمس» لتحديد أجزاء مجسّمة باللمس وحده؛ ومسارات جسدية يمرّ فيها جزء مسمّى من علامة إلى علامة (ركبة تلمس النجمة، كوع يلمس الدائرة)؛ وختم الجسم بالطبعات (يد وقدم ملونتان) يقارن بهما المتعلم نموه عبر الأشهر. تُختار الأنشطة من مواضع ثقوب خريطة المتعلم تحديدًا — الرسغ الضائع نجمُ الجلسة المقبلة — لا من قائمة عامة تدور على الجميع.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة المخطط الجسدي وتوصيات الصورة — خرائط تُبنى باللعب والفعل", "points": ["هدف معدود وخطوات وتدرج حتى الإغماض.", "التعيين بيد المتعلم — أمان وحدود داخل التصميم.", "القياس شبكة أجزاء في ثلاثة شروط."], "text": {"head": "بطاقة نشاط كاملة — «خريطة الجسد الحية»", "body": "<p>المجال: المخطط الجسدي — تعيين وتسمية. الهدف القابل للقياس: أن يعيّن المتعلم 8 أجزاء دقيقة (كوع، معصم، كعب، رقبة، ذقن، ركبة، كتف، إصبع قدم) على جسده بعينين مغمضتين عند اللمس والتسمية، في 4 من 5 محاولات. الأدوات: ورق كبير بطول المتعلم، ألوان، بطاقات أسماء الأجزاء، عصابة عينين اختيارية بموافقته. الإعداد: رسم محيط جسده مستلقيًا في جلسة سابقة ومعلّق على الحائط. الخطوات: يقف أمام خريطته، يسمّي المختص جزءًا فيضع بطاقته على الرسم ثم يلمس الجزء على جسده، ثم تنعكس الأدوار، ثم تُختم المحاولات الأخيرة بلمس الجزء على الجسد مباشرة بعينين مغمضتين. التدرج: أجزاء كبرى مكشوفة ← دقيقة مكشوفة ← دقيقة مغمضة ← نقل إلى جسد الآخر ونموذج. التنويع: سباق فرق صغير على خريطتين. الأمان: احترام رفض العصابة، لا لمس لمناطق حساسة أبدًا — التعيين بيد المتعلم نفسه. التكرار: مرتان أسبوعيًا 6 أسابيع. القياس: جدول أجزاء × (رسم/جسد مكشوف/جسد مغمض). مؤشر النجاح: بلوغ الهدف ثم نقل قائمة أجزاء جديدة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة المخطط الجسدي وتوصيات الصورة — خرائط تُبنى باللعب والفعل", "points": ["نجاحات موثقة وكلام أداء فقط ومرآة اختيارية.", "تنسيق كلام الجسد الآمن مع الأهل.", "توثيق وصفي وإحالة — بيئة داعمة لا علاج مدّعى."], "text": {"head": "توصيات دعم الصورة داخل الجلسة وخارجها", "body": "<p>لصورة الجسم توصيات دعم لا خطة علاج: اجعل الجلسة مخزن نجاحات جسدية موثقة (صور إنجازات بموافقة الأهل تُراجع مع المتعلم)؛ ولا تعلّق أبدًا على شكل جسد أو وزنه أو مظهره داخل الجلسة — التعليق الوحيد المشروع على الأداء والجهد؛ ووفّر مرآة كاملة يستعملها اختيارًا في سياق لعب لا فحص؛ ونسّق مع الأهل كلام جسد آمن في البيت (لا ألقاب جسدية، لا مقارنات أجساد بين الإخوة، استئذان وحدود في اللبس والاستحمام تنمو مع العمر)؛ ووثّق أي مؤشر ثقيل ومرّره للفريق في تقريرك بلغة وصفية لا تفسيرية. هذه التوصيات بيئة داعمة حول العمل النفسي المتخصص، ولا تُقدَّم للأهل بوصفها علاج الصورة نفسه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة المخطط الجسدي وتوصيات الصورة — خرائط تُبنى باللعب والفعل", "points": ["شبكة فحص ربعية بأرقام الثقوب المغلقة.", "مؤشرات صورة بالملاحظة: تصوير ومرآة ومشاركة.", "مراجعة فريق موحدة ربعية للبابين."], "text": {"head": "القياس والمتابعة — خريطة تكتمل وصورة تُراقب", "body": "<p>يُقاس المخطط بإعادة شبكة الفحص ربعيًا: أجزاء × شروط (مكشوف/مغمض/على آخر/في رسم)، فتظهر الثقوب المغلقة والباقية رقميًا، وترتبط بأداء يومي شاهد (أخطاء لبس أسبوعية، اصطدامات موثقة، دقة تحديد موضع ألم عند حدوثه). وتُراقب الصورة بمؤشرات ملاحظة لا اختبارات: قبول التصوير، وسلوك المرآة، ومشاركة الأنشطة الجسدية المُتجنَّبة سابقًا، وتعليقات المتعلم العفوية عن جسده. راجع الملفين في اجتماع فريق واحد كل ثلاثة أشهر: خريطة تُبنى هنا، وصورة تُدعَم هنا وتُعالج هناك، وجسد واحد يجني من الجبهتين.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا تُبنى أنشطة المخطط على «ثقوب خريطة المتعلم» لا على قائمة أنشطة عامة؟", "الإجابة: لأن ثقوب المخطط موضعية تختلف من متعلم لآخر (أجزاء ضائعة بعينها في شروط بعينها)؛ فالنشاط العام يدرّب المرسوم أصلًا ويترك الشبحي، بينما الاستهداف من شبكة الفحص يوجه الجهد إلى ما ينقص هذه الخريطة تحديدًا."], "text": null, "take": "المخطط يُبنى بأنشطة لعب مسمّاة أثناء الفعل ومتدرجة حتى الإغماض تُختار من ثقوب خريطة المتعلم، والصورة تُدعم بنجاح موثق وحدود محترمة وكلام آمن — بلا ادعاء علاجها من مقعد حركي.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 29, "title": "المشية عند المصاب بالتوحد — أشكال الانحراف", "intro": "<p>المشية (marche) أول مهارة حركية كبرى وأكثرها دلالة، لأنها تُلخّص نضج المنظومة كلها في ثلاثين ثانية من الملاحظة. في هذا الدرس تتعرف على أشكال انحراف المشية عند المصاب بالتوحد من السنة الثانية فصاعدًا، وما يميز كل شكل، ومتى يكون الانحراف علامة إحالة عصبية لا ملفًا حركيًا فقط.</p>", "slides": [{"kind": "cover", "title": "المشية عند المصاب بالتوحد — أشكال الانحراف", "sub": "الوحدة السابعة: اضطرابات المشية والحركة الكبرى", "goals": ["أن تصف انحرافات المشية الموثقة عند المصاب بالتوحد بأنماطها", "أن تميّز غياب تأرجح الذراعين والاستدارة الكتلية في الملاحظة الحية", "أن تربط شكل المشية بملفات المقوّية والتوازن المرافقة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act18_img1.webp", "img2": null}, {"kind": "slide", "title": "المشية عند المصاب بالتوحد — أشكال الانحراف", "points": ["قاعدة واسعة وخطوات قصيرة ووضعية حارس ممتدة.", "المشية حلقة في مسار استحقاقات لا حدث معزول.", "تُقرأ مع تاريخ السنة الأولى دائمًا."], "text": {"head": "مشية غير ناضجة عند السنتين", "body": "<p>وثّقت دراسات الملاحظة المبكرة أن مشية أطفال التوحد عند بلوغهم السنتين ما تزال غير ناضجة (marche immature) بالقياس إلى أقرانهم: قاعدة ارتكاز واسعة، وخطوات قصيرة مترددة، وذراعان مرفوعتان في وضعية «الحارس» التي يتجاوزها النموذجيون مبكرًا، وانتقالات متعثرة بين الوقوف والمشي. ويرتبط التأخر بسلسلة الاستحقاقات السابقة عليه — ضبط رأس وجلوس متأخران في السنة الأولى كما رأيت في وحدة العلامات — فالمشية المتأخرة ليست حدثًا معزولًا بل حلقة في مسار حركي كامل يجب أن يُقرأ متصلًا عند كل تقييم.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "المشية عند المصاب بالتوحد — أشكال الانحراف", "points": ["غياب تأرجح الذراعين توقيع تناسق بين الشقين مضطرب.", "المشية «الخشبية» قراءتها تناسقية لا عضلية.", "صورة شبه باركنسونية موصوفة عند بعض ذوي الأداء الأعلى."], "text": {"head": "فقدان تأرجح الذراعين وعدم التماثل", "body": "<p>أدق انحراف موثق في مشية الأكبر سنًا هو في التناسق بين الأطراف: عدم تماثل شاذ بين حركات الذراعين والساقين، وغياب أو ضعف شديد في التأرجح الطبيعي للذراعين (balancier des bras) الذي يرافق الخطو عند النموذجيين تلقائيًا. مشية بلا تأرجح ذراعين تبدو «خشبية» وتلفت نظر كل من يراها، وهي في الحقيقة توقيع اضطراب تناسق بين شقّي الجسد (coordination intersegmentaire): النصفان لا يتحاوران بإيقاع متعاكس سليم. وعند بعض ذوي الأداء الأعلى وُصفت مشية شبه باركنسونية بتردد في بدء الخطو وخطوات صغيرة بطيئة، تذكّر بأن الانحراف يمتد عبر الطيف كله.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "المشية عند المصاب بالتوحد — أشكال الانحراف", "points": ["ثلاثة أوجه: حسي عابر، ومقوّي وضعي، وتقصّر ثابت.", "الفحص الفارق: إنزال الكعب إراديًا وسلبيًا.", "التقصّر الثابت إحالة طبية واجبة لا ملف أنشطة."], "text": {"head": "المشي على أطراف الأصابع — العلامة المشهورة بحذر", "body": "<p>المشي على مقدمة القدم (marche en équin) أشهر علامات التوحد الحركية شعبية، ويحتاج قراءة منضبطة على ثلاثة أوجه: قد يكون بحثًا حسيًا (ضغط مقدمة القدم وإحساس عضلات الساق) يظهر ويختفي مع السياقات؛ وقد يكون عادة وضعية لمقوّية مفرطة في عضلات الساق الخلفية؛ وقد يصير مع السنوات تقصّرًا عضليًا-وتريًا ثابتًا (rétraction) يجعل الكعب عاجزًا عن بلوغ الأرض — وهنا تنتهي القراءة الوظيفية وتبدأ إحالة طبية وجراحية تقويمية واجبة. الفحص الفارق بسيط وحاسم: هل يستطيع المتعلم إنزال كعبه عند الطلب والوقوف المسطح، وهل يبلغ الكعب الأرض في التحريك السلبي؟</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "المشية عند المصاب بالتوحد — أشكال الانحراف", "points": ["استدارة كتلة واحدة بدل تدوير تسلسلي (1998).", "تستمر في الالتفافات عند الكبار كخراقة مكانية.", "التسلسل داخل الجسد يضطرب قبل التنسيق مع العالم."], "text": {"head": "التدوير كتلة واحدة — استراتيجية تعويض قديمة", "body": "<p>من أقدم توقيعات المسار الحركي للتوحد ما وثّقه تايتلباوم (Teitelbaum, 1998) في الاستدارات من الاستلقاء: الأطفال النموذجيون يستديرون بتدوير تسلسلي (كتف ثم حوض ثم ساقان)، بينما يستعمل أطفال التوحد استراتيجية كتلة واحدة (en bloc) يحرّكون فيها الجسد قطعة صلبة مستغلين وزنهم سلبيًا. تبقى هذه الاستراتيجية عند الأكبر سنًا في استدارات المشي والالتفافات المفاجئة: جسد يلتف كله بدل أن يلتف أجزاءً، فيبدو «أخرق» في المساحات الضيقة والألعاب الجماعية السريعة. وهي قراءة آلية مهمة: التسلسل الحركي داخل الجسد الواحد مضطرب قبل أن يضطرب تنسيقه مع العالم.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "المشية عند المصاب بالتوحد — أشكال الانحراف", "points": ["فقدان مهارة مكتسبة أو ضعف جهة واحدة = إحالة عاجلة.", "التدهور المطرد والحركات اللا إرادية الجديدة كذلك.", "التوثيق المؤرخ الدقيق خدمة طبية بذاته."], "text": {"head": "علامات الإنذار العصبي — متى لا تكون المشية ملفك وحده", "body": "<p>تخرج مشيات معينة من ميدان التقييم النفسي الحركي المنفرد فورًا: مشية متراجعة بعد اكتساب سليم (مهارة فُقدت)، ومشية غير متماثلة بضعف واضح في جهة واحدة، ومشية مصحوبة برجفات أو حركات لا إرادية جديدة، ومشية متدهورة باطراد. هذه إحالات عصبية عاجلة تُكتب في اليوم نفسه، لأن وراءها احتمالات طبية لا تنتظر خطط الأنشطة. والممارس الذي يوثّق الانحراف وصفًا دقيقًا مؤرخًا (منذ متى، وبأي تطور) يقدم للطبيب أنفس هدية: تاريخًا حركيًا منظمًا لا انطباعًا عامًا.</p><p>وسجّل في ملاحظتك عاملين يبدّلان المشية عند صاحبها نفسه: التعب الذي يفكك إيقاع خطوات المساء عما كانت عليه صباحًا عند مضطربي المقوّية والاستباق، والسطح الذي يمشي عليه — فمشية آمنة على أرضية مألوفة قد تنهار على أرضية زلقة أو مزدحمة بالمارة لأن حساباتها الارتجاعية لا تلحق بالمفاجآت. لهذا لا تُقاس المشية في رواق هادئ وحده؛ فالملاحظة التي لا تتضمن ازدحامًا وسطحًا متغيرًا تصف نصف المهارة التي تهمّ الأهل فعلًا: مشية الحياة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الفحص الفارق البسيط الذي يفرّق المشي على أطراف الأصابع الوظيفي عن التقصّر الثابت؟", "الإجابة: اختبار بلوغ الكعب للأرض: إن استطاع المتعلم إنزال كعبه إراديًا وبلغ الكعب الأرض في التحريك السلبي فالمشي وظيفي (حسي أو وضعي)، وإن عجز الكعب عن بلوغ الأرض سلبيًا فهو تقصّر عضلي-وتري ثابت يستوجب إحالة طبية."], "text": null, "take": "مشية المصاب بالتوحد غير ناضجة مبكرًا ثم منحرفة توقيعًا — بلا تأرجح ذراعين، وبكتلة واحدة، وأحيانًا على أطراف أصابع — بعضها وظيفي يُعمل عليه وبعضها إنذار عصبي يُحال فورًا.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 30, "title": "المهارات الحركية الكبرى — جري وقفز ورمي وتسلق", "intro": "<p>وراء المشية تقف عائلة الحركة الكبرى (motricité globale) كلها: جري وقفز وتسلق ورمي والتقاط وتوازن متحرك. في هذا الدرس تتعرف على صور اضطرابها عند المصاب بالتوحد، وعلى مفارقة موثقة فيها — قد تكون محفوظة نسبيًا بينما تنهار الدقيقة والتوازن — وعلى كلفة اضطرابها الاجتماعية في ساحات اللعب.</p>", "slides": [{"kind": "cover", "title": "المهارات الحركية الكبرى — جري وقفز ورمي وتسلق", "sub": "الوحدة السابعة: اضطرابات المشية والحركة الكبرى", "goals": ["أن تحلّل مهارات الجري والقفز والرمي والتسلق إلى مكوناتها القابلة للفحص", "أن تميّز ضعف مهارة كبرى عن تجنبها الحسي أو الاجتماعي", "أن تقرأ شبكة ملاحظة المشي والجري قراءة فاحص لا متفرج"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act9_img2.webp", "img2": null}, {"kind": "slide", "title": "المهارات الحركية الكبرى — جري وقفز ورمي وتسلق", "points": ["جري بلا إيقاع متعاكس صعب الإيقاف والانعطاف.", "القفز الأحادي المتعاقب آخر المستحقات وأول الغائبين.", "هبوط صلب بلا امتصاص يولّد تجنّبًا مفهومًا."], "text": {"head": "الجري والقفز — قوة موجودة وتنظيم غائب", "body": "<p>يملك كثير من متعلميك عضلات تجري وتقفز، لكن جريهم يفتقد الإيقاع المتعاكس المنتظم (ذراع مع ساق مقابلة) فيبدو اندفاعًا مستقيمًا صعب الإيقاف والانعطاف، وقفزهم يقف عند أشكاله الأولى: قفز في المكان بقدمين ملتصقتين متأخرًا، وعجز طويل عن القفز المتعاقب بقدم واحدة (saut à cloche-pied) لأنه يطلب توازنًا أحاديًا وتخطيطًا متسلسلًا معًا. والهبوط من القفز أدلّ من القفز نفسه: هبوط صلب بساقين مستقيمتين وبلا امتصاص مرن، يعرّض المفاصل ويخيف صاحبه فيتجنب المرتفعات كلها تجنبًا يبدو جبنًا وهو قراءة جسد صادقة لخطر حقيقي.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "المهارات الحركية الكبرى — جري وقفز ورمي وتسلق", "points": ["رمي بلا جذع والتقاط مختل التوقيت الاستباقي.", "الكرة اختبار زمن متحرك لا قوة عضلية.", "فشلها الاجتماعي المتكرر يولّد انسحابًا من الساحة."], "text": {"head": "الرمي والالتقاط — حيث تجتمع العين واليد والزمن", "body": "<p>مهارات الكرة (lancer et attraper) أصعب اختبارات الحركة الكبرى لأنها تضيف زمنًا خارجيًا: جسم متحرك يجب توقّع مساره. عند متعلمك تجد رميًا بلا دوران جذع (ذراع تعمل وحدها كأنها منفصلة)، والتقاطًا متأخر الإغلاق أو مبكرًا لأن الاستباق الزمني مضطرب، وتجنّبًا بصريًا للكرة القادمة عند من ترهبه المفاجآت الحركية. هذه المهارات هي عملة ساحات اللعب الاجتماعية؛ فشلها المتكرر أمام الأقران من أقوى مولّدات الانسحاب الاجتماعي الحركي: طفل يُستبعد من اللعبة فيستبعد نفسه من الساحة كلها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "المهارات الحركية الكبرى — جري وقفز ورمي وتسلق", "points": ["تردد انتقالات وتمسّك زائد أو مغامرة بلا تقدير.", "خوف توازني يُبنى، وخوف تخطيطي يُفكَّك ويُعلَّم.", "الانهيار عند تغيير بنية المسار علامة تخطيط."], "text": {"head": "التسلق والمهارات المركبة — تسلسل تحت ارتفاع", "body": "<p>التسلق (grimper) والمهارات المركبة (زحف تحت، عبور فوق، توازن على) تطلب تسلسلًا حركيًا كاملًا تحت شرط توازن وإحساس بالمخاطرة. اضطرابها يظهر ترددًا طويلًا عند كل انتقال، وتمسّكًا زائدًا أو مغامرة بلا تقدير خطر عند الطرف الآخر، وانهيارًا عند تغيّر غير متوقع في بنية المسار. وقراءتها الدقيقة تميز بين خوف توازني مشروع (جسد يعرف حدوده) وخوف تخطيطي (جسد لا يبني تسلسل العبور في تمثيله فيتردد حتى في المأمون) — فلكلٍّ خطة: الأول يُبنى توازنه تدريجيًا، والثاني تُفكَّك له المسارات وتُعلَّم خطواتها حتى تصير مأمونة التمثيل.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "المهارات الحركية الكبرى — جري وقفز ورمي وتسلق", "points": ["قد تحفَظ الكبرى وتنهار الدقيقة والتوازن — والعكس.", "لا بروفيل من باب واحد ولا حكم كلي واحد.", "كل ميدان يُفحص ويُكتب بمجاله."], "text": {"head": "المفارقة الموثقة — كبرى محفوظة ودقيقة منهارة", "body": "<p>سجّلت الأدبيات السريرية مفارقة يجب أن تمنع أي حكم كلي من مهمة واحدة: عند بعض أطفال التوحد تبدو الحركة الكبرى محفوظة نسبيًا — يجري ويقفز ويتسلق بقوة مقبولة — بينما تكون الحركة الدقيقة والتوازن في الحوصلة نفسها شديدَي العجز. والعكس يوجد أيضًا. الدرس المهني: لا «بروفيل حركي» من باب واحد؛ فمتعلم «رياضي» في الساحة قد يعجز عن إمساك قلم وتوازن خط مستقيم، ومتعلم «أخرق» كليًا في الساحة قد يكون دقيقًا مقبولًا على الطاولة. كل ميدان يُفحص بميدانه، وكل حكم يُكتب بمجاله، والمجموع الكلي الواحد («حركيًا متأخر») عبارة ممنوعة في تقرير محترف.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "المهارات الحركية الكبرى — جري وقفز ورمي وتسلق", "points": ["الكلفة اجتماعية: استبعاد وسخرية وانسحاب متراكم.", "الرياضة المدرسية قناة صحة وانتماء مهددة بالتجنب.", "كل خطة تحمل هدف ساحة اجتماعيًا معلنًا."], "text": {"head": "التأثيرات الممتدة — ساحة اللعب بوصفها ملفًا اجتماعيًا", "body": "<p>كلفة الحركة الكبرى المضطربة لا تقف عند الأداء: تُدفع في الاستراحات والساحات والرحلات حيث تُبنى الصداقات أو تنكسر. متعلم يُستبعد من كرة القدم لأنه لا يلتقط ولا ينعطف، ويُسخر من مشيته الخشبية فيتعلم كراهية الخروج، ويتجنب الرياضة المدرسية فتضيع منه قناة الصحة والانتماء معًا. لهذا تحمل خطط الحركة الكبرى في هذه الدورة هدفًا اجتماعيًا معلنًا دائمًا: مهارة ساحة واحدة قابلة للانضمام إلى لعب الأقران (التقاط متبادل، جري جماعي منظم، لعبة مسار) تساوي حركيًا واجتماعيًا أكثر من عشر مهارات مختبرية لا يعرفها أحد خارج الجلسة.</p><p>وتلحق بالعائلة مهارتان مركبتان تستحقان الذكر: قيادة الدراجة التي تجمع توازنًا ديناميكيًا وتبديلًا إيقاعيًا للساقين وتوجيهًا بصريًا في آن، وتتأخر عند متعلميك سنوات عن أقرانهم رغم قوتهم العضلية — وتُبنى بتفكيك مكوناتها (توازن انزلاقي بلا دواسات أولًا) لا بإصرار على الكل دفعة واحدة؛ والسباحة التي ينجح فيها كثيرون نجاحًا يفوق أداءهم البري، لأن الماء يمنح إحساسًا عميقًا شاملًا ويرفع جزئيًا عبء الجاذبية الوضعي — فتكون عند بعضهم أول نجاح حركي جماعي يعيشونه، وبوابة ثقة تُستثمر لبقية المهارات.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا تمنع المفارقة الموثقة (كبرى محفوظة ودقيقة منهارة) عبارة «حركيًا متأخر» في التقرير؟", "الإجابة: لأن مجالات الحركة عند المصاب بالتوحد تتفكك استقلالًا؛ فالحكم الكلي الواحد يخفي مجالًا محفوظًا يصلح أساسًا للخطة ومجالًا منهارًا يحتاجها، ويضلّل كل من يبني على التقرير بعده."], "text": null, "take": "الحركة الكبرى عند المصاب بالتوحد قوة حاضرة غالبًا وتنظيم مضطرب — إيقاع واستباق وتسلسل — وهي مستقلة القياس عن الدقيقة، وكلفتها الحقيقية تُدفع في ساحات اللعب والانتماء.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 31, "title": "آلية اضطراب المشية والحركة الكبرى — أربعة أنظمة في فعل واحد", "intro": "<p>المشية ليست مهارة عضلات الساقين؛ إنها اجتماع أربعة أنظمة في فعل واحد متكرر: مقوّية توزع الشدّ، وتوازن يضبط الثقل، واستباق يبرمج الخطوة التالية، وبصر يوجّه في الفضاء. في هذا الدرس تفكك اجتماعها، وتتعرف على التناسق بين القطاعات (coordination intersegmentaire) مفهومًا مركزيًا، وعلى كيفية توجيه الملاحظة المنظمة للمشية في الحوصلة.</p>", "slides": [{"kind": "cover", "title": "آلية اضطراب المشية والحركة الكبرى — أربعة أنظمة في فعل واحد", "sub": "الوحدة السابعة: اضطرابات المشية والحركة الكبرى", "goals": ["أن تشرح الأنظمة الأربعة المتداخلة في فعل حركي كبير واحد", "أن تفسّر لماذا تنهار مهارة كبرى من بوابة ليست بوابتها الظاهرة", "أن تطبق تحليل الأنظمة على أي فشل قفز أو رمي تلاحظه"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act6_img2.webp", "img2": null}, {"kind": "slide", "title": "آلية اضطراب المشية والحركة الكبرى — أربعة أنظمة في فعل واحد", "points": ["خطوة سليمة = تناوب منظم بين القطاعات الأربعة.", "الاضطراب في التوزيع الزمني لا في القطاعات فرادى.", "من كتلة الرضيع إلى خشبية المدرسي خيط واحد."], "text": {"head": "التناسق بين القطاعات — حوار النصفين", "body": "<p>كل خطوة سليمة حوار متناوب بين قطاعات الجسد: ساق يمنى تتقدم مع ذراع يسرى، وحوض يدور عكس الكتفين، ورأس يبقى مستقرًا فوق الكل. هذا هو التناسق بين القطاعات، واضطرابه عند المصاب بالتوحد موثق من الاستدارة كتلة واحدة في الطفولة المبكرة إلى غياب تأرجح الذراعين وعدم التماثل عند الأكبر. آليته العميقة برمجة مركزية للتسلسل: القطاعات تعرف «أدوارها» فرادى لكن التوزيع الزمني بينها — من يبدأ ومتى وبأي مقدار — هو المضطرب. ولهذا تبدو مشيته كموسيقى يعرف عازفوها نوتاتهم ولا يجمعهم قائد إيقاع واحد.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب المشية والحركة الكبرى — أربعة أنظمة في فعل واحد", "points": ["استباق بصري يبرمج الخطوة قبل هبوطها.", "نظر مثبت للأسفل علامة مراقبة ارتجاعية بديلة.", "التعثر عند تغير الأرضية والإضاءة قراءة وظيفية لا بصرية طبية."], "text": {"head": "البصر قائدًا — حين تقود العين القدم", "body": "<p>تعتمد المشية الناضجة على استباق بصري: العين تمسح الأرض قبل الخطوات فتبرمج القدم طول خطوتها وموضع هبوطها سلفًا. عند كثير من متعلميك تنعكس العلاقة: قدم «تتفاجأ» بالأرض لأن التوجيه البصري الاستباقي ضعيف، أو نظر مثبت إلى الأسفل باستمرار لأن الجسد لا يثق ببرمجته فيراقب كل خطوة ارتجاعيًا. علامات الملاحظة: تعثر في عتبات صغيرة غير مرسومة، وتردد عند تغير لون الأرضية أو ملمسها (يُقرأ تغيرَ عمق)، وانهيار المشية في الإضاءة الخافتة أو عند حمل شيء يحجب رؤية القدمين. البصر هنا ليس حدة نظر تُفحص عند طبيب العيون، بل استعمالًا وظيفيًا للنظر في خدمة الحركة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب المشية والحركة الكبرى — أربعة أنظمة في فعل واحد", "points": ["نصف زمن المشي ارتكاز أحادي تثبّته المقوّية الوضعية.", "الخطوات القصيرة الحذرة توقيع استباق وضعي لا يثق.", "لا علاج لمشية دون فحص مقوّيتها وتوازنها."], "text": {"head": "المقوّية والتوازن داخل كل خطوة", "body": "<p>داخل الخطوة الواحدة تعمل وحدتا هذه الدورة السابقتان بصمت: مقوّية وضعية تثبّت الجذع على ساق الارتكاز الواحدة نصف زمن المشي، وتعديلات استباقية تنقل الثقل قبل رفع القدم حتى لا يسقط الجسد نحو الفراغ الذي تركته القدم. فإذا اضطربت المقوّية جاءت خطوات متصلبة أو مترهلة، وإذا اضطرب الاستباق الوضعي جاءت خطوات قصيرة حذرة لأن الجسد لا يغامر بنقل ثقله إلى حيث لا يثق. قراءة المشية إذن لا تنفصل عن قراءتي المقوّية والتوازن؛ والمختص الذي يعالج «مشية» دون فحص ركيزتيها يعالج عرضًا فوق سببين.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب المشية والحركة الكبرى — أربعة أنظمة في فعل واحد", "points": ["مقاطع ملاحظة: مستقيم ومنعطف وخط ودرجة وإيقاف.", "تسجيل ستة مؤشرات في كل مقطع.", "مقارنة حافي/حذاء وبداية/نهاية تكشف التعب المقوّي."], "text": {"head": "ملاحظة المشية المنظمة — ماذا تسجّل عينك", "body": "<p>تتحول الملاحظة إلى فحص حين تُنظَّم: امشِ بمتعلمك مسافة مستقيمة ذهابًا وإيابًا، ثم منعطفًا، ثم فوق خط مرسوم، ثم صعود درجة وهبوطها، وسجّل في كل مقطع: طول الخطوة وتماثلها، تأرجح الذراعين حضورًا وتماثلًا، موضع القدم عند الهبوط (كعب أولًا أم مسطحة أم مقدمة)، دوران الجذع، ثبات الرأس، وقدرة الإيقاف الفوري عند إشارة. وقارن حافيًا وبحذائه، وفي بداية الجلسة ونهايتها (عامل التعب المقوّي). ورتّب بطاريات الحركة المقننة كمياتِ قياس إضافية حين تتوفر وتُقرأ نتائجها مجالًا مجالًا كما علمتك مفارقة الدرس السابق — رقمًا في ملف، لا حكمًا على طفل.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب المشية والحركة الكبرى — أربعة أنظمة في فعل واحد", "points": ["التفكيك حوّل شكوى عامة إلى خللين محددين.", "الخطة تبعت الخريطة: تناسق واستباق بصري فقط.", "غياب أنشطة التوازن كان قرارًا مهنيًا موثقًا."], "text": {"head": "مثال تطبيقي — مشية «خشبية» تُفكَّك", "body": "<p>متعلم في التاسعة، شكوى أهله ومدرسته: «يمشي كالروبوت ويتعثر كثيرًا». فكّكت الملاحظة المنظمة الشكوى إلى: تأرجح ذراعين غائب كليًا، وخطوات متماثلة الطول لكن بهبوط قدم مسطحة، وثبات رأس ممتاز، وتعثر مركز في العتبات والمنعطفات فقط. الخريطة الآلية: تناسق بين قطاعات مضطرب + استباق بصري ضعيف عند تغير الأرضية، مع مقوّية وتوازن قاعدي مقبولين. الخطة تبعت الخريطة لا الشكوى: ألعاب مشي بإيقاع ذراعين متقابل (عصيّ مشي، حمل متبادل)، ومسارات عتبات متدرجة بتوجيه بصري معلن ثم متناقص، ولا نشاط توازن عام واحد — لأنه لم يكن ناقصًا. بعد فصل دراسي صار التعثر حدثًا أسبوعيًا نادرًا وبدأ تأرجح خفيف يظهر في المشي الحر.</p><p>ويلحق بهذا التفكيك تنبيه قياسي: زمن الخطوة وطولها عند متعلمك يتغيران مع السرعة المطلوبة، فامشِ به بثلاث سرعات (بطيئة، معتادة، سريعة) في ملاحظتك؛ فبعض الاضطرابات لا تظهر إلا عند السرعة — تناسق يصمد بطيئًا وينهار سريعًا — وبعضها الآخر يتحسن مع السرعة لأن الإيقاع الأسرع يفرض تلقائية لا يمنحها البطء المتردد. مشية بسرعة واحدة نصف مشية، في الفحص وفي الخطة معًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يُعدّ النظر المثبت إلى الأسفل أثناء المشي علامة آلية مهمة رغم أنه يبدو «حذرًا» محمودًا؟", "الإجابة: لأنه يكشف أن المتعلم يراقب كل خطوة ارتجاعيًا بالبصر لعجزه عن برمجتها استباقيًا؛ فالحذر هنا تعويض عن استباق بصري-حركي ضعيف، وينهار الأداء متى حُجب البصر أو انشغل."], "text": null, "take": "المشية اجتماع مقوّية وتوازن واستباق وبصر يقودها تناسق بين قطاعات مضطرب التوزيع الزمني؛ وتُفحص بملاحظة منظمة مقطعية تسجل مؤشرات، فتتحول شكوى «يمشي غريبًا» إلى خريطة قابلة للعلاج.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 32, "title": "أنشطة المشية والحركة الكبرى وتوصياتها — من الجلسة إلى الساحة", "intro": "<p>أنشطة وتوصيات للمشية والحركة الكبرى عند المصاب بالتوحد. قاعدتها أن المشية لا تُدرَّب بالمشي وحده بل بمكوّناتها المضطربة عند هذا المتعلم، وأن كل خطة تحمل هدف ساحة اجتماعيًا، وتُقاس في مشي حر حقيقي لا في مسار الجلسة وحده.</p>", "slides": [{"kind": "cover", "title": "أنشطة المشية والحركة الكبرى وتوصياتها — من الجلسة إلى الساحة", "sub": "الوحدة السابعة: اضطرابات المشية والحركة الكبرى", "goals": ["أن تبني أنشطة حركة كبرى بتفكيك ودمج وسياق اجتماعي", "أن تطبق بطاقة نشاط حركة كبرى كاملة بعناصرها العشرة", "أن تنقل مكاسب الجلسة إلى ساحة اللعب الحقيقية بخطة مكتوبة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act12_img1.webp", "img2": null}, {"kind": "slide", "title": "أنشطة المشية والحركة الكبرى وتوصياتها — من الجلسة إلى الساحة", "points": ["مكوّنات تُدرَّب داخل مشي وظيفي كامل.", "تنوع الأرضيات مدرّب صامت متدرج.", "إيقاع خارجي مؤقت يُسحب، وسيناريو سقوط آمن مكتوب."], "text": {"head": "مبادئ حاكمة — درّب المكوّن وعمّم المشهد", "body": "<p>أربعة مبادئ. أولًا: درّب المكوّن المضطرب (تناسق ذراعين، استباق بصري، هبوط مرن) داخل مشيات وظيفية كاملة لا تمارين معزولة طويلة، فالمهارة تندمج في فعلها أو لا تندمج. ثانيًا: الأرضيات والمسارات المتنوعة هي المدرّب الصامت: عشبية ورملية ومنحدرة ومرسومة، تُدخَل تدريجيًا وبأمان. ثالثًا: الإيقاع الخارجي (عدّ، موسيقى، خطوات مختص مرافقة) منظم مؤقت للتناسق بين القطاعات يُسحب تدريجيًا حين يستقر الإيقاع الداخلي. رابعًا: السلامة قبل الجرعة: مرتفعات وسلالم وسرعات بلا حماية محسوبة ليست شجاعة مهنية بل مخاطرة، وكل نشاط يحمل سيناريو سقوطه الآمن مكتوبًا في بطاقته.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة المشية والحركة الكبرى وتوصياتها — من الجلسة إلى الساحة", "points": ["أربع عائلات: تناسق، استباق بصري، هبوط مرن، لعب ساحة.", "أهداف بصرية معلنة تُخفى تدريجيًا لبناء الاستباق.", "الاختيار من خريطة المتعلم لا من القائمة."], "text": {"head": "ترسانة الأنشطة بحسب الخريطة", "body": "<p>لتناسق الذراعين والساقين: مشي بعصيّين بإيقاع متقابل، وحمل أشياء متناوبة اليدين أثناء المشي، ومشي «الجندي والرجل الآلي» لعبًا واعيًا بالفرق. للاستباق البصري: مسارات عوائق منخفضة تُرسم أولًا ثم تُبنى مجسّمة، و«سلم أرضي» بمسافات متغيرة يفرض حساب الخطوة بالنظر، وألعاب اتباع قائد يغيّر اتجاهه تدريجيًا. للهبوط المرن: قفز من ارتفاعات صغيرة متدرجة على أسطح ماصة بهدف «هبوط القط» الصامت، ومنحدرات هبوطًا وصعودًا بسرعات مضبوطة. للمهارات الكبرى الاجتماعية: تبادل كرة كبير بقواعد بسيطة ثابتة، وجري جماعي على مسار مغلق بإشارات بدء وإيقاف بصرية. كل نشاط يُختار من خريطة الدرس السابق، ولكل متعلم ترسانته لا ترسانة الوحدة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة المشية والحركة الكبرى وتوصياتها — من الجلسة إلى الساحة", "points": ["هدف معدود بمؤشرات تعثر ونظرة أمامية.", "إعلان العتبات يُسحب تدريجيًا لبناء الاستباق.", "السلامة والإضاءة جزء من التدرج لا ملاحظة جانبية."], "text": {"head": "بطاقة نشاط كاملة — «مسار العتبات والخطوات المحسوبة»", "body": "<p>المجال: المشية — استباق بصري وتناسق. الهدف القابل للقياس: أن يعبر المتعلم مسار 10 أمتار فيه 6 عتبات منخفضة (5-10 سم) و4 فواصل أرضية متغيرة دون تعثر أو توقف، في 4 من 5 محاولات، وبنظرة أمامية غالبة. الأدوات: عتبات إسفنجية صلبة متدرجة، أشرطة أرضية ملونة، بطاقة «انظر بعيدًا» البصرية عند البداية. الإعداد: عتبات ثابتة لا تنزلق، مسار موازٍ آمن للمرافقة. الخطوات: عبور أول بمرافقة وإعلان كل عتبة، ثم بإعلان متناقص، ثم عبور حر مع عدّ خطوات مسموع، ثم إدخال حمل خفيف بيد واحدة. التدرج: عتبات أقل/أقصر ← أعلى/أطول ← إضاءة أخفّ تدريجيًا. التنويع: تحويل المسار إلى «توصيل رسالة» بين محطتين لربطه بغرض اجتماعي. الأمان: مرافقة جانبية في المستويات الجديدة، إيقاف عند خوف صريح، لا إضاءة خافتة إلا بعد إتقان المضيء. التكرار: 3 مرات أسبوعيًا 6 أسابيع. القياس: تعثرات وتوقفات ونسبة النظرة الأمامية في مقطع الأمتار الخمسة الأخيرة. مؤشر النجاح: بلوغ الهدف أسبوعين ثم تعقيد المسار درجة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة المشية والحركة الكبرى وتوصياتها — من الجلسة إلى الساحة", "points": ["تعميم على ثلاث درجات: بيئة ثم شريك ثم قواعد.", "قرين واحد متعلم القواعد قبل لعب جماعي مفتوح.", "نسخة مبسطة ثابتة من لعبة الأقران تُقرَّب تدريجيًا."], "text": {"head": "تعميم الساحة — شركاء وبيئات حقيقية", "body": "<p>لا تكتمل خطة حركة كبرى داخل الجلسة، لأن المهارة وُلدت لتعيش في ساحات الآخرين. عمّم على ثلاث درجات: أولًا البيئة — انقل النشاط الناجح من أرضية الجلسة إلى ساحة وحديقة ودرج بيت بتسلسل موثق. ثانيًا الشركاء — أدخل قرينًا واحدًا متعاونًا في ألعاب تبادل ومسارات قبل أي لعب جماعي مفتوح، وعلّم القرين قواعد اللعبة الثابتة قبل أن يعلّمها لعبُه المتغير كل لحظة. ثالثًا القواعد — اجعل لألعاب الساحة نسختها المبسطة الثابتة (أدوار معلنة وإشارات بصرية ونهايات واضحة) حتى تصير قابلة للانضمام، ثم قرّبها من نسخة الأقران درجة درجة. وكل درجة تنجح تُحتفى بها مع الأهل بوصفها هدف الخطة المعلن، لا نتيجة جانبية لها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة المشية والحركة الكبرى وتوصياتها — من الجلسة إلى الساحة", "points": ["القياس في ممرات ودرج وساحات حقيقية.", "تعريف موحد للتعثر باتفاق الأهل والمعلمين.", "تحسّن المسار المحفوظ وحده قياس مضلل."], "text": {"head": "القياس والمتابعة — مشي حر لا مشي مختبر", "body": "<p>قياس هذه الوحدة يكون في بيئات حقيقية: مشي ممر المدرسة في الزحام، وصعود درجها الفعلي، وعبور ساحتها بأرضيتها المتنوعة، مع تسجيل التعثرات والسقوطات أسبوعيًا من ملاحظة الأهل والمعلمين باتفاق مسبق على تعريف موحد للحدث. وأعد ملاحظتك المنظمة فصليًا بالمقاطع الستة نفسها لتقارن المؤشرات الستة. ونبّه الفريق إلى فخّ القياس المضلل: تحسّن مسار الجلسة المحفوظ لا يعني انتقالًا؛ فالانتقال الحقيقي يُقرأ حيث لا توجد علاماتك ولا مرافقتك. ووثّق للأهل مشيات بيته الآمنة المتنوعة (حديقة، سوق، درج) بوصفها جرعة التعميم الأسبوعية الأهم.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما فخّ القياس المضلل الذي تحذر منه الوحدة في أنشطة المشية؟", "الإجابة: الاكتفاء بتحسّن أداء المتعلم على مسار الجلسة المحفوظ بعلاماته ومرافقة مختصه؛ فالانتقال الحقيقي يُقاس في بيئات غير مهيأة (ممرات ودرج وساحات) حيث لا علامات ولا مرافقة."], "text": null, "take": "أنشطة المشية والحركة الكبرى تدريب مكوّنات داخل أفعال كاملة بأرضيات متنوعة وإيقاعات تُسحب، وهدفها الأخير مشي حر آمن في ساحات حقيقية ولعب أقران قابل للانضمام.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 33, "title": "منظومة التوازن والتحكم الوضعي — ثلاث قنوات وقاعدة واحدة", "intro": "<p>التوازن (équilibre) ليس حاسة سادسة غامضة ولا قوة عضلية؛ إنه ناتج منظومة تدمج ثلاث قنوات إحساس لحظيًا لتحفظ مركز ثقل الجسد فوق قاعدة ارتكازه. في هذا الدرس تتعرف على المنظومة وقنواتها، وعلى الفرق بين التوازن والتحكم الوضعي الأوسع منه، وأنواع التوازن الثلاثة التي سيفحصها الدرس الثالث نوعًا نوعًا.</p>", "slides": [{"kind": "cover", "title": "منظومة التوازن والتحكم الوضعي — ثلاث قنوات وقاعدة واحدة", "sub": "الوحدة الثامنة: اضطراب التوازن والتحكم الوضعي", "goals": ["أن تشرح منظومة التوازن بقنواتها الثلاث وقاعدتها الوضعية الواحدة", "أن تميّز مساهمة الدهليزي والبصري والعميق في أي موقف توازن", "أن تربط التحكم الوضعي بالمقوّية الخلفية ربطًا آليًا صحيحًا"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l33.jpg", "img2": null}, {"kind": "slide", "title": "منظومة التوازن والتحكم الوضعي — ثلاث قنوات وقاعدة واحدة", "points": ["مركز ثقل داخل قاعدة ارتكاز: تعريف عامل ميكانيكي.", "تصميم الصعوبة بأربعة متغيرات: قاعدة وثقل واضطراب وسرعة.", "قاعدة أصغر واضطراب أكبر = طلب أعلى."], "text": {"head": "التعريف العامل — مركز ثقل داخل قاعدة", "body": "<p>يُعرَّف التوازن عمليًا بأنه القدرة على إبقاء إسقاط مركز الثقل (centre de gravité) داخل قاعدة الارتكاز (base de sustentation) أثناء الثبات والحركة معًا. كلما صغرت القاعدة (قدم واحدة، خط مستقيم، سطح ضيق) وكبرت الاضطرابات (دفعات، حمل، التفات)، ارتفع طلب المنظومة. هذا التعريف الميكانيكي البسيط هو أداة تصميمك الأولى: كل نشاط توازن في العالم يلعب بمتغيراته الأربعة — حجم القاعدة، وموضع الثقل، وحجم الاضطراب، وسرعته — وستبني به تدرجات الدرس الرابع كلها بدل تخمين الصعوبة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "منظومة التوازن والتحكم الوضعي — ثلاث قنوات وقاعدة واحدة", "points": ["الدهليزية مرجع الجاذبية الأصدق.", "البصر يكشف الانحراف البطيء، والعميق يقرأ الأجزاء والقدمين.", "عطل قناة يختلف عن عطل دمج، والخطة تتبع التمييز."], "text": {"head": "القنوات الثلاث — دهليزية وبصرية وعميقة", "body": "<p>تغذّي المنظومةَ ثلاثُ قنوات: الدهليزية (vestibulaire) من الأذن الداخلية تخبر عن حركة الرأس وتسارعاته وموضعه من الجاذبية، وهي المرجع الأصدق لأنها لا تكذب بشأن «أين الأسفل»؛ والبصرية تخبر عن موضع الجسد من محيطه الثابت وتكشف الانحرافات البطيئة؛ والإحساس العميق من العضلات والمفاصل يخبر عن وضعية الأجزاء وضغوط باطن القدم. تدمج المنظومة القنوات بمرونة: تُثقل البصر في الظلام نسبيًا وتنقل الثقل للدهليزي والقدمين. اضطراب التوازن عند متعلمك قد يكون عطل قناة واحدة أو عطل دمج — والتمييز بينهما يوجّه الخطة كلها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "منظومة التوازن والتحكم الوضعي — ثلاث قنوات وقاعدة واحدة", "points": ["التحكم الوضعي تنظيم الوضعية في خدمة فعل مقصود.", "اضطرابه يحوّل كل فعل إلى مناورة إنقاذ وضعية.", "ثبات الجذع والرأس شرط الكتابة والقراءة والركل."], "text": {"head": "التحكم الوضعي — التوازن في خدمة فعل", "body": "<p>التحكم الوضعي (contrôle postural) أوسع من التوازن: إنه تنظيم وضعية الجسد كلها في خدمة فعل مقصود — ثبات جذع يحرر يدًا للكتابة، وثبات رأس يحرر عينين للقراءة، وثبات حوض يحرر ساقًا للركل. بلا تحكم وضعي سليم يصير كل فعل مناورة إنقاذ: يمسك المتعلم الطاولة ليثبت جذعه فتتعطل يده الثانية، أو يثبّت رأسه بيد تحت ذقنه فينسحب من المهمة يدًا وانتباهًا. لهذا يتصل هذا الدرس بكل دروس الدورة: التوازن عندنا ليس رياضة وقوف على قدم بل شرط إمكان للتعلم الجالس والحركة الهادفة معًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "منظومة التوازن والتحكم الوضعي — ثلاث قنوات وقاعدة واحدة", "points": ["ساكن في قاعدة ثابتة، وديناميكي أثناء الانتقال.", "تفاعلي بعد اضطراب مفاجئ — بطل السقوطات الحقيقية.", "الاستباقي يعلو الأنواع بتهيّئه قبل الاضطراب."], "text": {"head": "أنواع التوازن الثلاثة", "body": "<p>يُفحص التوازن ويُدرَّب في ثلاثة أوضاع. التوازن الساكن (statique): حفظ الثبات في قاعدة ثابتة (وقوف، جلوس بلا مسند). والتوازن الديناميكي (dynamique): حفظه أثناء انتقال مركز الثقل (مشي على خط، صعود، عبور). والتوازن التفاعلي (réactif): استعادة الثبات بعد اضطراب غير متوقع (دفعة، انزلاق، اصطدام خفيف) وهو الأكثر ارتباطًا بالسقوطات الحقيقية والأقل تدريبًا في الجلسات المهذبة. فوق الأنواع الثلاثة يجلس الاستباقي الذي درسته: تهيؤ يسبق الاضطراب المتوقَّع نفسه. منظومة الفحص الكاملة ترتّب الأنواع تصاعديًا من الساكن إلى التفاعلي.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "منظومة التوازن والتحكم الوضعي — ثلاث قنوات وقاعدة واحدة", "points": ["توقّع السقوط يشدّ المقوّية فيعطّل التعديل الناعم.", "خوف «غير متناسب» قد يكون تاريخ سقوطات وإذلال.", "الأمان المحسوب شرط آلية قبل طلب الأداء."], "text": {"head": "التوازن والأمان الانفعالي — جسد يخاف يسقط أكثر", "body": "<p>يرتبط التوازن بالأمان الانفعالي ارتباط آلية لا مجاز: جسد يتوقع السقوط يشدّ مقوّيته دفاعيًا، والشدّ الدفاعي يجمّد التعديلات الدقيقة التي يصنعها التوازن الناعم، فيسقط الجسد الخائف فعلًا أكثر مما يسقط الجسد الواثق بالسطح والمرافق. عند متعلمك قد تجد خوف مرتفعات «غير متناسب» مع قدرته المقاسة — تاريخ سقوطات مؤلمة وضحكات أقران علّم جسده أن التوازن ساحة إذلال. بناء التوازن إذن يبدأ دائمًا من أمان محسوب (أسطح ومساند ومرافقة) قبل أي طلب أداء، وتلك ليست رقة زائدة بل شرط آلية فيّاض.</p><p>وانتبه إلى أن قاعدة الارتكاز لا تخص الوقوف: في الجلوس قاعدة مثلثة (مقعدة وقدمان) وفي الزحف قاعدة رباعية وفي الاستلقاء قاعدة قصوى الاستقرار. مركز ثقل الطفل أعلى نسبيًا من البالغ لضخامة رأسه وجذعه العلوي في معادلة جسده، فيكون هامش أمانه التوازني أضيق بنيويًا قبل أي اضطراب — وهو ما يفسر لماذا تبدو اختبارات توازن مصممة على أجساد بالغين ظالمة للأطفال عمومًا، ولماذا تُقرأ أزمنة وقوفهم دائمًا بمقاييس عمرية لا بمقاييس الكبار.</p><p>ويتحرك مركز الثقل نفسه داخل الجسد بتحرك أجزائه: رفع الذراعين يرفعه، وحمل حقيبة ثقيلة على ظهره يزيحه خلفًا، وانحناء الجذع ينقله أمامًا نحو حافة القاعدة. بهذا الفهم تقرأ لماذا يفقد متعلمك توازنه في مهام تبدو ثابتة — حقيبة مدرسية ثقيلة غير متوازنة التوزيع قد تكون وحدها اضطراب توازن يومي متنقلًا — ولماذا تدخل توصيات بسيطة (حقيبة بحمّالتين موزعة، حمل قريب من الجذع) في خطط التوازن من بابها الميكانيكي الصريح.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يُعدّ التوازن التفاعلي (réactif) الأكثر ارتباطًا بالسقوطات الحقيقية رغم أنه الأقل تدريبًا؟", "الإجابة: لأن سقوطات الحياة الواقعية تحدث عند اضطرابات غير متوقعة (انزلاق، اصطدام، دفعة) لا في وقفات ثابتة مهيأة؛ وقدرة استعادة الثبات بعد المفاجأة هي بالضبط ما يختبره التوازن التفاعلي وحده."], "text": null, "take": "التوازن ناتج منظومة ثلاثية القنوات تحفظ مركز الثقل في قاعدته، والتحكم الوضعي توظيفها في خدمة الأفعال؛ وأنواعه ساكن وديناميكي وتفاعلي يعلوها الاستباقي، وكلها مشروطة بأمان انفعالي محسوب.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 34, "title": "أشكال اضطراب التوازن عند المصاب بالتوحد وتأثيراتها", "intro": "<p>يتنكر اضطراب التوازن (troubles de l'équilibre) عند المصاب بالتوحد في شكاوى لا تحمل اسمه: سقوطات متكررة، وجلوس مستحيل، وخوف من ألعاب الأقران، والتصاق بالجدران والأثاث. في هذا الدرس تجمع أشكاله في صور واضحة، وتصل كل صورة بكلفتها اليومية والصفية والاجتماعية.</p>", "slides": [{"kind": "cover", "title": "أشكال اضطراب التوازن عند المصاب بالتوحد وتأثيراتها", "sub": "الوحدة الثامنة: اضطراب التوازن والتحكم الوضعي", "goals": ["أن تصف أشكال اضطراب التوازن الثابت والديناميكي عند التوحد", "أن تسمّي التأثيرات اليومية: سقوطات وتجنب وكلفة اجتماعية", "أن تميّز اضطراب توازن عن خوف مكتسب من سقوطات سابقة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act13_img2.webp", "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التوازن عند المصاب بالتوحد وتأثيراتها", "points": ["سقوط بلا ردود حماية موقوتة توقيع مزدوج الأصل.", "سقوطات من وضعيات بسيطة كما من اللعب.", "سجل موثق (أين/متى/وضعية) يحوّل الشكوى إلى خريطة."], "text": {"head": "السقوطات وضعف التفاعلات الحامية", "body": "<p>الصورة الأشهر: متعلم يسقط أكثر من أقرانه وبأسوأ الطرق — يسقط «كسقوط الأشياء» بلا مدّ يدين حاميتين في الوقت المناسب، ويسقط من وضعيات بسيطة (من كرسيه، من وقفة قصيرة) كما يسقط في اللعب. جذره المزدوج معروف لك الآن: تعديلات استباقية متأخرة (لا تهيؤ قبل الاضطراب) وردود تفاعلية بطيئة أو غائبة (لا استعادة بعده). وسجل السقوطات إذا وُثّق بنظام — أين ومتى وبأي وضعية — يتحول من شكوى عائلية متكررة إلى خريطة تشخيصية: سقوطات التعب آخر النهار غير سقوطات الانتقالات غير سقوطات الاضطرابات المفاجئة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التوازن عند المصاب بالتوحد وتأثيراتها", "points": ["انزلاق والتفاف ونهوض متكرر تُقرأ سلوكًا وهي توازن.", "اتكاء ولفّ ساقين وسند رأس علامات فارقة جسدية.", "انهيار كتابي مع طول الحصة منحنى تعب وضعي."], "text": {"head": "الجلوس للكتابة — توازن يتنكر مشكلة انضباط", "body": "<p>أغلى صور الاضطراب صفّيًا: متعلم لا يستقر على كرسيه — يميل وينزلق ويلتف وينهض كل دقائق — فيُقرأ ملفُّه سلوكيًا كاملًا (فرط حركة، عدم انضباط، قلة احترام) بينما هو معركة توازن وضعي مستمرة: جذع لا يثبت بلا كلفة انتباه كاملة، فيسرق الثباتُ الدرسَ كلَّه. العلامات الفارقة جسدية: يتكئ على الطاولة ببطنه، ويلف ساقيه بقوائم الكرسي، ويسند رأسه بيد، وينهار أداؤه الكتابي مع طول الحصة منحنى تعبٍ وضعي. مدرسة كاملة من الأخطاء الانضباطية تُوفَّر بسؤال واحد: هل يملك هذا الجسد ثبات جلوسه أصلًا؟</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التوازن عند المصاب بالتوحد وتأثيراتها", "points": ["وضعيات معقدة أسهل من بسيطة عند بعضهم (1992).", "لجوء لأنظمة بدائية مخيخية بدل تكامل دهليزي-بصري أعلى.", "لا حكم على التوازن من مشهد لعب خطير واحد."], "text": {"head": "المفارقة الوضعية — معقّد أسهل من بسيط", "body": "<p>وثّق كوهين-راز (Kohen-Raz, 1992) وزملاؤه مفارقة وضعية دقيقة عند أطفال التوحد: بعضهم يتبنّى وضعيات معقدة بسهولة أكبر من وضعيات بسيطة، كأن المنظومة تلجأ إلى أنظمة تحكم وضعي بدائية مرتبطة بالمخيخ أكثر من اعتمادها على أنظمة التكامل الأعلى التي تدمج الدهليزي بالبصري. عمليًا قد ترى متعلمًا يتسلق ويتوازن في ألعاب خطرة ظاهرًا، ثم يعجز عن وقفة بسيطة هادئة على قدمين أو خط مستقيم بلا دعم بصري. لا تحكم إذن من مشهد خطير واحد أن «توازنه ممتاز»؛ فالألعاب الخطرة تعمل بأنظمة والأداء البسيط الهادئ بأنظمة أخرى.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التوازن عند المصاب بالتوحد وتأثيراتها", "points": ["تجنّب كلي وطلب بلا شبع طرفا تعديل قناة واحدة.", "التجنّب يُبنى تدريجًا، والطلب يُنظَّم بجرعات آمنة.", "اجتماع الطرفين عند متعلم واحد بحسب القناة وارد."], "text": {"head": "الطرفان — تجنّب المرتفعات وطلب الدوران بلا شبع", "body": "<p>يظهر الاضطراب في سلوكين متعاكسين يربكان الفرق: متعلم يتجنب كل ارتفاع وحركة (يرفض الأرجوحة والزلاقات والسلالم المتحركة، ويتشبث عند كل درجة) لأن منظومته لا تثق؛ وآخر يطلب الدهليزي بلا شبع (دوران طويل بلا دوار ظاهر، تأرجح عنيف، قفز من مرتفعات) لأن منظومته تحتاج جرعات عالية لتصل إلى عتبة التسجيل. الطرفان ملف قناة واحدة مضطربة التعديل: الأول يُبنى تدريجيًا بأمان، والثاني يُعطى جرعاته منظمة مقصودة داخل أنشطة آمنة حتى لا يأخذها عشوائيًا من أسطح البيوت. وقراءة الاثنين معًا — تجنب وطلب عند المتعلم نفسه بحسب القنوات — باب وحدة الاضطرابات الحسية الآتية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التوازن عند المصاب بالتوحد وتأثيراتها", "points": ["السقوطات العلنية تولّد انسحابًا متسعًا متراكمًا.", "حماية الأهل المفرطة تُتمّ حلقة التجويع الحركي.", "نجاح آمن موثق يعيد فتح اللعب الحر — هدف بذاته."], "text": {"head": "التأثيرات الممتدة — خوف يتعمم وفرص تضيع", "body": "<p>تتعدى الكلفة السقوطَ: كل سقوط مؤلم أو مضحك علنًا يرسّب تجنّبًا أوسع، فينسحب المتعلم من الملعب ثم من الرياضة ثم من رحلات الأقران، وتضيع مع الانسحاب سنوات من التمرين الطبيعي المجاني الذي يبني توازن الأقران بلا جلسات. ويدخل الأهل في حماية مفرطة مفهومة (منع كل نشاط خطير) تُتمّ حلقة التجويع الحركي. كسر الحلقة هدف علاجي بذاته: نشاط توازن آمن ناجح موثق أمام الأهل يعيد فتح باب اللعب الحر المحسوب، وهو الباب الذي سيدرّب التوازن كل يوم بلا كلفة جلسات.</p><p>وتظهر الكلفة في تفاصيل يومية قد لا تصل التقارير أبدًا: متعلم يرفض السلالم المتحركة والمصاعد الزجاجية فيُقرأ عناد سفر، وآخر يتمسك بدرابزين الدرج بيديه معًا في سنّ يصعده فيها أقرانه جريًا، وثالث لا يثق بالكراسي الدوارة والأراجيح المكتبية في بيئته الصفية فيبدو «صعب المراس» في كل ترتيب جلوس جديد. كل واحدة منها معاملة توازنية مع بيئة: الدرابزين قاعدة ارتكاز موسّعة يستعيرها الجسد بحكمة، والسلالم المتحركة سطح يتحرك تحت القدمين — أصعب شروط القناة الدهليزية والبصرية معًا. البيئة عند مضطرب التوازن ليست خلفية محايدة؛ إنها الطرف الثاني في كل معاملة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما العلامات الجسدية الفارقة التي تميز «عدم استقرار الجلوس» التوازني عن فرط الحركة السلوكي؟", "الإجابة: اتكاء البطن على الطاولة، ولفّ الساقين حول قوائم الكرسي، وسند الرأس باليد، وانهيار الأداء الكتابي باطراد مع طول الحصة — وهي علامات معركة ثبات وضعي وتعب وضعي، لا نمط نشاط سلوكي عام."], "text": null, "take": "اضطراب التوازن عند المصاب بالتوحد سقوطات بلا حماية، وجلوس منهك يتنكر سلوكًا، ومفارقة معقّدٍ أسهل من بسيط، وطرفا تجنب وطلب لا يشبع — وكلفته الكبرى سنوات لعب ضائعة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 35, "title": "آلية اضطراب التوازن وفحصه — استباق غائب ودمج مشوش", "intro": "<p>الآلية والفحص هنا وجهان لقراءة واحدة: توازن يضطرب لغياب التعديلات الاستباقية (ajustements posturaux anticipatoires) ولتشوّش دمج القنوات الثلاث. في هذا الدرس تربط الآلية بمهام الفحص التي تكشفها، من الوقفات المقننة إلى مواقف الكرة الكبيرة.</p>", "slides": [{"kind": "cover", "title": "آلية اضطراب التوازن وفحصه — استباق غائب ودمج مشوش", "sub": "الوحدة الثامنة: اضطراب التوازن والتحكم الوضعي", "goals": ["أن تشرح آلية الاستباق الوضعي الغائب والدمج الحسي المشوش", "أن تبني فحص توازن بمهام مقننة وشبكة ملاحظة منظمة", "أن تصوغ حكم توازن بثلاثة أسطر قابلة للخطة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l35.jpg", "img2": null}, {"kind": "slide", "title": "آلية اضطراب التوازن وفحصه — استباق غائب ودمج مشوش", "points": ["سقوط الجلوس المبكر بغياب APA موثق منذ 1998.", "العطل في طبقة التهيؤ المسبق تحديدًا.", "التدريب يبني الاستباق لا يكثر من الثبات."], "text": {"head": "التعديلات الاستباقية — نقطة الانهيار المركزية", "body": "<p>تذكّر من وحدة الآليات ومن درس العلامات: قبل كل حركة مُخلّة بالتوازن، يهيئ الجسد السليم عضلات جذعه وساقيه الداعمة استباقيًا. عند المصاب بالتوحد وثّق تايتلباوم (Teitelbaum, 1998) سقوطات الجلوس عند أول حركة رأس أو ذراع لأن الرضّع لم يستعملوا وظيفيًا لا التفاعلات الوضعية ولا التعديلات الاستباقية لحماية أنفسهم، ووثّق شميتز (Schmitz, 2003) تأخر التعديلات عند تفريغ اليدين. المعنى التوازني: متعلمك لا يسقط لأنه «ضعيف التوازن» إجمالًا، بل لأن منظومته تفتقد طبقة التهيؤ المسبق خاصة — وهو تحديد آلي يوجّه التدريب نحو بناء الاستباق ذاته (توقّع وإعلان وتهيؤ) لا نحو مزيد من الوقفات الثابتة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب التوازن وفحصه — استباق غائب ودمج مشوش", "points": ["عطل دمج يعني شواهد متضاربة التوقيت والثقل.", "الانهيار بالإغماض يكشف أسرًا بصريًا.", "الفحص يغيّر قناة واحدة في كل مرة ليعزل العطل."], "text": {"head": "دمج القنوات — حين لا تتفق الشواهد", "body": "<p>العطل الثاني في الدمج (intégration multisensorielle): أن تصل القنوات الثلاث بإشارات متضاربة التوقيت أو الثقل فيخرج تقدير الوضعية مشوشًا. علاماته الميدانية: متعلم ينهار توازنه بإغماض عينيه انهيارًا يفوق أقرانه (دمجه أسير البصر)، وآخر يضطرب في الأسطح المتحركة أو الناعمة (أسير سطح قدميه)، وثالث يدوخ أو يضطرب من حركات رأس عادية (قناة دهليزية مفرطة الاستجابة أو ملتبسة القراءة). مهام الفحص التالية مصممة كاشفة قناةً قناة: غيّر قناة واحدة في كل مرة (عينان مغمضتان، سطح إسفنجي، رأس يتحرك) وراقب أي تغيير يفكك الأداء.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب التوازن وفحصه — استباق غائب ودمج مشوش", "points": ["شبكة ساكنة وديناميكية بشروط قنوات متغيرة.", "ثلاثة أرقام لكل مهمة: زمن وردود إنقاذ وجودة ردود.", "الحمل باليدين والتفات الرأس شرطان كاشفان متقدمان."], "text": {"head": "مهام الفحص الساكن والديناميكي", "body": "<p>شبكة فحص عملية: ساكنًا — وقوف قدمين متلاصقتين ثم قدم أمام قدم ثم قدم واحدة، بعينين مفتوحتين ثم مغمضتين، على أرضية صلبة ثم إسفنجية، بأزمنة موقوتة وعدد تأرجحات أو خطوات إنقاذ. ديناميكيًا — مشي على خط مرسوم ثم على عارضة منخفضة، وصعود درجة وهبوطها، وعبور مع حمل شيء بيدين (يسحب البصر المساعد)، والتفات رأس أثناء المشي عند الأكبر. وسجّل في كل مهمة ثلاثة أرقام: الزمن قبل فقدان التوازن، وعدد ردود الإنقاذ، وجودة الردود (ذراعان ممدودتان في الوقت أم سقوط صلب). هذه الأرقام هي خط أساس الخطة وشهادة تقدمها لاحقًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب التوازن وفحصه — استباق غائب ودمج مشوش", "points": ["موقف واحد يكشف تفاعليًا واستباقيًا ومقوّية وقصدية.", "الإعلان عن الاتجاه يحوّله كاشفًا استباقيًا.", "أمان ومرافقة واحترام رفض شروط لا خيارات."], "text": {"head": "الكرة الكبيرة — مختبر التعديلات الكامل", "body": "<p>تستعمل الحوصلة الكلاسيكية مواقف الكرة الكبيرة (gros ballon) مختبرًا مركبًا: متعلم جالس أو مستلقٍ على بطنه أو ظهره فوق الكرة بينما يحرّكها الفاحص ببطء في الاتجاهات، فتظهر في موقف واحد التعديلات الوضعية التفاعلية والاستباقية (حين يُعلَن اتجاه الحركة)، وحالة المقوّية الخلفية، ومستوى القصدية في المشاركة، وردود الحماية عند الميل الزائد. لا يعطي موقف آخر هذا الكم من الطبقات في خمس دقائق. شرطه الأماني: مرافقة جسدية دائمة وارتفاع مضبوط ورفض المتعلم يُحترم فورًا — الكرة أداة فحص وتدريب معًا لاحقًا، وستلقاها في درس الأنشطة بثوب آخر.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب التوازن وفحصه — استباق غائب ودمج مشوش", "points": ["الحكم فقرة قنوات وطبقات وشروط انهار وصمود.", "الأرقام الثلاثة مرفقة لكل مهمة أساسية.", "كل نمط فحص يقابله نمط تدريب مختلف."], "text": {"head": "من الفحص إلى الحكم — ملف قنوات لا درجة واحدة", "body": "<p>يُكتب حكم التوازن فقرة قنوات: أي قناة تُسر الدمج، وأي طبقة تسقط أولًا (استباق أم تفاعل)، وبأي شروط ينهار الأداء وبأيها يصمد، وكيف يتصرف الجسد على الكرة. وتُرفق الأرقام الثلاثة لكل مهمة أساسية. على هذه الفقرة تُبنى تدرجات الدرس التالي بدقة: من يجيد الساكن المغمض ويسقط بالتفاعلي تدريبه مفاجآت آمنة متدرجة؛ ومن ينهار بسحب البصر تدريبه نقل ثقل تدريجي إلى الدهليزي والقدمين. حكم «توازن ضعيف 4/10» لا يبني شيئًا من هذا، ولهذا لا يدخل تقارير هذه الدورة.</p><p>وتذكّر ترتيبًا فحصيًا دقيقًا: ابدأ دائمًا بالملاحظة الحرة في اللعب والتنقل قبل أي مهمة مقننة؛ فكثير من متعلميك يؤدون في الحركة العفوية توازنًا لا يظهرونه تحت الطلب (حيث يسرق قلق الأداء وتعدد التعليمات مواردهم)، وآخرون يعكسون الصورة تمامًا. الفارق بين الحر والموجه معلومة تشخيصية بذاته عن طبقة الاضطراب — آلي في الأول، وأدائي-سياقي في الثاني. والبطاريات المقننة التي تتضمن بنود توازن (وقوفات موقوتة ومشيًا على عوارض) تأتي مرحلة ثانية لضبط الأرقام، لا بديلًا عن عين الملاحظة الأولى.</p><p>وفي الأطفال تُقرأ أزمنة الوقفات دائمًا على مقاييس عمرية؛ فالتحسن يُحسب داخل عمر المتعلم وتاريخه، لا بمقارنته ببالغين ولا حتى بأخ أكبر منه بسنتين — فلكل عمر هامش توازن بنيوي مختلف كما رأيت في درس المنظومة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: كيف تعزل مهام الفحص القناةَ المضطربة في دمج التوازن؟", "الإجابة: بتغيير قناة واحدة في كل مرة مع تثبيت الباقي: إغماض العينين يسحب البصر، والسطح الإسفنجي يشوّش إحساس القدمين، وحركات الرأس تستفز الدهليزي؛ فالقناة التي يفكك غيابُها أو تشويشها الأداء هي موضع العطل الأرجح."], "text": null, "take": "آلية اضطراب التوازن استباق غائب ودمج قنوات مشوش؛ وفحصه شبكة شروط متغيرة قناةً قناة تعلوها الكرة الكبيرة مختبرًا، وينتج فقرة قنوات تبني الخطة — لا درجة إجمالية.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 36, "title": "أنشطة التوازن وتوصياته — تدرّج بالأمان نحو الاستباق", "intro": "<p>أنشطة التوازن والتحكم الوضعي عند المصاب بالتوحد. قاعدتها التصميمية من درس المنظومة: العب بمتغيرات القاعدة والثقل والاضطراب والسرعة تدرجًا موثقًا، وابنِ الاستباق الغائب بإعلان يتناقص، واجعل الجلوس الصفي هدفًا موازيًا لكل هدف وقوف.</p>", "slides": [{"kind": "cover", "title": "أنشطة التوازن وتوصياته — تدرّج بالأمان نحو الاستباق", "sub": "الوحدة الثامنة: اضطراب التوازن والتحكم الوضعي", "goals": ["أن تبني تدرج توازن آمنًا من المحسوس إلى الاستباقي", "أن تطبق بطاقة نشاط توازن كاملة بعناصرها العشرة", "أن تقيس تقدم التوازن بأزمنة وسقوطات معدودة لا بانطباعات"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act19_img1.webp", "img2": null}, {"kind": "slide", "title": "أنشطة التوازن وتوصياته — تدرّج بالأمان نحو الاستباق", "points": ["تدرج رباعي المتغيرات بلا قفزات.", "إعلان الاضطراب يُسحب على ثلاث مراحل لبناء الاستباق.", "جرعة يومية قصيرة موزعة تفوق جلسة أسبوعية."], "text": {"head": "مبادئ حاكمة — تدرّج موثق واستباق يُبنى", "body": "<p>أربعة مبادئ. أولًا: لا قفز في التدرج — كل درجة تُتقن بأمان قبل أختها: قاعدة أوسع فأضيق، سطح أصلب فألين، عينان مفتوحتان فمغمضتان جزئيًا، اضطراب متوقَّع فمفاجئ. ثانيًا: الاستباق يُبنى بثلاثية: أعلن الاضطراب قبل حدوثه («سأدفع الكرة يمينًا بعد 3»)، ثم قلّص الإعلان إلى إشارة، ثم اسحبه — فتتحول التهيؤات من خارجية المنظم إلى داخلية البرمجة. ثالثًا: وزّع الجرعة: دفعات توازن قصيرة يوميًا بيد الأهل والمعلمين بأدوات بيئية تفوق جلسة أسبوعية طويلة. رابعًا: وثّق كل درجة بزمن وردود كما في الفحص، فالتقدم في هذا الباب أرقام لا انطباعات حماسية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التوازن وتوصياته — تدرّج بالأمان نحو الاستباق", "points": ["أربع عائلات: ساكن وديناميكي وتفاعلي-استباقي وجالس.", "مهام يدوية أثناء الوقوف تسرق البصر تدريجيًا.", "ترك عائلة سليمة عند المتعلم قرار مهني موثق."], "text": {"head": "ترسانة الأنشطة — من الأرض إلى المفاجأة الآمنة", "body": "<p>للساكن: وقفات متدرجة القاعدة على أسطح متنوعة، وألعاب «تمثال» عند إشارة توقف بصرية، ووقوف مع مهام يدوية تسرق البصر تدريجيًا (نقل كرات بين سلال). للديناميكي: خطوط وعوارض منخفضة، ومسارات أسطح متنوعة، وصعود وهبوط بدرجات متغيرة الارتفاع، ومشي بحمل ثنائي اليدين. للتفاعلي والاستباقي: أرجوحة وكرة كبيرة بإعلانات متناقصة، ودفعات كتف خفيفة متفق عليها بإشارة بدء، وألعاب كرة راجعة غير متوقعة الإيقاع. وللتحكم الوضعي الجالس: كراسٍ بلا ظهر لفترات قصيرة متزايدة داخل مهام محببة، ومساند قدم متغيرة، ومهام وصول بعيد تفرض نقل ثقل جذعي آمن. كل عائلة تُختار من فقرة قنوات المتعلم، وبعض العائلات تُترك لأنها ليست نقصه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التوازن وتوصياته — تدرّج بالأمان نحو الاستباق", "points": ["هدف مرحلي: من إعلان مسموع إلى بلا إعلان.", "مرافقة إنقاذ حاضرة بلا مسك يعطّل التعلم.", "القياس بردود الإنقاذ نوعًا وعددًا لا بالزمن فقط."], "text": {"head": "بطاقة نشاط كاملة — «قبطان الكرة الكبيرة»", "body": "<p>المجال: التوازن التفاعلي والاستباقي. الهدف القابل للقياس: أن يحافظ المتعلم جالسًا على الكرة الكبيرة على توازنه دون مسك، عند إزاحات بطيئة في 4 اتجاهات بإعلان مسموع، ثم بإشارة بصرية فقط، في 4 من 5 محاولات لكل مرحلة. الأدوات: كرة كبيرة بقطر مناسب (ركب مثنية ~90 درجة)، حصيرة أمان، بطاقة إشارة اتجاه. الإعداد: مرافقة خلفية دائمة بيدين قريبتين دون مسك فعلي إلا عند الإنقاذ. الخطوات: جلوس وتثبيت أول بمساعدة، إزاحات صغيرة معدودة بصوت المختص، ثم إظهار البطاقة بدل الصوت، ثم إزاحات بلا إعلان في نطاق صغير آمن. التدرج: سعة أصغر/إعلان كامل ← سعة أكبر/إشارة ← سعة متوسطة/بلا إعلان ← مهام يدوية أثناء الجلوس. التنويع: رمي كرة صغيرة والتقاطها جالسًا على الكرة في المراحل المتقدمة. الأمان: لا إزاحة مفاجئة خارج النطاق المتفق، إيقاف فوري عند رفض أو خوف، أرضية مغطاة بالكامل. التكرار: 3 مرات أسبوعيًا 8 أسابيع. القياس: محاولات ناجحة وعدد ردود الإنقاذ وجودتهما في كل مرحلة. مؤشر النجاح: إتمام المرحلة بلا إعلان ثم نقل المهارة إلى أرجوحة جالسة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التوازن وتوصياته — تدرّج بالأمان نحو الاستباق", "points": ["قدم مسطحة كاملة أو مسند — قاعدة الجلوس الأولى.", "حركة شرعية مجدولة داخل الحصة قبل الاضطراب.", "كل توصية بمالك تنفيذ وموعد مراجعة."], "text": {"head": "التوصيات الصفية والبيتية — جلوس يُبنى لا يُفرض", "body": "<p>لأن أغلى كلفة توازنية تُدفع على كرسي الصف، تحمل الخطة توصيات موازية: كرسي بارتفاع يضع القدمين مسطحتين كاملتين (قاعدة ارتكاز سفلية ثابتة)، أو مسند قدم عند تعذّر الضبط؛ ومهام وصول وحركة شرعية داخل الحصة كل 15-20 دقيقة تُفرّغ حاجة نقل الثقل قبل أن تخرج اضطرابًا؛ وجلوس أرضي متنوع الأشكال في الأنشطة الجماعية يدرّب الجذع بلا شعور بالعقوبة؛ وفي البيت ألعاب حديقة آمنة متدرجة الارتفاع بدل منعها، مع تعليم الأهل قراءة علامات التعب الوضعي لتوقيت الراحات. كل توصية تُكتب باسم صاحب تنفيذها وموعد مراجعتها، فالتوصية بلا مالك وموعد أمنية لا خطة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التوازن وتوصياته — تدرّج بالأمان نحو الاستباق", "points": ["مؤشرات واقعية: سقوطات وزمن جلوس وأرقام فحص.", "التحسن قد يكون طبقيًا — يُقرأ بطبقته.", "أرقام ملموسة للأهل وقود استمرار الجرعة البيتية."], "text": {"head": "القياس والمتابعة — سقوطات أقل وثبات أطول", "body": "<p>تُقاس الخطة بمؤشراتها الحقيقية: سجل سقوطات أسبوعي (عدد وسياق) من البيت والمدرسة، وزمن جلوس وضعي مقبول في الحصة قبل أول انهيار، وأرقام إعادة الفحص الفصلية (أزمنة الوقفات وردود الإنقاذ)، وعودة إلى لعب مُتجنَّب سابقًا موثقة بتاريخ. راجع كل ستة أسابيع على فقرة القنوات نفسها: فإن تحركت السقوطات ولم تتحرك أرقام الوقفات، فقد تحسّن التفاعلي دون الساكن — وكان ذلك نجاحًا صحيحًا في طبقته يُبنى عليه لا فشلًا إجماليًا. وشارك النتائج مع الأهل بالأرقام ذاتها؛ فرؤية «سقوطتان هذا الشهر بدل تسع» أشفع لاستمرار الجرعة البيتية من أي كلام عام عن التحسن.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما المراحل الثلاث لبناء الاستباق الوضعي في أنشطة الاضطرابات المتوقعة؟", "الإجابة: إعلان لفظي كامل عن الاضطراب قبل حدوثه، ثم تقليص الإعلان إلى إشارة بصرية فقط، ثم سحب الإعلان كليًا — فينتقل التهيؤ من تنظيم خارجي إلى برمجة داخلية عند المتعلم."], "text": null, "take": "أنشطة التوازن تدرّج موثق بمتغيرات المنظومة الأربعة، يبني الاستباق بإعلان يتناقص حتى يصير برمجة داخلية، ويُقاس بسقوطات الحياة وثبات الجلوس لا بانبهار الجلسة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 37, "title": "التناسق الحركي — أن تعمل الأجزاء معًا في الزمن الصحيح", "intro": "<p>التناسق الحركي (coordination motrice) هو القدرة على تنظيم حركات أجزاء الجسد المختلفة زمنيًا ومكانيًا لتنفيذ فعل واحد سلس واقتصادي وهادف. قد تكون العضلات قوية والمفاصل سليمة والنية حاضرة، ويفشل الفعل لأن الأجزاء لم تعمل معًا في ترتيبها وتوقيتها الصحيحين. في هذا الدرس تتعرف على أشكال التناسق الأربعة التي ستقود فحصك وخططك في هذا الباب.</p>", "slides": [{"kind": "cover", "title": "التناسق الحركي — أن تعمل الأجزاء معًا في الزمن الصحيح", "sub": "الوحدة التاسعة: اضطراب التناسق الحركي", "goals": ["أن تشرح التناسق الحركي وأشكاله الأربعة بتعريفات قابلة للملاحظة", "أن تميّز التناسق بين القطاعات عن الثنائي والبصري-الحركي والإيقاعي", "أن تقرأ مثال صبّ الماء قراءة تفكيكية بالمكونات الأربعة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l37.jpg", "img2": null}, {"kind": "slide", "title": "التناسق الحركي — أن تعمل الأجزاء معًا في الزمن الصحيح", "points": ["تناوب منظم بين القطاعات لا عمل أجزاء منفردة.", "الخلل في التوزيع الزمني والأدوار غالبًا.", "لا يوصف من حركة عضو واحد."], "text": {"head": "التناسق بين القطاعات — توزيع الأدوار داخل الجسد", "body": "<p>الشكل الأول تناسق بين القطاعات (coordination intersegmentaire): تناوب منظم بين أجزاء الجسد الواحد — ساق وذراع متقابلتان في المشي، وجذع يدور عكس الحوض في الرمي، وعينان ثابتتان فوق جسد متحرك. رأيت توقيع اضطرابه في المشية الخشبية بلا تأرجح ذراعين وفي الاستدارة كتلة واحدة. قاعدته أن كل حركة كبيرة هي في الحقيقة حركات كثيرة صغيرة موزعة الأدوار والتوقيت، وأن الخلل قد يقع في التوزيع وحده بينما كل جزء سليم منفردًا. لهذا لا يوصف التناسق من حركة عضو واحد أبدًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التناسق الحركي — أن تعمل الأجزاء معًا في الزمن الصحيح", "points": ["يد عاملة ويد مسانِدة بأدوار غير متماثلة.", "الأدوار تتبادل عند الحاجة بسلاسة.", "مهام الحياة اليومية أغلبها ثنائية خفية."], "text": {"head": "التناسق الثنائي — يدان بمهمتين مختلفتين", "body": "<p>الشكل الثاني التناسق الثنائي (coordination bimanuelle): أن تعمل اليدان معًا بأدوار متكاملة — غالبًا غير متماثلة: يد عاملة دقيقة (تقصّ، تكتب، تنقّط) ويد مسانِدة تثبّت وتقدّم وتضبط (تمسك الورقة، تدير العلبة، تشدّ الخيط). هو تناسق اجتماعي داخل الجسد: قيادة ومساندة وتبادل أدوار عند الحاجة. اضطرابه يظهر في مهام تبدو بسيطة: فتح علبة، ربط حذاء، قصّ على خط، سكب ماء أثناء إمساك الكأس — كلها أفعال «يدين» قبل أن تكون أفعال يد.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التناسق الحركي — أن تعمل الأجزاء معًا في الزمن الصحيح", "points": ["ترجمة مستمرة بين فضاء بصري وفضاء جسدي.", "التصحيح أثناء الفعل لا بعده فقط.", "أغلب أخطائه توقيت وصول لا اتجاه."], "text": {"head": "التناسق البصري-الحركي — العين تقود واليد تتبع", "body": "<p>الشكل الثالث التناسق البصري-الحركي (coordination oculo-manuelle في اليد، والبصري-الحركي العام في الجسد كله): ربط ما تراه العين بما تنفذه العضلات بتوقيت ومسار مضبوطين — يد تبلغ شيئًا مرئيًا دون تجاوزه أو إسقاطه، وقلم يتتبع خطًا، وقدم تصيب كرة قادمة. يتطلب ترجمة مستمرة بين فضاء بصري وفضاء جسدي مختلفَي الخرائط، وتغذية راجعة بصرية تصحح أثناء الفعل لا بعده فقط. ويرتبط بالاستباق ارتباطًا وثيقًا: فأغلب أخطائه أخطاء توقيت وصول لا أخطاء اتجاه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التناسق الحركي — أن تعمل الأجزاء معًا في الزمن الصحيح", "points": ["توزيع مراحل الفعل على إيقاع داخلي منتظم.", "اضطرابه يفكك فعلًا صحيح الأجزاء في الزمن.", "المشي والنقر والتصفيق أفعال إيقاعية أولًا."], "text": {"head": "التناسق الإيقاعي-الزمني — الفعل على وقع داخلي", "body": "<p>الشكل الرابع هو البعد الزمني الخالص: أن تتوزع مراحل الفعل على إيقاع داخلي منتظم — خطوات متساوية، ضربات متتابعة بفواصل ثابتة، تسلسل لا يتسارع ولا يتعثر. المشي نفسه تناسق إيقاعي قبل كل شيء، والنقر والتصفيق والرسم المتكرر كذلك. اضطراب هذا البعد يجعل الفعل الصحيح الأجزاء «مفككًا» في الزمن: بدايات متعثرة، تسارع فوضوي في الوسط، توقفات في غير مواضعها. وسيأخذ هذا البعد وحدته المستقلة في درس الإيقاع، لأنه عند المصاب بالتوحد باب قائم بذاته.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التناسق الحركي — أن تعمل الأجزاء معًا في الزمن الصحيح", "points": ["التناسق ناتج خمس ركائز لا مهارة معزولة.", "غالبًا عرَض أخير لاضطرابات أخرى متنكرة.", "فحصه إعادة فحص للمنظومة من باب واحد."], "text": {"head": "لماذا التناسق نقطة تجمّع الدورة كلها", "body": "<p>يقف التناسق عند تقاطع كل ما درسته: يحتاج مقوّية مضبوطة التوزيع، وتوازنًا يحرر الأطراف من مهمة الثبات، وتخطيطًا يرتب الخطوات، واستباقًا يهيئ التالية، وانتباهًا يراقب الكل. لهذا يكون غالبًا «العَرَض الأخير» الذي تصل إليه اضطرابات أخرى متنكرة في اسمه، ويكون فحصه الجيد إعادة فحص للمنظومة كلها من باب واحد. وقاعدة مهنية تخرج بها: لا تختم ملف تناسق قبل أن تسأل عن كل ركيزة من ركائزه الخمس في ملف متعلمك، فكثير من «اضطرابات التناسق» خططُها الحقيقية في باب آخر تمامًا.</p><p>مثال عيادي يجمع الأشكال الأربعة في فعل واحد: متعلم يصبّ الماء من إبريق إلى كأس. بين القطاعات: جذع يثبت بينما ينحني الرأس ليتابع مستوى الماء. ثنائي: يد تمسك الكأس وتثبّته وأخرى ترفع الإبريق وتميله بتدرج. بصري-حركي: عين تقارن مستوى الارتفاع بفوّهة الكأس وتصحح ميل الإبريق لحظيًا. إيقاعي: إمالة بوتيرة ثابتة لا اندفاع فيها ولا توقفات. فشل أي مكوّن يوقّع على الانسكاب توقيعًا مختلفًا: انسكاب بداية الفعل غالبًا استباق وتثبيت، وانسكاب منتصفه قوة وإيقاع، وانسكاب عند التوقف ضبط إيقاف بصري.</p><p>وتذكّر ترتيب قراءتها في الجلسة: ابدأ دائمًا بالتناسق الذي تراه قبل أن تطلبه؛ فما يقدمه المتعلم عفويًا في أول دقائقه أصدق تمثيلًا لقدرته الوظيفية مما ينتجه بعد سلسلة تعليمات، والفارق بين الصورتين هو نفسه مادة درسك الثاني عن الوصول إلى الحركة.</p><p>وأشكال التناسق الأربعة لا تتساوى حضورًا في ملفات التوحد: البصري-الحركي والثنائي أكثرها ظهورًا في الشكاوى اليومية، وبين القطاعات أكثرها خفاءً لأنه يُقرأ خطأً في ملفات المشي والتوازن، والإيقاعي أكثرها إهمالًا في الفحوص التقليدية لأنه يحتاج إصغاءً زمنيًا لا نظرة مكانية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا لا يكفي فحص حركة كل عضو منفردًا للحكم على التناسق الحركي؟", "الإجابة: لأن التناسق خاصية علاقة بين الأجزاء — توزيع أدوار وتوقيت متبادل — فقد تكون الأعضاء كلها سليمة فرادى بينما يفشل الفعل لاضطراب توزيعها الزمني والمكاني المشترك."], "text": null, "take": "التناسق الحركي تنظيم الأجزاء معًا في الترتيب والتوقيت الصحيحين، بأربعة أشكال: بين القطاعات، وثنائي، وبصري-حركي، وإيقاعي-زمني — وهو نقطة تجمّع ركائز المنظومة كلها.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 38, "title": "أشكال اضطراب التناسق عند المصاب بالتوحد", "intro": "<p>اضطراب التناسق (trouble de la coordination) من أكثر اضطرابات التوحد الحركية توثيقًا وأوسعها أسماء في الأدبيات: خراقة، لا تجانس، حركات متناقضة. في هذا الدرس تجمع أشكاله في صور قابلة للملاحظة، وتصلها بكلفتها اليومية في الأدوات واللعب والاستقلالية.</p>", "slides": [{"kind": "cover", "title": "أشكال اضطراب التناسق عند المصاب بالتوحد", "sub": "الوحدة التاسعة: اضطراب التناسق الحركي", "goals": ["أن تصف أشكال اضطراب التناسق: خراقة ولاَتجانس وحركات متناقضة", "أن تفسّر مفارقة الحركة الأداتية وحركة العلاقة عند روجي", "أن تميّز متعلم يفشل تحت الطلب وينجح في سياقه الحر"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l38.jpg", "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التناسق عند المصاب بالتوحد", "points": ["وصف أداء منذ دوبريه (1907) لا وصف شخصية.", "إسقاط واصطدام وانسكاب عبر مهام اليوم.", "التفكيك بالمكونات والشروط شرط أي تقرير."], "text": {"head": "الخراقة — التوقيع الأقدم", "body": "<p>أقدم أسماء الاضطراب وأشهرها الخراقة (maladresse) التي وصفها دوبريه (Dupré) منذ 1907 ضمن متلازمة الوهن الحركي مع الباراتونيا والحركات المصاحبة. عند متعلمك تظهر إسقاطًا متكررًا للأشياء، واصطدامًا بالأثاث والأشخاص، وانسكابًا عند كل سكب، وتعثرًا في أدوات الأكل واللبس والرسم. خطورة الاسم أنه صار في الاستعمال اليومي وصف شخصية («طفل أخرق») بينما هو وصف أداء قابل للتحليل والعلاج: خراقة في أي مهام؟ وبأي شروط؟ وبأي مكون من مكونات التناسق الأربعة؟ التقرير الذي لا يفكك الخراقة لا يخدم صاحبها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التناسق عند المصاب بالتوحد", "points": ["تأخر وسطي يقارب خمسة أشهر يخفي تمزقًا داخليًا.", "جزر كفاءة داخل مجالات منهارة عند البعض.", "الحكم خريطة مجالات لا درجة إجمالية."], "text": {"head": "اللاتجانس — بروفيل ممزق الاتجاهات", "body": "<p>رأيت في بداية الدورة أن النمو النفسي الحركي عند التوحد لا متجانس (dysharmonie développementale): تناسق قد يتأخر خمسة أشهر وسطيًا بحسب هوك وديوي (Hauck et Dewey, 2001)، لكن الرقم المتوسط يخفي الحقيقة العيادية: المجالات نفسها ممزقة الاتجاهات داخل المتعلم الواحد — تناسق عام متقدم وتناسق دقيق منهار، أو العكس. وبعضهم يُظهر جزر كفاءة (îlots de compétence) يتفوق فيها على أقرانه داخل بحر من الصعوبات. بروفيل التناسق إذن لا يُكتب درجة واحدة أبدًا، بل خريطة بمجالات، والخطة تنمو من الجزر بقدر ما تعالج المنخفضات.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التناسق عند المصاب بالتوحد", "points": ["فشل بسيط تحت الطلب ونجاح معقد في السياق (1996، 2006).", "الاضطراب اضطراب وصول إلى الحركة أحيانًا لا حركة.", "الفحص بمواقف متنوعة لا بأوامر متتالية فقط."], "text": {"head": "الحركات المتناقضة — يفشل البسيط وينجح المعقد", "body": "<p>أدق صور الاضطراب توثيقًا هي الحركات المتناقضة (kinésies paradoxales) عند ليري وهيل (Leary et Hill, 1996) وراينهارت (Rinehart, 2006): متعلم يفشل في حركات بسيطة مفردة تحت الطلب (يرفع ذراعًا بإشارة، يحاكي وضعية واحدة) وينجح في تنسيقات أعقد بكثير داخل سياقات ذات معنى أو تلقائية (يرتب لعبة معقدة، يؤدي تسلسلًا حركيًا في نشاط محبب). المفارقة تهدم تفسير «لا يستطيع» وتفرض تفسير «لا يستطيع عند الطلب خارج السياق». تداعياتها على الفحص عميقة: موقف الطلب المباشر قد يقيس اضطراب وصول إلى الحركة لا الحركة ذاتها — ولذلك تُبنى الحوصلة على مواقف متنوعة لا على أوامر متتالية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التناسق عند المصاب بالتوحد", "points": ["أداتية للأشياء وعلائقية للتواصل بالإيماء والوضعية.", "قد ينهار أحدهما ويصمد الآخر.", "سطران منفصلان في كل تقرير تناسق."], "text": {"head": "الحركة الأداتية وحركة العلاقة — ملفان في جسد واحد", "body": "<p>فرّق روجيه (Rogé, 1991) وليري وهيل بين حركتين تتعطلان معًا ولا تُقرآن معًا: الحركة الأداتية (motricité instrumentale) التي تكيّف الجسد مع بيئته وأدواته (إمساك، استعمال، تنقل)، وحركة العلاقة (motricité de relation) التي تتواصل بالإيماءات والوضعيات والتعبيرات. متعلمك قد يكون أداتيًا مقبولًا وعلائقيًا منهارًا (يستعمل أدواته ولا يشير ولا يومئ)، أو علائقيًا حاضر الإيماء وأداتيًا متعثرًا. والخلط بينهما في التقارير يجعل خططًا تعالج الباب الخطأ شهورًا. في كل ملف تناسق اكتب سطرين منفصلين: ماذا يفعل بالأشياء؟ وماذا يقول بجسده؟</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التناسق عند المصاب بالتوحد", "points": ["استقلالية تنزف: إطعام بدل أكل وتضييق عالم اللبس.", "تجنب جماعي يضيّع صداقات ومهارات معًا.", "هدف اجتماعي-استقلالي مختار مع المتعلم جزء من الخطة."], "text": {"head": "الكلفة اليومية — استقلالية تُنزف ببطء", "body": "<p>يُدفع ثمن اضطراب التناسق في الاستقلالية قطرة قطرة: وجبات تنتهي بملابس متسخة فيُطعَم بدل أن يأكل، وأزرار وسحّابات تُستبدل بملابس سهلة فيضيق عالم لبسه، وألعاب جماعية تُتجنب فتضيع سنوات صداقة ساحات، وواجبات رسم وقصّ تُنجَز عنه فيتعلم العجز الموثق رسميًا. والكلفة الأخطر نفسية التراكم: متعلم يعرف أنه «الأخرق» بين أقرانه يبني حول الحركة كلها موقف تجنب يحمي كرامته ويجوّع مهارته. كل خطة تناسق جيدة تحمل إذن هدفًا اجتماعيًا-استقلاليًا واحدًا على الأقل يُختار مع المتعلم وأهله، لا من قائمة المختص وحده.</p><p>ولهذا التفكيك ثمرة عملية مباشرة في التقرير الموجه للمعلم: بدل جملة «تناسقه ضعيف، درّبوه» التي لا يعمل بها أحد، يصله سطران قابلان للتنفيذ غدًا: «يفشل في المهام الثنائية عند حمل شيء باليدين معًا؛ قرّبوا المسافات وأعطوه مهام يد واحدة أولى»، و«ينجح في التنسيقات داخل ألعابه ويضطرب تحت الأوامر المباشرة؛ قدّموا النشاط نموذجًا حيًا لا تعليمات متتابعة». التقرير الجيد في هذا الباب وثيقة عمل لغيرك لا وثيقة إثبات لك، ومعياره ما سيتغير في صف المتعلم صباح الغد بسببه.</p><p>وللتقرير في هذا الباب صيغة ختامية ثابتة تحمي صاحب التقرير وصاحب الملف معًا: «التناسق مضطرب في كذا، محفوظ في كذا، ونقطة البناء الأولى كذا» — ثلاثة عناصر لا يغيب أحدها؛ فالاضطراب بلا محفوظات يُقرأ يأسًا، والمحفوظات بلا اضطراب تُقرأ تجاهلًا، وغياب نقطة البناء يجعل الوثيقة كلها وصفًا لا يغيّر شيئًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الذي تثبته «الحركات المتناقضة» (kinésies paradoxales) ضد تفسير «المتعلم لا يستطيع»؟", "الإجابة: أن المتعلم نفسه ينجح في تنسيقات أعقد داخل سياقات ذات معنى بينما يفشل في حركات بسيطة تحت الطلب المباشر؛ فالعطل إذن في الوصول إلى الحركة عند الطلب خارج السياق، لا في القدرة الحركية ذاتها."], "text": null, "take": "اضطراب التناسق عند المصاب بالتوحد خراقة يجب تفكيكها، ولاتجانس يمنع الدرجة الواحدة، وحركات متناقضة تفضح اضطراب الوصول لا القدرة، وملفان أداتي وعلائقي — وكلفته استقلالية تنزف ببطء.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 39, "title": "آلية اضطراب التناسق وفحصه — برمجة مركزية تُقاس في مواقف", "intro": "<p>يقف وراء التناسق المضطرب برمجة مركزية تجمع التخطيط والإيقاع والتغذية الحسية في قرار حركي واحد. في هذا الدرس تتعرف على الآلية بطبقاتها، وعلى شبكة فحص تجمع الملاحظة المنظمة والمهام المقننة دون أن يختزل أيٌّ منهما الآخر.</p>", "slides": [{"kind": "cover", "title": "آلية اضطراب التناسق وفحصه — برمجة مركزية تُقاس في مواقف", "sub": "الوحدة التاسعة: اضطراب التناسق الحركي", "goals": ["أن تشرح آلية البرمجة المركزية للتناسق عند هيوز وراينهارت", "أن تبني فحص تناسق بملاحظة منظمة ومهام مقارنة ثلاثية المستويات", "أن تصوغ حكم تناسق يصلح أساسًا مباشرًا لخطة أنشطة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l39.jpg", "img2": null}, {"kind": "slide", "title": "آلية اضطراب التناسق وفحصه — برمجة مركزية تُقاس في مواقف", "points": ["قرار مركزي يوزع العضلات والترتيب والقوة والتوقيت.", "أجزاء صحيحة وتجميع فاشل توقيع برمجة مرتبكة.", "ابحث عن الخطأ المشترك لا عن كل خطأ فرادى."], "text": {"head": "البرمجة المركزية — قرار واحد لعشرات العضلات", "body": "<p>كل فعل منسق يبدأ قرارًا مركزيًا يوزع: أي عضلات، بأي ترتيب، بأي قوة، وبأي توقيت إيقاف. هيوز (Hughes, 1996) ربط فشل التسلسلات عند التوحد بالوظائف التنفيذية، وراينهارت بيّن أن التحضير هو المضطرب. صورة الآلية عند التناسق: برنامج يُكتب ناقصًا أو مرتبك التوزيع، فيخرج الفعل بأجزاء صحيحة وتجميع فاشل — خطوة سابقة لأوانها، ويد تصل قبل أن يثبت الجذع، وقوة لا تتدرج مع مسافة الهدف. الفهم العملي: ما تراه «أخطاء متفرقة» هو غالبًا خطأ برنامج واحد يتكرر؛ فابحث عن الخطأ المشترك بين أخطاء متعلمك بدل مطاردة كل خطأ بتمرين.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب التناسق وفحصه — برمجة مركزية تُقاس في مواقف", "points": ["نضج التناسق في التصحيح أثناء الفعل لا قبله فقط.", "غياب التصحيح وإفراطه المتقطع نمطان متعاكسان.", "لكل نمط خطة عكس أختها تقريبًا."], "text": {"head": "التغذية الحسية أثناء الفعل — تصحيح بلا توقف", "body": "<p>البرنامج وحده لا يكفي؛ فالتناسق الناضج يصحح أثناء التنفيذ بتغذية عميقة وبصرية مستمرة دون أن يتوقف الفعل أو يتحول إلى حركات متقطعة. عند متعلمك قد تجد أحد نمطين: تصحيح غائب (فعل يجري حتى الاصطدام بلا تعديل مسار) أو تصحيح مفرط التقطع (فعل يتوقف عند كل جزء ليعيد الضبط بصريًا فيخرج متكسرًا بطيئًا). النمطان يفسران تناسقين «سيئين» متعاكسَي الشكل يحتاجان خطتين متعاكستين: الأول يحتاج إبطاءً وحواجز تصحيح مبكرة، والثاني يحتاج بناء ثقة برمجية بأفعال متدفقة متكررة حتى يستغني عن التوقف.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب التناسق وفحصه — برمجة مركزية تُقاس في مواقف", "points": ["مواقف: مشي وجري وقفز ورمي وتسلق منظمة المؤشرات.", "تسجيل نجاح وزمن وجودة وسلوك مرافق.", "مقارنة الموقف الموجه باللعب الحر نصف التشخيص."], "text": {"head": "الملاحظة المنظمة — شبكة المؤسس الميدانية", "body": "<p>تُفحص التنسيقات العامة بملاحظة منظمة في مواقف طبيعية ومصطنعة معًا: مشي وجري (تناوب ذراعين وساقين، طول خطوة، إيقاع، انتظام، وجود طور طيران في الجري)، وقفز متتابع (في حلقات أرضية بتسلسل معدود)، ورمي والتقاط بأحجام ومسافات متدرجة، وتسلق وعبور مسارات. لكل موقف سجّل: النجاح، وزمن الإنجاز، وجودة الحركة (تدرج، توقفات، تعويضات)، والسلوك المرافق (تجنب، طلب تكرار، انفعال). وتُقارن النتائج بمواقف اللعب الحر حيث تظهر الحركات المتناقضة أو تختفي — فالمقارنة بين الموقفين نصف التشخيص.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب التناسق وفحصه — برمجة مركزية تُقاس في مواقف", "points": ["شارلوب-أتويل وM-ABC أرقام موزعة المجالات.", "مهام محلية من فشل المتعلم اليومي نفسه.", "الأرقام خطوط أساس لا أحكام هوية."], "text": {"head": "المهام والبطاريات — أرقام في خدمة الخريطة", "body": "<p>تضيف البطاريات المقننة أرقامًا قابلة للمقارنة والمتابعة: بطاريات التوازن والتناسق الكلاسيكية كبطارية شارلوب-أتويل (Charlop-Atwell) في التنسيقات الديناميكية، وبطارية تقييم الحركة للأطفال (M-ABC) التي توزع نتائجها مجالات (مهارات يدوية، رمي والتقاط، توازن) فتحترم بذلك قاعدة «لا درجة كلية واحدة». وتُستكمل بمهام ثنائية مصممة محليًا من مهام المتعلم اليومية الفاشلة نفسها (فتح، سكب، ربط) لأنها الأصدق بيئيًا. شرط الاستعمال: أرقام البطاريات خطوط أساس للمتابعة، لا أحكام هوية؛ ومتعلم يتحسن رقمه ولا يتحسن أكله وحده لم يتحسن ما يهمّ أهله.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب التناسق وفحصه — برمجة مركزية تُقاس في مواقف", "points": ["ثلاثة أسطر: مكونات، وخطأ مشترك، وفارق موجه/حر.", "اسمان ممنوعان: إجمال الدرجة وخراقة بلا تفكيك.", "خطة قبل أسطر الحكم قفز فوق الفحص."], "text": {"head": "من الفحص إلى الحكم — خريطة مكونات وأخطاء مشتركة", "body": "<p>يُكتب حكم التناسق في ثلاثة أسطر إلزامية: المكونات الأربعة واحدًا واحدًا (بين القطاعات، ثنائي، بصري-حركي، إيقاعي) بقوة وضعف موثقين؛ والخطأ المشترك المتكرر عبر المهام إن وجد؛ والفارق بين الأداء الموجه والحر إن وجد. على هذه الأسطر تُبنى الترسانة التالية اختيارًا دقيقًا، ويُمنع فيها اسمان: «تناسقه ضعيف» إجمالًا، و«خراقة» بلا تفكيك. فإن عجز فحصك عن إنتاج الأسطر الثلاثة، فالفحص نفسه ناقص ولم يحن وقت الخطة بعد.</p><p>وتُبنى شبكة ملاحظتك على قاعدة المقارنة الثلاثية في كل موقف: مهمة بمستوى عمره المتوقع، ومهمة دونها بدرجة، ومهمة فوقها بدرجة؛ فالأولى تريك الفجوة، والثانية تريك ما هو آمن ومستقر في ملفه، والثالثة تريك سقفه الناشئ وما يحدث عند حدوده (أي المكونات ينهار أولًا تحت الضغط؟). هذا التدرج المثلث أرخص من كثير من البطاريات ويعطي خطة الأنشطة نقاط انطلاقها الدقيقة: تُبنى الجرعة من فوق المستوى الآمن بدرجة واحدة، لا من مستوى العمر ولا من مستوى الطموح.</p><p>واستكمل الشبكة بموقف ثنائي الأيدي خالص واحد على الأقل (فتح وإغلاق أغطية، سكب متبادل، تركيب براغي كبيرة) لأن شبكة المشي والرمي وحدها قد تفوّت نصف ملف التناسق اليومي الذي يعيشه المتعلم حول المائدة وخزانة الملابس، حيث لا توجد كرات ولا حلقات بل أغطية وسحّابات وأزرار.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا تجعل الحركات المتناقضة مقارنةَ الأداء الموجَّه بالأداء الحر نصفَ التشخيص في فحص التناسق؟", "الإجابة: لأنها تثبت أن الأداء يتغير جذريًا بين الطلب المباشر والسياق الحر ذي المعنى؛ فمن قاس في موقف واحد حكم على الموقف لا على تناسق المتعلم، والفارق بين الموقفين يحدد إن كان العطل في الحركة أو في الوصول إليها."], "text": null, "take": "آلية التناسق برمجة مركزية مرتبكة التوزيع وتصحيح أثناء فعل غائب أو متقطع؛ وفحصه ملاحظة منظمة وبطاريات مجالية ومهام يومية، ينتج حكمًا بثلاثة أسطر أو لا ينتج خطة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 40, "title": "أنشطة التناسق الحركي وتوصياته — تفكيك ثم دمج ثم سياق", "intro": "<p>أنشطة وتوصيات لاضطراب التناسق عند المصاب بالتوحد، بقاعدة ثلاثية الخطوات: فكّك الفعل إلى مكونه المضطرب، ودرّبه حتى يستقر، ثم أدمجه في أفعال كاملة داخل سياقات ذات معنى — لأن التناسق الذي لا يغادر طاولة التدريب لم يُبنَ أصلًا.</p>", "slides": [{"kind": "cover", "title": "أنشطة التناسق الحركي وتوصياته — تفكيك ثم دمج ثم سياق", "sub": "الوحدة التاسعة: اضطراب التناسق الحركي", "goals": ["أن تبني أنشطة تناسق بمنهج تفكيك ثم دمج ثم سياق", "أن تطبق بطاقة نشاط تناسق كاملة بعناصرها العشرة", "أن توحّد واجهات المائدة والصف والساحة باتفاقات مكتوبة صغيرة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act3_img1.webp", "img2": null}, {"kind": "slide", "title": "أنشطة التناسق الحركي وتوصياته — تفكيك ثم دمج ثم سياق", "points": ["مكون يُدرَّب ثم يُدمج فورًا في الكل.", "إيقاع خارجي منظم مؤقت يُسحب تدريجيًا.", "تنويع سياقي مبكر ضد وهم إتقان السياق الواحد."], "text": {"head": "مبادئ حاكمة — من الجزء إلى الكل إلى الحياة", "body": "<p>أربعة مبادئ. أولًا: التدريب على المكون لا على المهمة الكاملة أولًا (ذراعان متقابلتان في مكانها قبل مشي كامل بها)، ثم دمج فوري في الكل حتى لا يستقر الجزء جزيرة. ثانيًا: الإيقاع الخارجي (عدّ منتظم، تصفيق مرافق، موسيقى ثابتة السرعة) منظم زمني مؤقت يُسحب حين ينتظم الإيقاع الداخلي. ثالثًا: التنويع السياقي مبكر: نفس المهارة في غرفتين وسطحين ومع شخصين، لأن تناسق السياق الواحد وهم إتقان عند هذا المتعلم خصوصًا. رابعًا: النجاحات الصغيرة الموثقة وقود اجتماعي — مهارة ساحة أو مائدة واحدة متقنة تُقدَّم للأقران والأهل نتيجةً مرئية تفتح أبواب مشاركة جديدة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التناسق الحركي وتوصياته — تفكيك ثم دمج ثم سياق", "points": ["أربع عائلات بمكونات الحكم الأربعة.", "تبادل أدوار اليدين أسبوعيًا في الثنائي.", "الاختيار من الخريطة، والترك الموثق قرار مهني."], "text": {"head": "ترسانة الأنشطة بحسب المكون", "body": "<p>لبين القطاعات: مشي وجري بعصيّ متقابلة الإيقاع، وزحف متقاطع ببطاقات أرضية، وسباحة ظهرية مبسطة حيث يفرض الماء التناوب. للثنائي: مهام يد عاملة ويد مساندة متدرجة (علب تُفتح، أوراق تُثبّت وتُقصّ، خيوط تُشدّ وتُربط) بأدوار تتبادل بين اليدين أسبوعيًا. للبصري-الحركي: رمي على أهداف متدرجة الحجم والبعد، والتقاط كرات متدرجة السرعة والمسار، ومسارات كرة أرضية بين علامات. للإيقاعي: تسلسلات نقر وتصفيق وخطو على عدّ، تُبنى أطوالها بنية بنية. وتُختار العائلات من أسطر الحكم الثلاثة، لا تُستعمل كلها على كل متعلم بالتساوي.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التناسق الحركي وتوصياته — تفكيك ثم دمج ثم سياق", "points": ["هدف مركب: إسقاطات وزمن وجودة في قياس واحد.", "التدرج يمر بالثنائي واليد غير المهيمنة.", "التتابع الثنائي بوابة الساحة الاجتماعية."], "text": {"head": "بطاقة نشاط كاملة — «ساعي الكرات بالملعقة»", "body": "<p>المجال: التناسق البصري-الحركي والديناميكي العام. الهدف القابل للقياس: أن ينقل المتعلم 8 كرات تنس بالملعقة الكبيرة عبر مسار 6 أمتار فيه منعطفان، دون إسقاط أكثر من كرة واحدة، في 4 من 5 محاولات، وبزمن يتحسن أسبوعيًا. الأدوات: ملاعق كبيرة متدرجة الحجم، كرات تنس وكرات أكبر أخف، علامات مسار، سلّتا بداية ونهاية. الإعداد: مسار مستقيم أولًا حتى أول نجاح موثق. الخطوات: حمل ووقوف ثابت، مشي مستقيم، إضافة منعطف، إضافة كرة أصغر أو ملعقة أصغر، ثم نقل بيد غير المهيمنة جولة واحدة. التدرج: كرة كبيرة/ملعقة كبيرة/مسار مستقيم ← كرة أصغر/منعطفان ← حمل بملعقتين وكرة واحدة كبيرة (ثنائي) ← مسار بمهام جانبية (عدّ تنازلي مسموع). التنويع: سباق تتابع ثنائي مع قرين متعاون. الأمان: أرضية جافة، توقف فوري عند انزعاج، لا سرعة مفروضة. التكرار: 3 مرات أسبوعيًا 6 أسابيع. القياس: إسقاطات وزمن وجودة مشي (تأرجح ذراع حر). مؤشر النجاح: بلوغ الهدف أسبوعين متتاليين ثم تعقيد درجة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التناسق الحركي وتوصياته — تفكيك ثم دمج ثم سياق", "points": ["اختبارات حياة: لبس وانسكابات وعينات مدرسية ولعب.", "تحسن بلا انتقال = عدّل السياق لا الصعوبة.", "عينات قبل/بعد وقود إيمان الأسرة بالخطة."], "text": {"head": "القياس والمتابعة — مهام الحياة هي الاختبار", "body": "<p>يُقاس تقدم التناسق خارج الجلسة بوظائف الحياة نفسها: زمن ارتداء ملابس كاملة بأزرارها أسبوعيًا، وعدد انسكابات المائدة الموثقة، ومهام قصّ ورسم مدرسية بعينات محفوظة مؤرخة، ومشاركة لعب ساحة واحدة. وتُعاد شبكة الملاحظة المنظمة فصليًا بمؤشراتها ذاتها. قاعدة قراءة النتائج: تحسّن مهمة مدربة بلا تحسن في مهمة حياة شبيهة غير مدربة يعني انتقالًا لم يحدث بعد — عدّل التنويع السياقي قبل أن ترفع صعوبة التدريب. وكل تقدم يُعرَض على الأهل بعينات قبل/بعد (فيديو قصير بموافقتهم أو عينات ورقية)، فإيمان الأسرة بالخطة جزء من جرعتها.</p><p>وتُختم كل خطة تناسق ببند اتفاق واجهة: ثلاث ممارسات موحدة بين البيت والمدرسة والجلسة مكتوبة بلغة كل طرف (من يحمل الصينية؟ كيف يُعرض النشاط الثنائي؟ أي كلمات تشجيع موحدة؟) لأن تناسق المتعلم يتشتت حين تتناقض عليه البيئات في الطلب نفسه: بيت ينجز عنه كل ثنائي ومدرسة تطالبه بكل ثنائي فجأة. الواجهة الموحدة جزء من الجرعة، ومراجعتها في كل لقاء متابعة بند ثابت قبل سؤال الأرقام نفسها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التناسق الحركي وتوصياته — تفكيك ثم دمج ثم سياق", "points": ["ثبات القدمين والمقعد يحرر اليدين والجذع.", "مهام حمل وتوزيع صفية جرعة يومية مقنعة.", "أدوار مناولة اجتماعية تصنع صداقات لا اختبارات."], "text": {"head": "توصيات واجهة — المائدة والصينية والساحة", "body": "<p>نظّم واجهات التناسق الثلاث الكبرى باتفاقات صغيرة ثابتة. على المائدة: أدوات ثقيلة نسبيًا مستقرة القاعدة أولًا، وحمل بأيدٍ اثنتين للأواني الممتلئة مهارة تُدرَّب لا عيب يُخفى، ومقعد بارتفاع يجعل القدمين مستقرتين فيتحرر الجذع واليدان. في الصف: صينية حمل جانبية بيد مساندة مدربة، وانتقالات بمهام حمل حقيقية موزعة على الأسبوع (توزيع كراسات بتنسيق ثنائي مقصود) تصنع جرعة يومية بلا حصص إضافية. في الساحة: ألعاب تناسق اجتماعية بأدوار متبادلة (مناول ومتلقٍّ) تبدأ بأقران متعاونين مختارين، فتتحول المهارة إلى صداقات لا إلى اختبارات.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: متعلم تحسّن كثيرًا في نشاط النقل بالملعقة داخل الجلسات وبقي انسكاب مائدته كما هو؛ ما تعديلك الأول؟", "الإجابة: تعديل التنويع السياقي لا رفع الصعوبة: نقل المهارة إلى سياقات وأدوات وأشخاص متنوعين (ملاعق وأكواب حقيقية وطاولة أكل فعلية) لأن المشكلة انتقال لم يحدث، لا إتقان ناقص."], "text": null, "take": "أنشطة التناسق تفكيك للمكون المضطرب ثم دمج في أفعال كاملة ثم تنويع سياقات، بإيقاع خارجي يُسحب — وتُقاس بمهام الحياة والاستقلالية لا بزمن الجلسة وحده.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 41, "title": "الحركة الدقيقة — مكوناتها ومسار نضجها", "intro": "<p>الحركة الدقيقة (motricité fine) هي أفعال اليد والأصابع المضبوطة التي تبني الاستقلالية الأكاديمية واليومية: إمساك وتلاعب وكتابة وقصّ وربط. صغر عضلاتها يخفي تعقيد منظومتها: قبضات تتطور، وقوة تتدرج، وعين تقود، ويد ثانية تساند. في هذا الدرس تتعرف على مكوناتها ومسار نضجها الطبيعي الذي ستقيس عليه اضطراب متعلمك.</p>", "slides": [{"kind": "cover", "title": "الحركة الدقيقة — مكوناتها ومسار نضجها", "sub": "الوحدة العاشرة: اضطرابات الحركة الدقيقة والجانبية", "goals": ["أن تشرح مكونات الحركة الدقيقة ومسار القبضات حتى الثلاثية", "أن تميّز قبضة ناضجة الشكل عن قبضة متحملة الأداء عبر الزمن", "أن تقرأ محطات المسار النمائي قبل أي حكم على يد متعلمك"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act23_img1.webp", "img2": null}, {"kind": "slide", "title": "الحركة الدقيقة — مكوناتها ومسار نضجها", "points": ["تدرج: راحية ← أصابع ← ملقط سفلي ← دقيق ← ثلاثية.", "ثبات شكل بعد عمره مرحلة لم تُغادر.", "القبضة الثلاثية بوابة القلم والأدوات الدقيقة."], "text": {"head": "القبضات — من الراحة الكاملة إلى الملقط الثلاثي", "body": "<p>يتدرج الإمساك نمائيًا عبر أشكال مشهورة: قبضة راحية (préhension palmaire) يمسك فيها الرضيع بالراحة والأصابع منقبضة كلها، ثم قبضة أصابع ناشئة يتحرر فيها الإبهام تدريجيًا، ثم ملقط سفلي (إبهام وسبابة بجانبيهما)، ثم ملقط دقيق بأطراف الأصابع، ثم القبضة الثلاثية (tridigitale) الناضجة للأدوات الدقيقة والقلم: إبهام وسبابة ووسطى تعمل مثلثة مستقرة. كل شكل متأخر عن عمره أو ثابت بعد تجاوزه مرحلةً علامة قراءة: فمسكة راحية عند ذي سبع سنوات ليست «طريقته» بل مرحلة لم تُغادَر، وتُعامل في الخطة مرحلةً تُستكمل لا عادة تُحترم.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الحركة الدقيقة — مكوناتها ومسار نضجها", "points": ["ضبط قوة بتغذية عميقة لحظية.", "إفراط يسحق وتفريط يفلت — قطبا مقوّية مصغّرة.", "يُقرأ مع خلفية اليد المقوّية دائمًا."], "text": {"head": "القوة والتدرج — ضغط بقدر المهمة", "body": "<p>المكوّن الثاني ضبط القوة: أن تمسك البيضة دون كسرها والكأس الممتلئة دون انسكاب، وأن تضغط القلم بقدر ما يخطّ لا ما يمزّق. يُبنى هذا الضبط بتغذية عميقة من العضلات والمفاصل تخبر الجهاز «كم شددتَ الآن» لحظيًا. اضطرابه في الاتجاهين مألوف لك من المقوّية: إفراط يسحق الأشياء الهشة ويتعب اليد، وتفريط يفلت الأدوات ويبهت الخطوط. ويُقرأ دائمًا مع خلفية اليد المقوّية، فدرس الدقيقة امتداد طبيعي لدرس المقوّية على مسرح أصغر وأدق.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الحركة الدقيقة — مكوناتها ومسار نضجها", "points": ["عين تقود ملليمترات ويد تساند وتدوّر.", "إخفاقات كثيرة مصدرها المرافقان لا الأصابع.", "الفحص يراقب يدين وعينين معًا."], "text": {"head": "التنسيق البصري-الدقيق والثنائي المصغّر", "body": "<p>تحتاج اليد الدقيقة تنسيقين مرافقين: بصري-يدوي (oculo-manuelle) بقيادة عين تتابع أطراف الأصابع في مهام المليمترات (خرز، خيط في إبرة، قصّ على خط)، وثنائي مصغّر حيث تثبّت اليد المساندة وتدوّر وتقدّم بينما تعمل العاملة، بتبادل أدوار سلس عند الحاجة. وكثير من إخفاقات «الدقيقة» عند الفحص الدقيق إخفاقات أحد هذين المرافقين لا الأصابع نفسها: عين تفقد الموضع، أو ورقة تنزلق بلا يد تثبّتها. الفاحص الذي يراقب اليدين والعينين معًا يرى ما لا يراه من يراقب الأصابع وحدها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الحركة الدقيقة — مكوناتها ومسار نضجها", "points": ["غايتان: استقلالية يومية وكتابة ممكنة.", "الأهمية تُقاس بمساس الغايتين لا بدرجات الأصابع.", "النتائج للأهل بلغة «يفعله وحده»."], "text": {"head": "الاستقلالية والكتابة — غايتا الدقيقة الكبيرتان", "body": "<p>تنتهي مكونات الدقيقة كلها إلى غايتين عمليتين: استقلالية يومية (أكل بأدوات، لبس بأزرار وسحّابات ورباطات، نظافة شخصية بأدوات صغيرة) وكتابة (خط مقروء بسرعة مقبولة وكلفة محتملة). الغايتان معيارا أهمية أي اضطراب دقيق: خلل لا يمسّ أيًا منهما ملاحظة أكاديمية، وخلل يضرب إحداهما ملف خطة كامل. وبهذا الترتيب تُقدَّم النتائج للأهل دائمًا: لا بدرجات اختبارات الأصابع، بل بما صار ابنك يفعله وحده وبما سيأتي في خطته.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الحركة الدقيقة — مكوناتها ومسار نضجها", "points": ["المسار محطات قبضة وقوة وتنسيق متتابعة.", "المطلوب امتلاك المسار لا حفظ الأعمار.", "الخطة تُبنى من محطة التوقف لا من العمر وحده."], "text": {"head": "مثال نضج سليم يُقرأ عليه الاضطراب", "body": "<p>تأمل مسارًا سليمًا مختصرًا: رضيع يقبض راحيًا ثم ينقل بين يديه، وطفل سنة ونصف يبني برجًا ويمسك ملعقة بقبضة ناشئة، وطفل ثلاث سنوات يرسم دائرة ويفك أزرارًا كبيرة، وطفل خمس سنوات يقصّ على خطوط ويزرّر ويربط بمساعدة، وطفل سبع سنوات يكتب بقبضة ثلاثية مستقرة ويستعمل أدواته بلا إشراف. ليس المطلوب حفظ الأعمار بل امتلاك المسار: فمقابلة متعلمك عليه تريك أين توقف قطاره — عند أي محطة قبضة أو قوة أو تنسيق — ومن المحطة تُبنى الخطة لا من العمر الزمني وحده.</p><p>وتجدر قراءة محطة القبضات مع سياق اليد الكلي: فقبضة ثلاثية فوق مقوّية يد مرتخية تنهار بعد سطرين كتابة (القبضة صحيحة والتحمل غائب)، وقبضة ناشئة فوق مقوّية ثابتة قد تنتج خطًا مقروءًا ثابتًا أطول مما تظن. لهذا لا يُكتب حكم القبضة في هذه الدورة رقمًا معزولًا أبدًا: يُقرأ ثلاثيًا — شكل قبضة × زمن تحمل × جودة منتج — وعلى هذا الثلاثي وحده تُبنى توقعات الخطة الواقعية.</p><p>وللمسار النمائي وجه مدرسي دقيق: الخط يظهر في ملفات كثيرة بوصفه أول شكوى مكتوبة للأهل رغم أن جذره قبضات وقوة أسبق بسنوات؛ فلا تدع الشكوى الأعلى صوتًا تختصر الفحص في القلم والمقلمة، بل عد دائمًا بالفحص إلى المحطات الأولى في المسار، فالعلاج الذي يبدأ من محطة التوقف يختصر الطريق إلى شكوى الحاضر.</p><p>وهذا المسار نفسه هو ما يجعل ملاحظة اللعب الحر في أول الجلسات اختبارًا مصغرًا كاملًا: دقائق لعب غير موجهة تعرض قبضات المتعلم وقوته وتنسيقه العفويين قبل أن يلوّنها أداء الفحص المطلوب بأي توتر أو ملل.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا تُعامل مسكة راحية عند طفل في السابعة مرحلةً تُستكمل لا «طريقة إمساك» تُحترم؟", "الإجابة: لأن القبضات أشكال نمائية متتابعة لكل منها عمر تجاوز؛ فثبات شكل مبكر بعد عمره يعني أن التدرج توقف قبل القبضة الناضجة، والخطة تستكمل التدرج ببناء الملقط والقبضة الثلاثية لا بتثبيت الشكل المتوقف."], "text": null, "take": "الحركة الدقيقة منظومة قبضات متدرجة حتى الثلاثية، وضبط قوة، وتنسيق بصري وثنائي مصغّر — غايتها استقلالية يومية وكتابة ممكنة، ويُقرأ اضطرابها على مسار نضجها لا على انطباعات.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 42, "title": "اضطراب الحركة الدقيقة عند المصاب بالتوحد — أشكاله وكلفته", "intro": "<p>يظهر اضطراب الحركة الدقيقة عند المصاب بالتوحد في يد تتأخر محطاتها وخطّ يخذل صاحبه وواجبات تُتجنب حتى تصير موقفًا من المدرسة كلها. في هذا الدرس تقرأ أشكاله الموثقة، وتصل بينها وبين كلفته الأكاديمية والنفسية، وتتعلم قراءة إشاراته الدقيقة في الفحص السريع.</p>", "slides": [{"kind": "cover", "title": "اضطراب الحركة الدقيقة عند المصاب بالتوحد — أشكاله وكلفته", "sub": "الوحدة العاشرة: اضطرابات الحركة الدقيقة والجانبية", "goals": ["أن تصف أشكال اضطراب الدقيقة عند التوحد وكلفتها المدرسية والاجتماعية", "أن تفسّر دلالة ملقط الإبهام-الوسطى في فحص البيانوتاج", "أن تميّز اضطراب يدٍ عن تجنب ثانوي بنته سنوات الفشل"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l42.jpg", "img2": null}, {"kind": "slide", "title": "اضطراب الحركة الدقيقة عند المصاب بالتوحد — أشكاله وكلفته", "points": ["مسكة متأخرة وخط متردد وكتابة غير مقروءة سلسلة واحدة.", "«رفض الكتابة» قد يكون ناتجها الأخير لا سببها.", "التأخر في القراءة الصحيحة يرسّخ موقفًا نفسيًا."], "text": {"head": "مسكات غير ناضجة وخط متردد غير مقروء", "body": "<p>في تقارير الحوصلة الموثقة لأطفال التوحد تتكرر صورة مركبة: مسكة راحية غير ناضجة ناقصة المقوّية عند أحدهم، وخط متردد متذبذب، وكتابة عند من بلغها «غالبًا غير مقروءة» تجعل صاحبها شديد النفور من فكرة الكتابة أصلًا. أقرأ الصورة كاملة: ليست ثلاث مشكلات بل نتيجة واحدة لسلسلة — قبضة متأخرة × قوة غير مضبوطة × تنسيق بصري متعب — تخرج في النهاية سلوكًا اسمه «يرفض الكتابة» يُعالج في ملفات أخرى بينما بيته هنا. وكلما تأخرت القراءة الصحيحة، ترسّخ الرفض موقفًا نفسيًا يبقى حتى بعد إصلاح يده.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "اضطراب الحركة الدقيقة عند المصاب بالتوحد — أشكاله وكلفته", "points": ["ملقط إبهام-وسطى المفضّل ينذر بصعوبة الثلاثي.", "مصاحبات وجه ويد مع كل جهد دقيق.", "الإشارات تُقرأ في دقائق وتوجّه الخطة."], "text": {"head": "إشارات الفحص الدقيقة — ما تقوله الأصابع قبل المهام", "body": "<p>تحمل الأصابع نفسها علامات مبكرة في مهام بسيطة: في اختبار عزف البيانو الأصابعي (pianotage) — إبهام يقابل كل إصبع تباعًا — يظهر الملقط المفضّل: إبهام مقابل الوسطى غالبًا بدل السبابة، وهو ينذر بصعوبة الملقط الثلاثي الكتابي قبل أن يُطلب خط واحد. وتظهر حركات مصاحبة في اليد الأخرى والوجه مع كل جهد دقيق، وبطء انتقال بين الأصابع، وتعب سريع يحوّل مهمة دقيقة واحدة إلى نهاية طاقة اليد ليوم كامل. هذه الإشارات تُقرأ في دقائق وتوجّه الخطة كلها؛ إهمالها والاكتفاء بـ«خطه سيئ» أفقر قراءات هذا الباب.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "اضطراب الحركة الدقيقة عند المصاب بالتوحد — أشكاله وكلفته", "points": ["الاضطراب يعمّ القص واللصق والبناء وأدوات الأكل.", "حصص الأشغال قد تصير إذلالًا مقننًا بلا تكييف.", "التكييف بالأدوات والخطوط والزمن شرط بقاء في النشاط."], "text": {"head": "ما وراء القلم — قصّ ولصق وبناء وأدوات", "body": "<p>لا يقتصر الاضطراب على الكتابة: قصّ ينحرف عن خطوطه حتى يمزق العمل، ولصق يفيض أو يجف قبل الوصول، ومكعبات وبازل دقيق يسقط من الأصابع، وخرز وخيوط تُتجنب كليًا، وأدوات أكل دقيقة (شوكة وسكين) تُستبدل بالأصابع في سنّ متقدمة. وفي المدرسة تتحول حصص الأشغال اليدوية إلى جلسات إذلال مقننة إن لم تُكيَّف: أعمال تُعرَض على الجدران مرتبة، وعمل متعلمك في آخرها شكلًا وسرعة. التكييف الصفي هنا (أدوات أسمك، خطوط أعرض، زمن أطول، تقييم بالتقدم لا بأقران) ليس مجاملة بل شرط بقاء المتعلم داخل النشاط أصلًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "اضطراب الحركة الدقيقة عند المصاب بالتوحد — أشكاله وكلفته", "points": ["مئات الإخفاقات تبني تجنبًا شاملًا سابقًا للمحاولة.", "التجنب يعطّل جرعة التدريب نفسها.", "البداية بنجاحات مضمونة دون مستوى التوقف بدرجة."], "text": {"head": "التجنب الثانوي — حين يصير العجز موقفًا", "body": "<p>أخطر تطورات الملف نفسي: متعلم فشل بيده مئات المرات يبني موقف تجنب شامل — يرفض الرسم قبل أن يبدأ، ويمزق واجب الكتابة، ويختار ألعابًا بلا يدين، ويصف نفسه أحيانًا بـ«لا أعرف» قبل المحاولة. عند هذه النقطة لا تعود الخطة يدًا فقط: كل نشاط دقيق ناجح يجب أن يصل إليه نجاحًا محسوسًا سريعًا يعيد بناء توقعه لذاته، وإلا عطّل التجنب جرعة التدريب مهما أُتقنت. ولهذا تبدأ خطط الدقيقة عند المتجنبين بنجاحات مضمونة قصيرة (مهام عند مستوى ما قبل توقفه بدرجة) قبل أي تحدٍّ حقيقي.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "اضطراب الحركة الدقيقة عند المصاب بالتوحد — أشكاله وكلفته", "points": ["أربعة أبواب تُفرَّق بتعديل شرط واحد كل مرة.", "ترتيب الثقل يرتب الخطة.", "فحص نظر مهني عند الشك قبل أي خطة أصابع."], "text": {"head": "التفريق — دقيقة أم بصر أم انتباه أم مقوّية؟", "body": "<p>أربعة أبواب تتشابه أعراضها على الورقة: اضطراب دقيق حقيقي يفشل حتى في مهام قصيرة محببة بلا زمن؛ واضطراب انتباه يبدأ جيدًا ويتفكك مع طول المهمة وتكرارها؛ واضطراب بصري-حركي يفشل في الموجَّه بصريًا وينجح في اللمسي المغمض نسبيًا؛ ومقوّية يد مضطربة تظهر في تذبذب القوة قبل أي خطأ اتجاه. الفحص الفارق يمرّبالمهمة نفسها في أربعة شروط معدّلة واحدًا واحدًا. والواقع أن الأبواب تجتمع، لكن ترتيب ثقلها يقرر ترتيب الخطة — وقاعدة الباب العامة: لا خطة أصابع قبل فحص العينين مهنيًا عند الشك البصري، فبعض «الدقيقة» نظارة لم تُلبس.</p><p>وتتسع كلفة اليد المتأخرة إلى الكتابة بوصفها هوية مدرسية كاملة: متعلم خطه غير مقروء يصحح معلمه ما لا يستطيع قراءته ظلمًا مضاعفًا، ويُقرأ واجبه ناقصًا ولو اكتمل فكريًا، فيتعلم مبكرًا أن ما يفكر فيه لا يصل. لهذا تحمل خطط هذا الباب بندًا تواصليًا صريحًا مع المدرسة: صورة قبضة وخط زمني متوقع للتحسن واتفاق تقييم مرحلي يفصل محتوى الواجب عن شكل خطه حتى تلحق اليد بالفكر.</p><p>وكلما أبكرت القراءة الصحيحة لهذا الملف، كان تدخلها أرخص: مسكة راحية عند ذي خمس سنوات تُبنى ملاقطها في أسابيع لعب، وعند ذي عشر مع موقف تجنب راسخ تحتاج أشهرًا من فك الارتباط قبل بناء الملقط نفسه. أرقام المقارنة هذه مادة حديثك الأول مع أهل كل ملف دقيق مؤجل.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما دلالة تفضيل ملقط إبهام–وسطى في اختبار العزف الأصابعي (pianotage) بالنسبة للكتابة القادمة؟", "الإجابة: أنه ينذر بصعوبة بناء الملقط الثلاثي الذي تقوم عليه القبضة الكتابية الناضجة (إبهام-سبابة-وسطى)؛ فالجهاز يتفادى إشراك السبابة في الدور الذي ستحتاجه الكتابة، فيُبنى تدريب الملقط الصحيح قبل مطالبة الخط."], "text": null, "take": "اضطراب الدقيقة عند المصاب بالتوحد مسكات متأخرة وقوة مفرّطة وخط يولّد نفورًا وتجنبًا ثانويًا يهدد التدريب نفسه؛ ويُفرَّق عن الانتباه والبصر والمقوّية بفحص شروط معدّلة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 43, "title": "الجانبية — هيمنة تُبنى على ثلاثة مستويات", "intro": "<p>الجانبية (latéralité) هي هيمنة أحد جانبي الجسد في الأفعال الأحادية: يد تكتب، وعين تستهدف، وقدم تركل وتنطلق. ليست تفضيل يد واحدة كما تُختزل عادة، بل منظومة هيمنات متعددة الأعضاء والمستويات تكتمل نحو السابعة أو الثامنة. في هذا الدرس تتعرف على مستوياتها الثلاثة وأشكالها، وما يعنيه اضطرابها عند المصاب بالتوحد.</p>", "slides": [{"kind": "cover", "title": "الجانبية — هيمنة تُبنى على ثلاثة مستويات", "sub": "الوحدة العاشرة: اضطرابات الحركة الدقيقة والجانبية", "goals": ["أن تشرح مستويات الجانبية الثلاثة (عصبية وإيمائية واستعمالية)", "أن تميّز جانبية متجانسة عن متقاطعة ومتضاربة الحكم", "أن تحذّر من فرض يد على متعلم لم تستقر هيمنته بعد"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l43.jpg", "img2": null}, {"kind": "slide", "title": "الجانبية — هيمنة تُبنى على ثلاثة مستويات", "points": ["ثلاثة مستويات: عصبية مقوّية وإيمائية عفوية واستعمالية.", "عدم التطابق = جانبية متضاربة، مشكلة بذاتها.", "إشارات قيادة متنازعة تبطئ كل فعل أحادي."], "text": {"head": "المستويات الثلاثة — عصبية وإيمائية واستعمالية", "body": "<p>تُقرأ الجانبية على ثلاثة مستويات قد لا تتطابق. العصبية (neurologique): هيمنة مقوّية عميقة تُفحص بالتأرجح والامتدادية وتعاقب الحركات، وهي مرجع بيرجيس (Bergès) في الحوصلة الكلاسيكية. والإيمائية التلقائية: اليد التي ترتفع أولًا في الإيماءات العفوية (يد فوق يد على الرأس، تشابك أصابع وذراعين، إمساك يد خلف الظهر — حيث تكون الغالبة هي العليا أو الممسِكة). والاستعمالية: اليد التي تختارها المهام الفعلية (كتابة، رمي، قصّ، توزيع أوراق). عدم تطابق المستويات جانبية متضاربة (discordante) — وهي مشكلة سريرية بحد ذاتها لا تفصيل هامشي، لأن الجسد يعمل بإشارات قيادة متنازعة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الجانبية — هيمنة تُبنى على ثلاثة مستويات", "points": ["متجانسة ومتقاطعة وضرورة — صور لا أحكام جودة مباشرة.", "المتقاطعة ليست مرضًا وقد تكلّف في التصويب والقراءة.", "الحكم بالمستويات المتطابقة لا بالصورة وحدها."], "text": {"head": "الأشكال — متجانسة ومتقاطعة وضرورة", "body": "<p>بحسب توزع الهيمنات على الأعضاء تتشكل صور: جانبية متجانسة (homogène) تجمع اليد والعين والقدم في الجهة نفسها وهي الأرسخ أداءً عادة؛ ومتقاطعة أو متغايرة (croisée) كيد يمنى وعين يسرى، وهي شائعة وليست مرضًا لكنها قد تكلّف في مهام التصويب والقراءة عند بعضهم؛ وجانبية ضرورة (de nécessité) حيث تفرض إصابة أو ضعف في الجهة الغالبة أصلًا انتقال القيادة لغيرها. ولا يُبنى حكم على صورة واحدة دون المستويات: فمتقاطعة مستقرة بمستويات متطابقة أيسر حالًا من «متجانسة» ظاهرة تخفي تضاربًا عصبيًا-استعماليًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الجانبية — هيمنة تُبنى على ثلاثة مستويات", "points": ["تثبيت طويل من الرضاعة حتى السابعة أو الثامنة.", "التنقل قبل أوانه طبيعي وبعده قرينة.", "غير الغالبة مساندة متخصصة لا عاطلة."], "text": {"head": "مسار التثبيت — عملية طويلة تنتهي نحو الثامنة", "body": "<p>التثبيت الجانبي عملية نمائية طويلة تبدأ بتفضيلات رضيعية مبكرة (اتجاه رأس، يد تصل أولًا) وتتنظم عبر سنوات الخبرة الحركية حتى تستقر نحو سبع أو ثماني سنوات. قبله يكون التنقل بين اليدين طبيعيًا في أعمار بعينها ومقلقًا في أعمار أخرى؛ فالقراءة العمرية هنا جزء من التشخيص نفسه. وعند الاستقرار يعمل الجانب غير الغالب مساندًا متخصصًا لا عاطلًا: كتابة بيد وتثبيت بأخرى نظام قيادة ومساندة، لا فائز وخاسر. ولهذا كان فرض «نقل اليد» قسرًا في أي عمر تدخلًا ضد منظومة قيادة كاملة لا ضد عادة سطحية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الجانبية — هيمنة تُبنى على ثلاثة مستويات", "points": ["تثبيت متأخر ويد متنقلة وتضارب مستويات أنماط متكررة.", "تُقرأ مع المخطط فهي مخطط مُجانب.", "التثبيت من تفضيل المتعلم الناشئ لا من اختيار الكبار."], "text": {"head": "الجانبية عند المصاب بالتوحد — تأخر وتذبذب وتضارب", "body": "<p>تُظهر ملفات التوحد أنماطًا متكررة: تثبيت متأخر عن الأقران مع يد متنقلة في عمر يجب أن تستقر فيه؛ وجانبيات متقاطعة بنسبة ملحوظة؛ وتضارب مستويات (عصبية لجهة واستعمالية لأخرى)؛ وعند بعضهم يد «مهمة» ويد «لعب» منفصلتين كأن لكل سياق قيادته. وتُقرأ هذه الأنماط دائمًا مع ملف المخطط الجسدي، فالجانبية مخطط مُجانب: لا هيمنة ثابتة على خريطة ضبابية الاتجاهات. عمليًا: متعلم بلا يد مستقرة للكتابة يُدرَّب تثبيتها من تفضيله الناشئ لا من اختيار الكبار، وتُوثَّق نسبة استعمال كل يد عبر المهام لقياس الاستقرار أصلًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الجانبية — هيمنة تُبنى على ثلاثة مستويات", "points": ["كلفتها مكانية وقرائية-كتابية وإرهاق ثنائي.", "تُبنى بالخبرة الحركية المنتظمة لا بالإملاء.", "فقرة كاملة في الحوصلة لا سطر عابر."], "text": {"head": "لماذا تهمّ الجانبية وراء اليد — قراءة وكتابة وفضاء", "body": "<p>كلفتها تتجاوز اختيار اليد: جانبية غير مستقرة ترتبط عند كثير من المتعلمين بصعوبات تنظيم مكاني (يمين/يسار على الذات وعلى الآخرين)، وبطء انطلاق في القراءة والكتابة حيث تتطلب العين واليد قيادة متفقًا عليها، وإرهاق في المهام الثنائية حيث لا قيادة واضحة توزع الأدوار. والعمل النفسي الحركي هنا مثبت الفائدة خاصة عند غير المتجانبين وذوي صعوبات التكيف القرائي والكتابي، حيث تُبنى الهيمنة بالخبرات الحركية المتكررة المنتظمة لا بالإملاء. سجّل في كل حوصلة فقرة جانبية كاملة — مستويات وصورة واستقرارًا — لا سطر «أيمن/أعسر» العابر.</p><p>وللجانبية المتضاربة أثر مباشر في الجلسة نفسها: متعلم إيمائيته اليسرى واستعماليته اليمنى قد يبدو «متردد اليدين» في مهامك بينما هو في الحقيقة يعرض تضاربه لا تردده؛ فقراءة المستوى الغائب عن مهمتك تعطي حكمًا خاطئًا عن حضوره. لذلك تُوصف الجانبية في الحوصلة بمصفوفة صغيرة (مستوى × جهة × ثبات) لا بسطر واحد، وكل نشاط يبنى على المستوى الذي ستوظفه المهمة فعلًا لا على أشهر المستويات.</p><p>ومن صور الجانبية العملية ما يُعرف باليد الكاتبة والعين الأخرى: متعلم يكتب باليمنى ويقرأ متقاطع القيادة فيرهق سريعًا عند النسخ من السبورة تحديدًا، إذ تنتقل عينه بين بُعدين بقيادة لا تتفق مع يدها فتتضاعف كلفة كل سطر منقول. لا يُشخَّص هذا النمط من النظر بل من مقارنة كلفة النسخ القريب بالبعيد في فحصه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الجانبية المتضاربة (latéralité discordante) ولماذا تُعدّ مشكلة بحد ذاتها؟", "الإجابة: هي عدم تطابق مستويات الجانبية عند الفرد الواحد (كأن تكون العصبية المقوّية لجهة والاستعمالية للجهة الأخرى)؛ وهي مشكلة لأن أفعاله الأحادية تتلقى إشارات قيادة متنازعة بين مستويات جهازه، فيتباطأ الانطلاق وتضطرب المهام الثنائية والتصويبية."], "text": null, "take": "الجانبية منظومة هيمنات على ثلاثة مستويات (عصبية وإيمائية واستعمالية) تكتمل نحو الثامنة؛ واضطرابها عند المصاب بالتوحد تأخر وتضارب وتذبذب يُقرأ مع المخطط، ويكلف في الفضاء والقراءة والكتابة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 44, "title": "آلية الحركة الدقيقة والجانبية وفحصهما", "intro": "<p>درس آلية وفحص يجمع ملفَّي الدقيقة والجانبية لأنهما يشتركان في أساس عصبي واحد: نضج شبكات دقيقة التخصص وتوزيع قيادة بين نصفي دماغ وجسد. في هذا الدرس تتعرف على الآلية، وعلى منظومة فحص عملية من اختبارات الأصابع الكلاسيكية إلى شبكة ملاحظة الجانبية.</p>", "slides": [{"kind": "cover", "title": "آلية الحركة الدقيقة والجانبية وفحصهما", "sub": "الوحدة العاشرة: اضطرابات الحركة الدقيقة والجانبية", "goals": ["أن تسمّي اختبارات الدقيقة والجانبية المقننة وموضع كل منها", "أن تبني شبكة فحص جانبية ثلاثية الأبواب لمتعلم واحد", "أن تقارن أداء الفحص بأداء الرغبة الحر قبل أي حكم نهائي"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l44.jpg", "img2": null}, {"kind": "slide", "title": "آلية الحركة الدقيقة والجانبية وفحصهما", "points": ["تمثيل قشري ضخم وتغذية فائقة الكثافة لليد.", "الهيمنة توزيع قيادة بين نصفين متقابلَي الاستقبال.", "نادرًا ما يكون الاضطراب أصابع فقط عند التوحد."], "text": {"head": "الآلية — تخصص دقيق وقيادة موزعة", "body": "<p>تعمل اليد الدقيقة بشبكة عصبية عالية التخصص: تمثيل قشري ضخم لليد والأصابع نسبة لحجمها، وتغذية لمسية وعميقة فائقة الكثافة، وضبط قوة بمقاييس غرامات. والجانبية وجه التوزيع التنظيمي لهذه الشبكة: نصفا الدماغ يستقبل كلٌّ منهما معلومات نصف الجسد المقابل ويقود حركته، والهيمنة توزيع قيادة لا تفوق عضو. عند المصاب بالتوحد تتقاطع عوامل: نضج عصبي-حركي متأخر عمومًا، وحسية لمسية وعميقة مضطربة التعديل تغذي الشبكة بمواد مشوشة، ومخطط جسدي ضبابي الاتجاهات يضعف أرضية الهيمنة. لهذا نادرًا ما يكون اضطراب الدقيقة «أصابع فقط» في ملفاتهم.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية الحركة الدقيقة والجانبية وفحصهما", "points": ["عزف وتنقيط موقوت وقصّ دوائر وإيماءات رقمية.", "مهام وظيفية من يوم المتعلم تُكمل المقننة.", "تسجيل ثلاثي: نجاح وزمن وجودة."], "text": {"head": "فحص الدقيقة — منظومة الأصابع الكلاسيكية", "body": "<p>شبكة فحص مستقرة: العزف الأصابعي (pianotage) للتتابع والملقط المفضّل؛ وتنقيط ستامباك الموقوت (pointillage) لسرعة دقيقة منتظمة وتحملها؛ وقصّ دوائر متحدة المركز (من تقليد أوزيرتسكي Ozeretski) لضبط المسار البصري-اليدوي؛ وإيماءات الأصابع الرقمية (اختبار ري Rey) لتمثيل الأصابع وتسلسلها؛ ومهام وظيفية من يوم المتعلم (أزرار، سحّاب، ملعقة وشوكة، قلم بخطوط منسوخة). لكل مهمة سجّل ثلاثيًا: نجاح، وزمن، وجودة (مصاحبات، قبضة، قوة). وتُقارن النتائج بمهام اليدين معًا لأن كثيرًا من الصورة لا يظهر إلا ثنائيًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية الحركة الدقيقة والجانبية وفحصهما", "points": ["لكل مستوى بابه: عصبي مقوّي وإيمائي عفوي واستعمالي بأنشطة.", "هيمنة عين وقدم جزء من الشبكة لا ملحق.", "النقر الموقوت مقارنة رقمية بين اليدين."], "text": {"head": "فحص الجانبية — شبكة من ثلاثة أبواب", "body": "<p>يُفحص كل مستوى ببابه. العصبي: بالامتدادية والتأرجح وتعاقب الحركات المتناوبة بحثًا عن الهيمنات المقوّية. الإيمائي: بمواقف عفوية مصطنعة (يد فوق يد على الرأس، قبضتان متشابكتان، ذراعان متقاطعتان، إمساك يد خلف الظهر) مع تسجيل اليد العليا أو الممسِكة. الاستعمالي: باستبيانات أنشطة منظمة (من تقليد هيكاين وأجورياغيرا وبيرجيس: أي يد تمسك، ترمي، تقصّ، توزع، تفتح) ومحاكاة أفعال دون أدوات حاضرة. وتُستكمل بهيمنة العين (تصويب بثقب أو منظار لعبة — تنضج قراءته نحو الخامسة أو السادسة) والقدم (ركل، دقّ إيقاعي، أول قدم على الدرج، توازن أحادي) ونقر سريع موقوت يقارن اليدين رقميًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية الحركة الدقيقة والجانبية وفحصهما", "points": ["لا سؤال لفظيًا — ملاحظة استعمال فعلي متعدد.", "لا حكم من مهمة واحدة أو من الكتابة وحدها.", "نقل اليد المفروض ممنوع صراحة في هذه الممارسة."], "text": {"head": "أخطاء فحص شائعة — يد تُفرض وسؤال يُلوّن", "body": "<p>ثلاثة أخطاء تفسد هذا الفحص تحديدًا. أولًا: سؤال الطفل أو أهله «أي يد تستعمل؟» بدل ملاحظة الاستعمال الفعلي عبر مهام متعددة — الإجابة اللفظية تنقل رغبة الأهل أحيانًا لا هيمنة الجسد. ثانيًا: الحكم من مهمة واحدة أو من الكتابة وحدها، بينما الهيمنة صورة توزع عبر عشرات الأفعال. ثالثًا وأخطرها: اعتبار النتيجة رخصة لنقل اليد عند من بدأ يستعمل يساره، فتُفرض اليمنى «للمستقبل» — وهو تدخل يفكك قيادة ناشئة ويزرع اضطرابًا فوق اضطراب، وممنوع في ممارسة هذه الدورة منعًا صريحًا: الجانبية تُدعَم حيث تنشأ ولا تُنقَل حيث لا تعجبنا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية الحركة الدقيقة والجانبية وفحصهما", "points": ["حكم دقيقة بمحطة توقف، وحكم جانبية بفقرة هيمنة.", "الأنشطة تستكمل المحطة وتدعّم التفضيل الناشئ.", "«تمارين عامة» بلا حكمين خطة تُعاد كتابتها."], "text": {"head": "من الفحص إلى الحكم — محطة توقف وفقرة هيمنة", "body": "<p>ينتج الفحص حكمين منفصلين. للدقيقة: محطة التوقف على مسار النضج (أي قبضة، وأي ضبط قوة، وأي مرافق مضطرب) بصيغة «توقف عند كذا» العملية. وللجانبية: فقرة هيمنة كاملة (مستويات وصورة ونسبة استقرار موثقة). وعليهما تُبنى أنشطة الدرس التالي: تستكمل الدقيقة من محطتها، وتُدعّم الجانبية من تفضيلها الناشئ بأنشطة قيادة متكررة للجهة المختارة جسديًا ومساندة متدربة للأخرى. أي خطة تقفز فوق هذين الحكمين إلى «تمارين أصابع عامة» تُعاد كتابتها قبل أن تبدأ.</p><p>وفي شبكة الفحص سجّل أيضًا ما وراء الاختبارات: صورة يد المتعلم العفوية في أول خمس دقائق حرّة (كيف يمسك ما يثيره فعلًا؟ بأي يد يصل أولًا إلى شيء محبب عند طرفي الطاولة؟) فهذه الدقائق الصامتة أصدق أحيانًا من مهام مطلوبة يعرف أنها فحص. وازن دائمًا بين مقروءَين: أداء الفحص وأداء الرغبة؛ حيث اختلفا كان الخلاف نفسه أثمن ما في الجلسة، لأنه يفصل القدرة الحاضرة عن شروط ظهورها اليومية الحقيقية.</p><p>واحذر خاصة في هذا الباب فخ الأدوات اللامعة: اختبارات مرسومة على شاشات ولوحات إلكترونية قد تعطي أرقامًا نظيفة عن أصابع لا تشبه يد متعلمك على ورقة حقيقية بأدوات حقيقية. القاعدة: كل رقم رقمي في الملف يقابله مشاهدة مادية بأدوات المتعلم الفعلية، فإن تعارضا قُدّمت المادية وحُفظ الرقمي هامشَ مقارنة لا حكمًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يُمنع نقل اليد المهيمنة الناشئة (كفرض اليمنى على أيسر ناشئ) في ممارسة هذا الباب؟", "الإجابة: لأن الجانبية منظومة قيادة عصبية-حركية متكاملة لا عادة سطحية؛ فالنقل القسري يفكك قيادة بدأت تستقر ويضيف اضطراب تنسيق وتكيف فوق ملف المتعلم، بينما الممارسة الصحيحة تدعّم الهيمنة حيث تنشأ بخبرات متكررة."], "text": null, "take": "آلية الباب نضج شبكة دقيقة التخصص وقيادة موزعة بين نصفين؛ وفحصه منظومة أصابع كلاسيكية وشبكة جانبية ثلاثية الأبواب، يحرسه منع صريح لفرض اليد ونقلها.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 45, "title": "أنشطة الحركة الدقيقة والجانبية وتوصياتهما", "intro": "<p>أنشطة وتوصيات لباب الدقيقة والجانبية عند المصاب بالتوحد، بقاعدة مزدوجة: الدقيقة تُستكمل من محطة توقفها بمهام حقيقية متدرجة، والجانبية تُدعَّم بأنشطة قيادة متكررة لليد المختارة جسديًا ومساندة مدربة للأخرى — لا بتمارين أصابع عامة ولا بقرارات كبار عن اليدين.</p>", "slides": [{"kind": "cover", "title": "أنشطة الحركة الدقيقة والجانبية وتوصياتهما", "sub": "الوحدة العاشرة: اضطرابات الحركة الدقيقة والجانبية", "goals": ["أن تبني أنشطة دقيقة ببطاقة كاملة ومنتجات تسافر إلى العالم", "أن تدعم استقرار الجانبية بقيادة متكررة لا بفرض مباشر", "أن تقيس التقدم بنسب استعمال وجودة منتج معدودة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act22_img1.webp", "img2": null}, {"kind": "slide", "title": "أنشطة الحركة الدقيقة والجانبية وتوصياتهما", "points": ["مهام حقيقية ذات منتج قبل تمارين مجردة.", "تدرج بمتغير واحد قابل للعزل والقراءة.", "جرعات يومية قصيرة موزعة بيد الجميع."], "text": {"head": "مبادئ حاكمة — حقيقي ومتدرج ومحبوب", "body": "<p>أربعة مبادئ. أولًا: مهام حقيقية قبل تمارين مجردة: خرز يُصنع منه شيء يُلبس، وعجين يصير شكلًا يُهدى، لأن المعنى يحمل التكرار الذي تبنيه المهارة. ثانيًا: التدرج بمتغير واحد (حجم الأداة، أو دقة المطلوب، أو الزمن) حتى يُعرف أي متغير كسر الأداء. ثالثًا: جرعات قصيرة متكررة يوميًا بيد الأهل والمعلمين تتفوق على جلسة أسبوعية طويلة في هذا الباب تحديدًا، لأن الأصابع تتعلم بالتوزيع لا بالتركيز. رابعًا: عند المتجنبين ابدأ دون محطة التوقف بدرجة لضمان نجاحات أولى، فالثقة هنا جزء من العضلة المدربة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة الحركة الدقيقة والجانبية وتوصياتهما", "points": ["أربع عائلات: ملقط وقوة وبصري وثنائي.", "مقاومات وأحجام وثقوب متدرجة الأرقام.", "منتجات الأنشطة نماذج تقدم موثقة للأهل."], "text": {"head": "ترسانة الدقيقة — عائلات بحسب المكوّن المضطرب", "body": "<p>للقبضات والملقط: التقاط متدرج الأحجام (كرات قطنية، خرز كبير، حبوب) بأصابع ثم ملاقط ثم أعواد، ولعب عجين وصلصال بقوى مقاومة متزايدة. لضبط القوة: نقل بيض بلاستيكي ثم حقيقي مفرّغ، وسكب بين أكواب بفوّهات متناقصة، وألعاب ضغط بأهداف مرسومة (اعصر حتى العلامة). للبصري-الدقيق: خيوط في خرز متدرجة الثقوب، وقصّ على خطوط تزداد انحناء وضيقًا، ونقط ولصق داخل حدود مرسومة. للثنائي: مهام تثبيت وتدوير وتقديم (علب، أغطية لولبية، أوراق وكتب تُمسك وتُقلب). كل عائلة تُنتقى من محطة التوقف، وتوثَّق منتجاتها نماذج تقدم للأهل.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة الحركة الدقيقة والجانبية وتوصياتهما", "points": ["هدف زمني وقبضة مصوَّرة وقياس متعدد.", "المنتج يُلبس ويُهدى — معنى يحمل التكرار.", "أمان البلع بند تصميم لا ملاحظة."], "text": {"head": "بطاقة نشاط كاملة — «ورشة الأساور»", "body": "<p>المجال: الحركة الدقيقة — ملقط وبصري-يدوي وثنائي. الهدف القابل للقياس: أن يُدخل المتعلم 12 خرزة (قطر 12 مم بثقب 3 مم) في خيط مرن مثبَّت الطرف، مستعملًا ملقطًا ثلاثيًا، في زمن أقصاه 6 دقائق، في 4 من 5 محاولات. الأدوات: خرز متدرج الأحجام والثقوب، خيوط مرنة وصلدة، صينية حدودها ممسكة مانعة للتدحرج، نموذج سِوار منجز. الإعداد: الخيط مثبّت بمشبك على الصينية لتعمل اليد المساندة على الإمساك والتقديم، والنموذج أمام المتعلم. الخطوات: خرز كبير بخيط صلد، ثم أصغر بمرن، ثم نمط ألوان من بطاقة (لونان متناوبان)، ثم سِوار يُقاس على معصمه ويُلبس فورًا. التدرج: ثقوب أصغر/خيط ألين/نمط أطول ← خرز 8 مم ← زمن مستهدف متناقص. التنويع: صناعة لشخص يحبه وتغليفها هدية — غاية اجتماعية للمهارة. الأمان: إشراف دائم مع صغار الخرز (خطر بلع)، لا خرز في متناول من يستكشف فمويًا إلا بأحجام آمنة كبيرة. التكرار: 10 دقائق يوميًا 6 أسابيع. القياس: عدد الخرز في الزمن، ونوع القبضة المصوَّر كل أسبوعين، وزمن إتمام النمط. مؤشر النجاح: بلوغ الهدف ثم الانتقال لحجم أصغر.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة الحركة الدقيقة والجانبية وتوصياتهما", "points": ["قيادة متكررة ناجحة لأفعال محببة، ومساندة مدربة لأختها.", "المتضاربة تُبنى من مستوى قوتها وتُراقب ربعيًا.", "إقصاء يد أو ربطها أو سخرية منها ممنوع بات."], "text": {"head": "أنشطة دعم الجانبية — قيادة تتكرر فتستقر", "body": "<p>تُدعَّم الجانبية بمنطق واحد: امنح اليد المختارة جسديًا مئات فرص القيادة الناجحة في أفعال أحادية محببة (رمي على هدف، توزيع أوراق لعبة، فتح، ختم، دقّ إيقاعي) وامنح الأخرى مئات فرص المساندة المتقنة (تثبيت، تقديم، إدارة)، فيستقر التوزيع بخبرته لا بتعليمة. وعند الجانبية المتضاربة تُبنى الأنشطة أولًا حول أفعال المستوى الأقوى قراءةً، وتُراقب المستويات الأخرى ربعيًا. ويُمنع منعًا باتًا في هذه الأنشطة: ربط اليد غير المرغوبة أو إخفاؤها أو تعليق ساخر عليها — فالهيمنة تُبنى بالنجاح المتكرر لا بإقصاء المنافس.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة الحركة الدقيقة والجانبية وتوصياتهما", "points": ["مقياسا استقلالية: زمن ونسبة كلمات مقروءة.", "استقرار الجانبية نسبة استعمال تتجاوز 80 بالمئة ثابتة.", "تراجع المؤشرات يراجع الحكم لا همة المتعلم."], "text": {"head": "القياس والمتابعة — استقلالية تُحصى ويد تستقر", "body": "<p>يُقاس الباب بمؤشرين متوازيين عبر ستة أسابيع: للدقيقة — مهام استقلالية محددة (زمن فكّ أزرار قميصه، عدد خرز الورشة في زمنه، قراءة خطه بمقياس وضوح متفق: نسبة كلمات مقروءة من سطر نموذجي)؛ وللجانبية — نسبة استعمال اليد القائدة في عشرة أفعال مرصودة أسبوعيًا (استقرار = نسبة تتجاوز 80 بالمئة بثبات). وراجع الحكمين ربعيًا بصور القبضة ونسب الاستعمال؛ وشارك الأهل والمعلمين واجب جرعة يومية موحدة الأدوات حتى لا تتناقض البيئات على يد المتعلم. توقف التدرج أو تراجع النسب إشارة مراجعة للحكم نفسه لا لهمة المتعلم.</p><p>ويشمل القياس أيضًا بند إنتاج اجتماعي: منتج واحد كل أسبوعين يغادر الجلسة إلى العالم (بطاقة مكتوبة بيده، سِوار مهدى، ورقة مزخرفة بقصّه) لأن مهارات هذا الباب تُبنى دوافعها من مصير منتجاتها؛ متعلم يصنع أشياء تبقى وتُرى يعود غدًا ليده طوعًا، ومتعلم تمارينه تنتهي في سلة الجلسة يتعلم أن يده للفحص لا للحياة. المنتج المسافر مؤشر قياس وناقل دافعية في وثيقة واحدة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما مؤشر استقرار الجانبية الاستعمالية الذي تعتمده المتابعة، وكيف يُقاس؟", "الإجابة: نسبة استعمال اليد القائدة في أفعال أحادية مرصودة (عشرة أفعال أسبوعيًا)؛ ويُعدّ الاستقرار قائمًا حين تتجاوز النسبة 80 بالمئة بثبات عبر الأسابيع، لا بانطباع الأهل أو بمهمة واحدة."], "text": null, "take": "أنشطة هذا الباب تستكمل الدقيقة من محطتها بمهام حقيقية موزعة الجرعة، وتدعّم الجانبية بقيادة ومساندة ناجحتين متكررتين — وتُقاس باستقلالية تُحصى ونسبة استعمال تستقر.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 46, "title": "الإيقاع — المنظّم الزمني الخفي لكل حركة", "intro": "<p>الإيقاع (rythme) هو عودة منتظمة منظمة في الزمن: ضربات متتابعة تفصلها فواصل محسوبة، وأطوار تتعاقب بلا فوضى. كل حركة ناضجة راكبة على إيقاع ما — خطوات مشي، ضربات قلب، دورات تنفس، إيقاع كلام. في هذا الدرس تتعرف على إيقاعات الجسد الأولى، وعلى الإيقاع الداخلي والإيقاع المشترك، لتقرأ اضطرابه بعدها قراءة المختص لا قراءة الموسيقي.</p>", "slides": [{"kind": "cover", "title": "الإيقاع — المنظّم الزمني الخفي لكل حركة", "sub": "الوحدة الحادية عشرة: اضطراب الإيقاع", "goals": ["أن تشرح الإيقاع منظّمًا زمنيًا خفيًا لكل حركة وتفاعل", "أن تميّز دقة البنية الإيقاعية عن انتظام فواصلها في الفحص", "أن تقرأ الإيقاع المشترك أساسًا للتفاعل المبكر مع الآخر"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l46.jpg", "img2": null}, {"kind": "slide", "title": "الإيقاع — المنظّم الزمني الخفي لكل حركة", "points": ["القلب والتنفس والمصّ أول منظمي الزمن.", "الهزّ الإيقاعي أول لغة عاطفية ملموسة.", "الإيقاع طبقة مؤسسة للحركة والكلام معًا."], "text": {"head": "إيقاعات الجسد الأولى — مدرسة الزمن قبل اللغة", "body": "<p>يتعلم الإنسان الزمنَ المنظم بجسده قبل أي ساعة: نبض قلب الأم ثم قلبه أول مترونوم يعيش فيه، ودورات تنفس ومصّ وبلع إيقاعات غذائية منتظمة منذ الساعات الأولى، وهزّ وتهدئة إيقاعية هي أول لغة عاطفية بينه وبين حامليه. المشي نفسه عند نضجه إيقاع دوري تتعاقب فيه الأطوار بفواصل ثابتة تقريبًا. معنى ذلك في ممارستنا: الإيقاع ليس مهارة مضافة على الحركة بل طبقتها الزمنية المؤسسة — واضطرابه يمس كل مهارة مبنية عليه، بما فيها الكلام الذي هو في وجه منه إيقاع أصوات ومقاطع.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الإيقاع — المنظّم الزمني الخفي لكل حركة", "points": ["سرعة تلقائية فردية مستقرة نسبيًا كالبصمة.", "الانتظام محور الباب لا السرعة القصوى.", "«منتظم» و«سريع» حكمان مختلفان تمامًا."], "text": {"head": "الإيقاع الداخلي والسرعة التلقائية", "body": "<p>لكل إنسان إيقاع داخلي (rythme interne) تتولد عنه سرعته التلقائية (tempo spontané): الوتيرة التي ينقر بها ويخطو ويتحدث حين لا يحكمه مقياس خارجي. يثبت هذا الإيقاع نسبيًا عند الفرد ويختلف بين الأفراد اختلاف بصمات. وهو غير السرعة القصوى: فمتعلم سريع العدو قد يكون إيقاعه التلقائي مترددًا متقطعًا، ومتعلم بطيء الحركة قد يكون منتظم الإيقاع كساعة. الفاحص الحاذق يميز بين «لا يستطيع الذهاب أسرع» و«لا يستطيع الذهاب بانتظام» — فالثانية هي اضطراب هذا الباب ولو بدت سرعته عادية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الإيقاع — المنظّم الزمني الخفي لكل حركة", "points": ["تبادل الأدوار واللعب المشترك تزامنات إيقاعية.", "الإيقاع المشترك أساس التفاعل المبكر.", "اضطرابه يجعل الجماعة مكانًا خارج وقت المتعلم."], "text": {"head": "الإيقاع المشترك — أساس التفاعل المبكر", "body": "<p>في التواصل الإنساني إيقاع يوحد الطرفين: تبادل أدوار الرضيع وأمه إيقاعي التوقيت، واللعب المشترك والغناء الجماعي والتصفيق معًا تزامنات تُبنى عليها المشاعر المشتركة. في تأسيس منهج هذه الدورة أن التقليد والإيماءة والإيقاع المشترك أساس التفاعل المبكر. لهذا لا يكون اضطراب الإيقاع عند المصاب بالتوحد ملفًا حركيًا منعزلًا: متعلم لا يستطيع التزامن مع إيقاع آخر يعيش الحصص الجماعية والألعاب الإيقاعية والمحادثات نفسها كأماكن خارج وقته الخاص. باب الإيقاع إذن أحد الجسور الخفية بين الحركة والاجتماع.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الإيقاع — المنظّم الزمني الخفي لكل حركة", "points": ["أربعة أبواب فحص: مشي وبُنى منقولة ونقر حر وتنقيط.", "مؤشران منفصلان دائمًا: دقة بنية وانتظام فواصل.", "موضع الخلل يقرر موضع الخطة."], "text": {"head": "الإيقاع في الحوصلة — ماذا يُقاس فعلًا", "body": "<p>يدخل الإيقاع الفحص من أبواب عملية: انتظام خطوات المشي والجري في شبكة الملاحظة (إيقاع وانتظام من مؤشراتها الثابتة)، وإعادة إنتاج بنى إيقاعية مسموعة (مهمة ستامباك الكلاسيكية: بُنى من ضربات متباعدة بفواصل متنوعة يعيدها المتعلم نقرًا)، ونقر تلقائي حر يُقاس انتظام فواصله، وتنقيط موقوت يجمع الإيقاع والدقيقة معًا. لكل مهمة مؤشران منفصلان: الدقة (طابق البنية؟) والانتظام (ثبتت الفواصل؟). فلا يصح سحق المؤشرين في انطباع واحد «إيقاعه سيئ»، فالخلل قد يكون في سماع البنية أو في توليد الانتظام أو في كليهما — ولكل خطته.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الإيقاع — المنظّم الزمني الخفي لكل حركة", "points": ["باب الوحدة: إيقاع الفعل القابل للتدريب.", "نوم مضطرب يُوثق ويُحال ويُنسق، لا يُضم اعتباطًا.", "حدود واضحة حماية لصدق الملف المهني."], "text": {"head": "حدود الباب — إيقاع حركي لا إيقاع حياة عام", "body": "<p>يمتد الإيقاع استعارةً إلى إيقاعات الحياة (نوم ويقظة وشهية)، ولبعض أصحاب التوحد اضطرابات نوم موثقة فعلًا. لكن باب هذه الوحدة هو الإيقاع الحركي القابل للفحص والتدريب في الجلسة: تنظيم الفعل في الزمن. خلط الملفين يضخّم ملفك بما لا تملك أدواته ويُفقدك الدقة في ما تملكه؛ اضطرابات النوم تُوثق وتُحال وتُنسق مع الأطباء والأهل، ولا تُضم إلى خطة إيقاعك الحركي إلا حيث تتقاطع مع الأداء النهاري موثقًا. الحدود الواضحة هنا ليست تقليصًا للمختص بل حماية لصدق ملفه.</p><p>ومن باب الأمثلة المقربة: جرّب أن تنقر بإصبعك على إيقاع ثابت منتظم ثلاثين ثانية مغمضًا ثم تحقق بالتسجيل؛ ستجد فواصل متفاوتة أكثر مما أحسست. هذا التفاوت الصغير هو ما يعيشه متعلمك مضاعفًا، ومعه يبني كل فعل زمني: خطواته وحديثه وتسلسلاته. الغرض من المثال أن يتذكر المختص أن الانتظام قدرة مولّدة هشة عند الجميع بدرجات، فيعامل اضطرابها باحترام الآلية لا باستغراب الأداء.</p><p>ويمتد الإيقاع خفيًا حتى في أفعال لا تُصنف زمنية ظاهرًا: مصّ الرضيع وبلعه، ومضغ الطعام بوتيرته، وتبادل النظر والأصوات في أول المحادثات. لهذا تُقرأ شكاوى «لا يشارك في اللعب الجماعي» عند بعض المتعلمين قراءة إيقاعية أولًا قبل أي قراءة اجتماعية خالصة، فقد يكون باب الخروج من الجماعة بابًا زمنيًا لا باب رغبة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يفرّق الفاحص بين «لا يستطيع الذهاب أسرع» و«لا يستطيع الذهاب بانتظام»؟", "الإجابة: لأن باب الإيقاع محورُه الانتظام لا السرعة القصوى؛ فمتعلم سريع قد يكون إيقاعه التلقائي متقطعًا، ومتعلم بطيء قد يكون منتظمًا تمامًا — والحكمان المختلفان يقودان إلى خطتين مختلفتين."], "text": null, "take": "الإيقاع طبقة الزمن المؤسسة في كل حركة: إيقاعات جسد أولى، وإيقاع داخلي فردي الانتظام قبل سرعته، وإيقاع مشترك يبني التفاعل — ويُفحص بدقة بنية وانتظام فواصل منفصلتين.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 47, "title": "أشكال اضطراب الإيقاع عند المصاب بالتوحد", "intro": "<p>يظهر اضطراب الإيقاع عند المصاب بالتوحد في بنى لا تُعاد، وخطوات لا تنتظم، وجماعات لا يلحق بها المتعلم إلا متأخرًا عن ضربتها دائمًا. في هذا الدرس تجمع أشكاله الموثقة في مواقف قابلة للملاحظة والفحص، وتصلها بكلفتها في اللعب والصف والحياة.</p>", "slides": [{"kind": "cover", "title": "أشكال اضطراب الإيقاع عند المصاب بالتوحد", "sub": "الوحدة الحادية عشرة: اضطراب الإيقاع", "goals": ["أن تصف أشكال اضطراب الإيقاع: بُنى لا تُستعاد وفواصل متفاوتة وتزامن غائب", "أن تميّز اضطراب الإيقاع عن البطء والانتباه والمقوّية", "أن توثق اضطرابًا إيقاعيًا بمهام زمنية مضبوطة لا بانطباع سمعي"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l47.jpg", "img2": null}, {"kind": "slide", "title": "أشكال اضطراب الإيقاع عند المصاب بالتوحد", "points": ["عدد صحيح بفواصل خاطئة ≠ خطأ في الاثنين.", "نمط الخطأ يفصل سماع البنية عن توليد زمنها.", "التدرج حتى خمس ضربات يبني خريطة زمنية."], "text": {"head": "بنى إيقاعية لا تُستعاد", "body": "<p>أوضح الأشكال فحصيًا فشل إعادة إنتاج البنى (structures rythmiques): تُعرض على المتعلم بنية قصيرة (ثلاث ضربات: قوية-ضعيفة-قوية، أو فواصل طويل-قصير-طويل) فيعيدها مصحّحة العدد مضطربة الفواصل، أو يعيد فواصلها بعدد ناقص، أو يذيبها كلها في نقر متساوٍ. القيمة التشخيصية في نمط الخطأ: من يعيد العدد ويخطئ الفواصل يسمع البنية ولا يولّد زمنها؛ ومن يخطئ الاثنين يفتقد التمثيل نفسه. وتتدرج البنى في الحوصلة من ضربتين إلى خمس متنوعة الفواصل، فتتحول المهمة الصغيرة إلى خريطة قدرات زمنية كاملة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب الإيقاع عند المصاب بالتوحد", "points": ["تسارع وتباطؤ ووقفات بلا سبب ظاهر.", "تفاوت فواصل داخلي واسع عند الفرد نفسه.", "كل خطوة قرار جديد بلا مرساة زمنية."], "text": {"head": "خطو ونقر بلا انتظام — السرعة التلقائية المتعثرة", "body": "<p>الشكل الثاني مشي يتبدل إيقاعه بلا سبب ظاهر: خطوات تتسارع فجأة ثم تتباطأ، وقفات في منتصف المسارات، وانطلاقات مترددة كأن الجسد يفتقد عدّاده الداخلي. وفي النقر التلقائي الحر تتفاوت الفواصل تفاوتًا واسعًا عند المتعلم نفسه من محاولة لأخرى، بينما يثبت عند أقرانه ضمن مجال ضيق. هذا التفاوت الداخلي (variabilité intra-individuelle) توقيع الباب الأصدق: ليس بطئًا ولا سرعة، بل غياب مرساة زمنية ثابتة يستند إليها الفعل. ولهذا تتعب المهام الطويلة أصحاب هذا الشكل أكثر مما تتعب أقرانهم: كل خطوة قرار جديد بلا عادة زمنية تحملها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب الإيقاع عند المصاب بالتوحد", "points": ["تصفيق متأخر ثابت أو سابق أو منفرد بعد فقد الجماعة.", "«لا ينتبه» قراءة سطحية لقدرة تزامن غائبة.", "وجه كلامي: أدوار محادثة مضطربة التوقيت."], "text": {"head": "خارج وقت الجماعة — التزامن الاجتماعي الغائب", "body": "<p>في التصفيق الجماعي والغناء والألعاب الإيقاعية والحلقات، يظهر الشكل الاجتماعي للاضطراب: متعلم يصفق بعد الضربة بثابت زمني، أو يسبقها، أو يفقدها بعد ضربات قليلة ويصفق وحده في صمت الآخرين. المتفرج غير المختص يقرؤها «لا ينتبه» أو «لا يريد المشاركة»، بينما كثيرًا ما تكون قدرة تزامن غائبة لا رغبة مشاركة غائبة — والفرق بين القراءتين مصير كامل: الأولى تدفع إلى اللوم والانسحاب من الجماعة، والثانية إلى بناء تزامن متدرج من الثنائي البطيء إلى الحلقة. وفي المحادثات يظهر وجه لغوي موازٍ: أدوار كلام بإيقاع توقيت مضطرب (مقاطعات متكررة أو صمت طويل بعد كل سؤال).</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب الإيقاع عند المصاب بالتوحد", "points": ["الإيقاع يتفكك بالجهد والضجيج والجوع عند كثيرين.", "قياس بلا سياق يكذب في الاتجاهين.", "نشاط منظم مضبِط يُجدول قبل المواقف الصعبة."], "text": {"head": "تقلب اليوم الواحد — إيقاع مع الحالة لا ضدها", "body": "<p>يتشابك الإيقاع مع حالة الجهاز العامة: متعلم منظم الخطى صباحًا يتفكك إيقاعه بعد جهد أو ضجيج أو جوع، وآخر ينتظم بعد نشاط حسي منظم كأن الإيقاع الخارجي القوي أعاد ضبط عدّاده مؤقتًا. سجّل في ملاحظاتك سياق كل قياس إيقاعي (قبل/بعد ماذا؟) فالأرقام بلا سياقاتها تكذب في الاتجاهين. والتقلب نفسه معلومة خطة: إن كان النشاط المنظم يضبط الإيقاع ساعة كاملة، صار توقيته قبل المواقف الصعبة (حصص جماعية، انتقالات) جزءًا مشروعًا من التهيئة المجدولة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب الإيقاع عند المصاب بالتوحد", "points": ["بطء منتظم الفواصل ملفه التخطيط لا الإيقاع.", "انتباه يتفكك بالمشتت ويعود كاملًا بعده.", "نقر خفيف القوة يفصل المقوّية عن الزمن."], "text": {"head": "ما ليس اضطراب إيقاع — فروق تحمي الملف", "body": "<p>ثلاثة فروق تحمي من التوسع التشخيصي: بطء تنفيذي عام (يفحص في باب التخطيط) يبقي الفواصل منتظمة ولو طويلة؛ واضطراب انتباه يقطع النقر عند المشتتات ويستعيده كاملًا بعده، بينما اضطراب الإيقاع يتفكك بلا مشتت حاضر؛ ومقوّية مضطربة تهز انتظام الضربات بقوة متذبذبة فيُقرأ التذبذب فيها قوة لا زمنًا — وتُفرَّق بمهمة نقر بلا قوة مطلوبة (لمسات خفيفة): فإن انتظم فالملف مقوّي، وإن بقي التفاوت فهو زمني. الفحص الفارق الصغير هذا يوفّر شهور خطط في الباب الخطأ.</p><p>ومن السياقات المدرسية الحاسمة لهذا الباب الأناشيد والأنشطة الصباحية الجماعية كلها: فهي عند أغلب المتعلمين ترفيه، وعند صاحب هذا الملف اختبار تزامن يومي علني يقارن فيه نفسه بالصف كله. المختص الذي يقرأ الملف يوصي بتهيئة مسبقة قصيرة (إيقاع الأغنية نفسها ثنائيًا قبل الحصة بدقائق) أو بدور بديل داخل النشاط ريثما يُبنى التزامن، بدل ترك المتعلم يسجل فشلًا اجتماعيًا يوميًا قبل أن تبدأ حصصه الأكاديمية أصلًا.</p><p>ومن علامات الباب في الكلام نفسه: مقاطع تُنطق بوتيرة متفككة (تسارع داخل الكلمة الواحدة وبطء بين الكلمات) عند من يتكلم من أصحاب الملف، بحيث يصعب على السامع توقّع نهاية جمله فيتعطل تبادل الأدوار من جهته أيضًا. توثّق هذه الصورة في الملف ملاحظةً، وتُحال جوانبها اللغوية الدقيقة إلى مختص التخاطب تنسيقًا لا تنازلًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: متعلم يعيد بنية من ثلاث ضربات بعدد صحيح لكن بفواصل متساوية كلها؛ ماذا يخبرك نمط خطئه؟", "الإجابة: أنه سمع البنية ومثّل عددها لكنه لا يولّد زمنها الداخلي؛ فالعطل في توليد الفواصل الزمنية لا في تمثيل البنية، وتُبنى الخطة على توليد الانتظام والفواصل لا على إعادة تعليم البنى."], "text": null, "take": "اضطراب الإيقاع عند المصاب بالتوحد بنى لا تُستعاد، وتفاوت فواصل داخلي واسع، وتزامن اجتماعي غائب يُقرأ ظلمًا لا مبالاة — ويتقلب مع حالة الجهاز، ويُفرَّق عن البطء والانتباه والمقوّية بمهمات صغيرة حاسمة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 48, "title": "آلية اضطراب الإيقاع — ساعة داخلية وتزامن مع الآخر", "intro": "<p>وراء الإيقاع المضطرب آليتان متكاملتان: ساعة داخلية تولّد الزمن المنتظم داخل الجهاز، وقدرة تزامن تربط زمن المتعلم بزمن الآخرين والعالم. في هذا الدرس تتعرف على الآليتين وأدوارهما، وعلى انعكاس خلل كل منهما على الفحص والخطة.</p>", "slides": [{"kind": "cover", "title": "آلية اضطراب الإيقاع — ساعة داخلية وتزامن مع الآخر", "sub": "الوحدة الحادية عشرة: اضطراب الإيقاع", "goals": ["أن تشرح آلية الساعة الداخلية المخيخية وعمليات التزامن الثلاث", "أن تبني بروتوكول فحص إيقاع من خمس مهمات متدرجة", "أن تميّز ساعة ضعيفة التثبيت عن ساعة غائقة بمؤشر الاحتفاظ"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l48.jpg", "img2": null}, {"kind": "slide", "title": "آلية اضطراب الإيقاع — ساعة داخلية وتزامن مع الآخر", "points": ["المخيخ ودوائر التسلسل مولّد الزمن الداخلي.", "العطل إنتاج لا معرفة: يعرف ويريد ولا يستطيع التوليد.", "قراءة الآلية تنقل الملف من الإرادة إلى الجهاز."], "text": {"head": "الساعة الداخلية — مولّد الفواصل", "body": "<p>يُولد الإحساس بالزمن المنتظم وتقدير مدد الفواصل من شبكات عصبية يشارك فيها المخيخ مشاركة مركزية (منظّم المقوّية والتوازن والتناسق نفسه)، مع دوائر قاعدية وقشرية للتسلسل والتوقع. عملها العملي: حين تنوي نقرًا كل ثانية، ساعة ما تقطع لك الثانية أجزاء محسوسة وتطلق الضربة في موعدها. عند اضطرابها تخرج الفواصل من يدك لا من ذاكرتك: تعرف أن الضربات متساوية وتريدها كذلك، ويخرج إنتاجك متفاوتًا. بهذا الفهم يتحول «لماذا لا ينتظم؟» من سؤال إرادة إلى سؤال مولّد.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب الإيقاع — ساعة داخلية وتزامن مع الآخر", "points": ["ثلاث عمليات: تمثّل وتوليد وتصحيح لحظي.", "تزامن الإنسان يضيف تنبؤًا بالشريك وتكيفًا متبادلًا.", "الفحص يفصل العمليات فلكل تمرينها."], "text": {"head": "التزامن — مطابقة زمنين حيّين", "body": "<p>التزامن (synchronisation) قدرة مركبة من ثلاث عمليات: سماع إيقاع خارجي وتمثّله، وتوليد إيقاع داخلي مطابق، وتصحيح الانحراف لحظيًا بلا توقف. يضاف إليها في التزامن البشري عنصر رابع: التنبؤ بحركة الشريك وقصديته — فنحن لا نتزامن مع مترونوم كما نتزامن مع إنسان يتكيف معنا ونحن نتكيف معه. عند متعلمك قد تنهار عملية دون أخرى: يسمع ولا يولّد، أو يولّد منتظمًا وحده وينهار عند المطابقة، أو يطابق مترونومًا جامدًا ويفشل مع شريك حي متغير. الفحص يفصل العمليات الثلاث لأن لكل منها تمرينها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب الإيقاع — ساعة داخلية وتزامن مع الآخر", "points": ["عقدة وصل: زمني وحركي وانفعالي في باب واحد.", "طقوس منتظمة جرعة تنظيم عصبي لا إدارة جدول فقط.", "بنية الجلسة الإيقاعية علاج قبل الأنشطة."], "text": {"head": "الإيقاع بوابة بين الزمني والحركي والانفعالي", "body": "<p>يقف الإيقاع عقدة وصل في المنظومة: زمنيًا هو وجه التنظيم الزمني الذي سيجاوره في خريطة ملفك؛ وحركيًا هو الغراء الزمني للتناسق؛ وانفعاليًا هو وسيط التهدئة والتنشيط الأول (أغانٍ تهدهد، أناشيد تحمّس، طقوس منتظمة تطمئن). لهذا تتقاطع خطة الإيقاع مع التهيئة العامة لليوم: إيقاعات ثابتة في طقوس الصباح والانتقالات ليست «تنظيم جدول» إداريًا فحسب، بل جرعة تنظيم زمني عصبي يخفض كلفة كل ما بعدها عند ملفات هذا الباب. المختص الذي يبني إيقاع الجلسة نفسه (بداية ثابتة اللحن والإشارة، انتقالات معدودة الخطوات) يعالج بالبنية قبل الأنشطة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب الإيقاع — ساعة داخلية وتزامن مع الآخر", "points": ["خمس مهمات تفصل توليدًا وتمثلًا وتصحيحًا واحتفاظًا.", "جدول مؤشرات رقمي قابل للمقارنة الفصلية.", "بيت القصيد العملي يُسمّى قبل بناء الخطة."], "text": {"head": "فحص الآليتين — بروتوكول موجز", "body": "<p>بروتوكول عملي من خمس مهمات قصيرة: (1) نقر حر ثلاثين ثانية لقياس تفاوت الفواصل التلقائي؛ (2) نقر مطابق لمترونوم بسرعتين (بطيئة وسريعة) لقياس التمثّل والتصحيح؛ (3) إعادة بنى ستامباك متدرجة (ضربتان إلى خمس) لدقة البنية؛ (4) مشي على إيقاع خارجي ثم الاستمرار بعد إيقافه لقياس الاحتفاظ الداخلي؛ (5) تزامن ثنائي حي معك (نقر متبادل وجهًا لوجه) للوجه البشري. تُسجل النتائج جدول مؤشرات (تفاوت، انحراف عن النبض، بُنى صحيحة من محاولات، خطوات محفوظة بعد الإيقاف) فتقارن عبر الفصول أرقامًا لا انطباعات، وتحدد أي عملية من الثلاث هي بيت القصيد في خطة متعلمك.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب الإيقاع — ساعة داخلية وتزامن مع الآخر", "points": ["مواضع التفكك والجزر المنتظمة خريطة قراءة إلزامية.", "الجزر الموجودة أول أدوات الخطة.", "القراءة مع اليوم والملفات شرط قابلية الخطة للحياة."], "text": {"head": "قراءة تفاعلية — الإيقاع لا يُفحص معزولًا عن يوم المتعلم", "body": "<p>تُقرأ نتائج البروتوكول مع خريطة يوم كاملة: مواضع التفكك (انتقالات؟ نهايات حصص؟) ومواضع الانتظام المفاجئ (أغانٍ محفوظة؟ طقوس بيتية؟) فالجزر الإيقاعية الموجودة أدوات الخطة الأولى: نشاط يُبنى حول أغنية ينتظم عليها، أو انتقال يُعاد بناؤه على عدّاده الأقوى. وتُقرأ مع ملف الانتباه (مشتتات حقيقية تُفكك التوليد) وملف المقوّية (هزّات قوة تتنكر تفاوت زمن). ملف إيقاع مقروء وحده وثيقة أكاديمية؛ مقروء مع اليوم والملفات خطة قابلة للحياة.</p><p>وعند قراءة البروتوكول انتبه لمؤشر الاحتفاظ تحديدًا: خطوات منتظمة يواصلها المتعلم بعد صمت المترونوم لعشر خطوات ثم يفقدها ببطء تعني ساعة داخلية موجودة ضعيفة التثبيت — وهي أفضل صور الباب استجابة للتدريب. أما من يفقد الانتظام في الخطوة الثانية فقدًا فوريًا فملفه أعمق ومقاربته أبطأ وأكثر اعتمادًا على حامل خارجي طويل. التمييز بين الصورتين من مهمة واحدة صغيرة يوفر شهور توقعات خاطئة على الأهل والمتعلم معًا.</p><p>واحسب في مؤشراتك انحرافًا مقاسًا ببساطة: اطلب منه النقر معك عشر ضربات على إيقاع متوسط وسجّل كم ضربة خرجت عن المشترك كليًا وكم خرجت انحرافًا جزئيًا متداركًا؛ فالأولى قياس انقطاع والثانية قياس تصحيح، وبينهما يقع الحكم على أي عملية من العمليات الثلاث تستحق جرعتك الأولى وأيها يُترك ينمو بصحبة أخواتها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: متعلم نقره الحر منتظم وينهار تمامًا عند مطابقة المترونوم؛ أي عملية من عمليات التزامن هي بيته؟", "الإجابة: التمثّل والتصحيح عند المطابقة لا التوليد: ساعته الداخلية تعمل وحده، لكن ربط إنتاجه بإيقاع خارجي وتصحيح انحرافه لحظيًا هو المضطرب — فتُبنى الخطة على التدرج في المطابقة لا على تدريب الإيقاع الحر."], "text": null, "take": "آلية الباب ساعة داخلية مخيخية التوليد وقدرة تزامن ثلاثية العمليات؛ وفحصها بروتوكول خمس مهمات رقمي يُقرأ مع خريطة يوم المتعلم وجزر انتظامه الموجودة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 49, "title": "أنشطة الإيقاع وتوصياته — من الخارج إلى الداخل إلى الجماعة", "intro": "<p>أنشطة وتوصيات لاضطراب الإيقاع عند المصاب بالتوحد، بمسار ثلاثي: إيقاع خارجي قوي منتظم يحمل المتعلم أولًا، ثم سحب تدريجي نحو إيقاعه الداخلي، ثم نقل مكتسب إلى التزامن البشري الحي حيث تُصرف قيمة الباب الحقيقية — في الجماعة.</p>", "slides": [{"kind": "cover", "title": "أنشطة الإيقاع وتوصياته — من الخارج إلى الداخل إلى الجماعة", "sub": "الوحدة الحادية عشرة: اضطراب الإيقاع", "goals": ["أن تبني أنشطة إيقاع بتدرج خارجي فداخلي فبشري مشترك", "أن تطبق بطاقة نشاط إيقاعي ثنائي كاملة بعناصرها العشرة", "أن تضبط واجهات الصف والانتقالات على ميزان زمني ثابت"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act43_img1.webp", "img2": null}, {"kind": "slide", "title": "أنشطة الإيقاع وتوصياته — من الخارج إلى الداخل إلى الجماعة", "points": ["خبرة انتظام خارجية تسبق إنتاجها الداخلي.", "سحب بحجب تدريجي لا بانقطاع مفاجئ.", "ثنائي متكيف مرحلة كاملة قبل الجماعة."], "text": {"head": "مبادئ حاكمة — خارجي أولًا، سحب بطيء، شريك حي أخيرًا", "body": "<p>أربعة مبادئ. أولًا: لا تبدأ من الداخلي الغائب؛ ابدأ بخارجي لا يخطئ (مترونوم، عدّ مسموع، تصفيقك الثابت، أغنية مسجلة) حتى يعيش الجسد الانتظام خبرة قبل أن ينتجه. ثانيًا: السحب بالتدريج الصغير (اخفض صوت المترونوم، اجعل العدّ همسًا، أدخل فواصل صامتة يتممها هو) فلا يشعر بانقطاع الحامل. ثالثًا: الجسم الكبير قبل الصغير: خطو وتصفيق جسدي كامل قبل نقر أصابع، فالإيقاع يسكن القطاعات الكبرى أرسخ. رابعًا: الثنائي قبل الجماعة: شريك واحد متكيف (أنت) مرحلة كاملة قبل أي حلقة، لأن الجماعة لا تتكيف مع أحد.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة الإيقاع وتوصياته — من الخارج إلى الداخل إلى الجماعة", "points": ["أربع عائلات: إنتاج ومطابقة وبُنى وتزامن بشري.", "الجزر المحفوظة المحبوبة أول مادة المطابقة.", "لعبة التجميد على الضربة تدريب تصحيح متنكر."], "text": {"head": "ترسانة الأنشطة — عائلات الانتظام والتطابق", "body": "<p>لعائلة الإنتاج الداخلي: مشي وقفز على عدّ منتظم بمسافات متساوية العلامات، وتسلسلات حركية كاملة (قف-صفق-اخطُ) تُكرر حتى تنتظم أطوارها. لعائلة المطابقة: مشي على موسيقى بسرعات متدرجة، ونقر مصاحب لأغانٍ محفوظة محبوبة (جزر المتعلم أولًا)، وتوقّف جماعي عند إشارة داخل الإيقاع (تجميد على الضربة الأخيرة) كلعبة. لعائلة البنى: إعادة بنى نقر متدرجة الطول والتنويع، تُبنى من ضربتين إلى خمس، وتُحوّل لاحقًا إلى بنى حركية (خطوات وتصفيقات مركبة). لعائلة التزامن البشري: ألعاب مرآة إيقاعية ثنائية، وقرع متبادل سؤالًا وجوابًا، وأناشيد ثنائية الأدوار.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة الإيقاع وتوصياته — من الخارج إلى الداخل إلى الجماعة", "points": ["هدف مزدوج: تزامن مستمر وبُنى معادة.", "تبادل قيادة: يتبع مرة ويقود مرة.", "النجاح بشريكين شرط انتقال لا بصاحب الجلسة وحده."], "text": {"head": "بطاقة نشاط كاملة — «الثنائي الإيقاعي»", "body": "<p>المجال: الإيقاع — تزامن وتوليد بنى. الهدف القابل للقياس: أن يطابق المتعلم إيقاع شريكه في نقر متبادل ضمن انحراف غير ملحوظ لثماني ضربات متتالية، وأن يعيد بنية من أربع ضربات متنوعة الفواصل صحيحة في 4 من 5 محاولات. الأدوات: طبول يدوية أو أسطح نقر آمنة، مترونوم أو تطبيق إيقاع، بطاقات بُنى مرسومة (نقاط بأحجام تمثل الفواصل). الإعداد: جلوس متقابل ركب متقاربة، جولة استماع خالصة أولى. الخطوات: نقر موحد بسيط معًا على المترونوم، ثم بلا مترونوم معك قائدًا، ثم أدوار سؤال وجواب (أنت تنقر بنية وهو يرد بمثلها)، ثم هو يقود وأنت تتبع. التدرج: بُنى أطول وفواصل أعقد ← سرعات متنوعة ← ثنائي ثانٍ وجمهور صغير. التنويع: نقل البنى من النقر إلى خطوات وتصفيق في أغنية محبوبة. الأمان: أصوات بمستوى مريح، توقف عند انزعاج سمعي، لا مفاجآت إيقاعية مقصودة إلا في مرحلة التعميم المعلنة. التكرار: 3 مرات أسبوعيًا 6 أسابيع. القياس: ضربات متزامنة متتالية، ونسبة بُنى معادة صحيحة، ودرجة الانحراف المقدرة بالتسجيل الصوتي. مؤشر النجاح: بلوغ الهدف مع شريكين مختلفين.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة الإيقاع وتوصياته — من الخارج إلى الداخل إلى الجماعة", "points": ["بروتوكول فصلي رقمي ورصد بيئي مدرسي.", "تقدم آلي بلا بشري = انقل الجرعة لا ترفع التعقيد.", "تسجيل صوتي قبل/بعد أقوى أدوات الإقناع الأهلي."], "text": {"head": "القياس والمتابعة — الانتظام يُقاس في البرية", "body": "<p>يُعاد بروتوكول الدرس السابق فصليًا بمؤشراته الرقمية، ويُستكمل برصد بيئي: عدد ضربات التصفيق الجماعي المطابقة في حصص حقيقية، وملاحظة معلم لانتظام خطوات الانتقالات. قاعدة القراءة الذهبية: تقدم على المترونوم بلا تقدم مع البشر يعني أن ملفك توقف عند المحطة الثانية من المسار الثلاثي — فلا ترفع تعقيد البُنى، بل انقل الجرعة إلى الثنائيات الحية. ووثّق بصوت قبل/بعد (تسجيل نقر حر ثلاثين ثانية) لعرضه على الأهل؛ سماع الانتظام المولود أقوى من أي تقرير مكتوب.</p><p>وتدخل الخطة البيت بوصفة إيقاعية صغيرة: طقوس يومية ثابتة التسلسل والإشارات (أغنية صباح نفسها، عدّ ثابت قبل الانتقالات، أنشطة مشتركة إيقاعية قصيرة عند العودة) تساهم في تنظيم يوم المتعلم بما يتجاوز الجلسة، وتُعطى للأهل بوصفها ترتيب بيت محبب لا واجبًا علاجيًا حتى لا تموت في أسبوعها الأول. جرعة البيت الإيقاعية تُقاس بالتزام البيت بها لا بأداء المتعلم فيها، فالانتظام بضاعة يصنعها المحيط أولًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة الإيقاع وتوصياته — من الخارج إلى الداخل إلى الجماعة", "points": ["عدّ وإشارة ثابتة قبل كل انتقال صفي.", "دور إيقاعي بديل داخل الجماعة لا خارجها.", "عدّ وأغانٍ ثابتة ساعة خارجية محمولة لليوم كله."], "text": {"head": "توصيات واجهة — إيقاع الصف والانتقالات", "body": "<p>أعد بناء ثلاث واجهات صفية على ميزان هذا الباب. الانتقالات: عدّ تنازلي مسموع جماعي وإشارة إيقاعية ثابتة قبل كل انتقال، فلا يفاجأ صاحب الساعة الهشة بتغيير زمن العالم حوله. الحلقات والأناشيد: تهيئة ثنائية قصيرة بإيقاع النشاط نفسه قبل الدخول الجماعي، ودور إيقاعي بديل (عازف إيقاع مرافق) لمن لم يستقر تزامنه بعد حتى يبقى داخل الجماعة لا خارجها. الاستقلالية المنزلية: سلالم ومهام يومية تُقرن بعدّ أو أغنية ثابتة تصير ساعتَها الخارجية المحمولة — حتى يبني الجسد عدّاده.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: متعلم أتقن مطابقة المترونوم بسرعاتها كلها وما زال تصفيقه الجماعي متأخرًا دائمًا؛ ما قرارك؟", "الإجابة: إبقاء تعقيد البُنى ثابتًا ونقل الجرعة إلى التزامن الثنائي الحي بأشكال متدرجة، لأن عطلته في العمليات البشرية (تنبؤ بالشريك وتكيف متبادل) لا في المطابقة الآلية التي أتقنها أصلًا."], "text": null, "take": "أنشطة الإيقاع مسار من خارجي يحمل، إلى داخلي ينتج، إلى بشري يتزامن — وتُقاس عند البشر لا عند المترونوم وحده.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 50, "title": "الحركات النمطية — تعريفها وأشكالها وانتشارها", "intro": "<p>الحركات النمطية (stéréotypies motrices) حركات متكررة ثابتة الشكل والوتيرة، تبدو بلا هدف خارجي ظاهر، وتعود بالشكل نفسه عبر الأيام: رفرفة يديه، وتأرجح جذع، ودوران حول النفس، والتفاف أصابع. هي من أقدم علامات التوحد الموصوفة في التصنيفات العالمية ومن أكثرها إساءة قراءة في البيوت والمدارس. في هذا الدرس تتعرف على تعريفها الدقيق وأشكالها الكبرى ومكانتها في ملف متعلمك.</p>", "slides": [{"kind": "cover", "title": "الحركات النمطية — تعريفها وأشكالها وانتشارها", "sub": "الوحدة الثانية عشرة: الحركات النمطية: قراءتها وظيفيًا والتعامل معها", "goals": ["أن تعرّف الحركات النمطية بخصائصها الثلاث وأشكالها الموثقة", "أن تربط شدة النمطيات بعمق الاضطراب دون قراءة أخلاقية", "أن تميّز نمطية عن عادة تهدئة بشرية عامة بمعايير مكتوبة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l50.jpg", "img2": null}, {"kind": "slide", "title": "الحركات النمطية — تعريفها وأشكالها وانتشارها", "points": ["تكرار وثبات شكل وغياب هدف ظاهر — ثلاثية التعريف.", "كل خاصية تمنع خلطًا تشخيصيًا مختلفًا.", "خفقان اليدين والتواء الأصابع أمثلة التصنيفات نفسها."], "text": {"head": "التعريف — تكرار ثابت بلا هدف ظاهر", "body": "<p>تقوم النمطية على ثلاث خصائص مجتمعة: تكرار (الحركة تعود عشرات المرات بصورة دورية)، وثبات شكل (النسخة العاشرة تشبه الأولى بلا تنويع قصدي)، وغياب هدف ظاهر (لا تبلغ شيئًا ولا تصلح شيئًا ولا تخاطب أحدًا بمعناها الحرفي). وكل خاصية تحمي من خلط: فحركة متكررة متنوعة الشكل لعبٌ استكشافي، وحركة ثابتة هدفها واضح عادةٌ وظيفية، وحركة واحدة غير متكررة مهما غرُبت ليست نمطية بعد. وفي التصنيفات العالمية (CIM-10) تُذكر الأمثلة بنفسها: «حركات نمطية متكررة كخفقان اليدين أو التواء الأصابع» ضمن صورة الاضطراب.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الحركات النمطية — تعريفها وأشكالها وانتشارها", "points": ["خريطة: يدوية وجذعية ورأسية ومشوية ومركبة.", "ترسانة خاصة ثابتة لكل متعلم تقريبًا.", "التعدد والسياقات مادة الملف قبل الوظائف."], "text": {"head": "أشكالها الكبرى — خريطة أعضاء ومواقف", "body": "<p>تتوزع النمطيات الحركية الشائعة على خريطة: يدوية (رفرفة، فرك، التواءات أصابع، حركات أصابع أمام العينين — وهي جسر إلى الخصوصيات البصرية)، وجذعية (تأرجح أمامي-خلفي أو جانبي، دوران الجذع)، ورأسية-وجهية (هزّ رأس، تكلفات تعبيرية متكررة)، ومشوية (قفزات متكررة في المكان، دوران حول النفس، جريات ذهاب وإياب على مسار ثابت)، ومركبة (سلسلة ثابتة من حركات عدة تعود كوحدة واحدة). لكل متعلم ترسانته الخاصة الثابتة غالبًا، وتعدّد أشكالها وسياقاتها مادة الملف الأولية قبل أي كلام عن وظيفة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الحركات النمطية — تعريفها وأشكالها وانتشارها", "points": ["شدتها وتعددها قرينان للعمق المعرفي والاضطراب (2002).", "أشكال الصغار تتبدل مع النمو — لا أحكام أبدية مبكرة.", "أربع خانات توثيق: شكل وتكرار وأطول نوبة وسياقات."], "text": {"head": "مكانتها في الاضطراب — شدة وتطور قرينتان", "body": "<p>وثّق ميليتيرني (Militerni, 2002) ومن تبعه ارتباط شدة النمطيات وتعددها بالمستوى المعرفي وبشدة الاضطراب العام: فهي أكثر حضورًا عند من هم أشد إصابة وأقل قدرة لغوية وتواصلية. معنى ذلك مزدوج: عياديًا — كثافة نمطيات عامل قراءة لعمق الصورة لا وصمة أخلاقية لصاحبها؛ وتطوريًا — عند كثير من الأصغر سنًا تتبدل الأشكال مع النمو (أشكال باكرة تختفي أو تتحول لأشكال أرقّ) فلا يُبنى حكم «مدى الحياة» على صور العام الأول. ويُسجَّل دائمًا في الملف: شكل، وتكرار تقريبي، وأطول نوبة، وسياقات الظهور الكبرى — أربع خانات لا تنازل عنها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الحركات النمطية — تعريفها وأشكالها وانتشارها", "points": ["قراءات المحيط الجاهزة تعاملها رسالة معاندة مقصودة.", "الوظيفة الأولى للمختص هنا تربوية محيطية.", "الانتقال من سجل السوء إلى سجل الإشارة نصف العلاج البيئي."], "text": {"head": "ما تبدو عليه لغير المختص — قراءات جاهزة خاطئة", "body": "<p>يحمل المحيط قراءات تلقائية للنمطية كلها تقريبًا مؤذية: «يعبث»، «يعاند»، «لا ينتبه إليك»، «يستفزنا»، «يجب أن يتوقف فورًا عنها كي يتعلم». كل قراءة منها تعامل الحركة رسالة مقصودة ضد أحد، بينما ملفها العلمي أعمق وأهدأ. وظيفة المختص الأولى في هذا الباب تربوية محيطية: أن ينقل النمطية من سجل «السوء» إلى سجل «الإشارة» — ظاهرة تُقرأ وتُفهم ويُبنى عليها. أهل ومعلمون يفهمون الإشارة يتوقفون تلقائيًا عن نصف التدخلات الخاطئة التي كانت تغذي المشكلة أصلًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الحركات النمطية — تعريفها وأشكالها وانتشارها", "points": ["شكل واحد قد يعني ملفات مختلفة كليًا.", "لا رأي في نمطية بلا أسبوع توثيق سياقي.", "تدريب الأهل على التوثيق قبل التفسير."], "text": {"head": "نمطية واحدة لا تكفي — الصورة دائمًا ملف لا حركة", "body": "<p>تحذير بنيوي لهذا الباب: كل تحليل لاحق في هذه الوحدة يُبنى على ملف نمطية موثق (شكل وسياقات وتكرارات زمنية ووظائف مرشحة) لا على ملاحظة عابرة لحركة واحدة في جلسة واحدة. متعلم يرفرف عند الفرح وآخر يرفرف عند الغمرة وآخر عند الملل: شكل واحد وثلاثة ملفات وثلاث خطط. ومن لا يملك الملف لا يملك رأيًا في النمطية — قاعدة تُلزمك قبل أن تُلزم غيرك، وتُدرَّب عليها الأهل بجملتهم: «وثّق لي أسبوعًا كاملًا مواقفها، وبعدها نتحدث في معناها».</p><p>ولاحظ خاصةً فارقًا يغيب عن أكثر الملاحظين: النمطية تتصاعد غالبًا عند غياب البنية لا عند حضور المثيرات فقط — في أوقات «اللاشيء» (انتقالات غير منظمة، فراغات بين الأنشطة، مشاوير بلا مهمة). لهذا تُقرأ خريطة النوبات على خريطة اليوم البنيوية لا على قائمة أحداثه فقط، وكثير من ملفات هذا الباب تُحل نصف نوباتها إعادةَ بناء لبنية أوقات الفراغ قبل أي تدخل موجه للحركة نفسها بزمن طويل.</p><p>احفظ في جيبك معيار تمييز سريع عند أول لقاء بأي ملف: اسأل الأهل «متى كانت آخر مرة مرّ فيها يوم كامل بلا هذه الحركة، وماذا كان مختلفًا في ذلك اليوم؟» فإجابتهم الأولى غالبًا تحمل مفتاح سياقها الأكبر: يوم بلا انتظار، أو يوم كله حركة، أو يوم مع شخص بعينه — ومن المفتاح تُبنى أسئلة التوثيق المفصلة بدل أن تبدأ من صفر التخمين.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الخصائص الثلاث التي يجب اجتماعها لتسمية حركة ما نمطية حركية؟", "الإجابة: التكرار الدوري، وثبات الشكل عبر المرات، وغياب هدف خارجي ظاهر؛ فإن تنوّع شكلها كانت استكشافًا، وإن ظهر هدفها كانت عادة وظيفية، وإن لم تتكرر لم تستحق الاسم بعد."], "text": null, "take": "الحركات النمطية تكرار ثابت الشكل بلا هدف ظاهر، مرتبطة شدتها بعمق الاضطراب، وتُساء قراءتها محيطيًا باستمرار — ولا تُقرأ أبدًا حركةً مفردة، بل ملفًا موثقًا سياقيًا.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 51, "title": "قراءة النمطية وظيفيًا — ماذا تفعل لصاحبها؟", "intro": "<p>«بلا هدف ظاهر» في التعريف لا تعني بلا وظيفة؛ فالنمطية عند صاحبها تعمل عملًا ما: تنظّم إثارته، أو تعبّر عن حالته، أو تملأ فراغًا. القراءة الوظيفية (lecture fonctionnelle) هي منهج هذا الدرس: منهج توثيق سياقي يجعل من كل نمطية فرضية قابلة للفحص، بدل أحكام جاهزة تقفز إلى المنع أو التجاهل.</p>", "slides": [{"kind": "cover", "title": "قراءة النمطية وظيفيًا — ماذا تفعل لصاحبها؟", "sub": "الوحدة الثانية عشرة: الحركات النمطية: قراءتها وظيفيًا والتعامل معها", "goals": ["أن تقرأ أي نمطية وظيفيًا بشبكة متى وأين وقبل وبعد", "أن تبني فرضيات وظيفية وتختبرها بتعديل بيئي صغير آمن", "أن تميّز تغيّرًا مفاجئًا في نمطية يستدعي فحصًا طبيًا أو سياقيًا"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l51.jpg", "img2": null}, {"kind": "slide", "title": "قراءة النمطية وظيفيًا — ماذا تفعل لصاحبها؟", "points": ["أربعة أسئلة: متى وأين وقبل وبعد لكل نوبة.", "عشرون نوبة موثقة حدّ ظهور الأنماط الصادقة.", "التوثيق الموحد أهلًا ومدرسة وجلسة شرط المنهج."], "text": {"head": "منهج القراءة — متى وأين وقبل وبعد", "body": "<p>تُبنى القراءة على شبكة من أربعة أسئلة لكل نوبة موثقة: متى (ساعة ونشاط ومرحلة يوم)؟ وأين ومع من (مكان وأشخاص ومتطلبات)؟ وما قبل (المثير المباشر: ضجيج، انتظار، انتقال، طلب، انقطاع محبب)؟ وما بعد (ماذا تغير بسببها: توقف المثير، اقترب أحد، تُرك وحده، استمر كل شيء نفسه)؟ بعد عشرين نوبة موثقة إلى هذا الحد تبدأ الأنماط بالظهور بلا تخمين: ارتباطات بسياقات دون غيرها، وتوقيتات، وتسلسلات. أسبوع التوثيق الذي طُلب من الأهل والمعلمين بنفس الشبكة هو مادة هذا الدرس الخام — ومن دونه تبقى «الوظائف» ثرثرة نظرية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "قراءة النمطية وظيفيًا — ماذا تفعل لصاحبها؟", "points": ["صمّام تنظيم: تفريغ عند الغمرة وتوليد عند الخمول.", "الشكل الواحد قد يخدم الاتجاهين بسياقين.", "سؤال كل نوبة: أي اتجاه هذه المرة؟"], "text": {"head": "الوظيفة التنظيمية — صمّام إثارة في الاتجاهين", "body": "<p>أقوى الفرضيات وأوسعها توثيقًا أن النمطية صمّام تنظيم ذاتي للإثارة الحسية-الانفعالية: عند الغمرة (إثارة فائضة: ضجيج، ازدحام، انفعال كبير فرحًا كان أو قلقًا) تعمل الحركة الإيقاعية الثابتة تفريغًا وضبطًا — مدخل ثابت متوقع يصنعه الجسد لنفسه وسط عالم لا يُتوقع. وعند الخمول (إثارة ناقصة: انتظار طويل، بيئة فقيرة، ملل) تعمل مولّد إثارة ذاتيًا. الاتجاهان يخرجان بالشكل نفسه أحيانًا، ويفترقان بالسياق: نوبة بعد محفز صاخب ≠ نوبة في انتظار صامت؛ فلا تسأل «لماذا يفعلها؟» بل «في هذه النوبة، أي اتجاه؟».</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "قراءة النمطية وظيفيًا — ماذا تفعل لصاحبها؟", "points": ["قاموس انفعالي بدائي يقرؤه المحيط المدرب.", "إشارات تصعيد مبكرة تمنع أزمات كاملة.", "ما يتبع الحركة يعلّم عنها بقدر ما يسبقها."], "text": {"head": "الوظيفة التعبيرية والتواصلية البدائية", "body": "<p>عند من لا يملك لغة أو وسيلة تعبير ناضجة، تصير النمطيات جزءًا من قاموسه الانفعالي: رفرفة فرح يعرفها أهله قبل أي كلمة، وتأرجح قلق يقرؤه معلمه إشارة حاجة، وازدياد وتيرة نذير تصعيد قادم. قراءة المحيط المدرب لهذه الإشارات تمنع تصعيدات كاملة: حاجة تُلبى مبكرًا فلا تكبر. وبعض النمطيات ذات وظيفة اجتماعية غير مباشرة موثقة في الملاحظات: تستدعي اقترابًا أو انتباهًا تعلم صاحبها ربطها بهما — وهنا تلتقي القراءة الوظيفية بقراءة السلوك العامة (ما يتبع الحركة يعلم عنها بقدر ما يسبقها).</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "قراءة النمطية وظيفيًا — ماذا تفعل لصاحبها؟", "points": ["فرضيات متعددة تُرتَّب بقوة الارتباط الموثق.", "اختبار بتعديل بيئي صغير آمن واحد في كل مرة.", "لا تدخل كاملًا من فرضية غير مختبرة."], "text": {"head": "فرضيات متنافسة لنوبة واحدة — وانضباط الترجيح", "body": "<p>لنوبة واحدة قد تصلح ثلاث فرضيات معًا (غمرة حسية، وملل انتظار، واستدعاء انتباه)، والمنهج لا يخاف التعدد بل يديره: تُرتَّب الفرضيات بقوة ارتباطها السياقي الموثق، وتُختبر واحدة في كل مرة بتعديل بيئي صغير آمن (قلّل المثير المشتبه غمرةً أسبوعًا وراقب) فإن تراجعت النوبات في سياقها رجّحتَ فرضيتك دون أن تلغي الأخريات من الملف. ويُمنع في هذا المنهج الانتقال من فرضية واحدة غير مختبرة إلى تدخل سلوكي كامل؛ فكثير من «خطط إيقاف النمطية» الفاشلة كانت إجابات صحيحة عن أسئلة لم تُسأل.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "قراءة النمطية وظيفيًا — ماذا تفعل لصاحبها؟", "points": ["تصاعد مفاجئ: فحص ألم وبيئة ودواء ونوم أولًا.", "انهيار مفاجئ مع خمول رسالة مقابلة خطيرة.", "خط الأساس الراسخ مرجع قراءة كل انحراف."], "text": {"head": "النمطية مؤشر حالة — تغيّرها رسالة", "body": "<p>حين يستقر ملف نمطية متعلم أشهرًا، يصير تغيّرها المفاجئ رسالة تستحق الفحص قبل أي تفسير سلوكي: تصاعد حاد قد يرافق ألمًا صامتًا (أذن، أسنان، بطن — ومن لا يتكلم يعلن بجسده أولًا)، أو تغييرًا بيئيًا كبيرًا، أو دواء جديدًا، أو اضطراب نوم. وانهيار نمطية فجأة نحو الصفر مع خمول عام رسالة مقابلة لا تقل أهمية. القاعدة الحاكمة: النمطية الراسخة خط أساس لصاحبها؛ انحراف الخط المفاجئ يُفحص طبيًا وسياقيًا قبل أن يُحتفى به تحسنًا أو يُدان تراجعًا.</p><p>وفي منهج القراءة حذارِ اختصار «ما بعد» إلى انتباه الكبار وحده: فما يلي النوبة قد يكون انتهاء المثير نفسه (توقف الضجيج فهدأ — وهي قرينة وظيفة تفريغ لا استدعاء)، أو وصول نشاط منتظر، أو تعبًا ذاتيًا ينهي النوبة بلا أي دور بشري. توثيق الأتباع الثلاثة (بيئي، نشاطي، ذاتي) يمنع الخطأ الأشهر في القراءة الوظيفية عمومًا: نسبة كل سلوك إلى رد فعل المحيط به لا إلى دينامية صاحبه الداخلية.</p><p>وتُحفظ حدود المنهج واضحة: القراءة الوظيفية لا تدّعي قراءة النوايا ولا تفسيرات رمزية بعيدة (لا «يعبر عن غضب من أمه» ولا «يرمز إلى كذا») بل فرضيات سلوكية-حسية قابلة للاختبار بتعديلات صغيرة. كل تفسير لا يمكن اختباره في بيئة المتعلم الحقيقية خلال أسبوعين يخرج من الملف ويبقى حديث مجالس، وحماية الملف من التفسيرات الشعرية جزء من مهنيته.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: رفرفة تظهر بنوبتين مختلفتي السياق عند المتعلم نفسه: بعد أصوات صاخبة، وفي انتظارات طويلة صامتة؛ ما قراءتك؟", "الإجابة: أنها نمطية واحدة بوظيفة تنظيمية في اتجاهين متعاكسين: تفريغ إثارة فائضة بعد الغمرة الصوتية، وتوليد إثارة عند الخمول والملل — وتُبنى الخطة على الاتجاه في كل سياق لا على شكل الحركة وحده."], "text": null, "take": "القراءة الوظيفية توثيق رباعي الأسئلة يجعل لكل نمطية فرضيات مرتبة مختبرة — تنظيم إثارة في اتجاهين، أو تعبير بدائي، أو استدعاء — وتحوّل تغيّرها المفاجئ إلى رسالة فحص لا إلى حكم سلوكي.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 52, "title": "الموقف المهني من النمطيات وحدود التدخل", "intro": "<p>أكثر ما يُطلب من المختص في هذا الباب هو «أوقفها»، وأكثر إجاباته المهنية قيمة غالبًا هي ألا يوقفها — أو أن يوقف بيئتها لا حركتها. في هذا الدرس تبني موقفًا مهنيًا منضبطًا: متى تكون النمطية مقبولة كما هي، ومتى تصبح هدف تدخل مشروعًا، وبأي أخطاء شائعة يُمنع الاقتراب منها.</p>", "slides": [{"kind": "cover", "title": "الموقف المهني من النمطيات وحدود التدخل", "sub": "الوحدة الثانية عشرة: الحركات النمطية: قراءتها وظيفيًا والتعامل معها", "goals": ["أن تصوغ موقفًا مهنيًا من النمطيات بعتبات تدخل ثلاث فقط", "أن توقف أخطاء المحيط الأربعة الشائعة ببدائل تعليمية جاهزة", "أن تفرّق نمطية عن تشنجات وحركات مرضية تستحق الإحالة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l52.jpg", "img2": null}, {"kind": "slide", "title": "الموقف المهني من النمطيات وحدود التدخل", "points": ["عادات تهدئة بشرية عامة أصل القراءة.", "ثلاث عتبات للتدخل: أذى، إغلاق فرص، تصاعد رسالي.", "تركها بقرار موثق علاج لا إهمال."], "text": {"head": "القاعدة الأولى — ليست كل نمطية مشكلة", "body": "<p>نمطية لا تؤذي الجسد، ولا تمنع تعلمًا ولا مشاركة، ولا تنفّر محيطًا بدرجة العزل، هي عند صاحبها أداة تنظيم خاصة كأي عادة تهدئة بشرية (نقر أصابع، هزّ ساق) يعرفها كل البشر بدرجات. مطاردتها لأنها «تبدو غريبة» وحدها تدخل تجميلي يستنزف طاقة المتعلم وجهد الخطة ويحوّل جلستك إلى شرطة سلوك. المعيار المهني للتدخل ثلاثي العتبات: أذى جسدي، أو إغلاق فرص (تعلم/لعب/اندماج)، أو تصاعد رسالي لم يُفهم. دون إحداها: وثّق، علّم المحيط قراءتها، ودعها — واعتبر تركها قرارًا علاجيًا موثقًا في الخطة لا إهمالًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الموقف المهني من النمطيات وحدود التدخل", "points": ["أذى جسدي يرفع التدخل واجبًا فوريًا حمايةً لا قمعًا.", "تقييم طبي مرافق والألم الكامن مشتبه أول.", "حماية بلا خطة خفض موازية تقييد مقنّع ممنوع."], "text": {"head": "عتبة الأذى — حين يجرح الجسدُ الجسد", "body": "<p>بعض الأشكال يؤذي فعلًا: ضرب رأس متكرر، وعضّ يدين حتى الجروح، وحكّ جلد حتى التقرح، وخبط أعضاء بأشياء صلبة. هنا التدخل واجب فوري لكن طبيعته حماية لا قمع: تقييم طبي مرافق (جلد وأعصاب وألم كامن قد يكون المحرك نفسه)، ووسائل حماية مؤقتة عند الحاجة بقرار طبي-أسري موثق، وبحث وظيفي مضاعف السرعة لأن الأذى يرفع كلفة كل أسبوع انتظار. ويُمنع أن تتحول الحماية إلى تقييد مزمن بلا خطة خفض موازية — فالحماية جسر لخطة، لا خطة بحد ذاتها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الموقف المهني من النمطيات وحدود التدخل", "points": ["عقاب يرفع الإثارة التي طلبت تنظيمًا.", "سخرية تضيف وصمة فوق الحركة الأصلية.", "منع جسدي بلا بديل صراع علاقة لا علاج.", "اتفاق محيط موحد جزء من أي خطة."], "text": {"head": "أخطاء المحيط الأربعة — ما يجب إيقافه فورًا", "body": "<p>أربعة تدخلات شائعة تُوقَف فور رؤيتها وتُستبدل بتعليم المحيط: العقاب على النمطية (يضيف إثارة إلى جهاز يطلب تنظيمًا فيرفع ما أراد خفضه)؛ والسخرية أو التعليق الجارح أمام الأقران (يبني طبقة خجل فوق الحركة فتستمر الحركة وتُضاف إليها وصمة)؛ والمنع الجسدي المتكرر بلا بديل (إمساك يدين كلما رفرفتا — صراع يومي يستنزف العلاقة ويعلم أن الجلسة مكان قمع)؛ والإخفاء القسري أمام الضيوف بـ«توقّف الآن» الظرفي الذي يحول كل زيارة إلى محاكمة. استبدالها الرباعي جاهز: تنظيم بيئي، تعليم قراءة، بدائل مجدولة، واتفاق محيط موحد على تجاهل واعٍ للحركات غير المؤذية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الموقف المهني من النمطيات وحدود التدخل", "points": ["انتباه مع النمطية أو ضدها حكم فردي قابل للقياس.", "قارن منتج التعلم نفسه في الشرطين قبل القرار.", "البديل يوافق القناة والمهمة معًا عند التعارض."], "text": {"head": "النمطية والتعلم — التفاوض الدقيق على الانتباه", "body": "<p>أدق مناطق الباب هي النمطية أثناء التعلم: بحوث وملاحظات ميدانية تري أن بعض المتعلمين ينتبهون أفضل وهم يتحركون نمطيًا (الحركة تنظم فيتحرر الانتباه للمهمة)، بينما تتعارض أخرى مع المهمة نفسها عضويًا (يدان مشغولتان بالرفرفة لا تكتبان). القرار إذن فردي قابل للقياس لا عقيدة: جرّب الشرطين وقارن منتج التعلم نفسه (إجابات صحيحة، زمن إنجاز) في جلسات موازية. ونتائج كثيرة تفاجئ الكبار: متعلم «يصغي وهو يرفرف» ويغيب حين يُمنع. وعند التعارض العضوي وحده يكون الحل بديلًا يشغل القناة نفسها بما يوافق المهمة (كرة ضغط أثناء الاستماع لا أثناء الكتابة).</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "الموقف المهني من النمطيات وحدود التدخل", "points": ["تشنجات قابلة للكبت المؤقت وارتداد بعده — باب آخر.", "أشكال غير ثابتة أو نومية أو متراجعة = إحالة طبية.", "ظهور فجائي في سياق دوائي جديد يُعاد للطبيب."], "text": {"head": "فروق تحمي — نمطية أم تشنج أم حركة مرضية؟", "body": "<p>ثلاث حركات قد تتنكر نمطيات وتحتاج أبوابًا أخرى: التشنجات (tics) حركات فجائية سريعة قابلة للكبت المؤقت بجهد وتزداد بعده ارتدادًا، ومسارها وعلاجها طبي-نطقي مختلف؛ والحركات المرضية العصبية (رقصية أو التوائية لا إرادية بأنماط غير ثابتة الشكل تمامًا) تحال طبيًا فورًا؛ والنمطيات الدوائية أو الطارئة فجأة في سياق علاج جديد تُوثق وتُعاد إلى الطبيب المعالج. علامات الإحالة: ظهور فجائي بلا سوابق، أشكال غير ثابتة، حركات أثناء النوم، ترافقها علامات عصبية أخرى، أو تراجع مهارات مكتسبة. الفاحص الجيد يحمي ملفه بمعرفة ما ليس ملفه.</p><p>ويشمل الموقف المهني بندًا توثيقيًا تجاه المؤسسات: حين تطلب مدرسة «خطة لإيقاف الحركات» خطيًا، يرد المختص بملف مكتوب يعرض القراءة الوظيفية وعتبات التدخل وخطة البدائل والقياس — وثيقة تحمي المتعلم من قرارات الانطباع وتحمي المختص من ضغط الإيقاف الفوري غير المهني. المهنة هنا تُمارَس بالورق أحيانًا بقدر ما تُمارس بالجلسة، وترف المتعلم عن كل رد مكتوب رخيص هو نصف ما يشتريه أهله منك أصلًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: متعلم يرفرف أثناء الاستماع لدروسه ويجيب إجابات صحيحة، ويتشتت فورًا حين يُطلب منه إيقاف يديه؛ ما قرارك المهني؟", "الإجابة: ترك الرفرفة أثناء الاستماع موثقةً كأداة تنظيم تحرر انتباهه — إذ لا أذى ولا إغلاق تعلم بل العكس — وتعليم المحيط قراءتها كذلك، فعتبات التدخل الثلاث غير قائمة وعكس قرار المنع هو الصواب."], "text": null, "take": "الموقف المهني من النمطيات قبول موثق أصلًا، وتدخل عند ثلاث عتبات فقط (أذى وحماية، إغلاق فرص، تصاعد رسالي)، وتعليم محيط يوقف أربعة أخطاء شائعة — وفروق تحوّل بعض «النمطيات» إلى أبواب طبية أخرى.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 53, "title": "التعامل مع النمطيات وبناء البدائل — أنشطة وتوصيات", "intro": "<p>أنشطة وتوصيات للتعامل مع الحركات النمطية عند المصاب بالتوحد عند قيام إحدى عتبات التدخل. منهج الباب كله في جملة واحدة: لا تُنقص نمطية إلا ببديل يؤدي وظيفتها من قناتها الحسية نفسها ويُجدوَل في سياقاتها نفسها — فالفراغ الذي تتركه حركة مأخوذة بلا بديل تملؤه هي أو أخت لها.</p>", "slides": [{"kind": "cover", "title": "التعامل مع النمطيات وبناء البدائل — أنشطة وتوصيات", "sub": "الوحدة الثانية عشرة: الحركات النمطية: قراءتها وظيفيًا والتعامل معها", "goals": ["أن تبني بديلًا حسيًا منظمًا من قناة النمطية نفسها قبل أي إنقاص", "أن تطبق بطاقة خطة بديل حسي بخط أساس وقياس ثلاثي", "أن توحّد البيت والمدرسة باتفاق مكتوب من صفحة واحدة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act7_img1.webp", "img2": null}, {"kind": "slide", "title": "التعامل مع النمطيات وبناء البدائل — أنشطة وتوصيات", "points": ["الترتيب بديل ثم إنقاص — قلبه فشل مشهور.", "البديل من قناة النمطية الحسية نفسها.", "الهدف انخفاض اعتماد ومدة لا صفر أبديًا."], "text": {"head": "مبادئ حاكمة — بديل قبل إنقاص، وجدولة قبل مواجهة", "body": "<p>أربعة مبادئ. أولًا: الترتيب إلزامي — بديل يُبنى ويُتقن ويُحبَّب أولًا، وإنقاص مستهدف ثانيًا؛ قلب الترتيب أشهر أسباب فشل الخطط في هذا الباب. ثانيًا: البديل من القناة نفسها: رفرفة (اهتزاز وحركة يدوية) بديلها اهتزازي-يدوي، وتأرجح (دهليزي) بديله دهليزي مجدول، وفموي بديله فموي آمن. ثالثًا: الجدولة الاستباقية في سياقات الذروة الموثقة (قبل ضجيج معروف، أثناء انتظارات) تتفوق على التدخل أثناء النوبة أضعافًا. رابعًا: النجاح يُقاس انخفاض اعتماد لا اختفاءً: هدف «نصف النوبات، وأقصر» واقعي مهني، وهدف «صفر نهائيًا» طموح يفسد الخطط والعلاقات معًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التعامل مع النمطيات وبناء البدائل — أنشطة وتوصيات", "points": ["أربع قنوات بدائل وجرعات مجدولة استباقيًا.", "ركن تنظيم بدستور استعمال متفق عليه صفّيًا.", "كل بديل يُنتقى من سياق ذروة موثق لا من كتالوج."], "text": {"head": "ترسانة البدائل بحسب القناة", "body": "<p>للقناة اليدوية-الاهتزازية: كرات ضغط ومواد عجن وكرات اهتزاز يدوية وألعاب أصابع مضغوطة تُقدَّم في سياقات الذروة. للقناة الدهليزية: جرعات تأرجح وكراسٍ هزازة ودوران مضبوط موقوتة قبل المواقف المعروفة. للقناة العميقة الانضغاطية: أنشطة شدّ ودفع ولفّات ضاغطة مقبولة لصناعة إثارة مكافئة عند فئة الخمول. للقناة الفموية: مضغ آمن مخصص وأدوات نفخ عند نوبات الانتظار. وللسياقات المدرسية: ركن تنظيم مصغر متفق عليه (كرسي متحرك، وسادة ضغط، ممر مشي قصير) بدستور استعمال واضح يحوّل «خروجه من الصف» فوضى إلى إجراء منظمًا محترمًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التعامل مع النمطيات وبناء البدائل — أنشطة وتوصيات", "points": ["خط أساس موثق أسبوعًا شرط قبل التغيير.", "تعليم البديل في الهدوء لا في قلب النوبة.", "القياس ثلاثي: نوبات ومدة واستعمال مستقل."], "text": {"head": "بطاقة نشاط كاملة — «خطة البديل الحسي المنظم»", "body": "<p>المجال: الحركات النمطية — بناء بديل وظيفي لقناة واحدة. الهدف القابل للقياس: أن تنخفض نوبات نمطية الرفرفة عند متعلم واحد في سياق الانتظار الصفي من متوسط 9 نوبات (خط أساس أسبوع موثق) إلى 4 أو أقل أسبوعيًا خلال 6 أسابيع، مع استعمال مستقل للبديل في 3 من 4 فرص. الأدوات: كرة ضغط اهتزازية يدوية، وسادة مقعد ضاغطة، بطاقة اختيار مصورة «أحتاج كرتي»، مؤقت انتظار بصري. الإعداد: توثيق خط الأساس أسبوعًا قبل أي تغيير، وتعليم البديل في أوقات هدوء حتى يُتقنه ويستعمله رمزيًا بالبطاقة. الخطوات: تقديم البديل استباقيًا عند كل انتظار معلن، ثم إتاحة طلبه بالبطاقة فقط، ثم تعميمه على سياقي انتظار آخرين (طابور، تنقل) بمرافقة معلم مدرب. التدرج: تقصير مدد الانتظار المحمية تدريجيًا، وبدائل ثانية من القناة نفسها للتنويع. التنويع: استعمال البديل في البيت بنفس البطاقة والأداة. الأمان: أدوات فموية آمنة إن انتقل الاستعمال للفم، وتعليق الخطة فور أي أذى أو تصاعد غير مفهوم. التكرار: سياقات الانتظار اليومية كلها 6 أسابيع. القياس: عدّ نوبات أسبوعي بيد المعلم والأهل، ونسبة الاستعمال المستقل للبديل، ومدد النوبات. مؤشر النجاح: بلوغ الهدف 3 أسابيع متتالية ثم خفض حضور النوبات في سياق ثالث.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التعامل مع النمطيات وبناء البدائل — أنشطة وتوصيات", "points": ["ثلاث إشارات مراجعة فقط لا ذعر عند كل تأرجح.", "انتقال الشكل رسالة قناة لا فشل خطة تلقائيًا.", "الغاية متعلم منظم بأدواته ومحيط غير واصم."], "text": {"head": "القياس والمتابعة — عودة النوبة معلومة لا فشل", "body": "<p>تُعاد قراءة عدّات النوبات أسبوعيًا على رسم واحد مع سياقاتها، وتُراجع الخطة عند ثلاث إشارات حصرًا: ثبات بلا تقدم 3 أسابيع (راجع الوظيفة المرجحة — قد تكون فرضيتك الثانية هي الصواب)، أو انتقال النمطية لشكل جديد أشد (راجع القناة والبديل)، أو تحسّن في الجلسات دون البيئات (راجع التعميم والتدريب المحيطي). عودة النوبات بعد تحسن عند تغير بيئي أو ألم عابر حدث متوقع يُوثق ويُقرأ بمنهج الدرس الثاني، لا فشلًا يُلغى به صالح ما بُني. والهدف النهائي الأسمى في هذا الباب ليس ملفًا بلا نمطيات، بل متعلم منظَّم بأدوات يملكها ومحيط يقرؤه بلا وصمة.</p><p>وتُدار توقعات الأهل بلغة الأرقام منذ الأسبوع الأول: خط أساس موثق بعدّاته، وهدف ستة أسابيع بنسب انخفاض واقعية، وموعد مراجعة معلوم — لأن غياب الأرقام يترك حكمهم لانطباع يوم واحد سيئ يمحو في أذهانهم شهر تقدم حقيقيًا. خطة هذا الباب تعيش على رسمها البياني المشترك: خط ينحدر ببطء ويتعرج بصدق، يعرضه المختص والأهل معًا فيعرف الجميع متى نتقدم ومتى نعيد القراءة ولماذا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التعامل مع النمطيات وبناء البدائل — أنشطة وتوصيات", "points": ["صفحة اتفاق واحدة بأسماء الحركات المقبولة صراحة.", "بدائل وإشارة طلب وعداد أسبوعي موحدة البيئات.", "منع صريح لأي تأديب خارج عتبات التدخل."], "text": {"head": "توصيات واجهة — اتفاق البيت والمدرسة", "body": "<p>وحّد الواجهات الثلاث باتفاق مكتوب من صفحة واحدة: الحركات المقبولة كما هي بأسمائها الدقيقة (حتى لا يعاقب بديلٌ غائب ما تركه المختص واعيًا)، والبدائل المتاحة في كل بيئة وأماكنها الثابتة، وإشارة تواصل واحدة يطلب بها المتعلم بديله أو ركنه، وعدّاد أسبوعي مشترك بنموذج واحد يملؤه الطرفان. ويُمنع صراحة في الاتفاق أي إجراء تأديبي مرتبط بالنمطيات خارج عتبات هذا الباب. يوقّع الاتفاق ويُراجع مع كل مراجعة قياس، فيصير سلوك المحيط كله جزءًا محسوبًا من الجرعة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يُبنى البديل الحسي قبل أي استهداف لإنقاص النمطية، لا بالتوازي معه؟", "الإجابة: لأن النمطية تؤدي وظيفة تنظيمية قائمة؛ فأخذها قبل وجود بديل متقن يترك الجهاز بلا صمّامه فيرتفع ضغطه وتعود النمطية أقوى أو تظهر أخت لها — الترتيب «بديل يُتقن أولًا ثم إنقاص» هو ما يجعل الإنقاص ممكنًا أصلًا."], "text": null, "take": "التعامل مع النمطيات بناء بديل من القناة نفسها يُجدول استباقيًا في سياقات الذروة ويُقاس انخفاض اعتماد ومدة واستعمالًا مستقلًا — لا منعًا ولا مطاردة ولا وعودًا بالصفر الأبدي.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 54, "title": "حين تتحكم الحواس في الحركة — مدخل وقنوات", "intro": "<p>لا تتحرك العضلات في فراغ حسي؛ فكل حركة تُبنى على مدخلات تصل الجهاز قبلها وأثناءها: ثقل الجسد في الفراغ، وتمدد عضلاته، وملامسة الأرض، وصورة الهدف. عند المصاب بالتوحد تكون هذه المدخلات نفسها مضطربة الشدة والقراءة، فيتأثر البناء الحركي كله من بوابة الإحساس. في هذا الدرس تتعرف على حجم الظاهرة موثقًا وعلى القنوات الحسية الخمس ذات الصلة الحركية المباشرة.</p>", "slides": [{"kind": "cover", "title": "حين تتحكم الحواس في الحركة — مدخل وقنوات", "sub": "الوحدة الثالثة عشرة: الاضطرابات الحسية المؤثرة في الحركة", "goals": ["أن تسمّي القنوات الحسية الخمس ذات الصلة الحركية المباشرة", "أن تقرأ كل قناة فرطًا ونقصًا وتذبذبًا على خريطة واحدة", "أن تحدّد حدود بابك: أثر الحسي في الحركة لا ملف البروفيل الكامل"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l54.jpg", "img2": null}, {"kind": "slide", "title": "حين تتحكم الحواس في الحركة — مدخل وقنوات", "points": ["شذوذات حسية عند نحو 40 بالمئة في التقديرات المبكرة (1990).", "مكوّن منتظَر يُفحص في كل ملف لا صدفة تُكتشف.", "فشل حركي كثير البوابةُ حسية قبل القدرة والإرادة."], "text": {"head": "حجم الظاهرة — أقلية تُقاس لا انطباع يُروى", "body": "<p>سجّل ريملاند (Rimland, 1990) شذوذات حسية عند ما يقارب 40 بالمئة من الأطفال المصابين بالتوحد في عيناته المبكرة، وقدّرت دراسات لاحقة النسب أعلى من ذلك بكثير بحسب الأدوات والأعمار. الرقم الدقيق أقل أهمية من المغزى المهني: الخصوصية الحسية ليست زينة في ملف التوحد بل مكوّن منتظَر يجب فحصه في كل ملف حركي. متعلم يفشل في مهامك قد يكون فشله حسي البوابة، وفحص لا يسأل عن الحواس يقرأ نصف الصورة وينسب النصف الآخر ظلمًا للقدرة أو الإرادة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حين تتحكم الحواس في الحركة — مدخل وقنوات", "points": ["دهليزية: وضع الرأس وحركته أساس التوازن والجرأة.", "عميق: مواضع وقوى أساس ضبط القوة والمعايرة.", "فرط يهدد ونقص يطلب بإفراط — وضبابي يخمّن."], "text": {"head": "القناتان الخفيتان — الدهليزية والعميقة بوابتا الحركة", "body": "<p>أهم قناتين للحركة هما الأقل وعيًا بهما: الدهليزية (vestibulaire) تخبر الجهاز بوضع الرأس وحركته وسرعته — أساس التوازن والثبات وجرأة الحركة؛ والحس العميق (proprioception) يخبره بمواضع الأطراف وتمدد العضلات وقوى الشد — أساس ضبط القوة والمعايرة الحركية بلا نظر. فرط حساسية دهليزية يجعل الارتفاع والتأرجح تهديدًا، ونقصها يجعل المتعلم يطلب حركة قوية بلا شبع؛ وعميق ضبابي يجعل القوى تخمينًا دائمًا. كل ملفات الوحدات السابقة مرّت بهاتين القناتين؛ هنا تُسمّيان وتُقرآن معًا قراءة حسية صريحة وتصبح كل اضطراباتهما قابلة للخطة الحسية-الحركية المدمجة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حين تتحكم الحواس في الحركة — مدخل وقنوات", "points": ["دفاعية لمسية ترفض الأدوات والأسطح لا النشاط.", "ازدحام بصري يفسد مسارات بصرية القيادة.", "حساسية سمعية تقطع الحركة الجماعية الصاخبة."], "text": {"head": "اللمسية والبصرية والسمعية — مؤثرات الأطراف", "body": "<p>اللمس (tactile) يحكم قبول الأدوات والملابس وأسطح الحركة نفسها: دفاعية لمسية (défensivité tactile) تجعل نشاطك الأفضل مرفوضًا لملمس أدواته. والبصر (vision) يقود التخطيط والتصويب والتتبع، لكن فرط انتباهه للتفاصيل أو حساسيته للازدحام البصري يفسد مسارات كاملة. والسمع (audition) بوابة الإيقاع والتزامن والتعليمات: حساسية سمعية تقطع الحصص الصاخبة عند أجمل لحظاتها الحركية، وازدحام صوتي يبتلع صوت إرشادك. المختص يقرأ هذه القنوات الثلاث في سياق مهامه الحركية نفسها: أي أدوات تُرفض؟ أي بيئات تُفكك؟ أي أصوات تُطفئ الأداء؟</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حين تتحكم الحواس في الحركة — مدخل وقنوات", "points": ["ثلاث قراءات: فرط ونقص وتذبذب عبر اليوم.", "قنوات مختلفة بصور مختلفة عند المتعلم الواحد.", "الخريطة لا السلوك المفرد وثيقة الباب."], "text": {"head": "الفرط والنقص والتذبذب — ثلاث قراءات لكل قناة", "body": "<p>لا تُقرأ القناة ثنائية «حساسة/غير حساسة» بل ثلاثيًا: فرط استجابة (يصل المدخل مضخّمًا فيُتجنب أو يُفجّر ردًا)، ونقص استجابة (يصل باهتًا فيُطلب بجرعات أكبر أو يغيب أثره التنظيمي)، وتذبذب بينهما عبر اليوم والقناة. والصورة عند متعلمك الواحد قد تجمع فرطًا سمعيًا ونقصًا عميقًا ودفاعية لمسية معًا، فتخرج بسلوكيات تبدو متناقضة لمن يقرؤها أحكامًا، ومترابطة تمامًا لمن يقرؤها خريطة قنوات. الخريطة لا السلوك المفرد هي وثيقة هذا الباب.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حين تتحكم الحواس في الحركة — مدخل وقنوات", "points": ["بابك: أثر الحسي في الحركة وتعديلاتها وإحالاتها.", "البروفيل الشامل بأدواته مجال آخر يُنسق معه.", "تجاهل الحسي عمى، وادعاؤه بلا أدوات تجاوز."], "text": {"head": "حدود هذا الباب — أثر الحسي في الحركة لا ملف الحسي كاملًا", "body": "<p>لتقييم البروفيل الحسي الشامل بأدواته وخطط أنشطته مجاله المهني الكامل خارج نطاق هذه الدورة التفصيلي. بابك هنا أضيق وأدق: كيف تؤثر الخصوصيات الحسية الموثقة في الأداء الحركي، وكيف تعدّل مهامك وبيئاتك وجرعاتك على ضوئها، ومتى تحيل إلى تقييم حسي متخصص. الحفاظ على الحد يمنع خطأين متقابلين: مختص حركي يتجاهل الحسي فيعمى عن بوابات فشل متعلميه، ومختص حركي يدّعي ملفًا حسيًا كاملًا بلا أدواته المقننة.</p><p>ومن زاوية عملية أخيرة لهذا المدخل: وثّق في أول ملف حركي تفتحه لمتعلم جديد ثلاث ملاحظات حسية سريعة قبل أي اختبار — ماذا يطلب جسده تلقائيًا في الانتظار؟ وماذا يتجنب في غرفة مليئة بالأدوات؟ وكيف يتغير أداؤه بين أول الجلسة وآخرها؟ — فهذه الدقائق الثلاث المجانية تبني فرضيات قنواتك الأولى، وكل فحص لاحق في هذه الوحدة إنما يضبطها ويقيسها لا يبدأ من صفر الملاحظة.</p><p>وتجدر الإشارة إلى أن تسمية القنوات بأسمائها الفرنسية المقننة في المواضع الأولى من ملفاتك ليست زخرفة لغوية؛ بها تُقرأ أدبيات الباب وأدواته، وبها تتواصل مع زملائك عبر المدارس والبلدان، وكثير من تضييع الوقت المهني يبدأ من مصطلح مترجم بحرية لا يعرفه أحد غير كاتبه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: متعلم يرفض نشاط كرة كبير محببًا لديه عادة حين يُقدَّم في قاعة صدى صوتها عالٍ ويقبله في غرفة هادئة؛ ما قراءتك الأولى وما فحصك؟", "الإجابة: القراءة الأولى حسية بيئية لا حركية: حساسية سمعية أو غمرة صوتية تفكك أداءه في القاعة؛ والفحص مقارنة الأداء نفسه عبر بيئتين صوتيتين موثقة، قبل أي حكم على مهارته بالكرة."], "text": null, "take": "الخصوصيات الحسية مكوّن منتظَر في ملف التوحد الحركي؛ قنواته الحركية الكبرى دهليزية وعميقة ولمسية وبصرية وسمعية، وتُقرأ كلٌّ منها فرطًا ونقصًا وتذبذبًا على خريطة واحدة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 55, "title": "أشكال التأثير الحسي في الأداء الحركي", "intro": "<p>تترجم الخريطة الحسية نفسها إلى سلوكيات حركية محيرة حين لا تُعرف مفاتيحها: متعلم يتجنب الأرجوحة كأنها وحش، وآخر لا يشبع من الدوران، وثالث ينهار أداؤه لملمس حصيرة. في هذا الدرس تجمع أشكال التأثير الحركي للحسي في صور قابلة للتمييز والتوثيق، وتصل أخطرها بخطورة طبية تستحق جرس إنذار دائم.</p>", "slides": [{"kind": "cover", "title": "أشكال التأثير الحسي في الأداء الحركي", "sub": "الوحدة الثالثة عشرة: الاضطرابات الحسية المؤثرة في الحركة", "goals": ["أن تصف أشكال التأثير الحسي: تجنب دفاعي وطلب جرعة ودفاعية لمسية", "أن تفسّر نقص حس الألم بوصفه جرسًا طبيًا دائمًا في ملفاتك", "أن تشتبه بالبوابة الحسية عند كل تدهور مقترن ببيئة ثابتة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l55.jpg", "img2": null}, {"kind": "slide", "title": "أشكال التأثير الحسي في الأداء الحركي", "points": ["تجنب قد يكون دفاعًا حسيًا لا خوفًا ولا كسلًا.", "ثبات الشدة رغم تلطيف العرض قرينة حسية.", "الخطة معايرة مدخلات لا حملات تشجيع."], "text": {"head": "تجنب الحركة — دفاعات متنكرة في ثوب الخوف والكسل", "body": "<p>يُقرأ تجنب الحركة عند كثير من المتعلمين قراءات ظريفة خاطئة: «خائف»، «كسول»، «لا يحب الرياضة». وقد يكون الجسد في الحقيقة يدافع عن نفسه ضد مدخلات لا يحتملها: دهليزي فرط الحساسية يرفض التأرجح والارتفاع والانقلاب لأن كلًا منها إنذار داخلي؛ وعميق غير آمن يجعل القفز والهبوط مغامرة بلا خريطة جسد. معيار التفريق العملي: متعلم «الخائف» يهدأ بتدرج آمن بطيء ويبدأ القبول، ومتعلم الدفاع الحسي يبقى رفضه ثابت الشدة مهما لطفت العرض ما دام المدخل نفسه حاضرًا بحجمه. وهذه القراءة تغيّر الخطة من «تشجيع» إلى «معايرة مدخلات».</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال التأثير الحسي في الأداء الحركي", "points": ["فرط حركة قد يكون بحثًا حسيًا عن جرعة مفقودة.", "منع الوجبة العشوائية بلا بديل يزيد جوع الجسد.", "جرعات مجدولة منظمة تخفض فوضى الصيد الحسي."], "text": {"head": "طلب الحركة المفرط — بحث عن جرعة لا يجدها", "body": "<p>الوجه المقابل: متعلم لا يكف عن القفز والدوران والاصطدام والضغط، يبدو «مفرط النشاط» في كل تقاريره. القراءة الحسية تراه باحثًا عن مدخلات دهليزية وعميقة بجرعات لا توفرها بيئته الاعتيادية: جسد جائع حسيًا يصنع وجباته بنفسه حيثما وجد. خطورة القراءة السلوكية وحدها أنها تكافح الوجبة وتمنعها فيزداد الجوع سلوكًا. القراءة الحسية تبني «وجبات مجدولة» (جرعات حركة قوية منظمة في أوقات محسوبة) فتنخفض الفوضى الحركية لأن الشبع المنتظم أرخص على اليوم من الصيد العشوائي.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال التأثير الحسي في الأداء الحركي", "points": ["رفض أدوات وأسطح واتصال جسدي داخل المهام.", "استكشاف فموي ونفور لمسي علامتان مبكرتان (2003).", "الدفاع يُعايَر لا يُكسَر بالإصرار الجسدي."], "text": {"head": "الدفاعية اللمسية في قلب المهام الحركية", "body": "<p>تظهر الدفاعية اللمسية داخل أقدس مواضع عملك: يد ترفض الإمساك بمقابض خشنة أو لزجة، وجسد ينسحب من اتصال شريك في نشاط ثنائي، وأقدام ترفض أسطحًا (رمل، عشب، حصيرًا بعينه)، وملابس رياضية تُخرب الحصة قبل أن تبدأ. وثّق بارانيك (Baranek, 2003) في العلامات المبكرة استكشافًا فمويًا مفرطًا ونفورًا لمسيًا عند صغار التوحد. قاعدة التعامل الأولى: لا تكسر دفاعًا لمسيًا بالإصرار الجسدي؛ فالدفاع يُعايَر بمدخلات متدرجة مقبولة وببدائل أدوات، وإصرارك على «سيمسكها اليوم» يبني نفورًا منك ومن نشاطك يفوق قيمة أي مسكة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال التأثير الحسي في الأداء الحركي", "points": ["ألم منقوص الدلالة يخفي إصابات ورضوضًا متراكمة.", "«لم يبكِ» لا تعني «لم يتأذَّ» عند هؤلاء.", "فحص جسدي بصري بعد الأنشطة القوية واجب موثق."], "text": {"head": "نقص حس الألم — الجرس الطبي الأخطر", "body": "<p>أخطر خصوصيات هذا الباب طبيًا نقص الإحساس بالألم (hypoalgésie) الموثق عند فئة من أصحاب التوحد: متعلم يسقط ويجرح ولا يعلن، أو يضرب رأسه بقوة بلا رد فعل متناسب، أو يستمر في نشاط فوق إصابة كامنة. خطورته مضاعفة: إصابات لا تُرى، ورضوض تتراكم، وفرط تحمل يجعل مؤشرات الإرهاق الجسدي الطبيعية صامتة عند صاحبك وحده. واجبك المهني هنا توثيق وإنذار أهلي ومدرسي دائم وفحص جسدي بصري بعد كل نشاط قوي، وتعليم المحيط أن «لم يبكِ» عند هذا المتعلم لا تعني «لم يتأذَّ» أبدًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال التأثير الحسي في الأداء الحركي", "points": ["تدهور مقترن ببيئة ثابتة = اشتباه بوابة حسية.", "تعديل البيئة أرخص اختبار وأول علاج معًا.", "«غير ثابت» سؤال عن البيئات لا وصف للمتعلم."], "text": {"head": "حسية تقطع الإيقاع والتزامن والتعليمات", "body": "<p>تظهر حسية أخرى مقنعة في بابين درستهما: تزامن ينهار في البيئات الصاخبة بينما يثبت في الهادئة (ملفه إيقاع شكليًا وحسي بوابته)، وانتباه يتبدد في غرف مضيئة مزدحمة بصريًا (ملفه انتباه شكليًا وازدحام بصري بوابته)، وتعليمات شفهية تضيع وسط صدى القاعات. القاعدة القرائية العامة لهذا الباب: كل تدهور أداء مقترن ببيئة بعينها ومستقر عبر تكرارها يُشتبه ببوابته الحسية أولًا، وتعديل البيئة أرخص اختبار تشخيصي وأول خطوة علاجية معًا. وبعد هذا الدرس لن تقرأ «أداؤه غير ثابت» التقرير الشائع قراءة بريئة؛ ستسأل دائمًا: غير ثابت بين أي بيئات؟</p><p>وتذكّر أن أشكال هذا الدرس تتعايش عند المتعلم الواحد بترتيبات مدهشة: متجنب دهليزي قد يكون باحثًا عميقًا عنيف الطلب، ودفاعي اللمس قد يكون متسامحًا صوتيًا تمامًا. لهذا تُرسم صورة كل متعلم على خريطة القنوات المستقلة لا على محور «حساس/غير حساس» واحد؛ فالمحور الواحد يجعل خططك تخاطب متعلمًا غير موجود، بينما الخريطة تخاطب صاحب الملف الحقيقي بقنواته كما هي موزعة فعلًا.</p><p>ومثال أخير يجمع الصور: متعلم يضرب باب الخزانة كل صباح عند وصوله. قراءة سلوكية ترى عادة مزعجة؛ وقراءة قنواته ترى جسدًا يبحث بعد ركوب صاخب مهتز عن جرعة عميقة قوية يضبط بها بوابه قبل بدء يومه — فتُبنى له جرعة صباحية مشروعة فيستبدل البابَ بجدار الدفع المخصص له.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما المعيار العملي الذي يفرّق «خوفًا» من نشاط مرتفع عن دفاع دهليزي حسي ضده؟", "الإجابة: التدرج الآمن البطيء يهدئ الخوف ويبدأ القبول عادة، بينما يبقى رفض الدفاع الحسي ثابت الشدة ما دام المدخل الدهليزي حاضرًا بحجمه مهما لطُف العرض؛ فثبات الشدة أمام المدخل نفسه قرينة حسية تبني خطة معايرة لا خطة تشجيع."], "text": null, "take": "أشكال التأثير الحسي في الحركة أربعة كبرى: تجنب دفاعي، وطلب جرعة مفرط، ودفاعية لمسية داخل المهام، وانقطاعات بيئية للأداء — وفوقها جرس طبي دائم: نقص حس الألم.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 56, "title": "آلية التعديل الحسي وفحص الأثر الحركي", "intro": "<p>بين المدخل الحسي والأداء الحركي تقف آلية وسيطة اسمها التعديل الحسي (modulation sensorielle): قدرة الجهاز على تضخيم ما يهمّ وكتم ما لا يهمّ من المدخلات ليبقى الأداء ممكنًا. في هذا الدرس تتعرف على الآلية ومفهوم التكامل متعدد الوسائط، وعلى فحص عملي يربط الخريطة الحسية بأدائك الحركي المقاس بدل التخمين.</p>", "slides": [{"kind": "cover", "title": "آلية التعديل الحسي وفحص الأثر الحركي", "sub": "الوحدة الثالثة عشرة: الاضطرابات الحسية المؤثرة في الحركة", "goals": ["أن تشرح آلية التعديل الحسي بوابًا والتكامل متعدد الوسائط بناءً للفعل", "أن تبني فحص أثر بمقارنة مهمة واحدة في شرطين حسيين مختلفين", "أن تصوغ الخريطة الحسية في ثلاث جمل قابلة للخطة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l56.jpg", "img2": null}, {"kind": "slide", "title": "آلية التعديل الحسي وفحص الأثر الحركي", "points": ["بواب يضخّم المهم ويكتم الخلفية باستمرار.", "فشله فرط صرامة أو نوم قراءة.", "تشتت كثير بوابه مكسور لا انتباهه غائب."], "text": {"head": "التعديل الحسي — بواب الجهاز العصبي", "body": "<p>يعمل التعديل كبواب ذكي: مدخلات بالآلاف تصل كل ثانية، فيسمح للمهم منها بالوصول واعيًا (صوت اسمك في قاعة صاخبة)، ويكتم الخلفية (ملمس ملابسك الآن لا تفكر فيه). عند اضطرابه يحدث أحد فشلين: بواب مفرط الصرامة يصرخ عند كل مدخل صغير (فرط)، أو بواب نائم يمرر بلا قراءة (نقص). والنتيجة الحركية مباشرة: جهاز مشغول كليًا بمدخلات يجب أن تكون خلفية لا يجد موارد لبناء حركة دقيقة، وجهاز لا يقرأ مدخلاته العميقة يبني حركات على خريطة قديمة. كثير من «تشتت» متعلمك هو في الحقيقة بواب مكسور لا انتباه غائب.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية التعديل الحسي وفحص الأثر الحركي", "points": ["كل مهارة ناضجة وليدة دمج قنوات عدة.", "انهيار عند الجمع وتفوق بقناة مسيطرة صورتان.", "الفحص يفكك القنوات ويجمعها منهجيًا."], "text": {"head": "التكامل متعدد الوسائط — حركة واحدة من حواس كثيرة", "body": "<p>لا تعتمد أي مهارة حركية ناضجة على قناة واحدة: التوازن يدمج دهليزيًا وبصريًا وعميقًا، والإمساك الدقيق يدمج لمسيًا وعميقًا وبصريًا، والمشي الآمن يدمجها كلها مع السمع أحيانًا. التكامل متعدد الوسائط (intégration multisensorielle) هو قدرة الجهاز على دمج هذه التيارات في صورة جسدية واحدة قابلة للفعل. اضطرابه يفسر مهارات تنهار حين تُجمع قنواتها (يقف ثابتًا مغمضًا ويسقط مفتوحًا في ضجيج) ومهارات تنجو بقناة واحدة مسيطرة (أداء ممتاز بقيادة بصرية خالصة). فحصك البارع يفكك القنوات ويجمعها منهجيًا ليقرأ أين ينكسر الدمج.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية التعديل الحسي وفحص الأثر الحركي", "points": ["أداء أمثل في منطقة إثارة وسطى فردية العتبات.", "تراكم مدخلات اليوم يستهلك قدرة البواب تدريجيًا.", "توقيت الصعب في نوافذ مواتية جزء من الخطة."], "text": {"head": "الإثارة والعتبات — لماذا يتغير المتعلم نفسه عبر اليوم", "body": "<p>ترتبط قابلية الأداء بمنحنى إثارة: أداء أمثل في منطقة وسطى، وتفكك عند الانخفاض (خمول وبحث حسي) وعند الارتفاع (غمرة وتشتت). وعتبات المتعلمين الحسية تزيح منحنياتهم: ما هو «وسط مريح» لأقرانه قد يكون غمرة له أو صحراء. لهذا يتغير أداء صاحبك عبر اليوم مع تراكم مدخلاته (قاعة صباحية صاخبة تستهلك بوابه فينهار عصرًا في مهمة سهلة). الخطة الحكيمة تدير حمل اليوم الحسي كله لا نشاطها المفرد: توقيت الأنشطة الصعبة في نوافذ إثارة مواتية موثقة، واستباق الغمرات المعروفة بتنظيمات قبلها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية التعديل الحسي وفحص الأثر الحركي", "points": ["مقارنة مهمة واحدة في شرطين حسيين أقوى المصادر.", "سجل بيئات أسبوعين يسبق أي حكم نهائي.", "بيئة الفاحص المضبوطة نصف صورة المتعلم فقط."], "text": {"head": "فحص الأثر — مقارنة بيئية موثقة لا استبيان فقط", "body": "<p>يُبنى الحكم في هذا الباب على ثلاثة مصادر مرتّبة القوة: أقواها مقارنة أداء موثقة: المهمة الحركية نفسها في شرطين حسيين مختلفين (هادئ/صاخب، أداة مريحة/منفّرة، قبل/بعد جرعة منظمة) بفارق مقاس؛ ثم ملاحظة منظمة لسياقات التدهور والتحسن عبر أسبوعين بسجل بيئات؛ ثم استبيانات وتقارير الأهل والمعلمين إطارًا تفسيريًا. وخطأ الباب المنهجي الأشهر بناء حكم حسي كامل على انطباع جلسة واحدة في بيئتك أنت (المضبوطة أصلًا) — فأنت تفحص متعلمًا في أحسن بيئاته وتعمم على يومه الحقيقي الخشن. الفحص الذي لا يغادر غرفتك الهادئة نصف فحص.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية التعديل الحسي وفحص الأثر الحركي", "points": ["ثلاث جمل: قناة بنمطها، أثر مقاس، شرط أمثل.", "«مشاكل حسية» العامة تُحذف من التقارير.", "الخريطة صدر إلزامي لكل خطة حركية لاحقة."], "text": {"head": "من الخريطة إلى الحكم — جمل قابلة للخطة", "body": "<p>يُختم الفحص بجمل ثلاث بصيغة قابلة للبناء: قناة مضطربة بنمطها (دهليزية فرط، عميقة نقص...)؛ وأثرها الحركي المقاس (يسقط بعد جرعة تأرجح، تتحسن قبضته بعد ضغط عميق...)؛ وشرط الأداء الأمثل (ينجز مهام توازنه في بيئة بصرية هادئة بعد تنظيم عميق). أي جملة رابعة عامة من نوع «عنده مشاكل حسية» تخرج من التقرير بلا رحمة، لأنها لا تبني نشاطًا ولا تعدّل بيئة ولا تُقاس بعد شهر. وبعد هذا الدرس ستصير الخريطة الحسية لمتعلمك جزءًا إلزاميًا من صدر كل خطة حركية تكتبها.</p><p>واستعمل مقارنة البيئتين بمنهج صارم حتى تكون بيانات لا انطباعات: المهمة نفسها، والأدوات نفسها، والزمن نفسه من اليوم، والفارق الوحيد هو الشرط الحسي المعدَّل، مع تكرار التبديل مرتين على الأقل (هادئ ثم صاخب ثم هادئ) حتى يستبعد أثر الصدفة والتعب من قراءتك. مقارنة مضبوطة واحدة من هذا النوع تساوي في وزنها المهني عشرة تقارير انطباعية من بيئات عشوائية لا يعرف أحد شروطها.</p><p>وتُختتم منهجية هذا الدرس بترتيب ذهني ثابت كلما قرأت ملفًا جديدًا: قناة، فنمط استجابتها، فأثرها الحركي المقاس، فشرط الأداء الأفضل — وكل خطوة تُدعم بمشاهدة أو مقارنة لا بحدس. ملف يحمل هذا الرباعي كاملًا جاهز لأن يتحول خطة؛ وملف ينقصه ربع واحد يعود إلى الفحص لا إلى الأنشطة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا لا يكفي فحص متعلم في غرفتك المضبوطة هادئة الإضاءة والصوت للحكم على أثر الحسي في حركته؟", "الإجابة: لأنك تفحصه في أحسن بيئاته الممكنة؛ فالأثر الحسي يظهر في بيئات يومه الحقيقية الخشنة (صاخبة، مزدحمة، متغيرة) — والحكم الصادق يحتاج مقارنات أداء موثقة عبر شروط حسية مختلفة وسجل سياقات من بيئاته الفعلية."], "text": null, "take": "آلية الباب تعديل حسي يعمل بوابًا وتكامل متعدد الوسائط يبني الفعل؛ وفحصه مقارنة بيئية موثقة بسجل سياقات، يختم بثلاث جمل قابلة للخطة لا بأوصاف عامة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 57, "title": "أنشطة وتعديلات حسية في خدمة الحركة — جرعات منظمة وبيئات مضبوطة", "intro": "<p>أنشطة وتوصيات للاضطرابات الحسية المؤثرة في الحركة عند المصاب بالتوحد. فلسفة الباب العملية: الحركة نفسها أقوى منظم حسي حين تُعايَر جرعاتها وقنواتها، والبيئة المضبوطة نصف أي نشاط قبل أن يبدأ. هنا تبني جرعات منظمة قبل الأداء الصعب، وتعدّل بيئات مهامك، وتقيس الأثر على الحركة نفسها لا على «الهدوء» وحده.</p>", "slides": [{"kind": "cover", "title": "أنشطة وتعديلات حسية في خدمة الحركة — جرعات منظمة وبيئات مضبوطة", "sub": "الوحدة الثالثة عشرة: الاضطرابات الحسية المؤثرة في الحركة", "goals": ["أن تبني جرعات حسية منظمة تسبق الطلب الحركي الصعب", "أن تطبق بطاقة تحضير عميق قبل مسار توازن بقياس قبل/بعد", "أن تحوّل كل جرعة ناجحة إلى مهارة طلب ذاتي عند المتعلم"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act11_img1.webp", "img2": null}, {"kind": "slide", "title": "أنشطة وتعديلات حسية في خدمة الحركة — جرعات منظمة وبيئات مضبوطة", "points": ["التنظيم تحضير يسبق الطلب لا مكافأة تليه.", "جرعة فردية معايرة وموثقة وقابلة للتطور.", "القياس على الأداء الحركي لا على الهدوء المزاجي."], "text": {"head": "مبادئ حاكمة — جرعة قبل طلب، وقياس على الحركة", "body": "<p>أربعة مبادئ. أولًا: التنظيم الحسي تحضير للأداء لا مكافأة بعده؛ جرعة عميق ودهليزي مضبوطة قبل مهمة توازن صعبة تصنع نافذة أداء، وتقديمها «حين ينتهي» يهدر منطقها. ثانيًا: الجرعة فردية القناة والشدة والمدة، تُضبط بمحاولات موثقة، وتُعاد معايرتها مع تغير المتعلم. ثالثًا: الأثر يُقاس على المهمة الحركية المستهدفة (ثواني توازن، دقة قبضة) لا على انطباع «صار أهدأ» — فهدوء بلا تحسن أداء ليس هدف هذا الباب. رابعًا: كل جرعة ناجحة تتحول تدريجيًا إلى مهارة ذاتية: المتعلم يطلبها ويؤديها ويعرف متى يحتاجها، فالاستقلالية التنظيمية أثمن من أي جلسة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة وتعديلات حسية في خدمة الحركة — جرعات منظمة وبيئات مضبوطة", "points": ["جرعات موجهة بهدف حركي تالٍ محدد.", "بدائل أدوات مضبوطة اللمس قبل الدقة.", "تدرج دهليزي صغير مقبول ولا فرض مفاجئ."], "text": {"head": "ترسانة الجرعات بحسب القناة والهدف الحركي", "body": "<p>قبل مهام التوازن والثبات: جرعات عميقة انضغاطية (دفع جدار، حمل أثقال آمنة، مشي دب) ترفع خريطة الجسد، ودهليزية بطيئة منتظمة الإيقاع (تأرجح خطي قصير) لمن يحتملها. قبل مهام الدقة اليدوية: أنشطة ضغط ومقاومة لليدين (عجين قاسٍ، فتح أغطية مقاومة) ثم أدوات مضبوطة اللمس. لبيئات الغمرة السمعية: سماعات عازلة في الأنشطة الجماعية الصاخبة وتخفيض مفاجآت الصوت (إعلانات قبل الأصوات القوية). للتجنب الدهليزي: تدرج ارتفاعات وسرعات بمقادير صغيرة مقبولة موثقة، ولا قفزات ثقة مفروضة أبدًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة وتعديلات حسية في خدمة الحركة — جرعات منظمة وبيئات مضبوطة", "points": ["قياس قبل/بعد داخل الجلسة الواحدة جوهر البطاقة.", "جرعة تتحول مهارة طلب ذاتي ببطاقة مصورة.", "بروتوكول بيتي موازٍ قبل واجبات الجلوس."], "text": {"head": "بطاقة نشاط كاملة — «التحضير العميق قبل مسار التوازن»", "body": "<p>المجال: الاضطرابات الحسية المؤثرة في الحركة — تنظيم عميق استباقي. الهدف القابل للقياس: أن يرفع تحضير عميق من 4 دقائق (دفع جدار 10 مرات + حمل صندوق كتب 3 كغ لمسافة 5 أمتار ذهابًا وإيابًا + لفّ ضاغط مقبول 30 ثانية) زمن مشي المتعلم على خط مستقيم أرضي بطول 4 أمتار دون خروج عنه من مرتين (خط أساس) إلى 4 من 5 محاولات، مقاسًا في الجلسة نفسها قبل التحضير وبعده. الأدوات: صندوق وحمولة آمنة، خط أرضي لاصق، مؤقت مرئي، بطاقة تسلسل مصورة للتحضير نفسه. الإعداد: قياس خط الأساس أسبوعًا في 3 جلسات قبل اعتماد البروتوكول. الخطوات: تحضير كامل ثم مسار فورًا، وتسجيل الفارق؛ فإن ثبت الفارق عُمّم البروتوكول قبل كل مهمة توازن. التدرج: تقصير التحضير تدريجيًا مع ثبات الأثر (نحو جرعة ذاتية أقصر)، وإضافة مسار مرتفع لاحقًا. التنويع: نسخة بيتية بأدوات بيت (دفع باب، حمل سلة غسيل) قبل واجبات الجلوس. الأمان: أوزان آمنة للعمر والحجم، ولفّ ضاغط بلا ضغط على الصدر والرقبة أبدًا، وتوقف عند أي انزعاج. التكرار: كل جلسة توازن 6 أسابيع. القياس: محاولات ناجحة قبل/بعد في الجلسة الواحدة، ومدة بقاء الأثر بعد التحضير. مؤشر النجاح: فارق ثابت 3 أسابيع ثم تعليم المتعلم طلب التحضير ببطاقته.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة وتعديلات حسية في خدمة الحركة — جرعات منظمة وبيئات مضبوطة", "points": ["سجل مزدوج: أداء وحوادث بيئية مرتبطان أسبوعيًا.", "تدهور جديد يُراجع بيئيًا قبل صعوبة المهارة.", "صفحة شروط أداء تسافر مع المتعلم وثيقة عمل."], "text": {"head": "القياس والمتابعة — عدّل البيئة قبل أن ترفع الصعوبة", "body": "<p>تُتابع الخطة بسجل مزدوج: مؤشرات أداء حركي (كما في بطاقتها) وحوادث بيئية (كم مرة تفكك الأداء في أي بيئة وأي قناة مشتبهة) فيرتبطان أسبوعيًا. قاعدة القرار: كل تدهور جديد يُراجع بيئيًا وحسيًا قبل مراجعة صعوبة المهارة، وكل تحسن يُوثق شرطه الحسي ليُعاد إنتاجه. وتُراجع الخريطة الحسية فصليًا كاملة لأن القنوات تتغير بالنمو والخبرة؛ خريطة قديمة تُعامَل معاملة وثيقة تاريخية لا دليل عمل. وشارك المعلمين بطاقة «شروط أدائه الأفضل» من صفحة واحدة تلخص جرعاته وبيئاته — فهي أنفع وثيقة تسافر مع متعلمك خارج غرفتك.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة وتعديلات حسية في خدمة الحركة — جرعات منظمة وبيئات مضبوطة", "points": ["ثلاث ضبطات مكتوبة: صف وبيت وتنقلات.", "جرعات مجدولة باتفاق المؤسسات لا ارتجالًا.", "المفاجأة الحسية تُخصم من رصيد يوم كامل."], "text": {"head": "توصيات واجهة — بيئة اليوم الحسي المضبوطة", "body": "<p>لخّص لبيئات متعلمك ثلاث ضبطات مكتوبة. في الصف: مقعد بعيد عن مصادر الصوت الحادة والازدحام البصري، وأدواته بملمس مضبوط داخل علبته الخاصة، وجرعة حركية قصيرة مبرمجة قبل حصص الجلوس الطويلة باتفاق مع معلمه. في البيت: ركن حركة آمن بجرعات دهليزية وعميقة مجدولة في أوقات ثابتة بدل المنع المتقطع، وأدوات مضغ/ضغط متفق عليها عند الواجبات. في التنقلات: سماعات عند الحاجة ومسارات معروفة ثابتة للمشاوير المتكررة، فالمفاجآت الحسية في الطريق تُدفع من رصيد اليوم كله.</p><p>وبُعد أخير للقياس لا يقل أهمية: زمن التعافي بعد الغمرة. سجّل كم دقيقة يحتاجها متعلمك بعد موقف حسي قاسٍ (حفلة صاخبة، ازدحام سوق) حتى يعود لأدائه الأساسي؛ فزمن التعافي مؤشر تقدم مستقل بذاته: خطة ناجحة قد لا تمنع الغمرات كلها، لكنها تقصّر زمن الخروج منها شهرًا بعد شهر، وهذا التقصير نفسه دليل أهله الأبلغ على أن التنظيم يُبنى فعلًا في جهاز ابنهم.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يُقاس نجاح الجرعة الحسية على المهمة الحركية التالية لها لا على هدوء المتعلم العام؟", "الإجابة: لأن هدف هذا الباب حركي: الجرعة وُضعت لتصنع نافذة أداء لمهمة محددة؛ فهدوء بلا تحسن مقاس في التوازن أو الدقة لا يثبت أن الجرعة صحيحة القناة والشدة، والقياس الوظيفي وحده يوجّه معايرتها."], "text": null, "take": "أنشطة هذا الباب جرعات حسية معايَرة تسبق الطلب الحركي وتعديلات بيئية موثقة، تُقاس على الأداء الحركي نفسه وتتحول تدريجيًا إلى تنظيم ذاتي يملكه المتعلم.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 58, "title": "التقليد — بوابة التعلم الحركي والاجتماعي الأولى", "intro": "<p>التقليد (imitation) هو أن ترى فعلًا فتعيد إنتاجه بجسدك: وجهًا، أو إيماءة، أو فعلًا على شيء، أو تسلسلًا كاملًا. هو أول قنوات التعلم البشري وأوسعها — به يتعلم الصغير الإيماء واللعب والمهارات قبل أن يتعلم من أي كلام. في هذا الدرس تتعرف على أشكال التقليد ومسار نضجه، لتصير قراءة غيابه أو اضطرابه عند متعلمك قراءة على خريطة لا انطباعًا.</p>", "slides": [{"kind": "cover", "title": "التقليد — بوابة التعلم الحركي والاجتماعي الأولى", "sub": "الوحدة الرابعة عشرة: اضطراب التقليد", "goals": ["أن تشرح التقليد ترجمةً بين جسد مرئي وجسد محسوس عبر المخطط", "أن ترتّب عائلات التقليد الخمس ومسار محطات نضجها", "أن تفسّر كيف يفتح الكبار باب التقليد المتبادل عند نادل"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l58.jpg", "img2": null}, {"kind": "slide", "title": "التقليد — بوابة التعلم الحركي والاجتماعي الأولى", "points": ["خمس عائلات: وجهي وإيمائي وأشياء ومؤجل ومتبادل.", "المؤجل دليل تمثيل داخلي لا محاكاة لحظية.", "صور الانهيار الجزئي متعددة ومتباينة الخطط."], "text": {"head": "أشكال التقليد — وجه وإيماءة وأشياء وتسلسلات", "body": "<p>يتوزع التقليد عائلات: وجهي (expressions faciales) — أقدمها ظهورًا وأعمقها اجتماعيًا: تعبيرات وتقليد فموي-لساني يتصل لاحقًا بالنطق؛ وجسدي-إيمائي: وضعيات وحركات أطراف وجذع بلا أدوات؛ وعلى الأشياء: أفعال بأدوات (يطرق، يسكب، يبني كما رأى)؛ ومؤجل (imitation différée): إعادة فعل رآه قبل ساعات أو أيام، وهو دليل تمثيل داخلي لا مجرد محاكاة لحظية؛ ومتبادل: تقليد داخل تبادل لعبي حيث يقلدك ويستمتع بأن تقلده. كل عائلة تُفحص وحدها، فانهيار الوجهي مع سلامة الأشياء صورة، والعكس صورة أخرى تمامًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التقليد — بوابة التعلم الحركي والاجتماعي الأولى", "points": ["تدرج: وجهي ← أشياء ← إيماءات ← تسلسلات ← مؤجل.", "مرآتي نحو 3 سنوات و«بالحقيقة» ثم مؤجل عند 6-7.", "القراءة بالمحطات لا بالأخطاء المطلقة."], "text": {"head": "مسار النضج — من المحاكاة الوجهية إلى النماذج المعقدة", "body": "<p>يبدأ التقليد مبكرًا جدًا بتقليد وجهي عند الرضّع، ثم أفعال على أشياء في السنة الأولى، ثم إيماءات غائبة الأشياء، ثم تسلسلات متعددة الخطوات، ثم تقليد مؤجل ومتقن التفاصيل عبر سنوات ما قبل المدرسة. في اختبارات بيرجيس-ليزين الكلاسيكية لاستنساخ الإيماءات تظهر مراحل واضحة: استنساخ كالمرآة (en miroir) نحو الثالثة، ثم «بالحقيقة» التشريحية، ثم المؤجل عند السادسة أو السابعة. هذا التدرج خريطتك العمرية: فتقليد مرآتي عند ذي ست سنوات ليس خطأً فادحًا ولا صوابًا ناضجًا، بل محطة أبكر تُسمّى وتُبنى عليها الخطوة التالية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التقليد — بوابة التعلم الحركي والاجتماعي الأولى", "points": ["ترجمة بين جسد مرئي وجسد محسوس بخريطة المخطط.", "أخطاء الاتجاه والجانب بيانات مخطط جسدي.", "خطة تقليد جدية تحمل بناء مخطط مرافقًا."], "text": {"head": "التقليد والمخطط الجسدي — ترجمة بين جسدين", "body": "<p>كل تقليد ترجمة: جسد يُرى من الخارج يجب أن يُعاد إنتاجه بجسد يُحسّ من الداخل، وبينهما خريطة المخطط الجسدي التي درسها بابها: أي جزء يقابل أي جزء؟ وأين يقع في جسدي ما رأيته في جسده؟ لهذا يرتبط اضطراب التقليد باضطراب المخطط ارتباط التوائم، ويُقرأ فشل «ارفع يدك اليمنى مثلما رفعت» عند متعلم ضبابي الاتجاهات فشلَ خريطة لا فشل انتباه. عمليًا: كل خطة تقليد جدية تمر ببناء مخطط مرافق، وكل فحص تقليد يوثق أخطاء الاتجاه والجانب بوصفها بيانات مخطط لا أخطاء تقليد فقط.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التقليد — بوابة التعلم الحركي والاجتماعي الأولى", "points": ["الكبار يفتحون الباب بتقليد المتعلم أولًا (Nadel).", "التقليد المتبادل خبرة اجتماعية قبل أن يكون مهمة.", "«افعل مثلي» ليست المدخل الوحيد ولا الأفضل دائمًا."], "text": {"head": "التقليد بوابة اجتماعية — نادل والتقليد المتبادل", "body": "<p>أبرزت أعمال نادل (Nadel) أن التقليد عند صغار التوحد ليس مجرد مهارة مفقودة بل بوابة تفاعل يمكن فتحها من جهة الكبار: حين يقلّد البالغُ الطفلَ أولًا بأفعاله هو، ينتبه الطفل للتبادل ويبدأ تقليدًا متبادلًا أسرع مما تصنعه مطالبته «افعل مثلي». الدرس المنهجي عميق: بعض أبواب التقليد لا تُفتح من جهة المتعلم أصلًا، بل تُفتح حين يدخل المختص لعبته فيقلده فيصير التقليد خبرة اجتماعية آمنة قبل أن يصير مهمة. ستحتاج هذه القاعدة في أنشطة الدرس الرابع.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التقليد — بوابة التعلم الحركي والاجتماعي الأولى", "points": ["مشهد واحد يجمع عقد المنظومة الخمس كلها.", "لكل عقدة فاشلة توقيع مختلف في المشهد نفسه.", "قراءة التوقيعات مهارة الباب المركزية."], "text": {"head": "مثال تقليد سليم بمحطاته يُقرأ عليه الاضطراب", "body": "<p>تأمل مشهدًا اعتياديًا: معلمة ترفع يديها وتصفق نمطًا من ثلاث ضربات وتنظر؛ متعلم في الرابعة يراقب وجهها ويديها، يرفع يديه بمحاذاة خاطئة أولًا ثم يصحح، يصفق النمط بعدد صحيح وإيقاع قريب، ثم يبتسم طالبًا التكرار — وغدًا يعيد النمط وحده في الساحة. في هذا المشهد الصغير تعمل الآليات الخمس من وحدة الآليات العابرة كلها مجتمعة: انتباه مشترك، وتمثيل، وترجمة جسدية، وتخطيط، ومتعة اجتماعية. فشل أي عقدة يترك توقيعًا مختلفًا في المشهد، وقراءتك التوقيعية هي فن هذا الباب كله.</p><p>وتجمع خريطتك العمرية في ممارستك بصيغة عملية: لكل عمر سائدُ تقليده المتوقع ودرجة سلمه المناسبة للفحص. فقبل الثالثة تُقرأ الوجهيات والأفعال على الأشياء، وبين الثالثة والخامسة الإيماءات والتسلسلات القصيرة، وبعد السادسة المؤجل والتفاصيل الدقيقة. ومتعلم بعمر ثماني سنوات تُفحص عنده وجهيات الرضّع فقط يُبنى ملفه على أرضية طفولية زائفة، تمامًا كما يُبنى ملف ظالم لمن فُحص بسقف لا يناسب سنه.</p><p>وتُحفظ في قراءة المسار قاعدة عمرية عملية: ما يُقبل محطةً طبيعية عند عمر قد يصير قرينة اضطراب عند عمر آخر، والعكس صحيح في اتجاه التقييم — فلا تُكتب أحكام هذا الباب أبدًا بلا مقابلة العمر الزمني بمحطة المتعلم الفعلية على مساره، وسطر المقابلة هذا إلزامي في كل تقرير تقليد تكتبه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يُعدّ التقليد المؤجل دليلًا أقوى من التقليد الفوري على التمثيل الداخلي للفعل؟", "الإجابة: لأن الفوري قد يعتمد على مطابقة بصرية-حركية لحظية للنموذج الحاضر، بينما المؤجل يقتضي أن يكون الفعل قد مُثّل داخليًا وحُفظ واسترجع بغياب نموذجه؛ فنجاحه يثبت وجود تمثيل قابل للاستدعاء لا مجرد محاكاة آنية."], "text": null, "take": "التقليد ترجمة جسد مرئي إلى جسد محسوس عبر خريطة المخطط، بعائلات خمس ومسار محطات معلوم — وهو بوابة تعلم واجتماع معًا، تُفتح أحيانًا من جهة الكبار.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 59, "title": "أشكال اضطراب التقليد عند المصاب بالتوحد", "intro": "<p>اضطراب التقليد (trouble de l'imitation) من أقدم اضطرابات التوحد توثيقًا وأكثرها دراسة، وقد درسته في آلياته العابرة نظريًا؛ هنا ملفه العيادي الكامل: أي عائلات تسقط أولًا، وأي فروق بين النماذج والأشياء والأشخاص، وكيف يتنكر الاضطراب في صورة «لا ينتبه» أو «لا يريد». في هذا الدرس تجمع أشكاله الموثقة وفروقها الفاحصة.</p>", "slides": [{"kind": "cover", "title": "أشكال اضطراب التقليد عند المصاب بالتوحد", "sub": "الوحدة الرابعة عشرة: اضطراب التقليد", "goals": ["أن تصف سلّم اضطراب التقليد من أفعال الأشياء إلى الإيماءات المجردة", "أن تميّز نسخًا تلقائيًا بلا وظيفة (إيكوپراكسيا) عن تقليد وظيفي", "أن تفرّق ملف تقليد الشاشة عن ملف تقليد الإنسان الحي خططيًا"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l59.jpg", "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التقليد عند المصاب بالتوحد", "points": ["إيماءات مجردة أصعب من أفعال الأشياء ذات النتيجة (1972).", "ضعف فموي-وجهي خاص موثق عند روجرز (1996).", "الفحص يبدأ من قاعدة السلم لا من سقفه."], "text": {"head": "الإيماءات بلا معنى تسقط أولًا — درس دي ماير", "body": "<p>وثّق دي ماير (De Myer, 1972) ومن لحقه أن تقليد الإيماءات المجردة بلا معنى ولا أشياء هو الأشد إصابة عند أطفال التوحد، بينما تقليد الأفعال على الأشياء ذات النتيجة الملموسة أحفظ نسبيًا؛ فدرسهم المنهجي أن التقليد ليس قدرة واحدة تسقط كلها، بل سلّم صعوبة: فعل بشيء ونتيجة &lt; إيماءة رمزية &lt; تعبير وجهي دقيق. ويضيف روجرز وآخرون (Rogers, 1996) ضعفًا خاصًا في الحركات الفموية-الوجهية، يرتبط لاحقًا بمسارات النطق والتعبير. الفاحص الذي يبدأ فحصه بأصعب درجات السلم (إيماءات مجردة) يحكم على متعلمه من سقفه لا من قاعدته، فيبني ملف عجز مضخّمًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التقليد عند المصاب بالتوحد", "points": ["نموذج لا يُرى أو يُرى جزئيًا أو يُفقد مبكرًا.", "لا حكم تقليد قبل توثيق وصول الانتباه للنموذج.", "ملف توجيه النمذجة خطته مختلفة كليًا."], "text": {"head": "انتباه لا يصل إلى النموذج — الاضطراب قبل الترجمة", "body": "<p>جزء كبير من فشل التقليد يقع قبل التقليد نفسه: نموذج لا يُنظر إليه أصلًا، أو يُنظر إلى أجزائه الخطأ (الأداة لا اليد)، أو يُفقد قبل اكتماله (يبدأ المتعلم قبل نهاية العرض فيعطّل البناء كله). في حالتي وحدتنا التطبيقية سترى الصورتين: متعلم يقوم قبل انتهاء العرض فيبدأ فوضويًا، وآخر يجلس أمام النموذج دون أن يوجّه نظره إليه أصلًا فيستحيل أي تقليد مهما كانت قدرته الجسدية. القاعدة الفاحصة: لا تسجّل «فشل تقليد» إلا بعد توثيق أن النموذج وُجّه إليه الانتباه كاملًا — وإلا فملفك ملف توجيه انتباه ونمذجة، وهو ملف آخر بخطة أخرى.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التقليد عند المصاب بالتوحد", "points": ["نسخ تلقائي بلا وظيفة براغماتية صورة موثقة.", "آلة نسخ تعمل ومعنى النسخ غائب.", "الجسر العلاجي من النسخ إلى الاستعمال الوظيفي."], "text": {"head": "إيكولاليا حركية وإيكوپراكسيا — تقليد بلا وظيفة", "body": "<p>في ملفات أشدّ تظهر صور «تقليد» بلا فهم ولا وظيفة: إيكولاليا حركية وإيكوپراكسيا (échopraxie) يعيد فيها المتعلم حركات الآخرين وأصواتهم تلقائيًا — كلمات المعلم بنبرته وحركاته نفسها — دون أن يستعملها تواصلًا؛ فاللغة والحركات عنده «ليس لها وظيفة براغماتية» كما وثّقت الحالتان التطبيقيتان حرفيًا. المفارقة الفاحصة عميقة: آلة نسخ تعمل، ومعنى النسخ غائب. وهذه الصورة تعلّمك أن مهارة التقليد وحدها لا تكفي هدفًا؛ فالبناء على النسخ التلقائي نحو الاستعمال الوظيفي (يقلد ليفعل ويطلب ويشارك) هو جسر هذا الباب العلاجي الحقيقي.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التقليد عند المصاب بالتوحد", "points": ["أشياء وشاشات قد تُقلَّد وأشخاص أحياء لا يُقلَّدون.", "الفجوة بين المسارين قراءة تشخيصية ثرية.", "دربّ الباب المفتوح لا الأصعب إغلاقًا دائمًا."], "text": {"head": "تقليد الأشخاص وتقليد الأشياء — فجوة اجتماعية", "body": "<p>يفترق مساران في ملفات كثيرة: تقليد أفعال الأشياء (من شاشات، أو من أشياء تتحرك وحدها) مقبول نسبيًا، بينما تقليد أشخاص أحياء مباشرة مضطرب بشدة — لأن تقليد الإنسان يضيف طبقات: وجهًا يُقرأ، وزمن تبادل، ونظرًا متبادلًا، وقصدية تُخمن. وقراءتك التفريقية هنا تشخيصية الثراء: من يقلد الشاشة ولا يقلد الإنسان ملفه اجتماعي-انتباهي البوابة؛ ومن يفشل في الاثنين بدرجة متقاربة ملفه تمثيلي-حركي أعمق. والخطر المهني أن يُدرَّب الأول بتمارين تقليد ميكانيكية شهورًا بينما بابه المفتوح هو التبادل الاجتماعي المتدرج.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التقليد عند المصاب بالتوحد", "points": ["كل مهارة بلا نموذج = تدريب يدوي مضاعف الكلفة.", "لعب جماعي وقواعد اجتماعية بصرية تمر بلا أثر.", "إعادة بناء القناة استثمار يعيد فتح ملفات كاملة."], "text": {"head": "الكلفة — تعلم بلا نماذج يعني تعليمًا بلا اختصارات", "body": "<p>كلفة اضطراب التقليد تعليمية بامتياز: كل مهارة عند أقرانه تُختصر مشاهدةً واحدة تحتاج عند متعلمك تدريبًا يدويًا خطوة خطوة؛ واللعب الجماعي القائم على محاكاة الأقران يفوته؛ وقواعد اجتماعية كاملة تُتعلم عادة بالعدوى البصرية تمرّ بلا أثر. لهذا تكون إعادة بناء قناة التقليد عند القابلية هدفًا استراتيجيًا يعيد فتح عشرات الملفات الأخرى دفعة واحدة (مهارات يومية، لعب، إيماءات تواصل). وفي المقابل متعلم قويت قناة تقليده يصبح متعلمًا من بيئته كلها، فيتضاعف أثر كل ما حوله من نماذج — وهذا هو الاستثمار الأعلى عائدًا في خطط كثيرة.</p><p>ومن الفروق الفاحصة التي تستحق سطرًا مستقلًا في ملفك: تقليد الأفعال المألوفة عنده (يشرب، يمشط) مقابل الأفعال الاعتباطية غير المألوفة (حركات بلا معنى ولا أدوات)؛ فالأولى قد تعيش على مخزون خطط حركية جاهزة لا على قناة التقليد نفسها، بينما الثانية تكشف القناة عارية. فاحص يخلطهما يحكم سلامة على قناة مريضة لأن متعلمه يحفظ روتينه اليومي جيدًا — وهو خطأ شائع في تقييمات متعلمي السنوات الأكبر خصوصًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يبدأ فحص التقليد المهني بأفعال على أشياء ذات نتائج ملموسة لا بإيماءات مجردة؟", "الإجابة: لأن درجات السلم تتفاوت صعوبة بثبات: الأفعال ذات النتيجة أحفظ عند أصحاب التوحد والإيماءات المجردة أشدها إصابة منذ دراسات دي ماير (1972)؛ فالبدء من الأصعب يحكم على المتعلم من سقف قدرته المضطرب لا من قاعدته المحفوظة."], "text": null, "take": "اضطراب التقليد عند المصاب بالتوحد سلّم لا قدرة واحدة: إيماءات مجردة ووجهيات تسقط أولًا، وانتباه للنموذج قد يسبق فشله فشلَ الترجمة، ونسخ بلا وظيفة عند الأشدّ — وكلفته اختصارات تعلم مفقودة في كل يوم.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 60, "title": "آلية اضطراب التقليد وفحصه — من النظر إلى التمثيل إلى الفعل", "intro": "<p>يتحلل كل فعل تقليد ناجح إلى سلسلة من أربع حلقات: نظر موجه، وتمثيل داخلي، وترجمة إلى جسد الذات، وتنفيذ مضبوط. اضطراب أي حلقة ينتج «فشل تقليد» بالشكل الخارجي نفسه تقريبًا، بينما علاجه مختلف كليًا. في هذا الدرس تتعرف على الآلية بحلقاتها — بما فيها فرضية الخلايا المرآتية بحذرها العلمي الواجب — وعلى فحص يحدد الحلقة المكسورة قبل أي خطة.</p>", "slides": [{"kind": "cover", "title": "آلية اضطراب التقليد وفحصه — من النظر إلى التمثيل إلى الفعل", "sub": "الوحدة الرابعة عشرة: اضطراب التقليد", "goals": ["أن تحلّل فعل تقليد إلى حلقاته الأربع: نظر وتمثيل وترجمة وتنفيذ", "أن تقرأ فرضية الخلايا المرآتية بحذر علمي منضبط في تقاريرك", "أن تبني شبكة فحص تسع مهام تنتهي بتسمية الحلقة المكسورة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l60.jpg", "img2": null}, {"kind": "slide", "title": "آلية اضطراب التقليد وفحصه — من النظر إلى التمثيل إلى الفعل", "points": ["أربع حلقات: نظر وتمثيل وترجمة وتنفيذ.", "الشكل الخارجي الواحد يخفي كسورًا مختلفة.", "التشخيص هنا تحديد حلقة لا تسمية فشل."], "text": {"head": "السلسلة الرباعية — أربع نقاط كسر محتملة", "body": "<p>الحلقة الأولى إدراكية: توجيه نظر وانتقاء أجزاء النموذج الجوهرية. الثانية تمثيلية: بناء صورة داخلية للفعل قابلة للحفظ والاسترجاع. الثالثة ترجمية: مطابقة المرئي بالمخطط الجسدي (يمينه ويساري، قربه وبعده). الرابعة تنفيذية: برمجة الحركة وتسلسلها ومقوّيتها. متعلم قد يملك الحلقات الثلاث الأخيرة كاملة ويعطّله نظر لا يستقر على النموذج ثانيتين؛ وآخر ينظر كاملًا ويمثل جيدًا وتخذله ترجمة جانبية فيعكس كل شيء. التشخيص في هذا الباب هو تحديد الحلقة، وكل اختبارات الدرس آلات لتحديدها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب التقليد وفحصه — من النظر إلى التمثيل إلى الفعل", "points": ["شبكة تنشط عند التنفيذ والمشاهدة معًا — فرضية جسر.", "الأدلة جزئية والسببية المباشرة غير محسومة.", "تُستعمل لتنظيم الأسئلة لا لإغلاق التفسير."], "text": {"head": "الخلايا المرآتية — فرضية مشهورة بحذر واجب", "body": "<p>اشتهرت فرضية نظام الخلايا المرآتية (neurones miroirs): شبكة تنشط عند تنفيذ فعل وعند مشاهدته، اقتُرح أنها جسر الفهم والتقليد، واقتُرح أن اضطرابها يفسر جوانب من التوحد. موقف هذه الدورة العلمي المنضبط: الفرضية أداة تفكير خصبةولها أدلة جزئية، لكن الأدبيات اللاحقة أظهرت أن الصورة أعقد — فكثير من أصحاب التوحد يفهمون أفعال الآخرين وأهدافها رغم اضطراب تقليدهم التنفيذي، والعلاقة السببية المباشرة غير محسومة. تستعمل الفرضية هنا لتنظيم أسئلة الفحص (ماذا يفهم؟ ماذا ينفذ؟ أين ينفصلان؟) لا لتفسير ملف متعلمك بعبارة جاهزة مغلقة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب التقليد وفحصه — من النظر إلى التمثيل إلى الفعل", "points": ["التقليد البشري ينقل القصدية لا العضلات فقط.", "نسخ بلا فهم وفهم بلا نسخ صورتان منفصلتان.", "طريقة بديلة لبلوغ هدف مفهوم قد تكون تعويضًا ذكيًا."], "text": {"head": "القصدية بوابة التقليد الاجتماعي — فهم ما وراء الحركة", "body": "<p>لا يكتمل التقليد البشري بنسخ عضلات؛ فنحن نقلد الأفعال بقصديتها: متعلم يرى يدًا تمسك كوبًا لتشرب فيقلد الإمساك الشربي لا حركة الأصابع المجردة. عند المصاب بالتوحد قد ينفصل النسخ عن القصدية في الاتجاهين: نسخ أمين بلا فهم للغرض (فلا يعمم ولا يوظف)، أو فهم للغرض مع عجز تنفيذي (فيخترع طريقته الخاصة بلوغ الهدف — وهو أحيانًا ذكاء تعويضي يُحترم لا خطأ يُصحح). فحصك يسجل الاثنين منفصلين: هل نسخ؟ وهل فهم لتصير النسخة فعلًا وظيفيًا في سياق آخر؟</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب التقليد وفحصه — من النظر إلى التمثيل إلى الفعل", "points": ["تسع مهام من أشياء إلى وجه إلى تسلسلات إلى مؤجل.", "سجل رباعي: نظر ونسخ وكمون ووظيفية.", "بيرجيس-ليزين كاشفة للمشاهدة والتقليد معًا."], "text": {"head": "شبكة الفحص — تسع مهام بمنطق واحد", "body": "<p>شبكة عملية بمنطق تدرج السلم وتفكيك الحلقات: (1-3) أفعال على أشياء بنتيجة فورية (طرق، سكب، بناء برج من نموذج)؛ (4-6) إيماءات جسدية بلا أشياء من اختبارات بيرجيس-ليزين لاستنساخ الإيماءات بمستوياتها (مرآتي ثم «بالحقيقة»)؛ (7) حركات فموية-وجهية (فتح فم، إخراج لسان، نفخ)؛ (8) تسلسلان من خطوتين وثلاث خطوات؛ (9) مهمة مؤجلة تُعرض أول الجلسة وتُطلب آخرها. لكل مهمة سجل رباعي: نظر موثق للنموذج؟ نسخ كامل/جزئي/معكوس؟ زمن كمون؟ ووظيفية (استعمل النسخة لغرض؟). ومهام بيرجيس-ليزين تحديدًا تُقدَّم دائمًا لأنها تكشف إمكانات التقليد من جهة وغياب مشاهدة التسلسل من جهة أخرى كما نبهت المذكرة المؤسسة لهذا الباب.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية اضطراب التقليد وفحصه — من النظر إلى التمثيل إلى الفعل", "points": ["حكم بصيغة حلقة ودليل وقاعدة محفوظة.", "لكل حلقة مكسورة بوابة خطة مختلفة.", "بلا تسمية حلقة، الخطة قفزة عشوائية."], "text": {"head": "من الفحص إلى الحكم — حلقة مكسورة وخطة مسماة", "body": "<p>يُختم الفحص بجملة واحدة من صيغة ثابتة: «تقليد متعلمي ينكسر أساسًا عند حلقة كذا، ودليله كذا، وقاعدته المحفوظة كذا». فخطة كسر النظر تبدأ بمهندسة نماذج (قريبة، بطيئة، كبيرة، مكررة، داخل مجال نظره) وبناء مشاهدة؛ وخطة كسر الترجمة تبني مخططًا وجانبية مرافقة؛ وخطة كسر التنفيذ تبني على أفعال الأشياء الناجحة وتدرج نحو الإيماءات؛ وخطة كسر الوظيفية تنقل النسخ التلقائي إلى استعمالات مقصودة داخل تبادلات محببة. والحكم الذي لا يسمي حلقته خطةُ تقليده القادمة قفزة عشوائية بجرعة كبيرة.</p><p>وفي شبكة الفحص أضف مهمة عاشرة ذهبية حين يسمح الوقت: قلّد أنت خطأً مقصودًا في نموذج يعرفه (امسك الملعقة مقلوبة في فعل مألوف) وراقب ردّه: هل ينسخ خطأك حرفيًا، أم يصححه إلى الصواب الوظيفي، أم لا ينتبه أصلًا؟ إجاباته الثلاث تفرّق بعمق بين ناسخ آلي وفاعل فاهم وغائب الانتباه — وهي ثلاث خطط مختلفة تمامًا تُبنى على دقيقة ملاحظة واحدة ذكية.</p><p>واحفظ من هذا الدرس أخيرًا ترتيب الأسئلة حين يحضر إليك ملف تقليد جديد: هل وصل النظر؟ وهل مُثّل ما وصل؟ وهل تُرجم إلى الجسد بلا انعكاس مضلل؟ وهل نُفّذ ببرمجة كافية؟ أربعة أسئلة بترتيبها هذا تساوي في قيمتها العملية نصف أدوات الباب، لأنها تمنعك من علاج حلقة سليمة شهورًا بينما الكسر في أختها الصامتة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: متعلم يقلد من الشاشة بدقة ويفشل كليًا في تقليدك وجهًا لوجه رغم نظر موثق للنموذج؛ كيف توجه حكمك الأولي؟", "الإجابة: أن الكسر ليس في الترجمة الجسدية العامة (تثبتها الشاشة) بل في طبقة تقليد الإنسان الحي: تبادل ونظر اجتماعي وقصدية مباشرة — فتُبنى الخطة من التبادل الاجتماعي المتدرج والنمنذجة الحية القريبة، لا من تمارين نسخ ميكانيكية إضافية."], "text": null, "take": "آلية التقليد سلسلة نظر وتمثيل وترجمة وتنفيذ، تُقرأ الخلايا المرآتية فيها فرضيةً منظمة للأسئلة لا حكمًا مغلقًا؛ وفحصها شبكة تسع مهام تنتهي بتسمية الحلقة المكسورة قبل أي تدريب.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 61, "title": "أنشطة التقليد وتوصياته — سلّم يُصعَد من قاعدته", "intro": "<p>أنشطة وتوصيات لاضطراب التقليد عند المصاب بالتوحد. قاعدة الباب من درس أشكاله: الصعود من قاعدة السلم المحفوظة (أفعال أشياء ذات نتائج) نحو قمته المضطربة (إيماءات ووجهيات)، ببوابات اجتماعية تُفتح أحيانًا من جهة الكبار، ونماذج تُهندَس لتُرى قبل أن تُقلَّد.</p>", "slides": [{"kind": "cover", "title": "أنشطة التقليد وتوصياته — سلّم يُصعَد من قاعدته", "sub": "الوحدة الرابعة عشرة: اضطراب التقليد", "goals": ["أن تصعد بمتعلمك سلّم التقليد من قاعدته المحفوظة لا من قمته", "أن تطبق بطاقة مرآة أفعال ذات نتائج كاملة بعناصرها العشرة", "أن تقيس القناة الحقيقية بالتقاطات بيئية عفوية لا بنسخ الطاولة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act77_img1.webp", "img2": null}, {"kind": "slide", "title": "أنشطة التقليد وتوصياته — سلّم يُصعَد من قاعدته", "points": ["نموذج بطيء كبير قريب معزول ومكرر.", "مرافقة جسدية متلاشية تبني تمثيلًا من الداخل.", "كل نسخة توظف فورًا في معنى حقيقي."], "text": {"head": "مبادئ حاكمة — نموذج يُرى ونجاح يتراكم ومعنى حاضر", "body": "<p>أربعة مبادئ. أولًا: هندسة النموذج قبل مطالبة النسخ: نموذج بطيء، كبير الإيماءة، قريب من مجال النظر، معزول عن خلفيات مشتتة، ويُعاد بلا ملل حتى يكتمل وصوله. ثانيًا: مرافقة جسدية متلاشية عند الحاجة (توجيه يد المتعلم ليحس الحركة من جسده هو، يُسحب تدريجيًا) — فالإحساس الداخلي بالحركة يبني التمثيل أحيانًا أسرع من عشر مشاهدات. ثالثًا: كل نسخة ناجحة توظَّف فورًا في لعبة أو حاجة حقيقية حتى لا يبقى التقليد تمرينًا أجوف. رابعًا: ابدأ بجلسات تقليد متبادل تقلّد فيها أنت متعلمك (قاعدة نادل) في ألعابه هو، فتشتري انتباهه الاجتماعي بعملته قبل أن تبيع نماذجك.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التقليد وتوصياته — سلّم يُصعَد من قاعدته", "points": ["نتائج فورية محببة تحمل قاعدة السلم.", "أغانٍ حركية تبني الإيماءات مقاطع مركبة.", "وجهي يُبنى وظيفيًا (نفخ) قبل التمثيل المرآتي."], "text": {"head": "ترسانة بحسب درجة السلم", "body": "<p>لقاعدة الأشياء: أفعال نتائج فورية مضحكة أو لذيذة (إسقاط أبراج، مطرقة صوتية، سكب وتفريغ، فقاعات تُنفخ) بنماذج متعاقبة قصيرة. للإيماءات الجسدية: أغانٍ حركية بجمل إيمائية ثابتة (تصفيق، تلويح، لمس رأس وكتفين) تُبنى مقطعًا مقطعًا وتُركّب. للوجهي: مرايا وألعاب تعبيرات بطيئة مبالغًا فيها، ونفخ وشفط ألعابًا (فقاعات، قصاصات تطير) تبني الفموي وظيفيًا قبل تمثيليًا. للتسلسلات: سلاسل خطوتين فثلاث داخل روتين محبب (تحضير عصير لعبة). للمؤجل: «مفاجآت» يعرضها المختص أول اليوم ويطلب استرجاعها ختامًا بصيغة لعب لا اختبار.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التقليد وتوصياته — سلّم يُصعَد من قاعدته", "points": ["هدف مركب: أشياء أولًا ثم إيماءات بشروط واحدة.", "زمن كمون ونسبة مرافقة مؤشرا عمق لا نجاح فقط.", "توجيه النظر بالموضع والأداة لا بمسك الوجه أبدًا."], "text": {"head": "بطاقة نشاط كاملة — «مرآة الأفعال ذات النتائج»", "body": "<p>المجال: اضطراب التقليد — قاعدة السلم نحو الإيماءات. الهدف القابل للقياس: أن يقلد المتعلم 8 أفعال على أشياء (من قائمة 10 مدربة) فور عرضها مرة واحدة، بلا مرافقة، في 4 من 5 محاولات لكل فعل، ثم يقلد 3 إيماءات جسدية بسيطة بالمعيار نفسه. الأدوات: مطرقة لعبة ووتد، أكواب وسكب، مكعبات برج، فقاعات صابون، وصندوق «انتهى» توضع فيه الأداة بعد فعلها. الإعداد: جلوس متقابل على طاولة خالية إلا من أداة الفعل الحالي، ونموذج يُعرض ببطء مرتين قبل أول مطالبة. الخطوات: أفعال الأشياء العشرة متدرجة، وتوظيف كل نجاح بلعبة قصيرة، ثم إدخال الإيماءات واحدة بعد نجاحات الأشياء لا قبلها. التدرج: خطوتان متسلسلتان، ثم أفعال من ذاكرة الجلسة (مؤجل قصير)، ثم إيماءات بوجه متزايدة. التنويع: نموذج بشري ثانٍ، ثم قرين، ثم أفعال في ألعاب المتعلم الحرة. الأمان: لا إمساك وجه أو رأس لتوجيه النظر أبدًا — التوجيه بالأداة والموضع والصوت. التكرار: 4 مرات أسبوعيًا 6 أسابيع. القياس: أفعال مقلدة من عرض واحد، زمن كمون، ونسبة احتياج مرافقة. مؤشر النجاح: بلوغ هدف الأشياء والإيماءات مع نموذجين بشريين مختلفين.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التقليد وتوصياته — سلّم يُصعَد من قاعدته", "points": ["التقاطات بيئية عفوية مقياس القناة الحقيقي.", "ستة أسابيع بلا انتقال = راجع البوابة الاجتماعية.", "شبكة تساعية فصلية تحدّث موضع الحلقة المتحرك."], "text": {"head": "القياس والمتابعة — من الجلسة إلى الحياة الاجتماعية", "body": "<p>يُقاس أثر الخطة خارج طاولة التدريب: إيماءات تواصل جديدة تظهر عفويًا (تلويح، إيماء طلب)، ومهارات يومية التُقطت من نماذج وحيدة العرض في البيت (يرويها الأهل بسجل أسبوعي)، ومشاركة في أغانٍ حركية جماعية. قاعدة القراءة الذهبية: تقدم على الطاولة بلا أي التقاط بيئي بعد ستة أسابيع يعني أن القناة ما زالت «تمرينية» — راجع بوابة التبادل الاجتماعي وقاعدة نادل قبل رفع درجات السلم. وتُعاد شبكة الفحص التساعية فصليًا لتحديث موضع الحلقة، فكسور التقليد تتنقل مع النمو ولا يصح أن تجمد خطة عند أول حلقة شخصتها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التقليد وتوصياته — سلّم يُصعَد من قاعدته", "points": ["قيادة متبادلة للتقليد في ألعاب البيت اليومية.", "نموذج صامت يسبق الكلام في مهارات الصف الجديدة.", "النماذج الناجحة تُسمّى وتُوثق لتُعاد استعمالًا."], "text": {"head": "توصيات واجهة — نماذج في البيت والصف", "body": "<p>عمّم القناة باتفاقات نمذجة بسيطة. في البيت: ألعاب تقليد يومية قصيرة من اختيار المتعلم يقودها الأهل بالتبادل (هم يقلدونه مرة وهو يقلدهم مرة)، ومهارات جديدة تُقدَّم دائمًا بنموذج عملي صامت أولًا ثم كلام. في الصف: معلم يُظهر المهارة بجسده قبل أي تعليمة لفظية في الأنشطة الحركية، وقرين نموذجي قريب للأنشطة الجماعية، وأغانٍ حركية بإيماءات ثابتة افتتاحًا لليوم. وتوثَّق النماذج التي «تعمل» عند متعلمك بالاسم في سجل تعديلاته لتُعاد لا لتُخترع من جديد.</p><p>ويلحق بمبادئ هذا الدرس مبدأ اجتماعي خامس كثير النسيان: حماية كرامة المتعلم الأكبر سنًا من أشكال التدريب الطفولية. فتقليد يُبنى عند ذي عشر سنوات بأغانٍ وألعاب مصممة للرابعة قد ينجح ميكانيكيًا ويفشل اجتماعيًا كليًا لأنه يرفض المادة لا المهمة. القاعدة: المحتوى العمري للمتعلم دائمًا، وآلية السلم وحدها هي الطفولية الأصل إذا لزم — فمهارة تُبنى داخل اهتماماته الحقيقية تعيش، ومهارة تُبنى في مواد يخجل منها تموت عند باب الجلسة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا تُمنع طريقة إمساك رأس المتعلم أو وجهه لتوجيه نظره إلى النموذج في هذا الباب؟", "الإجابة: لأن توجيه النظر القسري جسديًا يبني نفورًا من النمذجة نفسها ويعلّم تقليدًا تحت الضغط لا قناة تعلم حرة، ولأن أدوات التوجيه المشروعة (موضع النموذج وقربه وحجم حركته وصوت مرافق وأداة تلفت) تحقق الوصول دون كلفة علائقية وحسية تفسد الباب كله."], "text": null, "take": "أنشطة التقليد صعود منظم من أفعال الأشياء إلى الإيماءات والوجهيات، بنماذج مهندسة لتُرى ومرافقات متلاشية وتوظيف فوري — وتُقاس بالتقاطات الحياة لا بنسخ الطاولة وحده.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 62, "title": "التخطيط الحركي والبراكسيا — من الفكرة إلى الفعل", "intro": "<p>التخطيط الحركي (planification motrice) هو القدرة على تصوّر فعل لم يُنفَّذ من قبل، وتنظيم خطواته، وتنفيذه بترتيبها — من الفكرة إلى الإنجاز. ويسمى اضطرابها عسر التخطيط الحركي أو اضطراب البراكسيا (dyspraxie). أما الاستباق (anticipation) فوجهها الزمني: تهيئة الجسد قبل الحدث لا بعده. في هذا الدرس تتعرف على بناء البراكسيا بأنواعها الكلاسيكية، وعلى الاستباق بأشكاله الثلاثة، لتقرأ اضطرابهما قراءة مرتبة.</p>", "slides": [{"kind": "cover", "title": "التخطيط الحركي والبراكسيا — من الفكرة إلى الفعل", "sub": "الوحدة الخامسة عشرة: اضطراب التخطيط والاستباق", "goals": ["أن تشرح التخطيط الحركي والبراكسيات بأنواعها الثلاثة الكلاسيكية", "أن تميّز الفعل الجديد المخطَّط عن الفعل المحفوظ المخزَّن", "أن تسمّي الاستباقات الثلاثة: وضعي ونظري وتسلسلي"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l62.jpg", "img2": null}, {"kind": "slide", "title": "التخطيط الحركي والبراكسيا — من الفكرة إلى الفعل", "points": ["ثلاث براكسيات: فكرية-حركية وفكرية وبنائية.", "انهيار ترتيب الخطوات مع سلامة كل خطوة توقيع الفكرية.", "حكم واحد بنوع واحد حكم ناقص دائمًا."], "text": {"head": "البراكسيا بأنواعها — فكرة وتنفيذ واستعمال أدوات", "body": "<p>ميّزت العيادة الكلاسيكية بين براكسيات: حركية-فكرية (idéomotrice): تنفيذ حركات وإيماءات رمزية عند الطلب (لوّح مودعًا، أرني كيف تمشط)؛ وفكرية (idéatoire): تسلسل استعمال أشياء حقيقية لغرض مركب (حضّر ظرفًا وبريده، أشعل شمعة بعيدان) حيث تنهار الخطوات ترتيبًا رغم سلامة كل خطوة منفردة؛ وبنائية (constructive): تركيب وبناء من نموذج (مكعبات، رسم، بازل). هذا التقسيم فاحصي الثراء: متعلم قد تكون إيماءاته سليمة وتسلسلات أدواته منهارة، فلا يصح حكم «براكسيا» بنوع واحد. وعند أولاد التوحد تمتزج الصور غالبًا باضطراب الآليات العابرة كلها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التخطيط الحركي والبراكسيا — من الفكرة إلى الفعل", "points": ["جديد يخطط ومحفوظ يعمل ببرامج مخزنة.", "انهيار انتقائي عند الجدة توقيع الباب الأشهر.", "الفحص بأفعال جديدة مضبوطة شرط الصدق."], "text": {"head": "الفعل الجديد والفعل المحفوظ — مفتاح الباب كله", "body": "<p>أصدق تمييز في هذا الباب: الفعل الجديد غير المدرَّب والفعل المحفوظ المتكرر يعيشان نظامين مختلفين نسبيًا. المحفوظ يعمل ببرامج جاهزة مخزنة لا تحتاج تخطيطًا واعيًا (يربط حذاءه المعتاد مغمضًا تقريبًا)، والجديد يحتاج التخطيط الكامل: تصوّرًا وترتيبًا ومراقبة. لهذا قد يبدو متعلمك «طبيعي الحركة» في روتينه كله وينهار في كل جديد — ملعب جديد، أداة جديدة، مهارة أولى — فيوصف ظلمًا بأنه «يعرف لكن لا يريد الجديد». القاعدة: لا تُفحص البراكسيا إلا بأفعال جديدة مضبوطة الجدة؛ فحصها بالمحفوظات يقيس الذاكرة الحركية لا التخطيط.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التخطيط الحركي والبراكسيا — من الفكرة إلى الفعل", "points": ["وضعي ونظري وتسلسلي — ثلاثة مسارح للتهيئة.", "عين تسبق يدًا توقيع نضج في كل مهارة.", "غيابه يحوّل الحركة سلسلة مفاجآت متتابعة."], "text": {"head": "الاستباق بأشكاله الثلاثة — وضعي ونظري وفعلي", "body": "<p>يظهر الاستباق في ثلاثة مسارح: وضعي (anticipation posturale): تجهيزات الجسم السابقة للحركة الكبيرة التي رأيتها في درس الاستباق عند التوازن (تُشدّ العضلات قبل رفع الذراع لئلا يسقط الجذع)؛ ونظري: توجيه النظر إلى الهدف التالي قبل وصول اليد (عين تسبق يدًا في كل مهارة ناضجة)؛ وفعلي-تسلسلي: تهيئة الخطوة التالية أثناء الحالية في التسلسلات (يمسك الغطاء وهو يفتح العلبة بذهن حاضر للخطوة الآتية). غيابه يجعل الحركة سلسلة مفاجآت: كل خطوة تبدأ من صفر، وكل كرة تصل قبل أن تستعد اليد — صورة التقاط الكرة الفاشل الموثقة في حالاتنا التطبيقية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التخطيط الحركي والبراكسيا — من الفكرة إلى الفعل", "points": ["تسلسل ومراقبة وكبح: وظائف تنفيذية بثوب حركي (1996).", "بطاقات خطوات خارجية تعويض مشروع لا مساعدة عابرة.", "الازدحام بالمشتتات يضاعف كلفة التخطيط التنفيذي."], "text": {"head": "التخطيط والوظائف التنفيذية — الجسر المعرفي", "body": "<p>يرتبط التخطيط الحركي بالوظائف التنفيذية (fonctions exécutives) ارتباط الجسر: تسلسل ومراقبة وكبح خطوات سابقة وتحديث خطة عند طارئ — وهي الوظائف نفسها التي وصف هيوز (Hughes, 1996) اضطرابها عند التوحد في مهام التسلسل. عمليًا يعني ذلك أن متعلمك قد يفشل في مهمة حركية مركبة لأسباب تنفيذية خالصة (لا يستطيع إبقاء الخطوات الثلاث حاضرة) لا لأسباب حركية، وأن تدريبات ذاكرة العمل التسلسلية والبطاقات المصورة الخارجية للخطوات ليست «مساعدات» بل تعويضات مشروعة عن حلقة مضطربة. ويفسر أيضًا لماذا ينهار أداؤه في البيئات المزدحمة بالمشتتات أكثر من أقرانه بفارق مضاعف.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "التخطيط الحركي والبراكسيا — من الفكرة إلى الفعل", "points": ["خطوات مقلوبة وأدوات متأخرة وتثبيت غائب.", "مكونات صحيحة وتجميع فوضوي = توقيع التخطيط.", "التعرف الفوري على التوقيع مهارة الباب الأولى."], "text": {"head": "مثال جامع — صنع شطيرة لأول مرة", "body": "<p>ادرس فعلًا يوميًا بسيطًا بعين هذا الباب: شطيرة أولى في حياة متعلم. تخطيط: اختيار أدوات وترتيب خطوات (خبز، فتح، دهن، إغلاق، تقطيع). تنفيذ: كل خطوة مهارة قائمة. استباق: إمساك الخبز باليد الأخرى قبل الدهن، وفتح العلبة قبل الحاجة إليها. مراقبة: تصحيح كمية الدهن أثناء الفعل. عند اضطراب الباب ترى الصورة المعروفة: خطوات بترتيب مقلوب (يقطع قبل أن يدهن)، وأدوات تُطلب بعد مواضعها، ودهن بلا يد مثبتة، ونهاية فوضوية بمكونات صحيحة كلها. هذه الصورة «فوضى منظمة الأجزاء» هي توقيع التخطيط الذي يجب أن تتعرف عليه فورًا في أي مهمة مركبة.</p><p>ومن الاستعمالات اليومية الدقيقة لهذه الأنواع الثلاثة قراءة واجبات متعلمك المدرسية: نسخ من السبورة يفشل (بنائية وعين تسبق يدًا)، وأنشطة أشغال متسلسلة تنهار في وسطها (فكرية)، وإيماءات المعلم الجسدية لا تُقرأ نماذجَ قابلة للتنفيذ (فكرية-حركية). الفاحص الذي يقرأ ملف البراكسيا بأنواعه يترجم شكاوى الصف إلى بنوده الصحيحة مباشرة، فيختصر شهورًا من التخبط بين «لا يركز» و«لا يحاول».</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يُشترط في فحص البراكسيا أن تكون الأفعال جديدة غير مدربة مسبقًا؟", "الإجابة: لأن الأفعال المحفوظة تعمل ببرامج حركية مخزنة لا تستدعي التخطيط الواعي؛ ففحصها يقيس الذاكرة الحركية ويعطي صورة سلامة كاذبة، بينما لا يظهر اضطراب التخطيط إلا حيث يجب بناء برنامج جديد: فعل جديد مضبوط الجدة."], "text": null, "take": "التخطيط الحركي بناء فعل جديد من فكرته إلى تسلسله، بأنواع براكسيا ثلاث واستباقات ثلاث، وجسره المعرفي الوظائف التنفيذية — واضطرابه يظهر انتقائيًا عند كل جديد رغم روتين محفوظ سليم المظهر.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 63, "title": "أشكال اضطراب التخطيط والاستباق عند المصاب بالتوحد", "intro": "<p>يترك اضطراب التخطيط والاستباق عند المصاب بالتوحد توقيعات شاهدت بعضها في آلياته العابرة: تحضير مضطرب وتنفيذ سليم. هنا ملفه العيادي الكامل بأشكاله اليومية القابلة للتوثيق: أفعال تنهار عند جدّتها، وتسلسلات تنقلب، وأجساد تصل متأخرة دائمًا إلى أحداثها، وانتقالات تتحول إلى أزمات بلا سبب ظاهر لغير المختص.</p>", "slides": [{"kind": "cover", "title": "أشكال اضطراب التخطيط والاستباق عند المصاب بالتوحد", "sub": "الوحدة الخامسة عشرة: اضطراب التخطيط والاستباق", "goals": ["أن تصف أشكال الباب: تحضير مضطرب ويد غائبة وأنماط أخطاء تسلسلية أربعة", "أن تقرأ أزمات الانتقالات قراءة تخطيطية قبل أي قراءة سلوكية", "أن تميّز جسدًا يصل متأخرًا لحدثه عن متعلم «لا يعرف اللعب»"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act96_img1.webp", "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التخطيط والاستباق عند المصاب بالتوحد", "points": ["تحضير مضطرب وتنفيذ محفوظ نسبيًا (2001).", "«بطيء البداية» يحتاج منصات انطلاق لا ضغطًا.", "الدفعة الأولى الصحيحة تغيّر يومًا كاملًا."], "text": {"head": "التحضير المضطرب والتنفيذ السليم — توقيع راينهارت", "body": "<p>لخّص راينهارت وزملاؤه (Rinehart, 2001) نتيجة أبحاثهم في قاعدة صارت عنوان الباب: عند التوحد التحضير للحركة (préparation) هو المضطرب أما التنفيذ فمحفوظ نسبيًا؛ فإذا انطلق الفعل جرى بسلاسة قريبة من الأقران، بينما زمن ما قبل الانطلاق — التهيؤ والتوجيه ومعايرة البداية — طويل مرتبك. الترجمة اليومية: متعلم «بطيء البداية» في كل شيء (يتأخر في الشروع، يبدو مترددًا، يحتاج دفعة أولى) ثم ينجز بجودة. معلم يقرؤها كسلًا يضغط على نقطة قوته الوهمية ويفسد علاقته به؛ ومختص يقرؤها تحضيرًا يبني له «منصات انطلاق» (إشارات بداية، تموضعات مسبقة، خطوة أولى مقسومة) فيتغير يومه كله.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التخطيط والاستباق عند المصاب بالتوحد", "points": ["يد غائبة عن دورها الاستباقي رغم مهارتها (2003).", "رحلات متكررة بدل حمل منظم واحد.", "قراءة استباقية تبني حيث فشل «ركّز وانتبه»."], "text": {"head": "مشكلة النادل — حين لا تصل الإشارة إلى الجسد", "body": "<p>وثّق شميتز (Schmitz, 2003) التجربة الأبلغ: متعلم يحمل صينية بيد كما يحملها النادل مادًّا ذراعه، ويده الأخرى لا تصعد لتساعد رغم وضوح الحاجة ومهارته في الإمساك ذاته — فالتواصل بين تخطيط اليدين واستباق إحداهما لحاجة الأخرى مقطوع. سترى نسخها اليومية في كل مكان: يد تحمل ويد غائبة عن دورها، وجسد لا يهيئ نفسه لحمل قادم، وأدوات تُنقل واحدة واحدة برحلات متكررة بدل حمل منظم. قراءة هذه الصورة تخطيطًا-استباقًا (لا انتباهًا ولا تعاونًا) تبني خطط ثنائية واستباقية حيث فشلت خطط «ركّز وانتبه» شهورًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التخطيط والاستباق عند المصاب بالتوحد", "points": ["أربعة أنماط: انقلاب وسقوط وتكرار حلقي وتوقف عند طارئ.", "كل نمط يرشح حلقة مختلفة وعلاجًا مختلفًا.", "خريطة الأنماط عبر مهام متعددة وثيقة الفحص."], "text": {"head": "تسلسلات تنقلب وخطوات تسقط من الوسط", "body": "<p>في المهام متعددة الخطوات يظهر الاضطراب أنماط أخطاء ثابتة نسبيًا عند صاحبها: انقلاب ترتيب (يغلق قبل أن يملأ)، وسقوط خطوات وسطى صامت (ينسى الغسل بين الصابون والشطف)، وتكرار حلقي لخطوة مريحة (يفرك وفرك...)، وتوقف كلي عند خطوة غير متوقعة (أداة ناقصة = نهاية المهمة لا بحث عن بديل). هذه الأنماط الأربعة توقيعات وثائقية: تسجيلها بأنواعها عبر مهام مختلفة يبني خريطة تخطيط متعلمك الدقيقة، ويفرّق بين اضطراب ترتيب (برمجة) واضطراب مرونة عند الطارئ (تنفيذي) واضطراب ذاكرة خطوات (تعويضه بطاقات خارجية).</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التخطيط والاستباق عند المصاب بالتوحد", "points": ["تجهيز يبدأ عند الاصطدام لا قبله.", "نجاح مفاجئ عند أحداث متوقعة ثابتة المسار.", "مقارنة شرطين = أسرع فحص استباق ميداني."], "text": {"head": "جسد يصل متأخرًا — استباق غائب في اللعب والرياضة", "body": "<p>في مواقف الكرات والألعاب الحركية يظهر الوجه الاجتماعي للاستباق الغائب: يد تُرفع بعد مرور الكرة، وتجهيز للإمساك يبدأ عند الاصطدام، وقفزات تهيئة لا تحدث (لا ينحني قبل القفز). النتيجة الاجتماعية قاسية: «لا يعرف اللعب» و«بطيء» أحكام أقران تتراكم. وفي المقابل مواقف آمنة التوقع (كرة متدحرجة ببطء ثابت المسار) قد ينجح فيها نجاحًا يفاجئ الجميع — لأنه أزال عنصر الاستباق الصعب وأبقى التنفيذ. المقارنة بين الشرطين (حدث متوقع تمامًا/حدث حي متغير) هي فحص الاستباق الميداني الأسرع.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أشكال اضطراب التخطيط والاستباق عند المصاب بالتوحد", "points": ["انتقال = إنهاء برنامج وبناء آخر: كلفة تخطيطية خالصة.", "«عناد الانتقالات» قراءة تخطيطية تغيّر الأدوات كلها.", "إنذارات وجداول وجسور قبل أي برنامج سلوكي."], "text": {"head": "الانتقالات — أزمات تخطيط متنكرة في ثوب السلوك", "body": "<p>أخطر متنكرات الباب: الانتقال بين نشاط وآخر. الانتقال فعل تخطيطي كامل: إنهاء برنامج جارٍ (بكل كلفته التنفيذية)، وحمل صورة القادم، والشروع فيه. عند متعلم مضطرب التخطيط يكون كل انتقال انهيارًا صغيرًا: بكاء ورفض و«عناد» عند انتهاء المحبب وبداية المطلوب عشرات المرات يوميًا. قراءتها سلوكًا محضًا أنتجت عقوبات وجداول تعزيز على باب خاطئ؛ وقراءتها تخطيطًا تنتج أدوات انتقال (إنذارات متدرجة، جداول مصورة، خطوات انتقال مكتوبة، جسور حسية بين النشاطين) فتنخفض الأزمات بلا أي برنامج سلوكي. هذه القراءة من أعلى دروس الدورة عائدًا على حياة متعلميك اليومية.</p><p>ولاحظ خاصة عائلات كاملة من الأنشطة اليومية تُبنى على الاستباق وحده: ركوب دراجة (توجيه نظري وتهيئة مستمرة)، وعبور شارع (قراءة سرعات قادمة واستباق زمني)، ورياضات كرة كلها. متعلمك قد يملك قوة وسرعة وتناسقًا سليمًا ويُستبعد من هذه العوالم كلها لباب الاستباق فقط؛ فحين تُدرَّب استباقاته بمواقف متدرجة التوقع، تُفتح له أبواب أنشطة لم تكن في أي خطة باب آخر — وهذا وحده مبرر أن يحمل الاستباق دائمًا سطرًا مستقلًا في كل خطة شاملة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: معلم يصف متعلمك بأنه «كسول يبدأ ببطء شديد ثم ينجز بجودة إذا بدأ»؛ ما إعادة القراءة المهنية وما أداتها الأولى؟", "الإجابة: الصورة توقيع تحضير مضطرب وتنفيذ محفوظ عند راينهارت (2001) لا كسل؛ فالعطل في زمن ما قبل الانطلاق، وأداته الأولى منصات انطلاق: إشارات بداية ثابتة وتموضع مسبق وخطوة أولى مقسومة صغيرة، لا ضغطًا على «الكسل»."], "text": null, "take": "أشكال الباب عند المصاب بالتوحد: تحضير مضطرب مع تنفيذ محفوظ، ويد غائبة عن استباقها، وأنماط أخطاء تسلسلية أربعة، وجسد يصل متأخرًا لأحداثه، وانتقالات تنهار — كلها توقيعات تُوثق بأنماطها لا بأحكام عامة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 64, "title": "آلية التخطيط والاستباق وفحصهما — نماذج داخلية وتغذية استباقية", "intro": "<p>يقف وراء التخطيط الحركي الناضج مفهوم آلي قوي: النماذج الداخلية (modèles internes) — محاكاة عصبية تتنبأ بنتائج الحركة قبل حدوثها، فتُبنى عليها التهيئة والتغذية الاستباقية. في هذا الدرس تتعرف على الآلية بعنصريها (تغذية استباقية وتغذية راجعة)، وعلى فحص منهجي يفرّق اضطراب التخطيط عن أخواته ويحدد أنماط أخطاء متعلمك بدقة قابلة للبناء.</p>", "slides": [{"kind": "cover", "title": "آلية التخطيط والاستباق وفحصهما — نماذج داخلية وتغذية استباقية", "sub": "الوحدة الخامسة عشرة: اضطراب التخطيط والاستباق", "goals": ["أن تشرح النماذج الداخلية والتغذية الاستباقية والراجعة وتوازنهما", "أن تبني شبكة فحص بأفعال جديدة وقياس اختزان بعد يومين", "أن تفرّق اضطراب التخطيط عن التقليد والفهم والذاكرة والتنفيذي"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l64.jpg", "img2": null}, {"kind": "slide", "title": "آلية التخطيط والاستباق وفحصهما — نماذج داخلية وتغذية استباقية", "points": ["محاكاة عصبية تتنبأ بنتائج الحركة قبل وقوعها.", "اضطرابها يفرض اعتمادًا كاملًا على التصحيح البعدي.", "تقطع الأداء وكثرة إعادة الضبط توقيع غيابها."], "text": {"head": "النموذج الداخلي — محاكاة تسبق العضلات", "body": "<p>حين تمدّ يدك إلى كوب، جهازك لا ينتظر أن يراه يتحرك ليصحح؛ بل يحاكي الحركة كاملة سلفًا: وزن الكوب المتوقع، وقوة الإمساك اللازمة، ومسار الذراع، ونقطة التوقف. هذه المحاكاة هي النموذج الداخلي الأمامي: يتنبأ بالنتائج الحسية للفعل قبل وصولها، فيصحح الكثير من الأخطاء قبل وقوعها. عند اضطرابه يعمل الجهاز بالتغذية الراجعة وحدها: يتحرك، يرى الخطأ، يصحح — فيخرج الأداء متقطعًا بطيئًا مليئًا بإعادات الضبط، وهي الصورة التي سمّيتَها في درس التناسق «تصحيحًا مفرط التقطع» من باب آخر.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية التخطيط والاستباق وفحصهما — نماذج داخلية وتغذية استباقية", "points": ["استباقية سريعة سلسة وراجعة مراقِبة مصححة.", "إفراط راجعة = بطء وتجزئة؛ وغيابها = سرعة واثقة مخطئة.", "النمطان متعاكسا الشكل والخطة."], "text": {"head": "تغذية استباقية وتغذية راجعة — توازن الجهاز الناضج", "body": "<p>النضج الحركي توازن بين نظامين: تغذية استباقية (feedforward) تنفذ البرنامج المتنبأ به بسرعة وسلاسة، وتغذية راجعة (feedback) تراقب وتصحح الانحرافات الحقيقية. إفراط الاعتماد على الراجعة يجعل الحركة بطيئة وحذرة ومجزأة، وغياب الراجعة عند برنامج خاطئ يجعلها سريعة واثقة ومخطئة حتى الاصطدام. في ملفات التوحد يغلب النمط الأول غالبًا، وترى الثاني عند متعلمين يتحركون اندفاعيًا بسرعات عالية ودقة منخفضة ثابتة. الفحص يحدد النمط المهيمن لأن خطتَيهما متعاكستان: الأول يحتاج أفعالًا متدفقة متكررة حتى يستقر نموذجه، والثاني يحتاج حواجز ومهام دقة بسرعة منخفضة مضبوطة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية التخطيط والاستباق وفحصهما — نماذج داخلية وتغذية استباقية", "points": ["الجديد يستهلك موارد واعية حتى يُخزَّن نموذجه.", "تعب الجديد حقيقي ويتنكر رفضًا وسلوكًا.", "جديد واحد عميق التكرار خير من خمسة رقيقة."], "text": {"head": "لماذا يتعب الجديد صاحبك — كلفة بناء النماذج", "body": "<p>بناء نموذج داخلي لفعل جديد يستهلك انتباهًا وتنفيذيًا عاليًا: كل خطوة واعية، وكل تصحيح مجهد. لهذا يتعب متعلم مضطرب التخطيط من الجديد تعبًا حقيقيًا لا يجده أقرانه، ويظهر التعب سلوكيًا (رفض، تشتت، بحث عن المألوف) فيُقرأ خطأً. ولهذا أيضًا يكون تكرار الفعل الجديد نفسه بأشكال ثابتة هو العلاج الآلي المباشر: كل تكرار ناجح يحوّل جزءًا من الفعل من مراقبة واعية إلى نموذج مخزن، فتتحرر الموارد تدريجيًا. قاعدة الجرعة المنبثقة: جديد واحد في الجلسة بجرعات متكررة خير من خمسة جدد بجرعات رقيقة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية التخطيط والاستباق وفحصهما — نماذج داخلية وتغذية استباقية", "points": ["خمس مجموعات: أدوات جديدة وتسلسلات وتوقع وتوقيت واختزان.", "تسجيل بأنماط الأخطاء الأربعة لا بالنجاح فقط.", "إعادة بعد يومين تقيس بناء النموذج نفسه."], "text": {"head": "شبكة الفحص — أفعال جديدة وأنماط أخطاء", "body": "<p>فحص عملي من خمس مجموعات: (1) أفعال جديدة بأدوات غير مألوفة التركيب (فتح علبة مجهولة الآلية، تركيب لعبة أول مرة)؛ (2) تسلسلات من 2-4 خطوات بأدوات حقيقية (تحضير مشروب، تجهيز حقيبة) مع تسجيل أنماط الأخطاء الأربعة (انقلاب/سقوط/حلقة/توقف)؛ (3) أفعال متوقعة مقابل متغيرة (التقاط كرة متدحرجة ثابتة مقابل مرتدة متغيرة الاتجاه)؛ (4) مهمة توقيت استباقي (إيقاف مؤقت، ضغط عند علامة قادمة)؛ (5) إعادة الفعل نفسه بعد يومين لقياس ما اختزن (فارق الأداء الثاني يقيس بناء النموذج). وتُستكمل بملاحظة انتقالات موثقة. النتيجة وثيقة أنماط لا درجة إجمالية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "آلية التخطيط والاستباق وفحصهما — نماذج داخلية وتغذية استباقية", "points": ["يبتكر حرًا = تقليد؛ ينجح عمليًا = فهم؛ ينجح قصيرًا = تنفيذي.", "مهمة واحدة بأربعة شروط معدلة توزيع سريع.", "التسمية النهائية بعد التوزيع لا قبله."], "text": {"head": "فروق تحمي الحكم — تخطيط أم تقليد أم ذاكرة أم فهم؟", "body": "<p>أربعة أبواب تتنكر توقيع التخطيط: فشل تقليد (يفشل في الجديد لأنه لا ينسخ النموذج، لكنه يبتكر تسلسلًا ناجحًا بطريقته إذا تُرك حرًا)؛ وفشل فهم تعليمات (ينجح كاملًا حين تُعرض المهمة عمليًا بدل الكلام)؛ واضطراب ذاكرة إجرائية ضيقة (ينجح في الجلسة ويبدأ من صفر كل مرة بلا أثر جسدي آخر)؛ وضعف انتباه تنفيذي (ينهار مع طول المهمة وتعدد مشتتاتها وينجح مقصّرًا معزولًا). تمرير مهمة واحدة عبر الشروط الأربعة المعدّلة (حر بلا نموذج، عملي بلا كلام، قصير، معزول) يوزع الاحتمالات توزيعًا عمليًا سريعًا قبل أي تسمية نهائية في الملف.</p><p>ومؤشر أخير في شبكة الفحص يميز النمطين بلا أدوات إطلاقًا: راقب يديه في مهمة جديدة بسيطة عشر ثوانٍ قبل أن يبدأ. صاحب التغذية الراجعة المفرطة يتردد ويجرّب حركات صغيرة متقطعة ويعيد وضع يديه مرارًا قبل الانطلاق الكامل؛ وصاحب النموذج الواثق الخاطئ ينطلق فورًا بكامل الفعل بلا أي تمهيد ثم يصطدم بخطئه. عين مدرّبة على ثواني ما قبل الفعل تقرأ نصف ملف النماذج الداخلية قبل أول مهمة رسمية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ماذا يقيس إعادة الفعل الجديد نفسه بعد يومين في فحص التخطيط، ولماذا لا تكفي جلسة واحدة؟", "الإجابة: يقيس بناء النموذج الداخلي واختزانه: فالأداء الأول يري كلفة البناء الواعي، والثاني بعد يومين يري ما تحوّل من الفعل إلى برنامج مخزن؛ وبجلسة واحدة لا تعرف إن كان فشل متعلمك في البناء الأولي أم في الاختزان — وهما ملفان مختلفان."], "text": null, "take": "آلية الباب نماذج داخلية متنبئة وتوازن تغذية استباقية وراجعة؛ وفحصه أفعال جديدة مضبوطة بأنماط أخطاء موثقة وقياس اختزان — محميًا بفروق أربعة تمنع تسميات متسرعة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 65, "title": "أنشطة التخطيط والاستباق وتوصياتهما — خارجنة الخطة ثم دخلنتها", "intro": "<p>أنشطة وتوصيات لاضطراب التخطيط والاستباق عند المصاب بالتوحد. المبدأ العلاجي المركزي: خارجنة (externalisation) — إخراج الخطة من رأس مضطرب التخطيط إلى العالم المرئي (بطاقات خطوات، نماذج مرسومة، منصات انطلاق) ثم سحب الدعائم تدريجيًا حتى تدخل الخطة رأس صاحبها نموذجًا مخزنًا.</p>", "slides": [{"kind": "cover", "title": "أنشطة التخطيط والاستباق وتوصياتهما — خارجنة الخطة ثم دخلنتها", "sub": "الوحدة الخامسة عشرة: اضطراب التخطيط والاستباق", "goals": ["أن تطبق مبدأ الخارجنة: بطاقات خطوات مرئية ثم سحب تدريجي للدعائم", "أن تطبق بطاقة «نفّذ خطتك المرسومة» بعناصرها العشرة", "أن تقيس الباب بقدرة متعلمك على الجديد غير المدرَّب لا بالمدرب"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act38_img1.webp", "img2": null}, {"kind": "slide", "title": "أنشطة التخطيط والاستباق وتوصياتهما — خارجنة الخطة ثم دخلنتها", "points": ["بطاقات خطوات تُقلب مع الإنجاز خارجنة تنفيذية.", "خطوة أولى صغيرة مضمونة تفتح التسلسل.", "تمثيل «ماذا لو» داخل التدريب قبل حياة الواقع."], "text": {"head": "مبادئ حاكمة — مرئي أولًا، وخطوة أولى مقسومة، وجديد واحد", "body": "<p>أربعة مبادئ. أولًا: كل تسلسل يُدرَّب يُعرَض خارجيًا أولًا: بطاقات صور للخطوات بترتيبها تُراجع قبل البدء وتُقلب كلما أُنجزت خطوة — فتتحول ذاكرة العمل التنفيذية إلى نظر بسيط. ثانيًا: قسّم الخطوة الأولى دائمًا: أصعب لحظة هي الانطلاق (درس التحضير)، فاجعل الخطوة الأولى صغيرة مضمونة النجاح تفتح بقية التسلسل. ثالثًا: جديد واحد عميق: مهارة جديدة واحدة تُكرر بأشكال قريبة حتى تخزَّن، قبل فتح جديد آخر. رابعًا: علّم «ماذا لو» قبل وقوعه: خطوة ناقصة أو أداة مفقودة تُمثَّل داخل التدريب لعبةً، فلا تصير في الحياة توقفًا كاملًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التخطيط والاستباق وتوصياتهما — خارجنة الخطة ثم دخلنتها", "points": ["ألبومات خطوات في مواضع الاستعمال الحقيقية.", "بالونات بطيئة تبني زمن تجهيز رحيمًا.", "جسر حسي قصير بين النشاطين أداة انتقال."], "text": {"head": "ترسانة بحسب الحاجة", "body": "<p>لبناء التسلسلات: ألبومات خطوات مصورة لمهارات حقيقية (غسل يدين كامل، تحضير حقيبة، صنع مشروب) تُستعمل في مواضعها الحقيقية لا على الطاولة فقط. للاستباق الوضعي والحركي: ألعاب إمساك متدرجة التوقع (كرات متدحرجة بسرعات ثابتة ثم متغيرة، بالونات بطيئة الطيران تبني زمن تجهيز رحيمًا)، ومهام حمل ثنائية مصممة (صينية بيدين، حمل مشترك مع شريك). للانتقالات: عدّادات إنذار بصرية ومؤقتات، وبطاقة «بعد قليل» بصورة النشاطين، وجسر حسي قصير بين النشاطين (حركة قوية محببة 30 ثانية) يعيد ضبط الجهاز للبرنامج الجديد.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التخطيط والاستباق وتوصياتهما — خارجنة الخطة ثم دخلنتها", "points": ["هدف مركب: ترتيب بطاقات وتنفيذ وسحب دعائم.", "طارئ مدروس داخل التدريب لا مفاجأة حياة.", "القياس بأنماط أخطاء الباب لا بالنجاح الكلي."], "text": {"head": "بطاقة نشاط كاملة — «نفّذ خطتك المرسومة»", "body": "<p>المجال: التخطيط الحركي — بناء تسلسل وتنفيذه (براكسيا فكرية). الهدف القابل للقياس: أن يبني المتعلم من بطاقات مصورة خطة تسلسل من 4 خطوات لتحضير مشروب لعبة (كأس، إبريق ماء، ملعقة، مسحوق لعبة)، يرتبها صحيحًا، ثم ينفذها بلا خطأ ترتيب ودون سقوط خطوة، في 4 من 5 محاولات، ثم بثلاث بطاقات فقط (خطوة تُستحضر ذهنيًا). الأدوات: بطاقات الخطوات الأربع مرسومة، أدوات حقيقية آمنة، طاولة بمساحة عمل محددة. الإعداد: عرض النموذج الكامل مرة واحدة فيزيائيًا في البداية. الخطوات: ترتيب بطاقات ثم تنفيذ بمرافقة البطاقات، ثم تنفيذ والبطاقات مقلوبة (تُكشف عند الحاجة فقط)، ثم بطاقة ناقصة خطوة يسميها قبل التنفيذ. التدرج: تسلسل 5-6 خطوات، ثم مهمة بطارئ مدروس (أداة مفقودة يبحث عن بديلها)، ثم مهام حياتية أخرى بالمنهج نفسه. التنويع: نقل المنهج إلى مهمة بيتية واحدة يتفق عليها مع الأهل. الأمان: أدوات آمنة العمر، وماء فاتر فقط، وإشراف دائم. التكرار: 3 مرات أسبوعيًا 6 أسابيع. القياس: أخطاء الترتيب بأنماطها، وخطوات ساقطة، ونسبة احتياج كشف البطاقات. مؤشر النجاح: بلوغ الهدف ببطاقة ناقصة، ثم تسلسل جديد بالمنهج نفسه بمحاولتين فقط.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التخطيط والاستباق وتوصياتهما — خارجنة الخطة ثم دخلنتها", "points": ["مؤشر ذهبي: محاولات أقل لإتقان جديد غير مدرب.", "مدربات تتحسن بلا جديد = مهارات لا تخطيط.", "تنويع منهجي صغير داخل المهارة يبني النماذج."], "text": {"head": "القياس والمتابعة — الجدة نفسها تُقاس بالجرعات", "body": "<p>يُقاس تقدم الباب باتجاهين متعاكسين ظاهريًا: مهارات مدربة تصير أسرع وأقل أخطاء (اختزان ينجح)، وقدرة على الجديد تتحسن (محاولات أقل لإتقان مهارة جديدة لم تُدرَّب — المؤشر الذهبي للباب). وسجل الانتقالات البيتي والمدرسي عددًا أسبوعيًا مؤشر حياة مرافق إلزامي. قاعدة القرار: إن تحسنت المدربات ولم يتحسن أي جديد بعد ثمانية أسابيع، فالتدريب يبني مهارات لا تخطيطًا — أدخل تنويعًا منهجيًا (تغييرات صغيرة مخططة داخل المهارة نفسها كل أسبوع) لتدريب بناء النماذج لا حفظها. ووثّق كل مهارة مخزنة بصورتها وبطاقتها؛ ألبوم «خططي المنجزة» وقود دافعية وسجل تقدم في وثيقة واحدة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أنشطة التخطيط والاستباق وتوصياتهما — خارجنة الخطة ثم دخلنتها", "points": ["قوائم خطوات قبل الشروع في كل مهمة مركبة.", "مهارة بيتية جديدة واحدة كل أسبوعين باتفاق مكتوب.", "أدوار رياضية متوقعة قبل الحرة المتغيرة."], "text": {"head": "توصيات واجهة — بيئات صديقة للتخطيط", "body": "<p>اضبط ثلاث واجهات على ميزان هذا الباب. في الصف: جدول يومي مرئي بتسلسله الحقيقي، ومهام مركبة تُقدَّم دائمًا قائمة خطوات مكتوبة/مصورة قبل الشروع، وانتقالات بإنذارين (قبل 5 دقائق وقبل دقيقة). في البيت: روتينات صباح ومساء ببطاقات خطوات ثابتة في أماكن استعمالها، ومهارة جديدة واحدة فقط في كل أسبوعين تُتفق عليها كتابة. وفي الأنشطة الرياضية الجماعية: أدوار متوقعة التسلسل أولًا (تمرير ثابت الاتجاه) قبل الأدوار الحرة المتغيرة حتى لا تُدفع كلفة الاستباق والاجتماع معًا من أول يوم.</p><p>وتذكّر أن منصات الانطلاق ليست للأطفال فقط داخل هذا الباب: معلم يبدأ كل نشاط بإشارة بصرية ثابتة وعدّ تنازلي مرئي وخطوة أولى معلنة يبني منصة انطلاق صفية جماعية يستفيد منها صاحب التحضير المضطرب دون أن يُفرد بأي إجراء مرئي مختلف. كثير من تعديلات هذا الباب تنجح صفّيًا بالصيغة العامة نفسها التي درسها باب التعديلات: فردي الحاجة، عام التقديم، خفي البصمة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يُعدّ تحسّن إتقان الجديد غير المدرَّب المؤشر الذهبي لتقدم خطة هذا الباب؟", "الإجابة: لأنه يثبت أن ما بُني هو قدرة التخطيط نفسها (بناء نماذج داخلية جديدة) لا مجرد حفظ مهارات بعينها؛ فالمدربات تتحسن بالتكرار حتى عند من لا يتحسن تخطيطه، أما انخفاض كلفة تعلم الجديد فلا يحدث إلا إذا نمت الآلية المستهدفة ذاتها."], "text": null, "take": "أنشطة التخطيط والاستباق خارجنة بصرية للخطوات ومنصات انطلاق وجرعات عميقة لجديد واحد، تُسحب دعائمها حتى تُختزن نماذج — وتُقاس بالقدرة على الجديد لا بالمدرب وحده.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 66, "title": "لماذا التعديل جزء من القياس والعلاج لا استثناء منهما", "intro": "<p>التعديلات (aménagements) هي تغييرات مقصودة وموثقة في ظروف الجلسة والتقييم — مكان وزمان وتعليمات وأدوات ومرافقة — تُدخل لتُظهر قدرات المتعلم الحقيقية بدل أن تقيسها ظروفه المعادية. كثير من المختصين يعدّونها «تسهيلات» تُضعف صدق القياس؛ وعيادة التوحد النفسية الحركية تثبت العكس منهجيًا. في هذا الدرس تبني فلسفة التعديل وقواعده الحاكمة قبل تفاصيله.</p>", "slides": [{"kind": "cover", "title": "لماذا التعديل جزء من القياس والعلاج لا استثناء منهما", "sub": "الوحدة السادسة عشرة: طبقة التعديلات: تهيئة الجلسة والتقييم", "goals": ["أن تشرح التعديل إزالةَ ضجيج من القياس لا تسهيلًا لنتيجته", "أن تميّز منطق تعديلات الفحص عن منطق تعديلات العلاج", "أن توثق كل تعديلة بحقولها الثلاثة: ماهية وسبب ومصير"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l66.jpg", "img2": null}, {"kind": "slide", "title": "لماذا التعديل جزء من القياس والعلاج لا استثناء منهما", "points": ["بلا تعديل تقيس الفهم والحساسية والتخمين لا الحركة.", "التعديل إزالة ضجيج من آلة القياس لا تسهيل نتيجته.", "قدرة تظهر بالتعديل قدرة حقيقية قابلة للبناء."], "text": {"head": "صدق بيئي — ماذا تقيس فعلًا حين لا تعدّل؟", "body": "<p>اختبار يُدار على متعلم لا يفهم تعليماته ولا يحتمل بيئته ولا يرى بنيته لا يقيس قدرته الحركية؛ يقيس فهمه وحساسيته وتخمينه. التعديل هنا ليس رشوة للمتعلم بل إزالة ضجيج من آلة القياس: تعليمة مبسّطة ومقسومة، وعرض عملي بدل كلام، ومقعد يستقر عليه ليرى النموذج — كلها تعيد سؤال الفحص إلى موضعه: «ماذا يستطيع جسدك» بدل «ماذا تستطيع في غرفتي كما هي». والقدرة التي تظهر بالتعديل قدرة حقيقية يملكها المتعلم ويستطيع البناء عليها، بينما «العجز» الظاهر بلا تعديل قد يكون وهمًا إجرائيًا خطيرًا يُبنى عليه ملف كامل.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "لماذا التعديل جزء من القياس والعلاج لا استثناء منهما", "points": ["فحص: تعديل وصول موثق وبنود ثابتة ما أمكن.", "علاج: تعديلات بناء تُدرَّج وتُسحب داخل الخطة.", "وثّق منطق اللحظة قبل أي تعديلة."], "text": {"head": "تعديلان لا تعديل واحد — للفحص وللعلاج منطقان", "body": "<p>تفترق تعديلات الفحص عن تعديلات العلاج افتراق الغايات: في الفحص تُدخل تعديلات الوصول (أن يفهم ويحتمل ويرى) مع تثبيت بنود القياس نفسها ما أمكن، وتُوثق كل تعديلة بدقة ليعرف قارئ نتيجتك أي نسخة من الاختبار قستَ بها. أما في العلاج فالتعديلات أدوات بناء تُدرَّج وتُسحب كجزء من الخطة (مرافقة تتلاشى، بنية تخف، دعائم تُستبدل بمهارات). خلط المنطقين ينتج فحوصًا «علاجية» لا تُقارن وعلاجات «فحصية» لا تُدرِّج. القاعدة: وثّق في أي منطق أنت الآن قبل أن تعدّل أي شيء.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "لماذا التعديل جزء من القياس والعلاج لا استثناء منهما", "points": ["المهمة المقاسة نفسها لا تُمسّ بما يغيّر مفهومها.", "إخفاء تعديل عن التقرير تزوير لا حماية.", "ثلاثة حقول لكل تعديلة: ماهية وسبب ومصير."], "text": {"head": "حدود التعديل — ما لا يُمسّ وما يجب التصريح به", "body": "<p>للتعديل حدود صدق صارمة: لا تُعدَّل المهمة المقاسة نفسها بما يغيّر ما تقيسه (لا تمسك الكرة عنه في بند التقاط)، ولا تُخفى التعديلات عن تقريرك بحجة حماية المتعلم (إخفاؤها تزوير مهني)، ولا تتحول التعديلات المؤقتة إلى بيئة أبدية بلا خطة سحب أو تثبيت واعٍ. وكل تعديلة تملك في ملفك ثلاثة حقول: ما هي، ولماذا (أي عائق أزالت)، وما مصيرها (تُسحب متى/تثبت لماذا). تعديلة بلا الحقول الثلاثة ليست قرارًا مهنيًا بل عادة تسللت إلى ممارستك دون أن تلاحظ.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "لماذا التعديل جزء من القياس والعلاج لا استثناء منهما", "points": ["الجواب بالمنهج: بلا تعديل تقيس العوائق لا القدرات.", "توثيق يجعل القياس قابلًا للتفسير والتكرار.", "تعديل معلن مفسَّر علامة نضج لا ضعف."], "text": {"head": "التعديل قرار يُدافَع عنه علميًا", "body": "<p>حين يسألك معلم أو ولي أو زميل «أليست هذه تسهيلات تبطل القياس؟» يكون جوابك جاهزًا بالمنهج لا بالانفعال: القياس بلا تعديل عند هذا المتعلم يقيس عوائقه لا قدراته (تسمي العائق موثقًا)، والتعديل الموثق يجعل القياس قابلًا للتفسير والمقارنة عبر الزمن بالشروط نفسها، والأدبيات والعيادات المؤسسة لإطارنا اعتمدت هذا المنطق في تقييماتها نفسها. المختص الواثق لا يخجل من تعديلاته ولا يتباهى بها؛ يوثقها ويفسرها ويراجعها — وهي علامة نضج مهني لا اعتراف ضعف.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "لماذا التعديل جزء من القياس والعلاج لا استثناء منهما", "points": ["رفض مطلق يبني عجزًا وهميًا، وإفراط يقيس نسختك.", "الميزان: عدّل الوصول لا المهمة، ووثّق واسحب.", "الميزان نفسه يُراجَع كلما تبدل المتعلم."], "text": {"head": "أين يخطئ الرافضون والمفرطون", "body": "<p>يرتكب الطرفان خطأين متقابلين: رافض للتعديلات باسم «الصرامة» يبني ملفات عجز وهمية ويحكم على أطفال بقدرات لم تُقَس أصلًا؛ ومفرط يحوّل كل موقف إلى نسخة مبسطة حتى يقيس نسخَته هو لا المتعلم، وينزع عن أنشطته كل احتكاك بنّاء. الوسط المهني قابل للتعليم والمراجعة: عدّل الوصول لا المهمة، ووثّق كل شيء، واسحب في العلاج ما لا يلزم، وثبّت في الفحص ما وثّقته لتُعيد القياس بشروطه. وبهذا الميزان ستدير دروس هذه الوحدة الثلاثة المقبلة: فضاء وزمانًا، وعلاقة وتعزيزًا، ومواقف خاصة وتوثيقًا.</p><p>ولهذه الفلسفة ثمرة تربوية تتجاوز الجلسة: متعلم يعيش سنوات تعليمه في بيئات معدّلة بوعي يتعلم ضمنيًا أن العالم قابل للضبط وأن طلب التعديل حق مهني له في كبره، لا ضعفًا يُخفى. وأنت حين تعلّم أهله ومعلميه لغة التعديلات وأسبابها تزرع حوله فريقًا يفكر بالشروط قبل الأحكام — وهو أبقى ما تتركه لمتعلمك بعد انتهاء خططك كلها.</p><p>وتُروى في أدبيات الباب صورة معكوسة تحذيرية: متعلمون قُدّموا في تقارير رسمية بوصفهم «غير قابلين للفحص» لأن شروط فحصهم القياسية لم تُعدَّل، ثم ظهرت ببضعة تعديلات موثقة قدرات كاملة أهلتهم لمسارات تعليمية مختلفة كليًا. بين التقريرين لم يتغير المتعلم أبدًا؛ تغيرت عدسة القياس وحدها — وهذا هو الدرس الذي يجب ألا يُنسى في أي ملف تقف فيه أمام حكم «غير قابل».</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الفرق الجوهري بين تعديلات الفحص وتعديلات العلاج في المنطق والتوثيق؟", "الإجابة: تعديلات الفحص تُدخل للوصول (فهم واحتمال ورؤية) مع تثبيت بنود القياس وتوثيق دقيق يجعل النتيجة قابلة للتفسير والتكرار بالشروط نفسها؛ أما تعديلات العلاج فأدوات بناء داخل الخطة تُدرَّج وتُسحب عمدًا مع تقدم المهارة — خلطهما يفسد قابلية المقارنة وسحب الدعائم معًا."], "text": null, "take": "التعديلات إزالة ضجيج منهجية تُظهر القدرات لا تصنعها؛ لها منطقا فحص وعلاج متميزان، وحدود صدق صارمة، وتوثيق بثلاثة حقول — وهي علامة نضج المختص لا ضعفه.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 67, "title": "تعديلات المكان والزمان والأدوات والتعليمات", "intro": "<p>تعديلات عملية في أربعة أبعاد قابلة للتطبيق غدًا: فضاء الجلسة يُنظَّم بصريًا حتى يقرأه المتعلم وحده، وزمانها يُقطَّع مرئيًا حتى يتوقعه، وأدواتها تُختار لحواسه لا لعينيك، وتعليماتها تُثبَّت صياغيًا حتى لا ترتد عليه. في هذا الدرس تفاصيل كل بُعد بمعاييره وقواعده المأخوذة من ممارسة تقييمات التوحد المؤسسة.</p>", "slides": [{"kind": "cover", "title": "تعديلات المكان والزمان والأدوات والتعليمات", "sub": "الوحدة السادسة عشرة: طبقة التعديلات: تهيئة الجلسة والتقييم", "goals": ["أن تنظّم فضاء جلستك وزمانها بعلامات وجداول مرئية تتكلم وحدها", "أن تصوغ تعليمات ثابتة بلا مرادفات مع زمن كمون محترم", "أن تطبق قاعدة التدريج المزدوج: لا رفع للمهمة وشروطها معًا"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act99_img1.webp", "img2": null}, {"kind": "slide", "title": "تعديلات المكان والزمان والأدوات والتعليمات", "points": ["علامة موضع وصندوق انتهاء ومسار معلّم.", "تصفية مشتتات بحسب خريطة المتعلم الحسية.", "النجاح: تنقل شبه مستقل عن التوجيه اللفظي."], "text": {"head": "الفضاء المنظم — علامات تتكلم بدل الكلام", "body": "<p>يُنظَّم فضاء العمل حتى يجيب عن أسئلة المتعلم الصامتة: أين أقف؟ (علامة أرضية، طوق، حصيرة — موضع جسدي مرئي)؛ أين ينتهي ما أنجزته؟ (صندوق «انتهى» boîte «fini» تُودع فيه الأداة أو البطاقة بعد كل نشاط فتصير نهاية كل مهمة محسوسة)؛ وما مساري؟ (أطواق أو علامات على المسار نفسه عند الحاجة). وتُصفّى البيئة من المشتتات البصرية والصوتية عند أصحاب التشويش الحسي (جدران أهدأ، أدوات غير المستعملة خارج النظر، خفض صدى). معيار نجاح التنظيم: متعلم يتنقل في جلستك شبه مستقل عن توجيهاتك اللفظية بعد جلستين أو ثلاث.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تعديلات المكان والزمان والأدوات والتعليمات", "points": ["جدول مرئي كامل اليوم يُشطب تدريجيًا.", "شكل الجدول يُفحص ملاءمة لمستوى الفهم.", "غموض زمني يُدفع من رصيد الانتباه الحركي."], "text": {"head": "الزمان المرئي — جدول يراه قبل أن يعيشه", "body": "<p>يُبنى زمن الجلسة مرئيًا: جدول أنشطة مصور أو مرسوم بالرموز بترتيب اليوم كله يُراجع عند الدخول، وتُشطب أو تُقلب كل وحدة عند إتمامها، ومؤقت مرئي لمدد الانتظار والمهام الطويلة. في تقييمات الإطار المؤسس لهذا الباب التزم بعض المتعلمين بالجدول المرئي التزامًا غيّر أداءهم كليًا بينما لم ينفع آخرين من ذوي الفهم الأدنى — فالقاعدة أن الجدول نفسه يُفحص ملاءمةً (رموز؟ صور؟ أشياء حقيقية مصغرة؟ كلمات؟) ولا يُفرض شكله الأعلى تجريدًا على الجميع. الزمان المتوقع زمان آمن، وكل دقيقة غموض زمني تُدفع من رصيد انتباه المتعلم الحركي.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تعديلات المكان والزمان والأدوات والتعليمات", "points": ["مواصفة الأدوات: حواس المتعلم وقوته وضبطه.", "أداة واحدة حاضرة عند أصحاب التشتت.", "سجل أدوات فردي يتراكم عبر الجلسات."], "text": {"head": "الأدوات المعدّلة — حواس المتعلم هي المواصفة", "body": "<p>تُختار الأدوات وتُعدَّل بمواصفة حواس متعلمك وقدراته: مقابض أسمك وأثقل لمن ضبط قوته ضعيف، وأسطح مضادة للانزلاق، وكرات بأحجام وملمس متنوع تجريبي، وحبال وخطوط أرضية بعرض واضح. وتُقدَّم الأدوات واحدة في كل مرة (الأداة الحالية فقط على الطاولة) عند أصحاب التشتت، وتُستبدل الأدوات المنفّرة لمسيًا ببدائل من المادة نفسها بوظيفة أهدأ قبل إعلان «لا يحتمل النشاط». وسجل أدوات خاص بكل متعلم يُبنى عبر الجلسات (ما قُبل، ما رُفض ولماذا) حتى لا تعيد اكتشاف حواسه كل شهر.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تعديلات المكان والزمان والأدوات والتعليمات", "points": ["صياغة واحدة بلا مرادفات لكل نشاط دائمًا.", "قصيرة مقسومة وواحدة كل مرة مع عرض ثابت.", "زمن كمون صامت قبل أي تكرار أو مساعدة."], "text": {"head": "التعليمات الثابتة — صياغة واحدة لا ترتد", "body": "<p>قاعدة التعليمات الذهبية من ممارسة الباب: تعليمة واحدة ثابتة الصياغة لكل نشاط، بلا مرادفات (sans synonymes) — فحين تقول اليوم «قفز» وغدًا «نطّ» وبعده «اثب» أنت عند صاحب الفهم الحرفي أمام ثلاث مهام مختلفة. تُبنى التعليمات قصيرة، مقسومة خطوة خطوة، واحدة في كل مرة، مصحوبة عند الحاجة بعرض عملي أو إيماءة ثابتة مرافقة تصير جزءًا من التعليمة نفسها. وتُترك بعد كل تعليمة فترة كمون (temps de latence) صامتة محسوبة قبل أي تكرار أو مساعدة — فكثير من «لا يستجيب» هو في الحقيقة «لم يُمنح زمن المعالجة بعد»، والتكرار المتعجل يقطع معالجته في منتصفها ويعلّمه أن ينتظر تكرارك بدل أن يعالج.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تعديلات المكان والزمان والأدوات والتعليمات", "points": ["بعدان: مهمة وشروط لا يُرفعان معًا أبدًا.", "انتقال بيئي أصعب يعوَّض بخفض مهمة درجة.", "جدول تعديلات مكتوب درع ضد الرفع المزدوج العفوي."], "text": {"head": "التدريج المزدوج — صعوبة المهمة وصعوبة الشروط معًا", "body": "<p>عند تعديل نشاط قائم وازن بُعدين منفصلين: صعوبة المهمة ذاتها (مسافة، سرعة، دقة، خطوات) وصعوبة شروطها (ضجيج، جمهور، زمن، تعليمات كلامية). القاعدة العملية: لا ترفعهما معًا أبدًا؛ فحين تنتقل بمهارة مستقرة إلى بيئة أصعب، اخفض صعوبة المهمة درجة تعويضًا، وحين ترفع صعوبة المهمة ثبّت الشروط في أهدأ صورها. أغلب «انتكاسات» الأنشطة المعدّلة ليست تراجع مهارة بل رفع مزدوج غير مقصود وقع في يوم واحد. جدول تعديلات مكتوب لكل نشاط رئيسي عندك يمنع الرفع المزدوج من الحدوث أصلًا.</p><p>وأضف إلى سجل أدواتك عمود مراجعة موسمي: فأدوات تُقبل في الشتاء (قفاز، قبعة نشاط) قد تُرفض في الصيف حرارةً، وملمس محبوب قد ينقلب بعد مرض أو تجربة سيئة واحدة. سجل بلا مراجعة يحوّل معرفتك الحية إلى أرشيف ميت توجه به متعلمًا لم يعد موجودًا؛ فعدّ مراجعة سجل الأدوات والشروط المقبولة ربعَ سنوية بندًا في جدول ملفك كمراجعة الخطة تمامًا وبنفس الجدية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا تُمنع المرادفات في تعليمات أنشطة أصحاب التوحد رغم أنها تثري اللغة عند غيرهم؟", "الإجابة: لأن صاحب الفهم الحرفي يقرأ كل صياغة جديدة مهمة جديدة؛ فتعدد المرادفات يضاعف عبء الفهم قبل أي عبء حركي ويشتت المعالجة، بينما الصياغة الواحدة الثابتة تتحول بسرعة إلى إشارة معروفة تطلق الفعل ويُبنى إثراء اللغة في مواضع أخرى غير تعليمات الأداء."], "text": null, "take": "تعديلات الأبعاد الأربعة: فضاء يتكلم بعلاماته، وزمان يُرى قبل أن يُعاش، وأدوات بمواصفة الحواس، وتعليمات ثابتة بلا مرادفات مع زمن كمون — وتدريج مزدوج لا يرفع المهمة وشروطها معًا.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 68, "title": "تعديلات العلاقة والتعزيز والمرافقة — الإنسان جزء من البيئة", "intro": "<p>أنت نفسك — موضعك وصوتك ويدك وتوقعاتك — جزء من بيئة جلستك، وقابل للتعديل كأي بُعد آخر. في هذا الدرس تعديلات العلاقة العلاجية أثناء التقييم والتدريب: مرافقة جسدية تُبنى وتتلاشى بمنهج، وتعزيز ثابت لا يهتز مع مزاجك، وقراءة مهنية لحالات المتعلم تقرر متى تتقدم ومتى توقف.</p>", "slides": [{"kind": "cover", "title": "تعديلات العلاقة والتعزيز والمرافقة — الإنسان جزء من البيئة", "sub": "الوحدة السادسة عشرة: طبقة التعديلات: تهيئة الجلسة والتقييم", "goals": ["أن تدير مرافقتك الجسدية بخطة تلاشٍ مكتوبة من اليوم الأول", "أن تهندس حضورك موضعًا وصوتًا وتعزيزًا ثابت الجرعة", "أن تقرأ حالات متعلمك بمناطق إتاحة وإشباع وإغراق وتتصرف بمعاييرها"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l68.jpg", "img2": null}, {"kind": "slide", "title": "تعديلات العلاقة والتعزيز والمرافقة — الإنسان جزء من البيئة", "points": ["أقوى إيصال للفهم وأخطر استمرارًا — تلاشٍ من اليوم الأول.", "سلّم خمس درجات من اللمس الكامل إلى الغياب.", "قبولها أو رفضها بيانات ملف تُوثق فورًا."], "text": {"head": "المرافقة الجسدية — توجيه يحمل زمن تلاشٍ", "body": "<p>التوجيه الجسدي (guidage physique) — يدك ترافق حركة المتعلم ليحسها من جسده — أقوى قنوات إيصال الفهم وأخطرها إن استمرت: تُستعمل لتثبيت فهم مهمة أو إتمام محاولة أولى كاملة، وتولد معها خطة تلاشٍ مكتوبة من أول يوم: مرافقة كاملة ← جزئية (لمسة عند مفصل) ← ظلّ قريب بلا لمس ← إيماءة ← غياب. بعض المتعلمين يقبلونه بامتنان ويبنون عليه بسرعة، وآخرون يرفضونه جسديًا كليًا — فالقبول نفسه بيانات تُوثق، والبديل عند الرفض نماذج بصرية ومرافقة أدوات. مرافقة بلا خطة تلاشٍ تتحول في أسابيع إلى عادة اعتماد يصعب فكّها أكثر من المهارة نفسها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تعديلات العلاقة والتعزيز والمرافقة — الإنسان جزء من البيئة", "points": ["موضع بحسب هدف النشاط لا بحسب عادتك.", "صوت ثابت الحجم والنبرة جزء من ثبات البيئة.", "كل دعم أثناء قياس يُسجَّل تعديلة موثقة."], "text": {"head": "موضعك وصوتك — هندسة حضور المختص", "body": "<p>عدّل حضورك كأداة: اجلس حيث يجب أن ينظر (أمامًا لتقليد، جانبًا لمرافقة، خلفًا لاستقلالية)، واخفض مستوى عينيك لمستواه في الأنشطة الأرضية، وثبّت نبرة صوتك وحجمه عبر الجلسات (صوتك جزء من ثبات البيئة عنده)، ورتّب انتظارك — فمختص يقف فوق متعلم منتظرًا بضغط جسدي صامت يرفع إثارة الغرفة كلها. وفي التقييم تحديدًا: محاولاتك التشجيعية المتحمسة قد تعلّم أثناء القياس؛ حافظ على حياد دافئ ثابت، وسجّل أي دعم لفظي قدمته ضمن تعديلات الجلسة لا كأنه لم يحدث.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تعديلات العلاقة والتعزيز والمرافقة — الإنسان جزء من البيئة", "points": ["نوع وتوقيت ثابتان متوقعان عبر الجلسات.", "عشوائية التعزيز تحوّل انتباهه إليك بدل مهمته.", "جرعته تُصمم وتُراجع كجرعة نشاط تمامًا."], "text": {"head": "التعزيز الثابت — توقع لا يفاجئ", "body": "<p>يُبنى التعزيز في جلستك ثابتًا متوقعًا (renforcement constant): نوع معروف للمتعلم (لفظي بصيغة واحدة، أو شيئي، أو نشاطي قصير)، يأتي عند إتمام وحدات واضحة، ولا يتغير نوعه ولا توقيته بتقلب مزاج الجلسة. أهميته عند التوحد مضاعفة: الثبات نفسه جزء من أمان العالم، والتعزيز المتقطع العشوائي يتحول عند أصحاب القلق إلى مصدر مراقبة دائمة لك بدل مراقبة المهمة. وفي المقابل يُحذر من التعزيز المفرط الكثافة الذي يبتلع زمن النشاط ويفكك تسلسله؛ فجرعته تُصمم كما تُصمم جرعات الأنشطة: نوعًا وتوقيتًا وكثافة، وتُراجع عند كل مراجعة خطة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تعديلات العلاقة والتعزيز والمرافقة — الإنسان جزء من البيئة", "points": ["ثلاث مناطق قراءة: إتاحة وإشباع وإغراق بمعايير مرئية.", "إكمال فوق إغراق يخسر الجلسات المقبلة.", "الإيقاف الموثق قرار علاجي لا انسحاب."], "text": {"head": "قراءة الحالة أثناء الجلسة — تقدم وتوقف بمعايير", "body": "<p>عدّل إيقاع جلستك بقراءة مستمرة لحالة متعلمك: مؤشرات إتاحة (انتباه متاح، جسد مستقر، قبول للتعليمات) خضراء للتقدم؛ ومؤشرات إشباع (تململ متصاعد، نمطيات تتكاثف، نظرات هاربة، تعرق وانفعال) صفراء للإبطاء أو تغيير القناة؛ ومؤشرات إغراق (بكاء، انسحاب جسدي، تصعيد) حمراء للإيقاف المحترم أو التحول لنشاط تنظيمي. المختص الذي يكمل «برنامج اليوم» فوق إغراق موثق يخسر جلستين قادمتين من أجل نصف نشاط. وسجّل في محضر جلستك متى أوقفت ولماذا؛ فالإيقاف الموثق قرار علاجي يُدافَع عنه، بينما إكمال منهك بلا توثيق هو الضعف الحقيقي.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تعديلات العلاقة والتعزيز والمرافقة — الإنسان جزء من البيئة", "points": ["موضع ودور وتعليمات لا-تفعل مكتوبة لكل حاضر.", "صوت ثانٍ فوق صوتك متغير غير موثق يفسد القياس.", "مرافق مُدار قناة تعميم أولى للبيت."], "text": {"head": "العمل مع المرافقين — اليد الثانية المدروسة", "body": "<p>حين يحضر مرافق أو ولي أو زميل داخل جلستك، يتحول حضوره هو الآخر إلى بُعد تعديل يُدار: موضع محدد لا يتجول، ودور مكتوب (مراقب صامت، شريك لعبة في جزء محدد، متلقّي مهارات البيت في الختام)، وتعليمات صريحة بما لا يفعله (لا يعيد التعليمات بصوته فوق صوتك، لا يساعد جسديًا إلا بطلبك). المرافق غير المُدار أسرع مفسدات الجلسات التقييمية رغم حسن نيته، لأنه يضيف قناة تعليمات ثانية ومتغيرات غير موثقة. وفي المقابل مرافق مُدار جيدًا هو قناة التعميم الأولى لمهارات بيت متعلمك.</p><p>ومن أخطاء المرافقة الخفية التي لا يلتقطها المبتدئ: مرافقة زائدة الدقة — يد تضبط كل ملليمتر حتى يصير أداء المتعلم أداءَ يديك متنكرًا في يديه، وتنهار المهارة فور غيابك كأنها لم تُبنَ. علامتها التحذيرية أن نسب نجاحه معك وبدونك تتطابق شعوريًا في محاضرك بينما تعرف في قرارة خبرتك أن حضورك هو نصف المهارة. العلاج وقائي: جرّب فك المرافقة تجريبيًا كل جلستين ولو لدقائق، وسجّل «أداء الاستقلال» بندًا منفصلًا لا يلتبس بأداء المرافقة أبدًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا تولد المرافقة الجسدية مع خطة تلاشيها في اليوم نفسه لا حين «يستقر الأداء»؟", "الإجابة: لأن المرافقة بلا أفق سحب تتحول بسرعة إلى اعتماد بنيوي يصعب فكّه أكثر من بناء المهارة نفسها؛ فخطة التلاشي المكتوبة من البداية تجعل كل مستوى مرافقة مؤقتًا بمعايير انتقال واضحة، وتحمي الاستقلالية التي هي غاية التدخل أصلًا."], "text": null, "take": "العلاقة بُعد تعديل كامل: مرافقة جسدية بتلاشٍ مكتوب، وحضور مهندس الموضع والصوت، وتعزيز ثابت الجرعة، وقراءة حالات بثلاث مناطق، ومرافقون يُدارون كجزء من البيئة لا كجمهور.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 69, "title": "تعديلات المواقف الخاصة وتوثيقها — حين تنكسر الشروط القياسية", "intro": "<p>تُختبر منظومة التعديلات حين تنكسر الشروط القياسية: متعلم جديد لا تعرفه، وجلسة أولى بلا خريطة، وموقف جماعي صفي لا تملكه، ويوم انهارت فيه خطة التعديلات كلها. في هذا الدرس تدير المواقف الخاصة بقواعد ثابتة، وتختم بمنظومة توثيق تجعل تعديلاتك قابلة للنقل والمحاسبة والمتابعة عبر الزمن والأشخاص.</p>", "slides": [{"kind": "cover", "title": "تعديلات المواقف الخاصة وتوثيقها — حين تنكسر الشروط القياسية", "sub": "الوحدة السادسة عشرة: طبقة التعديلات: تهيئة الجلسة والتقييم", "goals": ["أن تدير جلسة أولى ومواقف صفية وبروتوكول إنقاذ جلسة منهارة", "أن تبني سجل تعديلات من ستة حقول يسافر مع المتعلم", "أن تحوّل نشاطًا قياسيًا إلى نسخة معدّلة كاملة بُعدًا بُعدًا"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l69.jpg", "img2": null}, {"kind": "slide", "title": "تعديلات المواقف الخاصة وتوثيقها — حين تنكسر الشروط القياسية", "points": ["شروط أخفّ وملاحظة أوسع عند غياب الخريطة.", "استجابات الجلسة الأولى بيانات تأسيس موثقة.", "«مستواه الحقيقي» بشروطك قد يكون مستوى شروطك فقط."], "text": {"head": "الجلسة الأولى ومتعلم لا تعرفه — تعديل استكشافي مضبوط", "body": "<p>حين لا تملك خريطة بعد، تعمل بقاعدة «أخفّ الشروط وأوسع الملاحظة»: بيئة هادئة مصفّاة، وأنشطة قصيرة متتابعة متنوعة القنوات، وتعليمات بأكثر من قناة معًا (كلام + عرض + إيماءة)، ومرافقة عند الطلب فقط. وكل استجابة في الجلسة الأولى بيانات تعديل مؤسِّسة: ما الذي فُهم وبأي قناة؟ أين تشتت وبأي محفز؟ ما الذي قُبل جسديًا؟ تُبنى منها خطة التعديلات الأولية للجلسات المقبلة مكتوبة قبل مغادرته. والخطأ المقابل المألوف: جلسة أولى بشروطك القياسية «لنرى مستواه الحقيقي» تنتهي غالبًا بأنك رأيت مستوى شروطك لا مستواه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تعديلات المواقف الخاصة وتوثيقها — حين تنكسر الشروط القياسية", "points": ["تعديل عام النفع يخفي الفردي داخل العادي.", "أدوات مضبوطة بشكل عادي التقديم على الطاولة.", "عزل مبرر يُقدَّم إجراءً للجميع بفرص متكافئة."], "text": {"head": "المواقف الصفية الجماعية — تعديل لا يعزل", "body": "<p>تعديلاتك داخل صف كامل توازن بين حاجتين: أن تصله الشروط المضبوطة، وألا يتحول التعديل إلى عزل مرئي يوصمه (كرسي خاص في ركن دائم، مرافق ملتصق، مهام مختلفة علنًا عن الجميع). البدائل الأنجع: تعديلات عامة النفع يستفيد منها الصف كله دون تمييز (تعليمات مصورة للجميع، مؤقت جماعي، محطات عمل واضحة)، وتعديلات فردية خفية التقديم (أدواته على طاولته كأدوات غيره شكليًا وهي مضبوطة له، موضعه المختار داخل التوزيع العادي). واستثناء العزل المبرر زمنيًا (ركن تنظيم قصير) يُقدَّم كإجراء للجميع بفرص متكافئة حتى لا يصير بصمة خاصة به.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تعديلات المواقف الخاصة وتوثيقها — حين تنكسر الشروط القياسية", "points": ["أوقف تدهور الشروط قبل إنقاذ الأنشطة.", "جزيرة آمنة تستعيد الإتاحة ثم هدف صغير واحد.", "سجل الانهيارات خريطة تعديلات أصدق من خططها."], "text": {"head": "حين تنهار الخطة — بروتوكول إنقاذ الجلسة", "body": "<p>ستنهار خطط تعديل محكمة أحيانًا (يوم مرض خفيف، تغيير غرفة، زائر مفاجئ). بروتوكول الإنقاذ المهني ثابت: (1) أوقف تدهور الشروط أولًا قبل إنقاذ الأنشطة — أغلق بابًا، اخفض صوتًا، أخرج مثيرًا؛ (2) انتقل لنشاط تنظيمي معروف النجاح عند متعلمك (جزيرته الآمنة) لاستعادة الإتاحة؛ (3) أعد بناء بقية الجلسة مختصرة بهدف واحد صغير مضمون؛ (4) وثّق ما انهار وسببه المرجح في محضرك. جلسة منقذة بهدف صغير محقق تنجح علاجيًا أكثر من جلسة منهارة أصرّت على برنامجها الكامل، وسجل الانهيارات الموثقة عبر الشهور خريطة تعديلاتك الأصدق على الإطلاق.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تعديلات المواقف الخاصة وتوثيقها — حين تنكسر الشروط القياسية", "points": ["مهمة واحدة ونسخة وصول مختلفة بكل بعد.", "كل بُعد معدَّل يسمّى في الوثيقة المقابلة.", "الفرق بين الصرامة والمهنة يظهر في نشاط واحد."], "text": {"head": "نشاط معدَّل كامل — من النسخة القياسية إلى نسخة متعلمك", "body": "<p>طبّق المنظومة على نشاط واحد كاملًا: قفز متتابع عبر 6 أطواق على مسار مستقيم (قياسي). نسخة متعلم مضطرب الانتباه والتقليد مع دفاعية صوتية: طوقان فقط بداية ونهاية أولًا (بُعد مهمة)، مع طوق أرضي يقف فيه عند استلام التعليمة (فضاء)، وتعليمة ثابتة «اقفز» مع إيماءة قفز بيديك (قناة)، وجدول مصور يضع النشاط ثانيًا بعد نشاط محبب (زمان)، وتعزيز نشاطي ثابت عند الإتمام، وقاعة بأدوات مغطاة (تصفية)، ومرافقة عند المحاولة الأولى تتلاشى. لاحظ أن المهمة «نفسها» (قفز بين علامتين) بينما نسخة الوصول مختلفة كليًا — وهذا هو الفرق العملي بين تعديل رفضته الصرامة وتعديل تبنيه المهنة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تعديلات المواقف الخاصة وتوثيقها — حين تنكسر الشروط القياسية", "points": ["جدول ستة حقول يلازم الملف ويتحدث دائمًا.", "مراجعة فصلية: سحب وتثبيت وتسلل بلا قرار.", "ملخص يسافر مع المتعلم لكل مستلم جديد."], "text": {"head": "منظومة التوثيق — سجل تعديلات يسافر مع المتعلم", "body": "<p>ختم الباب وثيقة حية تلازم ملفه: «سجل تعديلات» بجدول بسيط (البُعد — التعديلة — السبب الموثق — المنطق فحص/علاج — خطة السحب أو التثبيت — آخر مراجعة). يُحدَّث عند كل تغيير، ويُراجع فصليًا كاملًا (ما سُحب؟ ما ثبت ولماذا؟ ما تسلل بلا قرار؟)، ويُسلَّم ملخصه لأي مختص أو معلم جديد يستلم المتعلم حتى لا تبدأ رحلته من صفر التجريب. سجل كهذا يحوّل التعديلات من ذاكرة شخصية في رأسك إلى أصل مهني للفريق كله، ويحمي متعلمك من تقلّبات الأشخاص والسنوات — وهو في الحقيقة الغاية العميقة لهذه الوحدة كلها.</p><p>وآخر دروس المواقف الخاصة يتعلق بك أنت: أيامك السيئة جزء من شروط جلساتك. مختص مرهق أو مستعجل ينقل إيقاعه المضطرب إلى غرفته كلها قبل أن ينطق. القاعدة المهنية الصادقة: عدّل نفسك كما تعدّل غرفتك — اختصر برنامج يومك السيئ إلى أهداف أصغر مضمونة، وأجّل الفحوص الدقيقة لأيام حضورك الكامل، ووثّق في محضرك إن أثّر يومك في قياس ما. الصدق التوثيقي هنا ليس اعتراف ضعف بل جزء من علمية القياس نفسها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: في بروتوكول إنقاذ جلسة منهارة، لماذا يسبق «إيقاف تدهور الشروط» أي محاولة لإنقاذ النشاط المخطط؟", "الإجابة: لأن الأنشطة كلها تُبنى على الشروط؛ فما دام مصدر الانهيار (مثير، ضجيج، تغيير) فعّالًا سيهدم أي نشاط تنقذه فوقه. تثبيت الشروط أولًا ثم الانتقال لجزيرة آمنة وهدف صغير هو الترتيب الوحيد الذي يبني على أرض مستقرة."], "text": null, "take": "تُدار المواقف الخاصة بقواعد الاستكشاف المضبوط والعزل المتجنَّب وبروتوكول إنقاذ ثابت؛ ويحفظها كلها سجل تعديلات موثق يسافر مع المتعلم ويجعل تهيئة ظروفه أصلًا للفريق لا ذاكرة لفرد.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 70, "title": "منطق الخطة — من أسطر الحكم إلى أولويات قابلة للدفاع", "intro": "<p>بين نهاية الحوصلة وبداية الجلسات تقع أخطر مرحلة في عملك كلها: تحويل أحكام مكتوبة إلى خطة حية (projet d'intervention). خطة ضعيفة المنطق تهدر حصيلة فحص ممتاز، وخطة سليمة تنقذ فحصًا متوسطًا. في هذا الدرس تتعلم منطق الانتقال: كيف تُشتق الأولويات من الأسطر، ولماذا لا تُعالج كل شيء، وكيف يُصاغ الهدف القابل للقياس الذي ستحمله بقية الوحدة.</p>", "slides": [{"kind": "cover", "title": "منطق الخطة — من أسطر الحكم إلى أولويات قابلة للدفاع", "sub": "الوحدة السابعة عشرة: من الاضطراب إلى الخطة", "goals": ["أن تشتق أولويات خطتك من تقاطع أسطر أحكام الملفات كلها", "أن تعلن الحلقة المركزية فرضيةً بموعد إعادة قياس مكتوب", "أن تصوغ أي هدف بصيغة العناصر الخمسة القابلة للقياس"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l70.jpg", "img2": null}, {"kind": "slide", "title": "منطق الخطة — من أسطر الحكم إلى أولويات قابلة للدفاع", "points": ["اقرأ الأسطر مجتمعة عبر الملفات لا فرادى.", "ثلاث قراءات: أقوى صعوبة وأعمق حلقة وأرسخ قاعدة.", "خطة من تقاطع الأسطر أقصر وأعمق أثرًا."], "text": {"head": "الخطة تُشتق من الأسطر لا من الانطباع العام", "body": "<p>كل وحدة اضطراب في هذه الدورة ختمت فحصها بأسطر حكم بصيغ ثابتة: مكونات بقوى وضعف، وخطأ مشترك، وحلقة مكسورة، وقناة بنمطها، وشروط أداء أفضل. الخطة تُبنى بقراءة هذه الأسطر مجتمعة عبر الملفات كلها لا بقراءة كل سطر وحده: فأقوى صعوبة وظيفية، وأعمق حلقة سببية (حلقة مركزية يتفرع عنها غيرها)، وأرسخ قاعدة محفوظة تُبنى عليها. المختص المبتدئ يبني خطته من أحدث ملف قرأه؛ والمختص المنهجي يبنيها من تقاطع الأسطر كلها، ولهذا تكون خطط الثاني أقصر وأعمق أثرًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "منطق الخطة — من أسطر الحكم إلى أولويات قابلة للدفاع", "points": ["سلسلة سببية واحدة تولّد أعراض أبواب كثيرة.", "نشاط جذري واحد أعمق من ثلاث جبهات سطحية.", "الحلقة فرضية معلنة قابلة للدحض بموعد إعادة قياس."], "text": {"head": "الحلقة المركزية — ابدأ من حيث يتفرع الأذى", "body": "<p>في ملفات كثيرة تتشابك الصعوبات سلسلة سببية واحدة: أساس مضطرب يولّد أعراضًا في أبواب لاحقة (ثبات محوري منهار تُقرأ نتائجه «كتابة سيئة» و«جلوسًا فوضويًا» و«توازنًا ضعيفًا»). البدء من الحلقة المركزية يعني أن نشاطًا واحدًا يخاطب جذور ثلاثة أعراض معًا، بينما البدء من الأعراض يوزع جهدك على ثلاث جبهات سطحية بلا تقدم عميق في أيها. تحديد الحلقة فرضية مهنية تُعلن في الخطة بصيغة قابلة للدحض («نفترض أن الثبات هو الحلقة، وسنعيد القياس بعد 6 أسابيع؛ إن لم تتحرك الأعراض التابعة أعدنا الترتيب») فتحميك من العناد التخطيطي.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "منطق الخطة — من أسطر الحكم إلى أولويات قابلة للدفاع", "points": ["أولويتان أو ثلاث كحد أقصى في دورة واحدة.", "جرعات رقيقة شاملة تُفشل الكل بلا استثناء تقريبًا.", "قائمة انتظار معلنة بمواعيد مراجعة مكتوبة."], "text": {"head": "لماذا لا تُعالج كل شيء — اقتصاد الانتباه والجرعة", "body": "<p>أمام ملف بعشر صعوبات، إغراء الخطة الشاملة قوي ونتائجه موثقة الفشل: جرعات رقيقة على كل جبهة فلا يتقن شيء، وأهل ومعلمون يغرقون بعشر واجبات فيتوقفون عن الكل، وقياسات تتشتت فلا يُعرف ما تحرك ولماذا. القاعدة المهنية: أولويتان أو ثلاث كحد أقصى في دورة خطة واحدة (8-12 أسبوعًا)، وبقية الصعوبات تُوثق في قائمة انتظار معلنة بمواعيد مراجعتها. الاختيار نفسه رسالة مهنية للأهل: «نبدأ بالأهم والأعمق، وللباقي مواعيده المكتوبة» أصدق وأبقى من وعود شاملة تتبخر في أسبوعها الثالث.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "منطق الخطة — من أسطر الحكم إلى أولويات قابلة للدفاع", "points": ["خمسة عناصر: فعل وشرط ومعيار وتكرار وأفق.", "«يحسّن توازنه» أمنية لا هدف قابل للبناء.", "هدف ناقص عنصر يُعاد قبل التنفيذ دائمًا."], "text": {"head": "الهدف القابل للقياس — صيغة من خمسة عناصر", "body": "<p>يُصاغ كل هدف خطة بخمسة عناصر لا تنازل عنها: سلوك/أداء محدد بصيغة فعل (يقف، ينقل، يقلد)، وشرط إجرائه (بأي دعائم وبأي بيئة)، ومعيار نجاح رقمي (زمن/عدد/نسبة/دقة)، ونسبة تكرار (4 من 5 محاولات، 3 جلسات متتالية)، وأفق زمني (بنهاية الأسبوع 8). هدف بلا عنصر منها يُعاد إلى صاحبه قبل التنفيذ — «يحسّن توازنه» ليست هدفًا بل أمنية، و«يقف على قدم واحدة 5 ثوانٍ لكل قدم دون استناد في 3 جلسات متتالية بنهاية الأسبوع 8» هدف يبني نشاطًا ويُقاس ويُحتفل به أو يُراجع. الصيغة هي ما يفصل خطة هذه الدورة عن خطط النوايا العامة التي درستَ أخطاءها في الدرس الأخير.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "منطق الخطة — من أسطر الحكم إلى أولويات قابلة للدفاع", "points": ["ثلاث جرعات: جلسة تبني وبيت يكرر وصف يعمّم.", "مالك اسمي وتوثيق بسيط واحد لكل دور.", "المختص منسّق إيقاعات لا مؤدّي كل الأدوار."], "text": {"head": "أدوار الخطة — جلسة وبيت وصف بجرعات موزعة", "body": "<p>لا تعيش الخطة في جلستك الأسبوعية وحدها؛ فجرعتها الحقيقية موزعة: حصتك تبني وتضبط، والبيت يكرر بجرعات قصيرة يومية مضبوطة الأدوات والتوقيت، والصف يستقبل التعميمات باتفاقات واجهة مكتوبة. ولكل دور مالك اسمي ووسيلة توثيق واحدة بسيطة (سجل من سطرين أسبوعيًا خير من دفتر لا يُفتح). الخطة التي لا تسمي مالكي أدوارها الثلاثة وتوثيقهم تُولد يتيمة ولو كانت أهدافها مثالية الصياغة؛ ومسؤوليتك أنت تنسيق الإيقاعات الثلاثة لا أداءها كلها بنفسك.</p><p>ومن لوازم منطق الخطة ما يمكن تسميته اختبار القراءة العكسية: اقرأ خطتك من آخرها إلى أولها — من الأنشطة إلى الأهداف إلى الأسطر — واسأل عن كل نشاط «لماذا أنت هنا؟». نشاط لا يصعد بسلسلة إجابات مقنعة حتى سطر حكمه يُحذف أو يُستبدل مهما كان محببًا لديك أو لدى المتعلم. هذا الاختبار العكسي أسرع أدوات مراجعة الخطط ذاتيًا قبل عرضها على الأهل، ويكشف خاصة أنشطة «التراث المهني» التي تسللت من خطط سابقة بلا دعوة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يُشترط أن تُعلن «الحلقة المركزية» في الخطة فرضيةً بموعد إعادة قياس بدل تقديمها حقيقة مؤسِّسة؟", "الإجابة: لأن ترتيب السببية داخل ملف متشابك استدلال مهني قابل للخطأ؛ فإعلانها فرضية بموعد فحص يحمي الخطة من العناد: إن لم تتحرك الأعراض التابعة في الموعد أُعيد ترتيب الأولويات بالدليل لا بالدفاع عن قرار قديم."], "text": null, "take": "الخطة تُشتق من تقاطع أسطر الحكم لا من انطباعات، وتبدأ من حلقة مركزية معلنة كفرضية، وتقتصر على أولويتين أو ثلاث، وتُصاغ أهدافها بخمسة عناصر، وتُوزع أدوارها على الجلسة والبيت والصف بأسماء ومالكين.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 71, "title": "بناء الخطة — تسلسل وجرعة ومؤشرات", "intro": "<p>بعد اختيار الأولويات وصياغة الأهداف، تُبنى الخطة بناءً هندسيًا: تسلسل يحترم اعتماد المهارات بعضها على بعض، وجرعة محسوبة بالدقائق والتكرارات لا بالمشاعر، ومؤشرات قياس تُزرع منذ اليوم الأول. في هذا الدرس تفاصيل البناء الثلاثة، وخاتمته نموذج هيكل خطة كامل ستفصّله الحالة التطبيقية القادمة بأرقام حقيقية.</p>", "slides": [{"kind": "cover", "title": "بناء الخطة — تسلسل وجرعة ومؤشرات", "sub": "الوحدة السابعة عشرة: من الاضطراب إلى الخطة", "goals": ["أن تبني سلالم تقدم بمعايير انتقال مكتوبة لا بانطباعات", "أن تحسب أي جرعة بأرقامها الثلاثة: مدة وتكرار وسياقات", "أن توثق خطوط أساس بمؤشرات الأهداف نفسها قبل أول تدخل"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l71.jpg", "img2": null}, {"kind": "slide", "title": "بناء الخطة — تسلسل وجرعة ومؤشرات", "points": ["اعتماد موثق: لا مركب قبل ركائزه المستقرة.", "سلّم بمعايير انتقال مكتوبة لا انطباعات.", "جديد واحد في كل مرحلة وعبء ثابت الحجم."], "text": {"head": "التسلسل — ركائز قبل مركبات وقواعد قبل قمم", "body": "<p>يحكم التسلسل مبدأ الاعتماد: لا تُطلب مهارة مركبة قبل استقرار ركائزها الموثقة في الأسطر (ثبات قبل خطّ، مخطط قبل جانبية معقدة، إنتاج نمط قبل بنى معقدة). ويُبنى كل هدف بسلّم تقدم خاص: المستوى الحالي المقاس، وخطوتان وسيطتان، والمستوى المستهدف — بمعايير انتقال بين الدرجات مكتوبة سلفًا حتى لا تقرر «تقدمه» انطباعات يوم جيد. وتُدخل الجدولة بديلًا واعيًا للحماس: مهارة جديدة واحدة في كل مرحلة، ومهارات مستقرة تتحول إلى واجبات توزيع بيتية في الوقت نفسه، فيبقى عبء الجديد ثابت الحجم عبر الخطة كلها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "بناء الخطة — تسلسل وجرعة ومؤشرات", "points": ["ثلاثة أرقام: مدة وتكرار أسبوعي وعدد سياقات.", "أنماط بابية ثابتة لتوزيع الجرعات.", "جرعة ناقصة رقم لم تُعطَ أصلًا بصيغتها."], "text": {"head": "الجرعة — دقائق وتكرارات وسياقات", "body": "<p>تُحسب الجرعة بثلاثة أرقام: مدة الجرعة الواحدة ونوعها (جلسة مختص/بيت/صف)، وتكرارها الأسبوعي، وعدد سياقاتها (أشخاص وأماكن). تُظهر خبرة أبواب هذه الدورة أنماطًا ثابتة: مهارات دقيقة وجانبية تحب جرعات قصيرة يومية موزعة؛ ومهارات توازن وتخطيط تحتاج جلسات مركزة أسبوعية بمتابعة بيتية بسيطة؛ ومهارات تنظيمية (نمطيات/حسية) تعيش بالجدولة البيئية المستمرة أكثر مما تعيش بجلسات. وأي جرعة بلا واحد من الأرقام الثلاثة خطة ناقصة الأبعاد ستُقرأ لاحقًا «لم تنجح» بينما هي لم تُعطَ أصلًا بصيغتها الموصوفة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "بناء الخطة — تسلسل وجرعة ومؤشرات", "points": ["خط أساس بمؤشر الهدف نفسه قبل التدخل.", "وسائط محفوظة تجعل المقارنة قابلة للعرض.", "مؤشرات قليلة حية تتفوق على لوحات ثقيلة ميتة."], "text": {"head": "المؤشرات — خط أساس قبل أول جلسة", "body": "<p>لا تبدأ أي خطة بلا خط أساس موثق (mesure initiale) لكل هدف بمؤشره نفسه الذي سيقاس به لاحقًا: زمن وقوف، عدد نوبات، نسبة بُنى صحيحة، أخطاء ترتيب. قاعدة الزمن صارمة: يُقاس خط الأساس قبل بدء التدخل أو في جلسته الأولى بظروفها الموثقة، ويُحفَظ بوسائط إن أمكن (فيديو قصير، تسجيل صوتي، عينات ورقية مؤرخة). خط أساس مفقود يجعل كل «تحسن» لاحق حكاية غير قابلة للدفاع أمام أهل يسألون — بحق — «بماذا قارنتم؟». وفي المقابل مؤشرات حية قليلة خير من لوحة مؤشرات ثقيلة تموت في أسبوعها الثاني.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "بناء الخطة — تسلسل وجرعة ومؤشرات", "points": ["مراجعة كل 4 أسابيع بأسئلة ثابتة معلنة.", "قرارات محتملة مكتوبة سلفًا بلا دراما.", "شركاء الجرعة يُدعون بملخصات لا يُفاجَؤون بنتائج."], "text": {"head": "نقاط المراجعة — مواعيد مكتوبة بقرارات محتملة", "body": "<p>تُزرع في الخطة منذ ولادتها نقاط مراجعة بتواريخ (كل 4 أسابيع نموذجيًا) وبأسئلة ثابتة: هل تحرك المؤشر؟ هل بقيت الحلقة المركزية فرضية صالحة؟ هل الجرعة تُعطى فعلًا كما وُصفت؟ ما القرار (استمرار/تعديل جرعة/تبديل نشاط/إعادة تقييم جزئي)؟ كتابة القرارات المحتملة سلفًا تمنع أن تتحول المراجعة إلى احتفال أو محاكمة؛ فهي محطة هندسية لها مدخلاتها ومخرجاتها. وتُدعى الأطراف المساهمة (بيت/مدرسة) بملخصات قصيرة عند كل نقطة — فهم شركاء جرعة لا جمهور نتائج.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "بناء الخطة — تسلسل وجرعة ومؤشرات", "points": ["سبعة أقسام ثابتة بصفحات قليلة موحدة.", "قابلية مقارنة وتسليم بين المختصين.", "شكل صارم = ذاكرة خطة لا تضيع."], "text": {"head": "هيكل وثيقة الخطة — صفحة واحدة تفي بالغرض", "body": "<p>تجمع الخطة في وثيقة قصيرة موحدة الشكل: ترويسة المتعلم ومواعيد الدورة؛ وأسطر الحكم المختارة منها البناء؛ والحلقة المركزية المعلنة وفرضيتها؛ والأهداف بصيغتها الخماسية مع خطوط أساسها؛ وجدول الجرعات والأدوار والمالكين؛ وسجل التعديلات المرتبط بها؛ ونقاط المراجعة بتواريخها. هذا الهيكل الصارم هو ما يجعل خطتين لمتعلمين مختلفين قابلتين للقراءة بالمقارنة نفسها، ويجعل تسليم متعلم لمختص آخر ممكنًا دون فقدان ذاكرة خطته. الصرامة الشكلية هنا ليست بيروقراطية: إنها ما يميز خطة مهنية عن قائمة تمارين موسمية.</p><p>احذر في بناء السلالم خطأ القفزات غير المتساوية: درجات صغيرة جدًا في أول السلم (ملّ مفرط وجرعة مهدورة على مستقَر) ودرجات واسعة في وسطه (انهيار متكرر عند قفزة بعينها يُقرأ خطأً سقف قدرة). القاعدة أن تُبنى الدرجات من بيانات خط الأساس نفسه: كل درجة ترفع متغيرًا واحدًا بمقدار يقارب ما أثبت المتعلم قدرته على تجاوزه في الفحص، فتصير السلالم فردية القياس كالثياب المفصلة لا مقاسات جاهزة.</p><p>ومثال يقرب حساب الجرعة الواقعي: هدف توازن بجلستين أسبوعيًا (30 دقيقة مركزة) وسياقين (جلسة وبيت) يختلف تمامًا في مآله عن الهدف نفسه بجلسة شهرية وسياق واحد، رغم تطابق صياغته الخماسية. لهذا لا تُقرأ الأهداف في المراجعات منعزلة عن أرقام جرعاتها، فالهدف واحد والخطط متعددة المصائر باختلاف الجرعة وحدها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا يُمنع بدء التدخل قبل قياس خط الأساس حتى عند ضغط الأهل للبدء فورًا؟", "الإجابة: لأن خط الأساس هو مرجع كل ادعاء تحسن لاحق؛ فبدونه تصبح الخطة غير قابلة للتقييم والدفاع («بماذا قارنتم؟»)، وتفقد نقاط المراجعة معناها، ويضيع احتمال اكتشاف أن الفرضية المركزية خاطئة في موعد مبكر."], "text": null, "take": "بناء الخطة تسلسل بمعايير انتقال، وجرعة بثلاثة أرقام، وخطوط أساس قبل أول تدخل، ونقاط مراجعة مكتوبة القرارات — موثقة كلها في هيكل موحد قصير.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 72, "title": "تنفيذ الخطة ومتابعتها — متغير واحد وتعميم مخطط", "intro": "<p>تُختبر الخطط في التنفيذ لا في صياغتها: أسابيع من الجلسات والجرعات والتقلبات تفرق بين خطة تُدار وخطة تُروى. في هذا الدرس تتعلم إدارة التنفيذ بقواعدها الأربع: تغيير متغير واحد في كل مرة، وتعميم مخطط منذ البداية، وتوثيق جلسات اقتصادي، وقراءة إشارات إعادة التقييم قبل أن تصير أزمات.</p>", "slides": [{"kind": "cover", "title": "تنفيذ الخطة ومتابعتها — متغير واحد وتعميم مخطط", "sub": "الوحدة السابعة عشرة: من الاضطراب إلى الخطة", "goals": ["أن تدير تنفيذ خطتك بقاعدة المتغير الواحد في كل تعديل", "أن تبني التعميم سلّم سياقات من الأسبوع الأول بمؤشر مستقل", "أن تختم أي دورة خطة بمقارنة T0/T1 وقرار انتقال مكتوب"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l72.jpg", "img2": null}, {"kind": "slide", "title": "تنفيذ الخطة ومتابعتها — متغير واحد وتعميم مخطط", "points": ["عنصر واحد في كل تعديل بمهلة قياس كافية.", "تغييران معًا يقتلان التعلم من النتيجة.", "أزمات السلامة استثناء موثق لا قاعدة."], "text": {"head": "متغير واحد — لتعرف ما الذي نجح", "body": "<p>حين تتغير النتائج إيجابًا أو سلبًا أثناء التنفيذ، عليك أن تعرف السبب لتتعلم منه. تغيير متغيرين معًا (نشاط جديد وجرعة جديدة وبيئة جديدة في أسبوع واحد) يجعل التعلم مستحيلًا: لا تدري ما حمل التحسن فتعممه، ولا ما سبب التراجع فتوقفه. القاعدة التنفيذية الذهبية: عدّل عنصرًا واحدًا في كل نقطة تعديل (النشاط أو الجرعة أو السياق أو الدعائم)، وامنحه زمنه المقاس قبل الحكم. الاستثناء الوحيد أزمات الأذى والسلامة حيث يُغيَّر كل ما يلزم فورًا وتُوثَّق الضرورة. الانضباط البطيء ظاهريًا أسرع الطرق فعليًا، لأنه يبني معرفة قابلة لإعادة الاستعمال عند كل متعلم قادم.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تنفيذ الخطة ومتابعتها — متغير واحد وتعميم مخطط", "points": ["سلّم سياقات معلن من الأسبوع الأول.", "التعميم مؤشر مستقل عن الإتقان في المراجعات.", "بلا دليل تعميم، النجاح نصف نجاح موثقًا."], "text": {"head": "التعميم المخطط — لا تنتظر أن يحدث وحده", "body": "<p>أشهر خيبات الخطط مهارة تتقن في الجلسة وتموت عند بابها. العلاج وقائي: يُبنى التعميم داخل تصميم الخطة من أسبوعها الأول بسلّم سياقات معلن: سياق التدريب، ثم سياق قريب (غرفة أخرى/شخص آخر)، ثم بيئة الهدف (بيت/صف) بأدواتها الحقيقية وأشخاصها الفعليين، مع شخص مسؤول عن كل درجة وتوثيقها. وتُعامل درجة التعميم في نقاط المراجعة كمؤشر مستقل عن مؤشر الإتقان نفسه؛ فمهارة «منجزة» بلا تعميم تُسجَّل نصف منجزة. كما يُمنع إعلان نجاح خطة كليًا قبل دليل تعميم واحد موثق على الأقل في بيئة حياة حقيقية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تنفيذ الخطة ومتابعتها — متغير واحد وتعميم مخطط", "points": ["خمسة حقول ثابتة بدقائق لا صفحات.", "منحنى مؤشرات يُجمع عند كل مراجعة.", "الاقتصاد شرط بقاء التوثيق حيًا طوال الخطة."], "text": {"head": "توثيق الجلسات — محضر اقتصادي يبقى حيًا", "body": "<p>يُوثق التنفيذ بمحضر جلسة اقتصادي ثابت الشكل لا يتجاوز دقائق: التاريخ والهدف المعمول عليه، والجرعة الفعلية المنجزة، ومؤشر اليوم الرقمي، وقرار الجلسة (متابعة/تعديل بمتغير واحد مسمى)، وملاحظة استثنائية واحدة عند وجودها. اقتصادية التوثيق شرط حياته؛ فالمحاضر الروائية الطويلة تموت في الشهر الأول وتأخذ معها ذاكرة الخطة. ويُجمع من المحاضر عند كل نقطة مراجعة منحنى المؤشرات — صورة واحدة تلخص شهرًا كاملًا — فيتحول التوثيق اليومي الصغير إلى قرارات فصلية كبيرة بلا أعباء إضافية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تنفيذ الخطة ومتابعتها — متغير واحد وتعميم مخطط", "points": ["خمس إشارات: ثبات، تراجع، جديد، تغير بيئي، طلب أسري موثق.", "عودة للحوصلة الجزئية قبل مواعيد الدورة.", "قرارات إعادة التقييم صدق مهني لا اعتراف فشل."], "text": {"head": "إشارات إعادة التقييم — متى تعود إلى الحوصلة", "body": "<p>ليست كل خطة تُستكمل كما بدأت؛ فخمس إشارات تعيدك إلى إعادة تقييم جزئي قبل موعد الدورة: ثبات المؤشرات رغم جرعة موثقة الالتزام (فرضية الحلقة على المحك)، وتراجع مهارات كانت مستقرة (رسالة طبية/سياقية محتملة)، وظهور صعوبات جديدة من باب لم يُفحص، وتغيّر بيئي كبير (مدرسة جديدة، دواء جديد)، وطلب أسري موثق بتغيرات لم ترها جلستك. إعادة التقييم هنا ليست فشلًا يُخفى بل بوابة الخطة الطبيعية — وسجل قراراتها جزء من صدق ملفك المهني كله.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "تنفيذ الخطة ومتابعتها — متغير واحد وتعميم مخطط", "points": ["مقارنة بمقاييس وشروط T0 نفسها بلا استثناء.", "خمس قرارات انتقال ثابتة القائمة.", "الاحتفال يلي الجدول ولا يحل محله."], "text": {"head": "نهاية الدورة — مقارنة T0/T1 وقرارات الانتقال", "body": "<p>تُختم كل دورة خطة (8-12 أسبوعًا) بمقارنة منهجية: مؤشرات الأهداف نفسها بشروط القياس نفسها (T1 مقابل T0)، وعرض مرئي على الأهل بالوسائط المحفوظة، وقرارات مكتوبة من قائمة ثابتة: استمرار بأهداف جديدة، أو تعديل عمق، أو انتقال لأولويات قائمة الانتظار، أو إحالة/تنسيق إضافي، أو إغلاق ملف بهدف مستقر مع خطة صيانة. ويُمنع ختم الدورة بانطباعات الاحتفال وحده؛ فالاحتفال مستحق ومكانه محفوظ، لكنه يلي جدول المقارنة لا يحل محله أبدًا.</p><p>وتُدار الخطة نفسيًا بقدر ما تُدار هندسيًا: فالأهل الذين يرون منحنى مؤشر واحد يتحرك في الأسبوع الرابع يمنحون الخطة صبر الأسابيع التالية كله. لهذا اختر منذ اليوم الأول «مؤشر عرض» واحدًا سريع الحركة نسبيًا (زمن جلوس، عدد وقفات) يُعرض عليهم مبكرًا بالرسم، إلى جانب مؤشراتك العميقة البطيئة. إدارة التوقعات بعرض صادق مبكر ليست تسويقًا؛ إنها جزء من جرعة الالتزام الأهلي التي بلا فعالية لها تموت أفضل الخطط عند باب البيت.</p><p>وفي إدارة التنفيذ أداة أخيرة بسيطة تمنع أشهر أزماته: اجتماع خطة قصير (عشر دقائق أسبوعيًا أو نصف شهريًا) بين مالكي الأدوار الثلاثة، بأجندة ثابتة من ثلاثة أسئلة فقط: ماذا حدث في المؤشرات؟ وما المتغير الواحد القادم؟ ومن يحتاج ماذا من الآخر؟ اجتماعات بلا هذه الأجندة تتحول إلى نقاشات عامة تستهلك الالتزام الذي جاءت لحمايته.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: مسؤول صفّي يقترح في أسبوع واحد تغيير النشاط والجرعة ومكان التدريب لتحسين نتائج راكدة؛ ما موقفك المهني ولماذا؟", "الإجابة: رفض الحزمة وتعديل عنصر واحد بمهلة قياس، لأن تغيير ثلاثة متغيرات معًا يجعل سبب أي تحسن أو تراجع مجهولًا فتضيع قيمة التجربة كلها؛ الاستثناء الوحيد توثيق ضرورة سلامة فورية، وهو غير قائم في «نتائج راكدة»."], "text": null, "take": "يُدار التنفيذ بمتغير واحد في كل مرة، وتعميم مخطط من الأسبوع الأول بمؤشر مستقل، وتوثيق اقتصادي يبني منحنيات قرار — وتُختم الدورات بمقارنات T0/T1 وقرارات انتقال مكتوبة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 73, "title": "أخطاء الخطط الشائعة وخطة مصغرة كاملة", "intro": "<p>تُختم الوحدة بمرآة الأخطاء: أنماط خطط فاشلة تتكرر عبر الممارسات بأسماء مختلفة، مع نموذج خطة مصغرة كاملة بصيغ الدروس الثلاثة السابقة. من تعلّم قراءة فشل الخطط قبل وقوعه وفّر على متعلميه شهورًا من الجرعات المهدورة — وهذه هي الفائدة العملية الكبرى لهذه الوحدة.</p>", "slides": [{"kind": "cover", "title": "أخطاء الخطط الشائعة وخطة مصغرة كاملة", "sub": "الوحدة السابعة عشرة: من الاضطراب إلى الخطة", "goals": ["أن تكشف خططًا يتيمة الاشتقاق وأهدافًا أمنيات ومؤشرات ميتة", "أن تحكم على نقل خطة بين نمطين متناقضين حكمًا مهنيًا صارمًا", "أن تمرّر أي خطة على أسئلة الفحص السبعة قبل إطلاقها"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l73.jpg", "img2": null}, {"kind": "slide", "title": "أخطاء الخطط الشائعة وخطة مصغرة كاملة", "points": ["خطة تبدأ بنشاط بلا أسطر حكم = يتيمة الأصل.", "أحكام بلا حلقة مختارة = جرعات رقيقة على الكل.", "سؤال الاشتقاق كاشف فوري لأي خطة تقرؤها."], "text": {"head": "وصفة بلا تقييم وخطة بلا حلقة", "body": "<p>الخطأ المؤسس: خطة تُبنى من شكوى واحدة ظاهرة («لا يكتب» فتمارين كتابة) دون حوصلة توزع الاحتمالات — فتُعالج أعراض الحلقات لا الحلقات. توقيعه القابل للتعرف: خطة تبدأ بنشاطها الأول في أول صفحة بلا أسطر حكم قبلها. والخطأ الشقيق: خطة جمعت أحكامًا صحيحة لكنها لم تختر حلقة مركزية، فوزعت نفسها على سبع صعوبات بجرعات رقيقة وانتهت بلا نتيجة في أيها. كلا الخطأين يُكتشفان بسؤال واحد عند قراءة أي خطة: «أرني السطر الذي اشتُقّ منه هذا النشاط» — فإن تعذّر الجواب فالنشاط يتيم مهما كان جميلًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أخطاء الخطط الشائعة وخطة مصغرة كاملة", "points": ["أمنية صياغية تجعل النتيجة والفشل غير قابلين للفصل.", "مؤشر يحتاج ما لا يوجد يموت في أسبوعه الثاني.", "دور بلا اسم مالك جرعة لم تُسلَّم أصلًا."], "text": {"head": "أهداف أمنيات ومؤشرات ميتة وخطط بلا مالك", "body": "<p>ثلاثة أخطاء تنفيذية قاتلة بهدوء: أهداف بصيغة أمنيات («يتحسن، يتقدم، يتطور») تجعل كل نتيجة قابلة للادعاء وكل فشل قابلًا للإنكار؛ ومؤشرات ميتة (قياسات تحتاج أدوات غير موجودة أو زمنًا لا يملكه أحد) فتتوقف المتابعة صامتة منذ الأسبوع الثاني؛ وخطط بلا مالكي أدوار (جرعة بيتية «على الأهل» بلا اسم ولا اتفاق ولا وسيلة سجل) فلا يعرف أحد من قصّر ولا متى. وكلها أخطاء تُراجع في وثيقة الخطة نفسها قبل أن تُراجع في نتائجها؛ فمدقق خطط جيد يمسكها بقلم أحمر في عشر دقائق ويوفر عشرة أسابيع.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أخطاء الخطط الشائعة وخطة مصغرة كاملة", "points": ["تشابه نشاط بين نمطين متشابهين جائز وموثق.", "نقل جرعات وتسلسلات وتعديلات بين أنماط ممنوع.", "تُورَّث الأدوات والبنى، لا الوصفات الجاهزة."], "text": {"head": "نسخ الخطط بين المتعلمين — تشابه مقبول وتبادل ممنوع", "body": "<p>يجوز أن تتشابه خططان في نشاط بالاسم والأدوات حين يتشابه نمطا ملفيهما فعلًا؛ فالأدوات براءات مشتركة. ويُمنع منعًا مهنيًا صارمًا أن تنتقل خطة كما هي — بتسلسلاتها وجرعاتها وتعديلاتها — من ملف إلى ملف مختلف النمط (خطة بُنيت لفرط دهليزي تُعطى لمتجنب دهليزي لأن «النشاط نفسه نجح مع الأول»). النشاط بلا نمط ملفه جرعة بلا تشخيص؛ ونقل الحلول بين أنماط متناقضة قد يضر ضررًا حقيقيًا فوق ضرر عدم النفع. القاعدة التي تضبط الباب: تُورَّث الأدوات وبنى الخطط، ولا تُورَّث جرعات ولا تسلسلات ولا تعديلات — فهذه الثلاثة تُشتق من أسطر كل ملف على حدة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أخطاء الخطط الشائعة وخطة مصغرة كاملة", "points": ["أسطر وحلقة وثلاث أولويات خماسية الصيغة.", "جرعة ثلاثية القنوات بمالكين مسمين.", "كل نشاط يجيب فورًا عن سؤال اشتقاقه."], "text": {"head": "خطة مصغرة كاملة — من الأسطر إلى المؤشرات", "body": "<p>اقرأ خطة مصغرة بأعين الدروس الثلاثة: أسطر حكمها: ثبات وضعي ينهار بعد 3 دقائق جلوس، وتوازن ثابت 2/1 ثانية، وقبضة مشدودة تكسر الأقلام. حلقتها المركزية المعلنة: الثبات المحوري (فرضية بمراجعة أسبوع 6). أولوياتها الثلاث بـ12 أسبوعًا: (1) يجلس 8 دقائق بإسناد قدمين أثناء نشاط تركيب في 4 من 5 جلسات؛ (2) يقف على قدم واحدة 5 ثوانٍ لكل قدم دون استناد في 3 جلسات متتالية؛ (3) يمسك قلمًا سميكًا بقبضة ثلاثية دون كسر في 80 بالمئة من محاولات 3 تمارين. جرعاتها: جلسة أسبوعية 45 دقيقة + 10 دقائق بيتية يوميًا بأسماء أنشطة محددة ومالك أسري مسمى + اتفاق أثاث صفي مكتوب. مراجعاتها: أسبوع 4 و8 و12 بمنحنيات مؤشرات. لاحظ اكتمال السلسلة: كل نشاط فيها يجيب عن سؤال الاشتقاق فورًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "أخطاء الخطط الشائعة وخطة مصغرة كاملة", "points": ["سبعة أسئلة أخيرة قبل أي إطلاق ميداني.", "«لا» واحدة تعيد الخطة إلى المكتب لا الميدان.", "القائمة نفسها أداة حكم الحالات القادمة."], "text": {"head": "قائمة فحص الخطة قبل إطلاقها", "body": "<p>قبل أن تغادر أي خطة مكتبك مرّر عليها بسبعة أسئلة أخيرة: هل لكل هدف سطر حكم مشتق منه؟ هل أهدافها بصيغة العناصر الخمسة؟ هل خطوط أساسها مقاسة وموثقة بوسائط؟ هل جرعاتها بثلاثة أرقام ومالكين مسمين؟ هل تعديلاتها في سجلها بحقولها الستة؟ هل مراجعاتها مؤرخة وأسئلتها ثابتة؟ هل تعميمها مسلّم السياقات من الأسبوع الأول؟ سؤال واحد بجواب «لا» يعيد الخطة إلى مكتبك لا إلى الميدان. هذه القائمة هي آخر ما تفعله في ملف التخطيط وأول ما سيسألك عنه حكم الدورة في وحدة الحالات، حيث ستُقرأ خطط حقيقية بهذه الأعين السبعة نفسها.</p><p>وراجع في ذهنك قبل إنهاء هذه الوحدة خريطة أخطاء الخطط قراءة واحدة أخيرة بوصفها أنماط فشل متوقعة الوقوع لا حالات نادرة: فكل ممارس سيقع في إحداها مرة على الأقل في مساره، والفرق بين مختص وآخر ليس تجنبها الأبدي بل سرعة اكتشافها بالأسئلة السبعة ومنحنيات المراجعة. من يراجع خططه بعيون هذا الدرس كل دورة يحوّل أخطاءه من تكاليف يدفعها متعلموه إلى دروس يدفعها هو وحده مرة واحدة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: خطة ناجحة عند متعلم متجنب دهليزي يراد تطبيقها كما هي على متعلم باحث دهليزي لأن «الأنشطة نفسها ممتعة»؛ ما الحكم المهني؟", "الإجابة: ممنوع نقلها كما هي: فالجرعات والتسلسلات والتعديلات في الخطة الأصلية مشتقة من نمط ملفها (تجنب) وعكسها تقريبًا حاجة النمط المقابل (بحث)؛ يجوز توريث الأدوات وبنية الخطة فقط، وتُشتق الجرعة والتعديلات من أسطر ملف المتعلم الثاني."], "text": null, "take": "تُقرأ الخطط الفاشلة بثلاث مرايا: يتيمة الاشتقاق، وأمنية الصياغة بلا مالكين، ونسخًا بين أنماط متناقضة — وتُفحص كل خطة بسبعة أسئلة قبل إطلاقها.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 74, "title": "حالة يان — حين يكشف التعديل قدرةً يخفيها الاضطراب العلائقي", "intro": "<p>حالة موثقة كاملة من أدبيات تقييمنا المرجعية: يان، 4 سنوات، في قسم متوسط بالمدرسة (سبعة أنصاف أيام أسبوعيًا دون مرافق بعد، والطلب قيد الدرس)، ويتابع نفسيًا حركيًا في مركز علاجي. خلص تقييمه الشامل إلى اضطراب نمائي من نوع متلازمة أسبرجر. لغته المنطوقة متطورة البنية وغنية المفردات، بينما جسده وعلاقاته يحملان الصورة الأخرى كاملة. اقرأ الحالة بأدوات الدورة كلها: أرقام، وأسطر حكم، وتعديلات كشفت ما لا تكشفه الشروط القياسية.</p>", "slides": [{"kind": "cover", "title": "حالة يان — حين يكشف التعديل قدرةً يخفيها الاضطراب العلائقي", "sub": "الوحدة الثامنة عشرة: حالات تطبيقية", "goals": ["أن تقرأ حالة يان بأرقامها وتعديلاتها قراءة فاحص كاملة", "أن تميّز ما سقط عند يان حركيًا مما سقط بواباتٍ اجتماعية وانتباهية", "أن تستخلص درس الجدول المرئي والبنية الكافية لملف مشابه"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l74.jpg", "img2": null}, {"kind": "slide", "title": "حالة يان — حين يكشف التعديل قدرةً يخفيها الاضطراب العلائقي", "points": ["سياق آخر الصباح في يوم تقييم أخير جزء من قراءة النتائج.", "أسئلة نمطية معروفة الأجوبة مدخل اجتماعي وتحويل مهمة.", "لغته الغنية بنيةً تخفي اضطراب استعمالها كاملًا."], "text": {"head": "سياق التقييم وخصوصيات صاحب الحالة", "body": "<p>جرت الحوصلة في اليوم الأخير من تقييم شامل، في ساعة واحدة تقريبًا آخر الصباح — سياق زمني يجب أن يبقى حاضرًا في قراءة كل نتائجها. خصوصيات يان المؤثرة في الجلسة موثقة: تجنب تواصل بصري، وخراقة اجتماعية وعجز انتباه مشترك، وإيكولاليا فورية، وفهم حرفي للتعليمات، ولغة تلقائية قليلة رغم غنى بنيتها، وعدم استقرار حركي، وتشويش حسي (parasitage sensoriel)، وصلابة ومثابرة سلوكية. وكان يفتتح العلاقة بأسئلة نمطية يعرف أجوبتها («كم عمرك؟»، «هل نحن الثلاثاء 20 نوفمبر؟») يستعملها مدخلًا اجتماعيًا أو تحويلًا عن المهام الصعبة — بيانات علائقية لا «ثرثرة».</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة يان — حين يكشف التعديل قدرةً يخفيها الاضطراب العلائقي", "points": ["عمر حركي 3.5 سنة عند عمر زمني 4 سنوات.", "شارلوب-أتويل −1 انحراف، وM-ABC دون المئوي 5 بمجالاته.", "ديناميكي أفضل من ثابت، ونهاية الجلسة تنهار بالتعب."], "text": {"head": "بيانات الفحص — أرقام تحكي قصة متناسقة", "body": "<p>حُدّد عمره الحركي العام بنحو 3 سنوات و6 أشهر. في بطارية شارلوب-أتويل سجّل 38 نقطة (14 موضوعية و24 ذاتية) أي بانحراف معياري واحد دون فئته العمرية. وفي بطارية الحركة (M-ABC) جاء دون المئوي الخامس في المجالات الثلاثة كلها: مهارة يدوية، وإتقان كرات، وتوازن. في التوازن الأحادي وقف 3 ثوانٍ يمينًا وثانيتين يسارًا — دون المنتظر لعمره — ومشى على مقعد وعارضة بنجاح. تعثّرت بنود أصابع القدم ونهاية الجلسة كلها. لاحظ تناسق الصورة: انخفاض عام معتدل (لا انهيار كليًا)، وتفوق نسبي للتوازن الديناميكي على الثابت، وتدهور حاد مقترن بنهاية زمن التقييم المتراكم.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة يان — حين يكشف التعديل قدرةً يخفيها الاضطراب العلائقي", "points": ["جدول رموز مرئي استجابة لالتزامه بالبنية المكانية-الزمانية.", "طوق بداية ونهاية بنية كافية لقفزاته بلا زيادة.", "«تحايله» بحث نجاح بوسائله يُقرأ لا يُعاقب."], "text": {"head": "التعديلات التي غيّرت الصورة — جدول مرئي وأطواق", "body": "<p>لأنه لوحظ في تقييماته السابقة التزامه الاستثنائي بالبنية المكانية-الزمانية، بُني له جدول أنشطة مرئي برموز مرسومة على اللوح يرجع إليه طوال الحوصلة — فاستقر إيقاع العمل. وفي التوازن وُضع داخل طوق لدعم فهم التعليمة، فوثّق ردودًا مركبة: صلابة (يريد إنجازها وحده ويعيد وضع الطوق بنفسه)، ومثابرة التفافية (يرفع ساقًا مستندًا إلى مقعد أو جدار، ثم يضع يديه أرضًا ليرفع قدمًا) مع إيكولاليا مرافقة — سلوكيات تُقرأ بحثًا عن نجاح المهمة بوسائله لا «غشًا». وفي القفزات كان طوقان (بداية ونهاية) بنية كافية له بلا مزيد. وقبل التنسيقات جلس على كرسي ليشاهد العرض كاملًا لأنه لا ينتظر نهايته عادة ويبدأ قبل اكتماله.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة يان — حين يكشف التعديل قدرةً يخفيها الاضطراب العلائقي", "points": ["صدى التعليمات بلا تنفيذ: لغة منفصلة الوظيفة تحت الصعوبة.", "الصلابة والإيكولاليا تشتدان عند الصعوبة تحديدًا (مؤشر حالة).", "مسكة راحية ناقصة مقوّية وخط متردد في الدقيقة."], "text": {"head": "الحركة الدقيقة والتنسيقات — وما وراء الأرقام", "body": "<p>في التنسيقات المعقدة (بنود الدمية المتحركة والحيوان ما قبل التاريخ والدوران في بطارية شارلوب-أتويل) أدى بتركيز عالٍ مكلف، مكررًا التعليمات صدىً بلا تنفيذ فعال — «اللغة بلا وظيفة براغماتية» كما وثّق التقرير. وقفزاته: قدمًا بملتحمتين أمامًا وخلفًا ناجحة بالبنية، بينما سقطت قفزة القدم الواحدة والقفز فوق الحبل والقفز بنصف دورة مع إيكولاليا وصلابة تشتد عند الصعوبة تحديدًا. وفي الدقيقة: مسكة راحية غير ناضجة ناقصة المقوّية وخط متردد. ورفض كل مساعدة رغم صعوباته الموثقة. صورة متكاملة: قدرة متوسطة منخفضة بأداء يتفكك تحت تراكم متطلبات فهم وانتباه وتعب، وصلابة ترتفع درعًا كلما ارتفعت الصعوبة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة يان — حين يكشف التعديل قدرةً يخفيها الاضطراب العلائقي", "points": ["حكم مركب: انخفاض معتدل وبوابات اجتماعية للأداء.", "سلوك الصعوبة أثمن توجيهيًا من الدرجات الخام.", "سياق زمان التقييم شريك دائم في تفسير أرقامه."], "text": {"head": "أسطر الحكم والدروس المهنية المستخلصة", "body": "<p>أسطر الحكم بصيغ الدورة: توازن ثابت ضعيف نسبيًا وديناميكي أحفظ؛ تناسق عام −1 انحراف مع انهيارات اجتماعية البوابة (عروض لا تُشاهد كاملة، مساعدة تُرفض)؛ دقيقة متأخرة المحطة؛ تقليد تنفيذي حاضر مشروط بمشاهدة مهندسة؛ وبنية مرئية تعديلة مركزية عنده. الدروس العامة: (1) أداء هذا المتعلم بشروط قياسية مجردة يقلّ عن قدرته بما يكفي لبناء ملف خاطئ؛ (2) ملاحظة «ماذا يفعل عند الصعوبة» (صلابة، صدى، رفض مساعدة) أثمن من درجاته في توجيه الخطة العلائقية؛ (3) التقييم الموضوع في يومه الأخير وآخر صباحه جزء من نتيجته — فلتُوثق السياقات ولتُقرأ الأرقام داخلها أبدًا.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا لا يجوز قراءة درجات يان في M-ABC (دون المئوي الخامس في كل شيء) حكمًا نهائيًا على قدرته الحركية؟", "الإجابة: لأن بنودًا سقطت بأبواب غير حركية موثقة (عروض لم تُشاهد كاملة، فهم حرفي، إيكولاليا تحت الصعوبة، تعب نهاية جلسة أخيرة في سياق متراكم)؛ فالدرجات تقيس أداءه في تلك الشروط مجتمعة، والحكم المهني يفصل ما سقط حركيًا مما سقط وصولًا قبل ترتيب أي خطة."], "text": null, "take": "حالة يان ملف قدرة متوسطة منخفضة تكشفها التعديلات (جدول مرئي وبنية مكانية) وتخفيها الشروط المجردة، بسلوك صعوبة موثق (صلابة وصدى ورفض مساعدة) هو نصف خطته القادمة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 75, "title": "حالة هوغو — حين يكون التوجيه الجسدي بوابة الفهم نفسها", "intro": "<p>حالة ثانية من الإطار نفسه للمقارنة المنهجية: هوغو، 4 سنوات و9 أشهر، في قسم متوسط (خمسة أنصاف أيام) مع مرافق مدرسي، ويتابع في مستشفى نهاري. خلص تقييمه إلى توحد طفولي مصحوب بتأخر نمو شامل. قارن وأنت تقرأ بين تعديلات نجحت عند يان وفشلت هنا وتعديلات انعكست نتيجتها تمامًا — فهذا هو درس الحالة الحقيقي: التعديل لا يُورَّث بين الملفات.</p>", "slides": [{"kind": "cover", "title": "حالة هوغو — حين يكون التوجيه الجسدي بوابة الفهم نفسها", "sub": "الوحدة الثامنة عشرة: حالات تطبيقية", "goals": ["أن تقرأ حالة هوغو وتقارنها بيان منهجيًا في الأعماق والتعديلات", "أن تفسّر لماذا صار التوجيه الجسدي بوابة فهمه الأولى", "أن توثق سرقة بنود الاختبارات بمدخلات حسية من داخلها"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l75.jpg", "img2": null}, {"kind": "slide", "title": "حالة هوغو — حين يكون التوجيه الجسدي بوابة الفهم نفسها", "points": ["فهم لفظي وقصدية وتواصل كلها أعمق إصابة من يان.", "صدى اجتماعي بلا فهم وظيفته توقيع علائقي.", "لا استثمار للكرة الكبيرة ولا انفعال ظاهر — بيانات لا فراغ."], "text": {"head": "سياق وخصوصيات — صورة أعمق على كل المحاور", "body": "<p>خصوصيات هوغو الموثقة: تواصل بصري هارب ورد متقلب على اسمه، وإدارة انفعالية صعبة مع إثارة حركية ونمطيات، وإيكولاليا فورية وثرثرة غير مفهومة (jargon)، وعجز فهم لفظي وتواصل غير لفظي، وقلة نشاط (hypoactivité) ولعب تلقائي شحيح، وتشويش حسي. في اللقاء الأول بقي غير مبالٍ بالمحاولات، هاربًا من التواصل البصري والجسدي، لا يجيب عند مناداته، ويكرر «صباح الخير» صدىً دون فهم لوظيفتها الاجتماعية. وحين وُضع على الكرة الكبيرة جالسًا ثم مستلقيًا لم يستثمرها ولم يظهر رضًا — بيانات قصدية وانفعالية بليغة عن ملف أعمق من سابقه بمراحل.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة هوغو — حين يكون التوجيه الجسدي بوابة الفهم نفسها", "points": ["شارلوب-أتويل −5.8 انحراف وM-ABC ‏32.5 نقطة.", "ديناميكي أفضل من ثابت كصورة يان لكن بأعماق مختلفة.", "استباق غائب يفسّر فشل التقاط الكرات وبُعده عن التبادل."], "text": {"head": "بيانات الفحص — انحرافات أعمق وصورة متوازنة الاتجاه", "body": "<p>حُدّد عمره الحركي العام دون 3 سنوات. شارلوب-أتويل: 6 نقاط فقط (نقطتان موضوعيتان و6 ذاتية) أي −5.8 انحراف معياري عن فئته — هوة كاملة. M-ABC: ‏32.5 نقطة ودون المئوي الخامس إجمالًا وفي كل مجال. لكن الصورة الداخلية ليست انهيارًا متساويًا: توازنه الديناميكي (مشي على مقعد وعارضة) أفضل من ثابته (أحادي غير كافٍ، أصابع قدم مستحيلة)؛ ودرجه غير ناضج؛ ولا يستطيع تتابع قفزات بملتحمتين ولا قفزًا من ارتفاع أو فوق حبل أو بقدم واحدة؛ وبطء ومسكات متغيرة في الدقيقة مع مسكة قلم يسارية راحية غير ناضجة وخط غير دقيق؛ ولا يلتقط كرة لغياب الاستباق، ورميه غير دقيق وخارج لعب التبادل. أرقام أعمق بفئتين كاملتين من حالة يان رغم تقارب العمرين.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة هوغو — حين يكون التوجيه الجسدي بوابة الفهم نفسها", "points": ["جدول يان المرئي غير صالح لهوغو: لا توريث تعديلات.", "توجيه جسدي مقبول تمامًا صار بوابة فهمه الأولى.", "بنية مسارية أكثف (أطواق بطول المسار) لفهم أعمق إصابة."], "text": {"head": "تعديلات انعكست — ما نفع يان لم ينفع هوغو", "body": "<p>هنا قلب الحالة التعليمي: الجدول المرئي الذي ثبّت يان لم يكن لينفع هوغو لمستوى فهمه وتجريده الأدنى، وصندوق «انتهى» نفسه صعب عليه فهمه واحترامه. بينما التوجيه الجسدي الذي كان سيرفضه سياق يان قبِله هوغو تمامًا وصار بوابته: يد تُمسك ليقفز فوق الحبل فيحس الحركة، ووقوف خلفه لوضع يديه واستباق التقاط الكرة. واحتاج أطواقًا على طول مسار القفز كله (طوقا يان لا يكفيانه)، وتعليمات مبسّطة مقسومة بطيئة واحدة واحدة مصحوبة بإيماءات ونبرة معدّلة. وحتى «لا تتوقع طلباته» استُعملت تدريبًا: كرات تُعطى واحدة واحدة بانتظار نظرة أو كلمة «أعطِ» — دون أن يلتقط القاعدة رغم التكرار، فبقيت بيانات قصدية لا فشل جلسة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة هوغو — حين يكون التوجيه الجسدي بوابة الفهم نفسها", "points": ["مظهر العملات وملمسها سرقا بندًا يدويًا كاملًا.", "إخفاء الوجه الجذاب من العملة تعديلة حسية استعادت البند.", "اصطفاف المكعبات استهلك بند تركيب من داخله أيضًا."], "text": {"head": "التشويش الحسي داخل بنود الفحص — حين تسرق المدخلات البند", "body": "<p>في بند مهارة يدوية (وضع عملات في حصّالة) كان هوغو غير مستقر حتى احتاج أن تُمسك يداه ليضع العملات على الحصيرة دون أن يلمسها؛ فقد كان مشوَّشًا بشدة بمظهر العملات وملمسها حتى أخفى الفاحص الوجه الذي يعجبه منها ليستعيد البند. وفي بند تركيب المكعبات خسر زمنًا طويلًا في اصطفافها (tendance à aligner) واحتاج إعادة توجيه جسدي متكررة للنظر. درس عام بليغ: بنود الاختبارات المقننة نفسها تحمل مدخلات حسية قد تسرقها من داخلها؛ والفاحص الذي يوثق «بندًا فشل» دون توثيق سارقه الحسي يبني حكمًا يدويًا على سرقة سمعية-بصرية-لمسية لم تُقرأ.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة هوغو — حين يكون التوجيه الجسدي بوابة الفهم نفسها", "points": ["بوابتاه المركزيتان: فهم لفظي وتوجيه جسدي مقبول.", "التعديل مشتق ملف لا وصفة فئة عمرية أو تشخيصية.", "أرقام صادمة بلا سياق تعديلات أحكام ظالمة مبكرة."], "text": {"head": "أسطر الحكم والدروس المهنية المستخلصة", "body": "<p>أسطر الحكم: تأخر حركي شامل عميق (عمر حركي دون 3 سنوات عند 4;9)؛ توازن ثابت أضعف من ديناميكي؛ استباق شبه غائب؛ تقليد منهار البوابة (نظر لا يتوجه أصلًا)؛ فهم لفظي بوابة مركزية لكل فحص؛ وتوجيه جسدي وبنية محسوسة تعديلتاه المركزيتان. الدروس العامة: (1) التعديلة قرار مشتق من ملف لا وصفة فئة — فجدول مرئي ناجح عند أسبرجر قد يكون عبثًا عند توحد طفولي بتأخر شامل؛ (2) قبول التوجيه الجسدي أو رفضه يقسم خطط بناء الفهم نصفين؛ (3) أعمق الملفات يحتاج أصدق التوثيق، لأن أرقامه الصادمة (−5.8) بلا سياق تعديلاتها تصير أحكامًا نهائية ظالمة على متعلم لم تُقَس قدرته بعد ببواباته هو.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا رُفض استعمال الجدول المرئي (الذي نجح مع يان) في تقييم هوغو، وما المبدأ العام؟", "الإجابة: لأن نجاح الجدول عند يان اعتمد على مستوى فهم وتجريد والتزام بالبنية لا يملكه هوغو بتأخره الشامل وفهمه الأدنى؛ والمبدأ أن التعديلة تُشتق من أسطر ملف المتعلم نفسه وتُفحص ملاءمتها، ولا تُورَّث بين الملفات مهما تشابهت الأعمار أو العناوين التشخيصية."], "text": null, "take": "حالة هوغو ملف تأخر شامل عميق بوابته الفهم والتوجيه الجسدي المقبول، يثبت أن التعديلات تُشتق من كل ملف على حدة وأن بنود الاختبارات نفسها قد تُسرق من داخلها بمدخلات حسية.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 76, "title": "حالة يوسف — الحلقة المركزية تصنع الخطة كلها", "intro": "<p>حالة تدريبية كاملة من نماذج ممارستنا الموثقة: يوسف، 6 سنوات و4 أشهر، في السنة التحضيرية، أُحيل بشكوى معلمته وأسرته. قيمته التعليمية أنه النموذج المقابل لحالتَي التقييم السابقتين: هنا ترى السلسلة كاملة من شكاوى متناثرة إلى فرضية حلقة مركزية واحدة تصنع مشروعًا علاجيًا من 12 أسبوعًا بأهداف قابلة للقياس ومقارنة إغلاق منجزة.</p>", "slides": [{"kind": "cover", "title": "حالة يوسف — الحلقة المركزية تصنع الخطة كلها", "sub": "الوحدة الثامنة عشرة: حالات تطبيقية", "goals": ["أن تتبع سلسلة يوسف من شكاوى متناثرة إلى فرضية حلقة مركزية", "أن تقرأ مشروع 12 أسبوعًا بأهدافه وجرعاته وأدواره الموزعة", "أن تحكم على فرضية الحلقة من مقارنة إغلاق T0/T1"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l76.jpg", "img2": null}, {"kind": "slide", "title": "حالة يوسف — الحلقة المركزية تصنع الخطة كلها", "points": ["ثلاث قوى افتتاحية: إيقاع وصور وضغط عميق.", "شكاوى متناثرة البيوت تبحث عن حلقة جامعة.", "سؤال الحلقة الواحدة بوابة التخطيط كلها هنا."], "text": {"head": "تقديم الحالة — قوى تُقرأ قبل الصعوبات", "body": "<p>يستجيب يوسف بقوة للإيقاع والنماذج المصورة ويحب الضغط العميق — ثلاث قوى تُفتتح بها كل قراءة مهنية له لأنها ستكون وسائط خطته نفسها. شكاواه الظاهرة متفرقة البيوت: ينهار جذعه على الطاولة بعد 3 دقائق من الجلوس، ويسقط في الساحة 3 مرات يوميًا، ويكسر الأقلام بقبضته المشدودة كاملة الإمساك. قراءة سطحية توزع الشكاوى على ثلاثة ملفات (جلوس، ساحة، كتابة)؛ وقراءة هذه الدورة تسأل أولًا: ما الحلقة الواحدة التي لو صحّت انهارت وراءها الشكاوى الثلاث؟ بهذا السؤال وحده وُلدت خطته كلها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة يوسف — الحلقة المركزية تصنع الخطة كلها", "points": ["صورة ممزقة الاتجاه: إيقاعي قوي ومحوري منهار.", "بنود «لم تُدَر بعد» معلنة لا مخفية في ملفه.", "تعريفات بسيطة للوظائف تجعل الجدول مقروءًا للأهل."], "text": {"head": "بيانات الفحص بتعريفاتها — جدول يوسف الكامل", "body": "<p>فُحصت وظائفه بمهام معرّفة بسيطة: النغمة (امتداد وانفعالية): محورية منخفضة وتوتر طرفي مرتفع — يحتاج دعمًا. الوضعية (جلوس 5 دقائق): ثبات 3 دقائق ثم انهيار — يحتاج دعمًا. التوازن (قدم واحدة): ثانيتان يمينًا وثانية يسارًا مع تعويض ذراعين — دعم كبير. التناسق العام (مشي وقفز بقدمين): متوسط بتناوب ذراعين مضطرب. الدقيقة: قبض راحي وإفلات غير دقيق — متوسط. الجانبية: يمنى مفضلة وقدم غير مستقرة. المخطط: يسمي 8 أجزاء ويقلد بالصور — متوسط. التخطيط (تسلسل 3 حركات): ينجح بالصور فقط — يحتاج دعمًا. المكاني: أساسي ناجح دون يمين/يسار. الزماني-الإيقاعي: ينجح بثلاث نبضات مع الطبل — قوي نسبيًا. الغرافوموتور: دائرة ناجحة وصليب بمساعدة وضغط شديد. وبقيت بنود معلنة «لم تُدار بعد» بمواضعها في جولة قادمة — صدق توثيقي يُحتذى.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة يوسف — الحلقة المركزية تصنع الخطة كلها", "points": ["خمس حلقات تصل المقوّية بقبضة القلم المكسورة.", "عدسة حسية ترتّب المدخلات قبل تدريب التوازن.", "وسائط الخطة مأخوذة من قوى المتعلم لا من كتالوج."], "text": {"head": "الفرضية — سلسلة سببية من خمس حلقات", "body": "<p>صيغت فرضية العمل سلسلة واحدة: نغمة محورية منخفضة ← ثبات وضعي ضعيف ← توازن غير مستقر وخوف سقوط ← تعب وتجنّب حركي ← مسكة قلم مشدودة تعوّض غياب الثبات بشدّ طرفي. وقُرئ البروفيل الحسي عدسة مرافقة: بحثه عن الضغط العميق وتجنبه الأرضيات غير المستقرة يفسران جزءًا من صورة توازنه وتجنبه، فسبق تنظيم المدخلات العميقة تدريبَ التوازن في ترتيب المشروع، وصار ضغطه المحبوب وسيطًا مهدئًا قبل المهام الصعبة. لاحظ اقتصاد الفرضية: سلسلة واحدة فسّرت شكاوى ثلاثة بيوت، وبنت ترتيب خطة، وحددت وسائطها من قوى المتعلم نفسه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة يوسف — الحلقة المركزية تصنع الخطة كلها", "points": ["أولوية أولى للحلقة المركزية وقبضة أخيرة تابعة.", "وسائط بيتية من قوى المتعلم (طبل وضغط عميق).", "أثاث صفي جزء مكتوب من الجرعة لا توصية جانبية."], "text": {"head": "المشروع العلاجي — 12 أسبوعًا بثلاث أولويات", "body": "<p>بُني مشروعه على الحلقة المركزية (الثبات المحوري): (1) ثبات وضعي: يجلس 8 دقائق بإسناد قدمين أثناء نشاط تركيب — مساعدة تلميح بصري نحو استقلال، ومعيار 4 من 5 جلسات؛ (2) توازن: يقف على قدم واحدة 5 ثوانٍ لكل قدم دون استناد — من مساعدة جزئية إلى تلميح لفظي، معيار 3 جلسات متتالية؛ (3) تنظيم ضغط وقبض: قلم سميك بقبضة ثلاثية دون كسر في 3 تمارين — من نمذجة إلى استقلال، معيار 80 بالمئة. أدوار موزعة: الأسرة 10 دقائق يوميًا (مشي دب، دفع جدار، تماثيل على إيقاع الطبل — قواه نفسها)، والمدرسة كرسي مناسب ومسند قدمان وطاولة بارتفاع صحيح، ومراجعة كل 4 أسابيع.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة يوسف — الحلقة المركزية تصنع الخطة كلها", "points": ["مؤشرات تابعة تحركت مع مؤشر الحلقة — دعم فرضية.", "تغير وظيفي (سقوط أسبوعي بدل يومي) قبل الأرقام جمالًا.", "قرار انتقال مكتوب بأولويات دورة قادمة وموعد إعادة."], "text": {"head": "مقارنة الإغلاق T0/T1 — أرقام تحسم الفرضية", "body": "<p>بعد 12 أسبوعًا أُعيد القياس بالمؤشرات نفسها: ثبات الجلوس من 3 إلى 8 دقائق (+5) وصار يكمل نشاط الطاولة دون انهيار؛ والوقوف الأحادي من 2/1 إلى 5/4 ثوانٍ وسقوط الساحة من 3 يوميًا إلى مرة أسبوعيًا؛ ومسك القلم من قبضة كاملة إلى رباعية بقلم سميك بلا كسر في معظم التمارين؛ والدرج من رفض بلا درابزين إلى نزول به وصعود دونه. حركة المؤشرات التابعة (توازن، قبضة) مع مؤشر الحلقة (ثبات) دعمت الفرضية المركزية عمليًا. وكان قرار الانتقال مكتوبًا: استمرار بأولويات دورة تالية (تناسق ثنائي، رمي والتقاط، تدرج نحو الصليب والمربع) وإعادة حوصلة بالأدوات نفسها بعد 6 أشهر.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الدليل العملي في مقارنة إغلاق يوسف على صحة فرضية الحلقة المركزية؟", "الإجابة: أن المؤشرات التابعة البعيدة ظاهريًا عن التدريب المباشر (قبضة القلم وكسره، وسقوط الساحة) تحركت بموازاة مؤشر الحلقة المركزية (ثبات الجلوس) رغم أن الخطة لم تستهدف القلم مباشرة إلا أخيرًا بتنظيم ضغط — فتحرك التابع مع المركز يدعم أن الرابط بينهما كان سببيًا كما افترضت الفرضية."], "text": null, "take": "حالة يوسف نموذج السلسلة الكاملة: شكاوى متناثرة ربطتها فرضية حلقة مركزية واحدة (الثبات المحوري)، فبنت مشروع 12 أسبوعًا بوسائط مأخوذة من قوى المتعلم، وأثبتت مقارنة إغلاقه أن الأعراض التابعة تتحرك مع حلقتها.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 77, "title": "حالة سارة — المخطط الجسدي وصورة الجسم في ملف واحد", "intro": "<p>حالة تدريبية مركبة جُمعت من ملفات متشابهة لأغراض هذا الدرس، لا تخص طفلة بعينها: سارة، 6 سنوات، أُحيلت بشكاوى «تصطدم بالأثاث والزملاء»، و«لا تعرف أسماء أجزاء جسدها كأقرانها»، و«ترفض أن تنظر في المرآة أو تُلتقط صورتها». ملفها يجمع اضطرابَي وحدة المخطط والصورة في حالة واحدة، ويُقرأ بأدوات تلك الوحدة كاملة: تعرّف وتعيين وتسمية، وحدود جسدية، ومرآة وصور وحياء.</p>", "slides": [{"kind": "cover", "title": "حالة سارة — المخطط الجسدي وصورة الجسم في ملف واحد", "sub": "الوحدة الثامنة عشرة: حالات تطبيقية", "goals": ["أن تقرأ ملف مخطط وصورة مركبًا بحلقة تغذية متبادلة واحدة", "أن تبني خطة خطين متوازيين بمؤشرات معدودة لكل خط", "أن تحترم رضا صاحب الجسد خطًا أحمر في أنشطة التعرّض والصورة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/act69_img1.webp", "img2": null}, {"kind": "slide", "title": "حالة سارة — المخطط الجسدي وصورة الجسم في ملف واحد", "points": ["تدرج هابط: نفس 14، دمية 9، صورة 7 من 18.", "تعيين بالإشارة أضعف من تسمية لفظية.", "اصطدام موثق يوميًا توقيع حدود خريطة عملية."], "text": {"head": "بيانات الفحص — أرقام خريطة ناقصة الاتجاهات", "body": "<p>سُمّيت أجزاء الجسد على نفسها 14 من 18، وعلى دمية 9 من 18، وعلى صورة إنسان 7 من 18 — تدرج هابط من المحسوس إلى الممثَّل. والتعيين بالإشارة أضعف من التسمية في المستويات الثلاثة. ورسمها للرجل 5 عناصر بلا رقبة ولا جذع مميز متناسب. وفي مهام الوضعيات المقلدة أخطأت الاتجاهات والجوانب في أكثر من نصف المحاولات. أما اصطدامها الموثق: 6-8 مرات يوميًا بأطر الأبواب وأركان الطاولات في الصف والممرات. صورة متكاملة: خريطة جسدية غير مكتملة التمثيل، تضعف كلما ابتعدت عن الجسد المحسوس نحو صورته — وهي الصيغة التي بُنيت عليها خطتها بالترتيب نفسه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة سارة — المخطط الجسدي وصورة الجسم في ملف واحد", "points": ["تهرب مرآة ورفض تصوير وحياء لافت — صورة هشة.", "لا قفز لتفسيرات رمزية بلا أدلة أوسع موثقة.", "خطة داخل الباب ويقظة إحالة مفتوحة دائمًا."], "text": {"head": "صورة الجسم — الوجه النفسي للملف", "body": "<p>في المرآة: نظرات خاطفة وتهرب سريع، وتعليقات قليلة سلبية عن مظهرها سمعها الأهل. وترفض التصوير الجماعي، وتختار ملابس واسعة تخفي جسدها باستمرار رغم حرّ الصيف، وحياؤها أشدّ من أقرانها بدرجة لافتة في مواقف تغيير الملابس الرياضية. ولا تاريخ تنمّر موثق، ولا علامات باب نفسي أوسع حاليًا. القراءة المنضبطة: صورة جسم هشة غير مستقرة الاستثمار، بلا قفز إلى تفسيرات رمزية بعيدة — تُبنى خطتها داخل بابنا (خبرات جسدية ناجحة ومقبولة اجتماعيًا وصور إيجابية متدرجة) مع يقظة إحالة مفتوحة لأي علامة أعمق.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة سارة — المخطط الجسدي وصورة الجسم في ملف واحد", "points": ["خريطة ناقصة تُهين الصورة اجتماعيًا أسبوعيًا.", "صورة هشة تحرم الخريطة من خبرات إغنائها.", "القطع بخطين متوازيين لا بباب واحد."], "text": {"head": "القراءة المركبة — كيف يغذي كل اضطراب أخاه", "body": "<p>يغذي الاضطرابان بعضهما هنا تغذية متبادلة قابلة للتوثيق: خريطة ناقصة تجعل الجسد أداة غير موثوقة (اصطدامات متكررة أمام الأقران) فتتلقى الصورة ضربات اجتماعية أسبوعية؛ وصورة هشة تجعل صاحبها يتجنب مواقف عرض الجسد (رياضة ومرايا ولعب حركي جماعي) فتُحرم الخريطة من خبرات إغنائها الطبيعية فتزداد نقصًا. الحلقة المغلقة هذه هي الحلقة المركزية لملفها، وقطعها يكون من بابيها معًا في خطة واحدة بخطين متوازيين: بناء خريطة بخبرات محسوسة آمنة، وبناء صورة بنجاحات جسدية اجتماعية مقبولة لا تعرّض صاحبها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة سارة — المخطط الجسدي وصورة الجسم في ملف واحد", "points": ["بناء الخريطة عكس تدرج هبوطها الموثق تمامًا.", "صور تختارها صاحبتها برضاها وحده — بلا فرض تعرّض.", "اتفاق مدرسي ضد التعليقات المظهرية جزء جرعة."], "text": {"head": "الخطة — 10 أسابيع بخطين متوازيين", "body": "<p>الخط الأول (خريطة): أنشطة خريطة الجسد الحية بصيغ وحدة المخطط (تعرف فتعيين فتسمية على الجسد الحي ثم الدمية ثم الصورة عكس تدرج هبوطها)، ومسارات اصطدام مقصودة متدرجة الضيق بلا أذى لتدريب الحدود بالنجاح، هدفها رفع التسمية على الصورة إلى 12 من 18 وخفض الاصطدامات إلى 2 يوميًا أو أقل. الخط الثاني (صورة): نشاطان جسديان اجتماعيان أسبوعيًا في مجموعات صغيرة آمنة بدور ناجح مضمون، وصور فوتوغرافية يختارها هي ويحتفظ بها في ألبومها الخاص (تقديم متدرج من صور يديها وألعابها إلى صورها الكاملة برضاها وحده)، واتفاق مدرسي يمنع أي تعليق مظهري عنها ويحوّل حصص الرياضة لمهام أزواج لا عروضًا جماعية. قياس الخطين بمؤشراتهما المنفصلة كل 5 أسابيع.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "حالة سارة — المخطط الجسدي وصورة الجسم في ملف واحد", "points": ["اتجاهان يتحركان معًا يدعمان قراءة الحلقة المغلقة.", "صورة الجسم تُقاس بسلوكيات معدودة لا بانطباعات.", "رضا صاحبة الجسد خط أحمر في أنشطة التعرّض."], "text": {"head": "متابعة باكرة ودروس الحالة العامة", "body": "<p>في مراجعة الأسبوع الخامس: تسمية الصورة 10 من 18، والاصطدامات 3-4 يوميًا، وقبلت أول صورة جماعية لها في نشاط تحبه بعد اختيارها مكان وقوفها. لم يكتمل شيء بعد ولم يُعلَن نجاح؛ لكن اتجاهي الخطين يتحركان معًا كما تنبأت قراءة التغذية المتبادلة. دروس الحالة العامة: (1) ملفات المخطط والصورة تُقرأ مركبة دائمًا لا بملفين منفصلين عند اجتماعهما؛ (2) مؤشرات صورة الجسم تُقاس بسلوكيات قابلة للعدّ (قبول صور، مواقف مشاركة) لا بانطباعات «تحسّنت ثقتها»؛ (3) رضا صاحبة الصورة وحدودها خط أحمر تصميمي في أي نشاط تعرّض مهما كانت فوائده المفترضة.</p><p>وفي ملف سارة يظهر أخيرًا معنى توثيق «لم يُدَر بعد» بوجهه الثاني: بنود صورة الجسم الأعمق (تاريخ علاقاتها بجسدها في البيت، ومواقف تغيير الملابس الجماعية كاملة) بقيت مقصودة للأسبوع العاشر بعد بناء ثقة — لأن ملف الصورة يُفتح بسرعة صاحبه لا بسرعة فاحصه، وقد سُجّل التأجيل قرارًا معللًا في خطتها لا فراغًا منسيًا في أوراقها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: لماذا بُني خط الخريطة في خطة سارة بتدرج (نفس ثم دمية ثم صورة) بينما جاءت نتائج فحصها بالترتيب العددي نفسه متناقصًا؟", "الإجابة: لأن الفحص أظهر أن قدرتها تهبط كلما ابتعد التمثيل عن الجسد المحسوس؛ فبناء الخطة يبدأ من مستواها الأقوى المحفوظ (جسدها الحي) ويصعد بدرجات التمثيل نفسها نحو أضعف مستوياتها (الصورة)، مطبقًا قاعدة البناء من القاعدة المحفوظة لا من القمة المضطربة."], "text": null, "take": "حالة سارة ملف تغذية متبادلة بين خريطة جسدية ناقصة التمثيل وصورة جسم هشة، تُقطع بخطة خطين متوازيين تُقاس بمؤشرات معدودة في كل خط، باحترام مطلق لحدود صاحبتها.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 78, "title": "مراجع الدورة — الببليوغرافيا الكاملة", "intro": "<p>تجمع هذه الصفحة مراجع الدورة الكاملة التي بُنيت عليها دروسها ووحداتها، مرتبة بأبوابها. داخل الدروس وردت أسماء العلماء والبحوث عند الدعاوى الجوهرية وحدها دون عناوين مؤلفات، تأسيسًا لقاعدة الدورة: أن يتعلم المتعلم من متن وحداته، وأن يجد من أراد التوسع خريطة المصادر كاملة هنا في موضع واحد معروف.</p>", "slides": [{"kind": "cover", "title": "مراجع الدورة — الببليوغرافيا الكاملة", "sub": "الوحدة التاسعة عشرة: مراجع الدورة ومسردها", "goals": ["أن تجد أي مرجع من مراجع الدورة في بابه الصحيح من الأبواب الخمسة", "أن تشرح قاعدة النسبة: أسماء داخل الدروس وعناوين كاملة هنا فقط", "أن تستعمل الببليوغرافيا خريطة توسع لقراءاتك اللاحقة"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l78.jpg", "img2": null}, {"kind": "slide", "title": "مراجع الدورة — الببليوغرافيا الكاملة", "points": ["وثائق التأسيس من 1907 إلى دبلوم الدولة 1974.", "أصول المفاهيم عند أصحابها لا عند ناقليها.", "مصدر مؤلَّف عربي في التأريخ ضمن قائمة الباب."], "text": {"head": "مراجع التأسيس والتاريخ", "body": "<p>- Dupré, E. (1907). أعمال متلازمة الوهن الحركي والخراقة والباراتونيا والحركات المصاحبة — التأسيس الأول لعيادة الحركة النفسية. - Wallon, H. (1925 وما بعدها). أعمال المقوّية العضلية والانفعال ومرحلية النمو — وأصل مفهوم الحوار المقوّي كما صاغه لاحقًا أجورياغيرا. - Ajuriaguerra, J. de (أعمال 1947-1974). تأسيس فريق إعادة التربية النفسية الحركية في مستشفى Henri-Rousselle وميثاق المهنة وبرامج الحوصلة — مع Soubiran, G. وBergès, J. وStambak, M. وZazzo, R. - Guilmain, É. (1931-1935). نماذج الفحص النفسي الحركي الأولى ومنهجية ملاحظته. - Head, H. أعمال المخطط الجسدي الأولى (postural scheme) — أصل مفهوم schéma corporel الحديث. - Dolto, F. أعمال صورة الجسم واللاوعي الجسدي — مرجع التمييز بين المخطط الجسدي وصورة الجسم. - Mazet, P. &amp; Houzel, D. تعريفات الممارسة النفسية الحركية ومجالاتها في الأدبيات الفرنسية المعاصرة. - عبد الحليم خليلي (2007). «نشأة العلاج النفسي الحركي» — مقال المؤسس في تأريخ التخصص ووحدة النفس والجسد وجلسة العلاج، أحد مصادر وحدة التاريخ المؤلَّفة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مراجع الدورة — الببليوغرافيا الكاملة", "points": ["أربعة عشر مرجعًا تحمل وحدات العلامات والآليات والاضطرابات.", "دراسات أصلية مقاسة لا ملخصات منقولة.", "حضور متوازن للمدارس الفرنسية والأنجلوسكسونية."], "text": {"head": "مراجع التوحد النفسي الحركي وآلياته", "body": "<p>- Teitelbaum, P. et al. (1998). تحليل الحركات المبكرة عند الرضّع الذين شُخّصوا لاحقًا بالتوحد — سقوطات الاستباق الوضعي. - Baranek, G. (2003). الخصوصيات الحسية المبكرة: استكشاف فموي ونفور لمسي في السنة الأولى. - Adrien, J.-L. et al. (1993). العلامات المبكرة في السنة الأولى: مقوّية وتعبيرات وانتباه. - Juhel, J.-C. (2003). تنظيم العلامات النمائية بمراحل 0-6 و6-12 و12-24 شهرًا. - Leary, M. &amp; Hill, D. (1996). الحركات المتناقضة والحركة الأداتية وحركة العلاقة عند التوحد. - Hauck &amp; Dewey (2001). قياسات التأخر الحركي الوسطي عند أطفال التوحد. - Baron-Cohen, S., Leslie, A. &amp; Frith, U. (1985). نظرية العقل عند التوحد — الدراسة المؤسسة. - Bullinger, A. أعمال القصدية والوضعية والمنظور الحسي-المقوّي لنمو الرضيع. - Pierce, K. &amp; Courchesne, E. (2001). الانتباه المشترك وقصدية الحركة عند التوحد. - Vernazza-Martin, S. et al. (2005). تقلب الأداء الحركي ولا تجانسه عند التوحد. - Kohen-Raz, R. (1992). المفارقات الوضعية وأنظمة التوازن عند التوحد. - Militerni, R. et al. (2002). الحركات النمطية وعلاقتها بشدة الاضطراب والمستوى المعرفي. - Rimland, B. (1990). تقديرات الشذوذات الحسية عند أطفال التوحد. - Rogé, B. (1991). أعمال الحركة والتوحد وتقسيماتها الوظيفية.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مراجع الدورة — الببليوغرافيا الكاملة", "points": ["ثلاثة أبواب آليّة بمراجعها المؤسسة والمحدّثة.", "أعمال التقليد من 1972 إلى أعمال التبادل الحديثة.", "مراجع بنية مكانية-زمانية لطبقة التعديلات."], "text": {"head": "مراجع التقليد والتخطيط والوظائف التنفيذية", "body": "<p>- De Myer, M. et al. (1972). الدراسات التأسيسية لتقليد الإيماءات عند أطفال التوحد. - Rogers, S. et al. (1996) وRogers &amp; Benetto (2002). اضطراب التقليد الفموي-الوجهي وبواباته الاجتماعية. - Nadel, J. أعمال التقليد المتبادل وفتح بوابات التفاعل عند صغار التوحد. - Jones &amp; Prior (1985). سلوكيات التقليد عند التوحد في الملاحظة المبكرة. - Hughes, C. (1996). الوظائف التنفيذية وتسلسل الأفعال عند التوحد. - Rinehart, N. et al. (2001، 2006). اضطراب تحضير الحركة مع سلامة تنفيذها والحركات المتناقضة. - Schmitz, C. et al. (2003). الاستباق الحركي وتجربة حمل الصينية عند التوحد. - Schopler, E. et al. أدبيات برنامج TEACCH في البنية المكانية-الزمانية والتقييم التطوري (PEP) التي استندت إليها طبقة التعديلات ومجالات التقييم التطوري السبعة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مراجع الدورة — الببليوغرافيا الكاملة", "points": ["ثلاث عشرة أداة وبطارية بأسماء أصحابها الأصلية.", "كل أداة وردت في دروس الفحص موثقة هنا بمصدرها.", "الأدوات وسائل ملاحظة منظمة لا بدائل عن الحكم العيادي."], "text": {"head": "أدوات الحوصلة وبطارياتها المرجعية", "body": "<p>- Soubiran, G. B. Pratique du bilan psychomoteur — المرجع الكلاسيكي في فحص المقوّية والتناسقات والجانبية والفضاء بمكوناته الموثقة. - Charlop &amp; Atwell. Échelle d'évaluation de la motricité (بطارية التنسيقات الديناميكية). - Henderson, S. &amp; Sugden, D. Movement Assessment Battery for Children (M-ABC) — بطاريات المهارة اليدوية والكرات والتوازن. - Bergès &amp; Lézine. اختبارات استنساخ الإيماءات وتقليدها بمراحلها (مرآتي/حقيقي/مؤجل). - Stambak, M. épreuves — التنقيط الموقوت وإعادة البنى الإيقاعية. - Ozeretski, N. مقاييس التناسق الدقيق وقصّ الدوائر النمائية. - Rey, A. اختبارات الشكل المركب والإيماءات الرقمية والنسخ من الذاكرة. - Kwint, L. التناسقات الوجهية وفحصها. - Vyl, M. اختبارات التنسيق البصري-اليدوي وخطوات تقدير المسافة. - Bender-Santucci. اختبارات الأشكال الهندسية والتنظيم المكاني. - Frostig, M. برامج الإدراك البصري وتقييمه. - Korkman et al. NEPSY — بطاريات التقييم النفسي العصبي للأطفال. - Hecaen &amp; Ajuriaguerra؛ وGalifret-Granjon &amp; Zazzo. استبيانات الجانبية وفحوص هيمناتها.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مراجع الدورة — الببليوغرافيا الكاملة", "points": ["مذكرة تولوز 2008 وثيقة الإطار والحالات الأولى.", "تصنيفان عالميان مرجعيان للتعريفات.", "مواد برنامج المؤسس مصدر توسع معلن في موضعه هذا فقط."], "text": {"head": "الوثيقة المؤسسة وتصنيفات مرجعية", "body": "<p>- Fillol, C. (2008). L'évaluation psychomotrice de l'enfant TED. Mémoire, Université Toulouse III — المذكرة المؤسسة لإطار هذه الدورة التقييمي والتعديلي، ومنها حالتا يان وهوغو التطبيقيتان ببياناتهما الأصلية. - منظمة الصحة العالمية. CIM-10 / ICD-10، التصنيف الدولي للأمراض — تعريفات الاضطرابات النمائية الشاملة والحركات النمطية. - الجمعية الأمريكية للطب النفسي. DSM — أطر تصنيف اضطراب طيف التوحد المتتابعة. - برنامج التدريب النفسي الحركي لمؤسس الدورة (مواد الوحدات العشرين وكتاب الحوصلة ونماذج تقاريرها وحالاتها الثماني) — مصدر التوسع التطبيقي لوحدات المكونات والأنشطة والحالات، ومنه نموذجا يوسف التدريبي ودارة تقييماته.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: وفق قاعدة النسبة في هذه الدورة، أين يجد المتعلم عناوين المؤلفات والدراسات كاملة، وماذا يجد داخل الدروس بدلًا عنها؟", "الإجابة: يجد العناوين الكاملة هنا في درس المراجع وحده مجمّعة بأبوابها؛ أما داخل الدروس فيجد أسماء العلماء والبحوث عند الدعاوى الجوهرية فقط (كأن يُقال عند راينهارت 2001 في موضع التحضير والتنفيذ) دون عناوين كتب أو صيغ إحالة ببليوغرافية."], "text": null, "take": "مراجع الدورة كاملة في خمسة أبواب: تأسيس وتاريخ، وتوحد وآليات، وتقليد وتخطيط، وأدوات حوصلة، ووثائق إطار وتصنيفات — وهي الموضع الوحيد الذي تُنسب فيه المؤلفات كاملة في هذه الدورة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}, {"n": 79, "title": "مسرد المصطلحات — عربي/فرنسي", "intro": "<p>مسرد ختامي يجمع مصطلحات الدورة بمقابلاتها الفرنسية وتعريف موجز لكل منها، مرتبًا بأبواب خمسة. وظيفته مرجعية محضة: أن يعود إليه المتعلم كلما احتاج تثبيت مصطلح بوجهيه العربي والفرنسي أثناء عمله اللاحق في الحوصلات والتقارير.</p>", "slides": [{"kind": "cover", "title": "مسرد المصطلحات — عربي/فرنسي", "sub": "الوحدة التاسعة عشرة: مراجع الدورة ومسردها", "goals": ["أن تستعمل المسرد مرجعًا سريعًا لمصطلحات الحوصلة والتقارير", "أن تثبّت المقابل الفرنسي الدقيق لأهم ثمانية وأربعين مصطلحًا", "أن تميّز أزواج المصطلحات المتقاربة (مخطط/صورة، تغذية استباقية/راجعة)"], "points": [], "text": null, "take": "", "task": "", "check": [], "img": "img-psycho/psydis-l79.jpg", "img2": null}, {"kind": "slide", "title": "مسرد المصطلحات — عربي/فرنسي", "points": ["ثمانية مصطلحات مؤسسة تُبنى عليها بقية المسرد.", "التعريف بجملة مهنية واحدة لكل مصطلح.", "المقوّية والباراتونيا والمصاحبات ثلاثية دوبريه التاريخية محفوظة."], "text": {"head": "مصطلحات البنية العامة", "body": "<p>- النفسية الحركية (psychomotricité): تخصص يدرس الجسد الحركي وانفعاله وتمثيله ويتدخل فيه تقييمًا وعلاجًا. - الحوصلة النفسية الحركية (bilan psychomoteur): فحص منهجي شامل للمكونات النفسية الحركية بأدوات مقننة وملاحظة منظمة. - المقوّية العضلية (tonus musculaire): توتر عضلي خلفي دائم ينظم الوضعية والاستعداد الحركي والانفعال. - الباراتونيا (paratonie): عجز عن الإرخاء الإرادي أمام مقاومة الفاحص، بدرجات. - الحركات المصاحبة (syncinésies): حركات لا إرادية ترافق جهدًا مقصودًا في أعضاء أخرى. - الخراقة (maladresse): اضطراب أداء حركي عام قوامه إسقاط واصطدام وانسكاب متكرر. - البراكسيا (praxies): منظومة بناء الأفعال المتعلمة من فكرتها إلى تنفيذها. - التنظيم الذاتي (autorégulation): قدرة الجهاز على ضبط إثارته وحالاته بوسائله الخاصة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مسرد المصطلحات — عربي/فرنسي", "points": ["عشرة مصطلحات مكونات بوحداتها المقابلة في الدورة.", "تمييز المخطط (حسي-حركي) عن الصورة (نفسي-وجداني) ثابت هنا.", "الاستباق الوضعي بمصطلحه الفرنسي المختصر الشائع APA."], "text": {"head": "مصطلحات المكونات", "body": "<p>- الوضعية (posture): تنظيم الجسد ضد الجاذبية في الثبات والحركة. - التوازن (équilibre): إبقاء مركز الثقل داخل قاعدة الارتكاز ثابتًا ومتحركًا. - التعديلات الوضعية الاستباقية (ajustements posturaux anticipés - APA): تجهيزات عضلية سابقة للحركة الكبيرة تحفظ الثبات. - التناسق الحركي (coordination motrice): تنظيم أجزاء الجسد زمنيًا ومكانيًا لفعل سلس هادف. - التناسق البصري-الحركي (coordination oculo-manuelle/visuo-motrice): قيادة العين لليد والجسد في الأفعال الموجهة. - المخطط الجسدي (schéma corporel): تمثيل حسي-حركي حي لمواضع الجسد وأجزائه وحدوده. - صورة الجسم (image du corps): تمثيل نفسي-وجداني للجسد عند دولتو، مبني على تاريخ صاحبه وعلاقاته. - الجانبية (latéralité): هيمنة أحد جانبي الجسد يدًا وعينًا وقدمًا بأفعال أحادية. - التخطيط الحركي (planification motrice): تصور فعل جديد وتنظيم خطواته السابقة لتنفيذه. - الإيقاع (rythme): تنظيم الفعل في فواصل زمنية منتظمة قابلة للتوليد والمطابقة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مسرد المصطلحات — عربي/فرنسي", "points": ["ثلاثة عشر مصطلحًا للاضطرابات وآلياتها المركزية.", "أزواج متقابلة (فرط/نقص) تُعرّف معًا اختصارًا ووضوحًا.", "الكمون والبوابة الحسية مصطلحا ممارسة يوميان لا نظريان فقط."], "text": {"head": "مصطلحات الاضطرابات والآليات", "body": "<p>- فرط المقوّية (hypertonie) ونقصها (hypotonie): ارتفاع التوتر الخلفي أو انخفاضه عن مجاله الوظيفي. - عسر التخطيط الحركي (dyspraxie): اضطراب بناء الأفعال الجديدة وتسلسلها مع سلامة مكوناتها. - الحركات النمطية (stéréotypies motrices): حركات متكررة ثابتة الشكل بلا هدف خارجي ظاهر. - الحركات المتناقضة (kinésies paradoxales): فشل أفعال بسيطة تحت الطلب ونجاح تنسيقات أعقد في السياق. - اللاتجانس النمائي (dysharmonie développementale): تفاوت اتجاهات النمو بين مجالات المتعلم الواحد. - التقليد (imitation): إعادة إنتاج فعل مرئي بالجسد نفسه ترجمة عبر المخطط الجسدي. - الإيكوپراكسيا (échopraxie): نسخ تلقائي لحركات الآخرين بلا وظيفة تواصلية. - القصدية (intentionnalité): توجيه الذات العملي نحو العالم والأشخاص بأفعال هادفة. - الوظائف التنفيذية (fonctions exécutives): تسلسل ومراقبة وكبح وتحديث خطط معرفية-حركية. - التعديل الحسي (modulation sensorielle): بوابة الجهاز التي تضخّم المدخلات المهمة وتكتم خلفيتها. - التكامل متعدد الوسائط (intégration multisensorielle): دمج قنوات حسية عدة في صورة جسدية واحدة قابلة للفعل. - الدفاعية اللمسية (défensivité tactile): ردود تجنب ودفاع مفرطة تجاه مدخلات اللمس. - زمن الكمون (temps de latence): زمن معالجة داخلي بين التعليمة والاستجابة يجب احترامه.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مسرد المصطلحات — عربي/فرنسي", "points": ["تسعة مصطلحات فحص وقياس وتعديل بمقابلاتها.", "T0/T1 ثنائية قياس الدورة القياسية في الخطط.", "التعديلات بمفهومها المهني الدقيق لا بمعنى التسهيل."], "text": {"head": "مصطلحات الفحص والقياس", "body": "<p>- الملاحظة المنظمة (observation structurée): رصد بمؤشرات محددة سلفًا في مواقف مضبوطة. - خط الأساس (mesure initiale / T0): قياس ما قبل التدخل بمؤشرات الخطة نفسها. - قياس الإغلاق (T1): إعادة القياس بشروط خط الأساس عند نهاية كل دورة خطة. - الانحراف المعياري (écart-type / DS): مسافة نتيجة المتعلم عن متوسط فئته بوحدات التشتت. - المئوي (percentile): مرتبة النتيجة ضمن مئة من الأقران. - التوجيه الجسدي (guidage physique): مرافقة يد الفاحص لحركة المتعلم لبناء فهمها جسديًا. - صندوق «انتهى» (boîte «fini»): أداة بنية مكانية تجعل نهاية كل نشاط محسوسة بالإيداع. - التعديلات (aménagements): تغييرات موثقة في شروط الوصول تُظهر القدرات دون مساس بالمهمة المقاسة. - الجانبية المتضاربة (latéralité discordante): عدم تطابق مستويات الهيمنة (عصبية وإيمائية واستعمالية) عند فرد واحد.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "مسرد المصطلحات — عربي/فرنسي", "points": ["ثمانية مصطلحات خطة وتدخل بمفاهيم الدورة الخاصة.", "الحلقة المركزية والخارجنة مصطلحا خطاب هذه الدورة المميزان.", "التلاشي مقابل التوجيه الجسدي في قسم الفحص وجهان لعملة واحدة."], "text": {"head": "مصطلحات التدخل والخطط", "body": "<p>- المشروع العلاجي (projet thérapeutique/intervention): وثيقة الخطة بأهدافها وجرعاتها ومراجعاتها من الحوصلة إلى الإغلاق. - الحلقة المركزية (noyau central): الصعوبة الجذرية التي يتفرع عنها أكبر عدد من أعراض الملف. - التعميم (généralisation): انتقال المهارة من سياق تدريبها إلى بيئات الحياة وأشخاصها. - الخارجنة (externalisation): إخراج الخطة من الذاكرة التنفيذية إلى دعائم مرئية خارجية ثم سحبها تدريجيًا. - منصات الانطلاق (rampes de lancement): إشارات وتموضعات تخفض كلفة الشروع في الأفعال. - الجرعة (dosage): مدة النشاط وتكراره وسياقاته بأرقام ثلاثة محددة. - البديل الحسي المنظم (substitution sensorielle organisée): نشاط من قناة النمطية نفسها يؤدي وظيفتها التنظيمية بصورة مقبولة. - التلاشي (fading/estompage): سحب تدريجي مخطط للمرافقات والدعائم مع استقرار المهارة.</p>"}, "take": "", "task": "", "check": [], "img": null, "img2": null}, {"kind": "slide", "title": "فحص الدرس", "points": ["السؤال: ما الفرق الدقيق بين المخطط الجسدي وصورة الجسم كما يثبته هذا المسرد؟", "الإجابة: المخطط الجسدي تمثيل حسي-حركي لمواضع الجسد وأجزائه وحدوده يعمل في الفعل الحاضر؛ أما صورة الجسم فتمثيل نفسي-وجداني عند دولتو مبني على تاريخ صاحبه وعلاقاته وخبراته مع جسده — الأول يُفحص بخرائط ومهام، والثانية تُقرأ في علاقة صاحبها بجسده ومظهره."], "text": null, "take": "مسرد الدورة ثمانية وأربعون مصطلحًا بمقابلاتها الفرنسية في خمسة أبواب: بنية عامة، ومكونات، واضطرابات وآليات، وفحص وقياس، وتدخل وخطط — مرجعك الثابت في الحوصلات والتقارير القادمة.", "task": "", "check": [], "img": null, "img2": null}], "quiz": []}]};
